window.QUESTION_BANK=[{"id": "马原-单选-1", "subject": "马原", "chapter": 0, "chapterTitle": "导论", "type": "单选", "number": 1, "stem": "1921年中国共产党的成立，是中华民族伟大复兴征程中的一大里程碑。100多年来，不管形势和任务如何变化，不管遇到什么样的惊涛骇浪，我们党都始终把握历史主动、锚定奋斗目标，沿着正确方向坚定前行。历史和实践充分证明，我们党坚定信仰信念、把握历史主动的根本所在是", "options": {"A": "拥有马克思主义科学理论指导", "B": "坚持不懈用党的创新理论凝心铸魂", "C": "始终把人民放在心中最高位置", "D": "科学社会主义提供了解决实际问题的正确答案"}, "answer": ["A"], "note": "我们党坚定信仰信念、把握历史主动的根本所在是：拥有马克思主义科学理论指导", "sourcePages": [1], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-2", "subject": "马原", "chapter": 0, "chapterTitle": "导论", "type": "单选", "number": 2, "stem": "马克思、恩格斯并不是先知先觉的圣人，他们从小面对的也是一个充满矛盾的现实世界，在家庭、学校和社会的影响下，也曾接受过那个时代的唯心主义和资产阶级民主主义思想。但是资本主义制度的弊端和劳动群众渴求解放的呼声，促使他们立志进行社会变革，并走上求索科学真理的道路。1844年2月，马克思、恩格斯发表在《德法年鉴》上的论文表明，他们\n\n①完成了从唯心主义向唯物主义的转变\n\n②完成了从革命民主主义向共产主义的转变\n\n③实现了历史观上的伟大变革\n\n④为创立马克思主义奠定了思想前提", "options": {"A": "①②③", "B": "②③④", "C": "①③④", "D": "①②④"}, "answer": ["D"], "note": "马克思、恩格斯发表在《德法年鉴》上的论文表明，他们：完成了从唯心主义向唯物主义的转变；完成了从革命民主主义向共产主义的转变；为创立马克思主义奠定了思想前提", "sourcePages": [1], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-3", "subject": "马原", "chapter": 0, "chapterTitle": "导论", "type": "单选", "number": 3, "stem": "马克思主义产生于19世纪40年代，为马克思主义的创立提供了直接的理论来源的是", "options": {"A": "德国古典哲学、英国古典政治经济学、英法空想社会主义", "B": "细胞学说、能量守恒与转化定律、生物进化论", "C": "古希腊罗马哲学、文艺复兴运动的思想成果、法国复辟时期历史学家的进步思想", "D": "朴素唯物主义、近代形而上学唯物主义、概念辩证法"}, "answer": ["A"], "note": "为马克思主义的创立提供了直接的理论来源的是：德国古典哲学、英国古典政治经济学、英法空想社会主义", "sourcePages": [1], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-5", "subject": "马原", "chapter": 0, "chapterTitle": "导论", "type": "单选", "number": 5, "stem": "1844年8月底，马克思、恩格斯在巴黎会面。这次会面使他们发现彼此的基本观点完全一致，于是开始了在科学理论研究和革命活动中的长期合作。马克思、恩格斯第一次合作的著作是", "options": {"A": "《神圣家族》", "B": "《德意志意识形态》", "C": "《哲学的贫困》", "D": "《共产党宣言》"}, "answer": ["A"], "note": "马克思、恩格斯第一次合作的著作是：《神圣家族》", "sourcePages": [1], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-6", "subject": "马原", "chapter": 0, "chapterTitle": "导论", "type": "单选", "number": 6, "stem": "在人类思想史上，马克思主义第一次站在人民的立场探求人类自由解放的道路，人民性是马克思主义的", "options": {"A": "本质属性", "B": "首要的和基本的观点", "C": "唯一特征", "D": "根本价值目标"}, "answer": ["A"], "note": "人民性是马克思主义的：本质属性", "sourcePages": [2], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-7", "subject": "马原", "chapter": 0, "chapterTitle": "导论", "type": "单选", "number": 7, "stem": "马克思主义具有鲜明的科学性、人民性、实践性、发展性，这些特征体现了马克思主义的本质和使命，也展现出马克思主义的理论形象。马克思主义的基本特征，如果用一句话来概括就是", "options": {"A": "人民性与实践性的统一", "B": "科学性与实践性的统一", "C": "科学性与革命性的统一", "D": "实践性与发展性的统一"}, "answer": ["C"], "note": "马克思主义的基本特征，如果用一句话来概括就是：科学性与革命性的统一", "sourcePages": [2], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-1", "subject": "马原", "chapter": 0, "chapterTitle": "导论", "type": "多选", "number": 1, "stem": "习近平深刻指出：“中国共产党为什么能，中国特色社会主义为什么好，归根到底是马克思主义行，是中国化时代化的马克思主义行。”马克思主义的当代价值在于，它是", "options": {"A": "观察当代世界变化的认识工具", "B": "指引当代中国发展的行动指南", "C": "引领人类社会进步的科学真理", "D": "指导革命、建设、改革的现成方案"}, "answer": ["A", "B", "C"], "note": "马克思主义的当代价值在于，它是：观察当代世界变化的认识工具；指引当代中国发展的行动指南；引领人类社会进步的科学真理", "sourcePages": [25], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-2", "subject": "马原", "chapter": 0, "chapterTitle": "导论", "type": "多选", "number": 2, "stem": "马克思主义主要由哲学、政治经济学、科学社会主义三大组成部分构成。这三大组成部分分别来源于德国古典哲学、英国古典政治经济学、英法空想社会主义，最终升华为马克思主义。最终升华的根本原因在于", "options": {"A": "马克思对所处的时代和世界的深入考察", "B": "马克思拥有优良的家庭背景和教育经历", "C": "马克思对人类社会发展规律的深刻把握", "D": "马克思出生和生活的德国、英国、法国是当时最为发达的资本主义国家"}, "answer": ["A", "C"], "note": "马克思主义哲学、政治经济学、科学社会主义这三大组成部分最终升华为马克思主义的根本原因在于：马克思对所处的时代和世界的深入考察；马克思对人类社会发展规律的深刻把握", "sourcePages": [25], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-8", "subject": "马原", "chapter": 1, "chapterTitle": "第一章世界的物质性及发展规律", "type": "单选", "number": 8, "stem": "辩证唯物主义是中国共产党人的世界观和方法论。辩证唯物主义最基本、最核心的观点是", "options": {"A": "对立统一规律", "B": "世界的物质统一性原理", "C": "资本主义必然灭亡，社会主义必然胜利", "D": "人民群众创造历史"}, "answer": ["B"], "note": "辩证唯物主义最基本、最核心的观点是：世界的物质统一性原理", "sourcePages": [2], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-9", "subject": "马原", "chapter": 1, "chapterTitle": "第一章世界的物质性及发展规律", "type": "单选", "number": 9, "stem": "唯物主义和唯心主义这两个专门的哲学术语有着特定的含义和确定的标准，不能随意乱用，也不能另立标准，否则会造成混乱。这里所说的特定含义和确定标准是指", "options": {"A": "对世界本原究竟是物质还是精神的回答", "B": "对存在和思维是否具有同一性的回答", "C": "对社会存在与社会意识关系的回答", "D": "对世界是怎样存在的问题的回答"}, "answer": ["A"], "note": "唯物主义和唯心主义的特定含义和确定标准是指：对世界本原究竟是物质还是精神的回答", "sourcePages": [2], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-11", "subject": "马原", "chapter": 1, "chapterTitle": "第一章世界的物质性及发展规律", "type": "单选", "number": 11, "stem": "物质和意识的对立只有在非常有限的范围内才具有绝对的意义，超出这个范围便是相对的了。这个范围是指", "options": {"A": "物质和意识何者为第一性", "B": "物质和意识是否具有同一性", "C": "物质和意识何者更重要", "D": "物质和意识何者与社会生活的关系更密切"}, "answer": ["A"], "note": "物质和意识的对立具有绝对的意义的范围是指：物质和意识何者为第一性", "sourcePages": [2], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-16", "subject": "马原", "chapter": 1, "chapterTitle": "第一章世界的物质性及发展规律", "type": "单选", "number": 16, "stem": "人类的出现，使世界发生了二重分化，即从自然界中分化出人类社会，从客观世界中分化出主观世界。自然界与人类社会、客观世界与主观世界相分化的关键是", "options": {"A": "人的实践活动", "B": "人的意识活动", "C": "语言文字的出现", "D": "人脑的出现"}, "answer": ["A"], "note": "自然界与人类社会、客观世界与主观世界相分化的关键是：人的实践活动", "sourcePages": [3], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-17", "subject": "马原", "chapter": 1, "chapterTitle": "第一章世界的物质性及发展规律", "type": "单选", "number": 17, "stem": "人类的出现，特别是人类改造世界的实践活动，极大地改变了世界的面貌，使世界发生了二重分化，即从自然界中分化出人类社会，从客观世界中分化出主观世界。人类社会与自然界的不同主要在于", "options": {"A": "在自然界中一切都是自发产生的，而在人类社会中一切都打着人的意识的印记", "B": "自然界受自然规律支配，而人类社会的发展方向是由每一个参与历史的人决定的", "C": "在自然界中有“人化自然”，而在人类社会中则没有自然物质和自然力的运用", "D": "自然界属于客观世界，而人类社会属于主观世界"}, "answer": ["A"], "note": "人类社会与自然界的不同主要在于：在自然界中一切都是自发产生的，而在人类社会中一切都打着人的意识的印记", "sourcePages": [3], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-26", "subject": "马原", "chapter": 1, "chapterTitle": "第一章世界的物质性及发展规律", "type": "单选", "number": 26, "stem": "发展的实质是新事物的产生和旧事物的灭亡。新、旧事物的区别在于", "options": {"A": "出现时间的先后", "B": "形式的新旧", "C": "力量的大小对比", "D": "同历史前进方向是否符合"}, "answer": ["D"], "note": "新、旧事物的区别在于：同历史前进方向是否符合", "sourcePages": [4], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-31", "subject": "马原", "chapter": 1, "chapterTitle": "第一章世界的物质性及发展规律", "type": "单选", "number": 31, "stem": "“君子以思患而豫防之”，有备才能无患。党的十八大以来，习近平总书记十分重视底线思维，强调凡事不能超越底线。如法律底线、政策底线、利益底线、道德底线等，一旦被突破，就会出现无法接受的坏结果。从哲学的角度分析，底线是指", "options": {"A": "联系的条件性", "B": "度的关节点", "C": "主要矛盾", "D": "事物发展的连续性"}, "answer": ["B"], "note": "底线是指：度的关节点", "sourcePages": [5], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-34", "subject": "马原", "chapter": 1, "chapterTitle": "第一章世界的物质性及发展规律", "type": "单选", "number": 34, "stem": "“知人善察，难眩以伪。”现象有真象和假象之分，假象是", "options": {"A": "从反面歪曲表现本质的现象", "B": "人们在认识中产生的错觉", "C": "与本质无关的现象", "D": "人们主观自生的观念"}, "answer": ["A"], "note": "假象是：从反面歪曲表现本质的现象", "sourcePages": [6], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-35", "subject": "马原", "chapter": 1, "chapterTitle": "第一章世界的物质性及发展规律", "type": "单选", "number": 35, "stem": "现象有真象和假象之分，真象和假象的区别在于", "options": {"A": "真象从正面表现本质，假象从反面歪曲地表现本质", "B": "真象深藏于事物内部，假象外露于事物外部", "C": "真象表现本质，假象不表现本质", "D": "真象是真实的，假象是一种错觉"}, "answer": ["A"], "note": "真象和假象的区别在于：真象从正面表现本质，假象从反面歪曲地表现本质", "sourcePages": [6], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-36", "subject": "马原", "chapter": 1, "chapterTitle": "第一章世界的物质性及发展规律", "type": "单选", "number": 36, "stem": "做事情时要区分可能性和不可能性，二者的区别在于", "options": {"A": "人的主观努力程度", "B": "对人是否有利", "C": "现实中有无根据和条件", "D": "现实中的根据和条件是否充分"}, "answer": ["C"], "note": "可能性和不可能性的区别在于：现实中有无根据和条件", "sourcePages": [6], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-38", "subject": "马原", "chapter": 1, "chapterTitle": "第一章世界的物质性及发展规律", "type": "单选", "number": 38, "stem": "“概念的辩证法本身就变成只是现实世界的辩证运动的自觉的反映，从而黑格尔的辩证法就被倒转过来了。”这段话表明，主观辩证法与客观辩证法的关系是", "options": {"A": "反映与被反映的关系", "B": "唯心主义与唯物主义的关系", "C": "抽象与具体的关系", "D": "唯心辩证法与唯物辩证法的关系"}, "answer": ["A"], "note": "主观辩证法与客观辩证法的关系是：反映与被反映的关系", "sourcePages": [6], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-42", "subject": "马原", "chapter": 1, "chapterTitle": "第一章世界的物质性及发展规律", "type": "单选", "number": 42, "stem": "学习和掌握唯物辩证法的科学思维方法，要求我们在实践中不断增强辩证思维能力。提高辩证思维能力，要自觉运用对立统一规律，掌握运用好辩证的逻辑思维方法。在这些思维方法中，人类思维从个别到一般，又由一般到个别的最常见的推理形式是", "options": {"A": "分析与综合", "B": "归纳与演绎", "C": "抽象与具体", "D": "逻辑与历史"}, "answer": ["B"], "note": "人类思维从个别到一般，又由一般到个别的最常见的推理形式是：归纳与演绎", "sourcePages": [7], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-5", "subject": "马原", "chapter": 1, "chapterTitle": "第一章世界的物质性及发展规律", "type": "多选", "number": 5, "stem": "形而上学唯物主义物质观的缺陷在于", "options": {"A": "把某种特殊的物质形态误认为物质的一般", "B": "割裂了自然界与人类社会的物质统一性", "C": "否认意识由物质决定", "D": "不了解人类对物质的认识是一个永无止境的发展过程"}, "answer": ["A", "B", "D"], "note": "形而上学唯物主义物质观的缺陷在于：把某种特殊的物质形态误认为物质的一般；割裂了自然界与人类社会的物质统一性；不了解人类对物质的认识是一个永无止境的发展过程", "sourcePages": [25], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-7", "subject": "马原", "chapter": 1, "chapterTitle": "第一章世界的物质性及发展规律", "type": "多选", "number": 7, "stem": "马克思主义物质观认为，客观实在性是物质的唯一特性，既肯定了哲学物质范畴同自然科学物质结构理论的联系，又把它们区别开来，体现了唯物论和辩证法的统一，克服了形而上学唯物主义的缺陷。马克思主义物质观所体现的唯物辩证法是指", "options": {"A": "从个性中看到共性", "B": "从相对中找到绝对", "C": "从暂时中发现永恒", "D": "从局部中看到整体"}, "answer": ["A", "B", "C"], "note": "马克思主义物质观所体现的唯物辩证法是指：从个性中看到共性；从相对中找到绝对；从暂时中发现永恒", "sourcePages": [26], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-16", "subject": "马原", "chapter": 1, "chapterTitle": "第一章世界的物质性及发展规律", "type": "多选", "number": 16, "stem": "物质世界是运动变化着的，并从中分化出多样化的特别是更高级的事物和运动形式。人类的出现，特别是人类改造世界的实践活动，极大地改变了世界的面貌，使世界发生了二重分化，即", "options": {"A": "从自然界中分化出人类社会", "B": "从客观世界中分化出主观世界", "C": "从必然王国中分化出自由王国", "D": "从现实世界中分化出虚拟世界"}, "answer": ["A", "B"], "note": "人类的出现、特别是人类改造世界的实践活动，使世界发生了二重分化，即：丛自然界中分化出人类社会；从客观世界中分化出主观世界", "sourcePages": [27], "answerSource": "配套资料与题目核对"}, {"id": "马原-多选-24", "subject": "马原", "chapter": 1, "chapterTitle": "第一章世界的物质性及发展规律", "type": "多选", "number": 24, "stem": "唯物辩证法就其本质来说是批判的、革命的，因为它", "options": {"A": "认为凡是现存的都是应当灭亡的", "B": "对每一种既成的形式都从其暂时性方面去理解和对待", "C": "认为事物变化发展只有间断性，没有连续性", "D": "在对现存事物的肯定理解中包含对现存事物的否定理解"}, "answer": ["A", "B", "D"], "note": "唯物辩证法就其本质来说是批判的、革命的，因为：它认为凡是现存的都是应当灭亡的；对每一种既成的形式都从其暂时性方面去理解和对待；在对现存事物的肯定理解中包含对现存事物的否定理解", "sourcePages": [29], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-35", "subject": "马原", "chapter": 1, "chapterTitle": "第一章世界的物质性及发展规律", "type": "多选", "number": 35, "stem": "增强忧患意识、坚持底线思维，是我们党的优良传统和宝贵经验。在党的七大上，毛泽东同志提出全党要“准备吃亏”，强调“要在最坏的可能性上建立我们的政策”。改革开放后，邓小平同志强调：“我们要把工作的基点放在出现较大的风险上，准备好对策。”党的十八大以来，习近平总书记反复强调坚持底线思维，告诫全党要“坚持底线思维、增强忧患意识，有效防范和化解前进道路上的各种风险”。坚持底线思维蕴含的哲学原理是", "options": {"A": "要坚持“两点论”，不能只看到有利的一面、忽视不利的一面", "B": "要充分发挥主观能动性，将事物的发展永远控制在量变的范围内", "C": "要以积极的态度研判风险、防患于未然，变挑战为机遇，追求最佳结果", "D": "要认清事物发生质变的临界点，自觉把握事物量变引起质变的“度”"}, "answer": ["A", "C", "D"], "note": "坚持底线思维蕴含的哲学原理是：要坚持“两点论”，不能只看到有利的一面、忽视不利的一面；要以积极的态度研判风险、防患于未然，变挑战为机遇，追求最佳结果；要认清事物发生质变的临界点，自觉把握事物量变引起质变的“度”", "sourcePages": [31], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-36", "subject": "马原", "chapter": 1, "chapterTitle": "第一章世界的物质性及发展规律", "type": "多选", "number": 36, "stem": "“是就是，不是就不是；除此之外，都是鬼话。”形而上学否定观的错误在于", "options": {"A": "它只承认克服，不承认保留", "B": "它只看到了事物之间的联系，没有看到事物之间的区别", "C": "它在绝对不相容的对立中进行思维", "D": "它认为否定是绝对的否定，是不包含肯定的否定"}, "answer": ["A", "C", "D"], "note": "形而上学否定观的错误在于：它只承认克服，不承认保留；它在绝对不相容的对立中进行思维；它认为否定是绝对的否定，是不包含肯定的否定", "sourcePages": [31], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-44", "subject": "马原", "chapter": 1, "chapterTitle": "第一章世界的物质性及发展规律", "type": "多选", "number": 44, "stem": "恩格斯指出：“所谓主观辩证法，即辩证的思维，不过是自然界中到处盛行的对立中的运动的反映。”主观辩证法与客观辩证法的关系是", "options": {"A": "反映与被反映的关系", "B": "源与流的关系", "C": "唯物主义和唯心主义的关系", "D": "在本质上是统一的，在表现形式上是不同的"}, "answer": ["A", "D"], "note": "主观辩证法与客观辩证法的关系是：反映与被反映的关系；在本质上是统一的，在表现形式上是不同的", "sourcePages": [32], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-43", "subject": "马原", "chapter": 2, "chapterTitle": "第二章实践与认识及其发展规律", "type": "单选", "number": 43, "stem": "马克思主义理论区别于其他理论的根本特征是", "options": {"A": "科学性", "B": "人民性", "C": "实践性", "D": "发展性"}, "answer": ["C"], "note": "马克思主义理论区别于其他理论的根本特征是：实践性", "sourcePages": [7], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-44", "subject": "马原", "chapter": 2, "chapterTitle": "第二章实践与认识及其发展规律", "type": "单选", "number": 44, "stem": "马克思、恩格斯以前的中外哲学都使用过实践的概念。一些思想家对实践也有过不少论述，但他们都没有真正理解人类实践的本质，没有看到实践在社会生活和认识活动中的决定意义。马克思在他的著作中系统论述了实践的观点，揭示了科学实践观的基本内容。这个被称为“包含新世界观天才萌芽的第一个文件”的著作是", "options": {"A": "《德意志意识形态》", "B": "《反杜林论》", "C": "《关于费尔巴哈的提纲》", "D": "《路德维希·费尔巴哈和德国古典哲学的终结》"}, "answer": ["C"], "note": "这个被称为“包含新世界观天才萌芽的第一个文件”的著作是：《关于费尔巴哈的提纲》", "sourcePages": [7], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-53", "subject": "马原", "chapter": 2, "chapterTitle": "第二章实践与认识及其发展规律", "type": "单选", "number": 53, "stem": "“调查研究是从实际出发的中心一环。没有调查就没有发言权，没有调查也没有决策权。”调查才能获得第一手材料，获得感性认识。感性认识的突出特点是\n\n①直接性\n\n②深刻性\n\n③具体性\n\n④间接性", "options": {"A": "①③", "B": "①②", "C": "②③", "D": "②④"}, "answer": ["A"], "note": "感性认识的突出特点是：直接性；具体性", "sourcePages": [8], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-55", "subject": "马原", "chapter": 2, "chapterTitle": "第二章实践与认识及其发展规律", "type": "单选", "number": 55, "stem": "感性认识和理性认识是统一的认识过程中的两个阶段，它们既有区别，又有联系。感性认识和理性认识的区别在于", "options": {"A": "感性认识反映事物的现象，理性认识反映事物的本质", "B": "感性认识来源于社会实践，理性认识来源于抽象思维", "C": "感性认识来源于感性具体，理性认识来源于理性具体", "D": "感性认识包含错误，理性认识则完全正确"}, "answer": ["A"], "note": "感性认识和理性认识的区别在于：感性认识反映事物的现象，理性认识反映事物的本质", "sourcePages": [8, 9], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-68", "subject": "马原", "chapter": 2, "chapterTitle": "第二章实践与认识及其发展规律", "type": "单选", "number": 68, "stem": "“自由不在于幻想中摆脱自然规律而独立，而在于认识这些规律，从而能够有计划地使自然规律为一定的目的服务。”这说明自由是", "options": {"A": "选择的随意性", "B": "活动的主动性", "C": "摆脱必然性", "D": "对必然的认识和对客观世界的改造"}, "answer": ["D"], "note": "自由是：对必然的认识和对客观世界的改造", "sourcePages": [10], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-51", "subject": "马原", "chapter": 2, "chapterTitle": "第二章实践与认识及其发展规律", "type": "多选", "number": 51, "stem": "人的意识是一种精神力量，要使它得到实现，必须通过实践活动。一种活动能否被称为实践活动，关键看它是否", "options": {"A": "超出了纯粹的意识活动", "B": "以客观世界作为客体", "C": "改变了除实践主体的意识状态之外的其他存在物的状态", "D": "具有目的性"}, "answer": ["A", "C"], "note": "一种活动能否被称为实践活动，关键看它是否：超出了纯粹的意识活动；改变了除实践主体的意识状态之外的其他存在物的状态", "sourcePages": [34], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-52", "subject": "马原", "chapter": 2, "chapterTitle": "第二章实践与认识及其发展规律", "type": "多选", "number": 52, "stem": "“元宇宙”作为全球科技领域关注的焦点，正在为产业带来深刻变革，昭示着数字化未来的无限可能性。元宇宙到底是什么，目前尚无统一定义。有人认为，元宇宙是平行于现实世界的、始终存在的虚拟世界；有人认为，元宇宙是现实世界和虚拟世界的无缝融合；还有人认为，元宇宙是对现实世界的一种超越。无论大家在理解上有何不同，从哲学上看，元宇宙", "options": {"A": "是对虚幻世界的摹写与反映", "B": "依然是人的实践活动的产物", "C": "归根到底是现实世界的一种延伸和拓展", "D": "不是一个完全不同于现实世界的“第三世界”"}, "answer": ["B", "C", "D"], "note": "从哲学上看，元宇宙：依然是人的实践活动的产物；归根到底是现实世界的一种延伸和拓展；不是一个完全不同于现实世界的“第三世界”", "sourcePages": [34], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-56", "subject": "马原", "chapter": 2, "chapterTitle": "第二章实践与认识及其发展规律", "type": "多选", "number": 56, "stem": "自然界中只有山川、河流、湖泊等自然物质，并没有火车、飞机、轮船、桥梁、水库等符合人需要的现成形式。这些形式的出现，表明了人的认识活动的能动性。辩证唯物主义认识论认为，认识是主体在实践基础上对客体的能动反映。这种能动反映的基本特点是", "options": {"A": "摹写性", "B": "创造性", "C": "重复性", "D": "规律性"}, "answer": ["A", "B"], "note": "认识的能动反映的基本特点是：墓写性；创造性", "sourcePages": [35], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-59", "subject": "马原", "chapter": 2, "chapterTitle": "第二章实践与认识及其发展规律", "type": "多选", "number": 59, "stem": "在认识的本质问题上，各种哲学派别有着不同的观点。其中，旧唯物主义认识论的缺陷在于", "options": {"A": "没有坚持从物到感觉和思想的认识路线", "B": "不了解实践对认识的决定作用", "C": "看不到主观和客观之间的矛盾及其相互作用", "D": "没有把认识看作一个不断发展的过程"}, "answer": ["B", "C", "D"], "note": "旧唯物主义认识论的缺陷在于：不了解实践对认识的决定作用；看不到主观和客观之间的矛盾及其相互作用；没有把认识看作一个不断发展的过程", "sourcePages": [35], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-61", "subject": "马原", "chapter": 2, "chapterTitle": "第二章实践与认识及其发展规律", "type": "多选", "number": 61, "stem": "对于同一棵大树，在木匠的眼中是木材，画家看到的是色彩和色调，植物学家看到的是它的形态特征，这是由于", "options": {"A": "人的感觉受理性指导", "B": "人的认识具有能动性", "C": "理性认识是感性认识的基础", "D": "已有的认识影响感觉活动"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [35], "answerSource": "待核对"}, {"id": "马原-多选-62", "subject": "马原", "chapter": 2, "chapterTitle": "第二章实践与认识及其发展规律", "type": "多选", "number": 62, "stem": "信息技术迅猛发展，催生了一个信息爆炸、思想奔涌的时代。海量信息以前所未有的速度与密度涌入社会认知领域，深度浸润青年一代。如何在纷繁复杂的信息海洋中保持清醒？人们需要批判性思维。辩证唯物主义揭示了“实践、认识、再实践、再认识”的螺旋式上升规律，而批判性思维正是实现这一认识飞跃的关键枢纽。它要求以实践为标准，不断检验、修正和发展认识，防止思想僵化。具备批判性思维的青年，就如同拥有穿透迷雾的“理性之眼”，能够洞察事物本质与发展规律，在复杂社会现象前保持头脑冷静，作出明智判断与理性决策。在认识和实践活动中，批判性思维体现在", "options": {"A": "对感性材料加以去粗取精、去伪存真", "B": "在认识活动中避免任何非理性因素的作用", "C": "在对现存事物的肯定的理解中同时包含对现存事物的否定的理解", "D": "在实践中不断推翻以往的真理并建立新的真理"}, "answer": ["A", "C"], "note": "在认识和实践活动中，批判性思维体现在：对感性材料加以去粗取精、去伪存真；在对现存事物的肯定的理解中同时包含对现存事物的否定的理解", "sourcePages": [36], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-70", "subject": "马原", "chapter": 2, "chapterTitle": "第二章实践与认识及其发展规律", "type": "多选", "number": 70, "stem": "如何发掘、研究化石，是古生物学研究的重要课题。一块块化石诉说着地球的演变，承载着远古的奥秘。过去，挖化石如同“拆盲盒”。如今，在新技术的助力下，古生物学研究正加速破解更多生命密码。你能想象吗？一块大小不到4平方厘米的琥珀，能揭示一个热带海岸森林的滨海环境。研究人员利用CT扫描技术，重建白垩纪中期一块缅甸克钦琥珀中各类化石的三维图像。他们发现，这枚琥珀保存了异常丰富的化石类群，包括1个菊石、4个螺类、4个等足虫、23个螨虫、1个蜘蛛、1个马陆和至少12个昆虫，以及一些砂粒、植物碎屑。这为揭示周围4平方公里乃至40平方公里的森林生态提供了重要证据。借助新技术，从一块琥珀，可以“看见”一片热带森林，这说明人的认识能力", "options": {"A": "以人的感觉器官生理阈限为界限", "B": "是无限性和有限性的统一", "C": "可以通过实践得到锻炼和提高", "D": "随着时代的发展而发展"}, "answer": ["B", "C", "D"], "note": "人的认识能力：是无限性和有限性的统一；可以通过实践得到锻炼和提高；随着时代的发展而发展", "sourcePages": [37], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-72", "subject": "马原", "chapter": 2, "chapterTitle": "第二章实践与认识及其发展规律", "type": "多选", "number": 72, "stem": "在实践检验真理的过程中，逻辑证明", "options": {"A": "能够取代实践作为检验认识真理性的标准", "B": "是对实践标准的一个重要的补充", "C": "是探索和论证真理的方式", "D": "必须服从实践检验的最后结果"}, "answer": ["B", "C", "D"], "note": "在实践检验真理的过程中，逻辑证明是：对实践标准的一个重要的补充；是探索和论证真理的方式；必须服从实践检验的最后结果", "sourcePages": [37], "answerSource": "配套资料与题目核对"}, {"id": "马原-单选-69", "subject": "马原", "chapter": 3, "chapterTitle": "第三章人类社会及其发展规律", "type": "单选", "number": 69, "stem": "马克思主义哲学创立后，开始出现了", "options": {"A": "唯物论与唯心论的对立", "B": "可知论与不可知论的对立", "C": "辩证法与形而上学的对立", "D": "唯物史观与唯心史观的对立"}, "answer": ["D"], "note": "马克思主义哲学创立后，开始出现了：唯物史观与唯心史观的对立", "sourcePages": [11], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-76", "subject": "马原", "chapter": 3, "chapterTitle": "第三章人类社会及其发展规律", "type": "单选", "number": 76, "stem": "炎炎夏日，却不见“汗滴禾下土”。在智慧农场内，农业机器人穿梭田间、巡检苗情，各类传感器遍布其间，探测情、气象、病虫害等信息，并实时传输到后方的指挥中心。农田管理员坐镇指挥中心，手持平板电脑这个“新农具”，远程操控着整个农场的运行。“犁地不用牛，种地不跟楼，浇水不拿，喷药不进田，收麦不带镰，晒麦不用场，卖麦不用忙”的“新农谚”，成为乡村新写照。平板电脑变成“新农具”启示我们，区分社会经济时代的客观依据是", "options": {"A": "生产工具的状况", "B": "劳动者的素质", "C": "劳动对象的广度和深度", "D": "劳动产品的数量和质量"}, "answer": ["A"], "note": "区分社会经济时代的客观依据是：生产工具的状况", "sourcePages": [12], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-78", "subject": "马原", "chapter": 3, "chapterTitle": "第三章人类社会及其发展规律", "type": "单选", "number": 78, "stem": "马克思指出：“为了进行生产，人们相互之间便发生一定的联系和关系；只有在这些社会联系和社会关系的范围内，才会有他们对自然界的影响，才会有生产。”在生产关系中，区分不同生产方式、判定社会经济结构性质的客观依据是", "options": {"A": "生产中人与人的关系", "B": "产品分配关系", "C": "阶级关系", "D": "生产资料所有制关系"}, "answer": ["D"], "note": "区分不同生产方式、判定社会经济结构性质的客观依据是：生产资料所有制关系", "sourcePages": [12], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-80", "subject": "马原", "chapter": 3, "chapterTitle": "第三章人类社会及其发展规律", "type": "单选", "number": 80, "stem": "在整个上层建筑中，政治上层建筑居于主导地位，政治上层建筑的核心是", "options": {"A": "国家政权", "B": "政治法律思想", "C": "道德、艺术", "D": "政党"}, "answer": ["A"], "note": "政治上层建筑的核心是：国家政权", "sourcePages": [13], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-81", "subject": "马原", "chapter": 3, "chapterTitle": "第三章人类社会及其发展规律", "type": "单选", "number": 81, "stem": "唯物史观视域中的“世界历史”是指各民族、国家通过普遍交往，打破孤立隔绝的状态，进入相互依存、相互联系的世界整体化的历史。世界历史形成和发展的基础是", "options": {"A": "生产方式的发展变革", "B": "地理科学的逐渐完善", "C": "意识形态的普遍认同", "D": "信息技术的广泛应用"}, "answer": ["A"], "note": "世界历史形成和发展的基础是：生产方式的发展变革", "sourcePages": [13], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-82", "subject": "马原", "chapter": 3, "chapterTitle": "第三章人类社会及其发展规律", "type": "单选", "number": 82, "stem": "人类通过实践活动在不断改造世界过程中推动社会发展和进步。社会的发展和进步集中表现为", "options": {"A": "社会形态的更替", "B": "社会生产力的发展", "C": "人类自身得到改造和发展", "D": "人类对社会规律的认识和改造"}, "answer": ["A"], "note": "社会的发展和进步集中表现为：社会形态的更替", "sourcePages": [13], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-83", "subject": "马原", "chapter": 3, "chapterTitle": "第三章人类社会及其发展规律", "type": "单选", "number": 83, "stem": "人的发展是一个社会历史过程，既包括人类整体的发展，也包括人类个体的发展。人的发展指人的体力、智力、个性和交往能力等的发展，其中最根本的是", "options": {"A": "人的本质力量的对象化、现实化", "B": "人类智慧和认知能力的发展", "C": "人的自由程度的提高", "D": "人的文明程度的提高"}, "answer": ["C"], "note": "人的发展中，最根本的是：人的自由程度的提高", "sourcePages": [13], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-85", "subject": "马原", "chapter": 3, "chapterTitle": "第三章人类社会及其发展规律", "type": "单选", "number": 85, "stem": "社会形态更替的必然性，主要是指社会形态依次更替的过程和规律是客观的，其发展的基本趋势是确定不移的。社会形态更替归根结底是社会基本矛盾运动的结果。其中具有最终决定意义的是", "options": {"A": "人民的意志和选择", "B": "生产资料所有权的归属", "C": "生产力的发展", "D": "对本民族特点的把握程度"}, "answer": ["C"], "note": "社会形态更替中，具有最终决定意义的是：生产力的发展", "sourcePages": [13], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-88", "subject": "马原", "chapter": 3, "chapterTitle": "第三章人类社会及其发展规律", "type": "单选", "number": 88, "stem": "人类同疾病较量最有力的武器就是科学技术，人类战胜大灾大疫离不开科学发展和技术创新。马克思主义认为，科学技术是", "options": {"A": "社会形态变革的决定力量", "B": "社会存在和发展的基础及决定力量", "C": "先进生产力的集中体现和主要标志", "D": "区分社会经济时代的客观依据"}, "answer": ["C"], "note": "科学技术是：先进生产力的集中体现和主要标志", "sourcePages": [13], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-94", "subject": "马原", "chapter": 3, "chapterTitle": "第三章人类社会及其发展规律", "type": "单选", "number": 94, "stem": "唯物史观就是“关于现实的人及其历史发展的科学”。只有把人看作现实的人，才能正确把握人的本质，把握人与社会历史的关系。人的本质是", "options": {"A": "从所有个体的人身上抽象出来的共同性", "B": "单个人天生就具有的东西", "C": "一切社会关系的总和", "D": "人的自然属性和社会属性的综合"}, "answer": ["C"], "note": "人的本质是：一切社会关系的总和", "sourcePages": [14], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-92", "subject": "马原", "chapter": 3, "chapterTitle": "第三章人类社会及其发展规律", "type": "多选", "number": 92, "stem": "社会意识既依赖于社会存在，又有其相对独立性。社会意识的相对独立性表现在", "options": {"A": "社会经济发展水平较高的国家或地区，其社会意识的发展水平未必都更高", "B": "社会意识对社会存在具有能动的反作用", "C": "“经济上落后的国家在哲学上仍然能够演奏第一提琴”", "D": "社会意识内部各种形式之间存在相互影响且各自具有历史继承性"}, "answer": ["A", "B", "C", "D"], "note": "社会意识的相对独立性表现在：社会经济发展水平较高的国家或地区，其社会意识的发展水平未必都更高；社会意识对社会存在具有能动的反作用；“经济上落后的国家在哲学上仍然能够演奏第一小提琴”；社会意识内部各种形式之间存在相互影响且各自具有历史继承性", "sourcePages": [42], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-97", "subject": "马原", "chapter": 3, "chapterTitle": "第三章人类社会及其发展规律", "type": "多选", "number": 97, "stem": "恩格斯说，国家“照例是最强大的、在经济上占统治地位的阶级的国家，这个阶级借助于国家而在政治上也成为占统治地位的阶级，因而获得了镇压和剥削被压迫阶级的新手段”。国家是", "options": {"A": "一个历史范畴", "B": "阶级矛盾不可调和的产物", "C": "社会存在的核心", "D": "一个阶级统治另一个阶级的工具"}, "answer": ["A", "B", "D"], "note": "国家是：一个历史范畴；阶级矛盾不可调和的产物；一个阶级统治另一个阶级的工具", "sourcePages": [43], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-104", "subject": "马原", "chapter": 3, "chapterTitle": "第三章人类社会及其发展规律", "type": "多选", "number": 104, "stem": "人类历史中的文明，不论是古代文明，还是近现代文明，都在不同民族那里有不同的表现。人类文明具有多样性，每一种文明都", "options": {"A": "是在特定的自然环境、历史背景、民族传统中生长起来的", "B": "体现着独特的生产、生活、交往方式", "C": "代表着一方文化的沃土和绿洲", "D": "是人类文明的重要组成部分"}, "answer": ["A", "B", "C", "D"], "note": "人类文明具有多样性，每一种文明都：是在特定的自然环境、历史背景、民族传统中生长起来的；体现着独特的生产、生活、交往方式；代表着一方文化的沃土和绿洲；是人类文明的重要组成部分", "sourcePages": [44], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-105", "subject": "马原", "chapter": 3, "chapterTitle": "第三章人类社会及其发展规律", "type": "多选", "number": 105, "stem": "发生在18世纪70年代以蒸汽机的发明为主要标志的科技革命，推动西欧国家相继完成了第一次产业革命，使资本主义生产迅速过渡到机器大工业，为资本主义生产方式的确立奠定了物质基础。发生在19世纪末20世纪初以电力的广泛运用为标志的科技革命，使电力取代蒸汽机成为新的动力，社会生产力又一次得到迅猛发展。20世纪中期以后出现的以原子能的利用、电子计算机和空间技术的发展，特别是以信息技术、新材料、新能源、生物工程、海洋工程等高科技的出现为主要标志的科技革命，使人类进入了互联网、智能化、数字化的时代，推动了由工业经济形态向信息社会或知识经济形态的过渡。当今时代，数字技术作为世界科技革命和产业变革的先导力量，日益融入经济社会发展各领域全过程。这说明科技革命", "options": {"A": "集中体现了科学技术在历史发展中的杠杆作用", "B": "会引起生产方式、生活方式和思维方式的深刻变化", "C": "最终必然导致生产关系的变革", "D": "已成为推动社会历史进步的根本动力"}, "answer": ["A", "B", "C"], "note": "科技革命：集中体现了科学技术在历史发展中的杠杆作用；会引起生产方式、生活方式和思维方式的深刻变化；最终必然导致生产关系的变革", "sourcePages": [44], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-107", "subject": "马原", "chapter": 3, "chapterTitle": "第三章人类社会及其发展规律", "type": "多选", "number": 107, "stem": "关于人的本质，马克思说，“在其现实性上，它是一切社会关系的总和”。其内涵有", "options": {"A": "人的本质是单个人所固有的抽象物", "B": "人的本质属性是社会属性", "C": "人的本质是自由", "D": "人的本质是变化发展的"}, "answer": ["B", "D"], "note": "人的本质，其内涵有：人的本质属性是社会属性；人的本质是变化发展的", "sourcePages": [44], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-108", "subject": "马原", "chapter": 3, "chapterTitle": "第三章人类社会及其发展规律", "type": "多选", "number": 108, "stem": "唯物史观就是“关于现实的人及其历史发展的科学”。只有把人看作现实的人，才能正确把握人的本质，把握人与社会历史的关系。现实的人是指", "options": {"A": "基于自身需要和社会需要而从事一定实践活动的人", "B": "处于一定社会关系中的人", "C": "具有能动性的人", "D": "生物学意义上的人"}, "answer": ["A", "B", "C"], "note": "现实的人是指：基于自身需要和社会需要而从事一定实践活动的人；处于一定社会关系中的人；具有能动性的人", "sourcePages": [44], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-109", "subject": "马原", "chapter": 3, "chapterTitle": "第三章人类社会及其发展规律", "type": "多选", "number": 109, "stem": "2025年《政府工作报告》提出，推动更多资金资源“投资于人”、服务于民生，支持扩大就业、促进居民增收减负、加强消费激励，形成经济发展和民生改善的良性循环。“投资于人”是相对于“投资于物”而言的，表明财政资源的导向要与人的需求直接挂钩，这既是满足人民对美好生活的需要，更是提高财政资金使用效率的必然要求。人的需求是随着经济发展阶段而变化的。随着经济发展水平提高，居民消费需求从生存型消费转向发展型消费；相应地，资金资源要从过去的“铁公基”等领域，越来越多地转到医疗、教育、养老、住房保障等与民生相关的发展型消费领域。“投资于人”这一政策导向的深刻现实与理论依据在于", "options": {"A": "人民群众是历史的创造者，“投资于人”是坚持以人民为中心的生动体现", "B": "劳动者是生产力中最活跃的因素，“投资于人”就是投资于未来生产力", "C": "人的物质欲望是社会发展的根本动力，必须将满足个体欲望作为资源配置的最高准则", "D": "人口因素是社会存在和发展的基础及决定力量， “投资于人”能决定整个社会历史的变化发展"}, "answer": ["A", "B"], "note": "“投资于人”这一政策导向的深刻现实与理论依据在于：人民群众是历史的创造者，“投资于人”是坚持以人民为中心的生动体现；劳动者是生产力中最活跃的因素，“投资于人”就是投资于未来生产力", "sourcePages": [45], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-104", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 104, "stem": "在商品交换过程中，生产商品使用价值的具体劳动是不能直接进行量的比较的，只有将具体劳动还原为抽象劳动，也就是从具体劳动中抽象出无差别的一般人类劳动，才能进行量的比较。具体劳动能否还原为抽象劳动，在根本上取决于", "options": {"A": "必要劳动和剩余劳动能否实现统一", "B": "简单劳动和复杂劳动能否实现统一", "C": "私人劳动和社会劳动能否实现统一", "D": "体力劳动和脑力劳动能否实现统一"}, "answer": ["C"], "note": "具体劳动能否还原为抽象劳动，在根本上取决于：私人劳动和社会劳动能否实现统一", "sourcePages": [16], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-105", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 105, "stem": "商品是劳动产品，生产商品的劳动具有二重性，即具体劳动和抽象劳动。具体劳动和抽象劳动是对立统一的关系，二者的区别体现在", "options": {"A": "具体劳动和抽象劳动是各自独立存在的两种劳动", "B": "具体劳动反映人与自然的关系，抽象劳动反映商品生产者的社会关系", "C": "具体劳动和抽象劳动必须在空间上并存、时间上继起", "D": "具体劳动创造商品的质，抽象劳动形成商品的量"}, "answer": ["B"], "note": "具体劳动和抽象劳动是对立统一的关系，二者的区别体现在：县体劳动反映人与自然的关系，抽象劳动反映商品生产者的社会关系", "sourcePages": [16], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-106", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 106, "stem": "在商品经济条件下，解决私人劳动和社会劳动之间矛盾的唯一途径是", "options": {"A": "按劳分配", "B": "扩大再生产", "C": "经济危机", "D": "商品交换"}, "answer": ["D"], "note": "在商品经济条件下，解决私人劳动和社会劳动之间矛盾的唯一途径是：商品交换", "sourcePages": [16], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-108", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 108, "stem": "生产商品所需要的社会必要劳动时间随着劳动生产率的变化而变化。劳动生产率是指", "options": {"A": "劳动者的劳动强度", "B": "劳动者生产使用价值的效率", "C": "劳动者生产剩余价值的效率", "D": "劳动在整个生产中所占的比例"}, "answer": ["B"], "note": "劳动生产率是指：劳动者生产使用价值的效率", "sourcePages": [16], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-112", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 112, "stem": "近年来，数字货币的概念越来越火热，引起了人们对货币本质的新一轮讨论。有专家指出，随着经济的发展和技术的进步，货币在发展过程中被不同的价值符号所代表，从金属货币、纸币、电子货币到数字货币不断转变。每种不同的货币形式代表了人们不同的信任形式。马克思主义认为，货币是", "options": {"A": "能够带来剩余价值的价值", "B": "资本的唯一物质形态", "C": "商品特有的社会属性", "D": "固定充当一般等价物的商品"}, "answer": ["D"], "note": "货币是：固定充当一般等价物的商品", "sourcePages": [16], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-113", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 113, "stem": "充当贮藏手段的货币", "options": {"A": "必须是现实的货币", "B": "可以是观念上的货币", "C": "必须是足值的金属货币", "D": "必须是现实的货币，但不一定是足值的货币"}, "answer": ["C"], "note": "充当贮藏手段的货币：必须是足值的金属货币", "sourcePages": [17], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-115", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 115, "stem": "商品的使用价值和价值的矛盾、生产商品的具体劳动和抽象劳动的矛盾，根源于", "options": {"A": "生产社会化和生产资料资本主义私人占有之间的矛盾", "B": "商品和货币的矛盾", "C": "简单劳动和复杂劳动的矛盾", "D": "私人劳动和社会劳动的矛盾"}, "answer": ["D"], "note": "商品的使用价值和价值的矛盾、生产商品的具体劳动和抽象劳动的矛盾，根源于：私人劳动和社会劳动的矛盾", "sourcePages": [17], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-116", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 116, "stem": "在以私有制为基础的商品经济中，商品生产者的劳动具有两重性：既是具有社会性质的社会劳动，又是具有私人性质的私人劳动。商品生产者的劳动的社会性质是由", "options": {"A": "生产者的阶级地位决定的", "B": "社会分工决定的", "C": "生产资料所有制决定的", "D": "国家法律制度规定的"}, "answer": ["B"], "note": "商品生产者的劳动的社会性质是由：社会分工决定的", "sourcePages": [17], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-118", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 118, "stem": "在资本主义条件下，劳动是否是生产性的，取决于", "options": {"A": "劳动是生产物质产品还是提供服务", "B": "劳动能否为资本家带来剩余价值", "C": "具体劳动能否还原为抽象劳动", "D": "劳动力是否为社会生产发展所绝对需要"}, "answer": ["B"], "note": "在资本主义条件下，劳动是否是生产性的，取决于：劳动能否为资本家带来剩余价值", "sourcePages": [17], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-119", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 119, "stem": "商品经济是以交换为目的而进行生产的经济形式，它是一定社会历史条件的产物。以私有制为基础的商品经济的基本矛盾是", "options": {"A": "生产社会化和生产资料资本主义私人占有之间的矛盾", "B": "私人劳动和社会劳动的矛盾", "C": "无产阶级和资产阶级的矛盾", "D": "商品使用价值和价值之间的矛盾"}, "answer": ["B"], "note": "以私有制为基础的商品经济的基本矛盾是：私人劳动和社会劳动的矛盾", "sourcePages": [17], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-120", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 120, "stem": "商品经济的发展经历了简单商品经济与发达商品经济两个阶段，资本主义商品经济是商品经济的高级或发达形态。简单商品生产发展到资本主义商品生产的新阶段的标志是", "options": {"A": "货币的产生和存在", "B": "机器大工业代替工场手工业", "C": "劳动力成为商品", "D": "社会生产划分为两大部类"}, "answer": ["C"], "note": "简单商品生产发展到资本主义商品生产的新阶段的标志是：劳动力成为商品", "sourcePages": [17], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-121", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 121, "stem": "在资本总公式“G一W一G”中，W代表商品，G代表的不是一般意义上的货币，而是作为资本的货币，G'代表的是价值增殖后的货币。从形式上看，资本总公式与商品交换的原则是矛盾的。价值规律要求商品交换遵循等价交换原则，交换领域不能创造新价值，但资本总公式却表明，资本在流通中创造了新价值。理解这一矛盾的关键在于", "options": {"A": "价值规律", "B": "等价交换原则", "C": "劳动力成为商品", "D": "利润转化为平均利润"}, "answer": ["C"], "note": "价值规律要求商品交换遵循等价交换原则，交换领域不能创造新价值，但资本总公式“G一W一G”却表明，资本在流通中创造了新价值。理解这一矛盾的关键在于：劳动力成为商品", "sourcePages": [17], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-122", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 122, "stem": "马克思在《资本论》中写道：“实际上，在商品市场上同货币所有者对立的不是劳动，而是工人。”这说明资本家购买的是", "options": {"A": "工人的劳动", "B": "工人的人身自由", "C": "工人的劳动能力", "D": "工人的消费能力"}, "answer": ["C"], "note": "资本家购买的是：工人的劳动能力", "sourcePages": [18], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-123", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 123, "stem": "资本主义的生产过程具有二重性。其中，作为资本主义生产过程的主要方面的是", "options": {"A": "价值增殖过程", "B": "补偿劳动力的价值形成过程", "C": "资本家监督下的劳动过程", "D": "创造出满足人们某种需要的使用价值的过程"}, "answer": ["A"], "note": "资本主义的生产过程具有二重性其中，作为资本主义生产过程的主要方面的是：价值增殖过程", "sourcePages": [18], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-124", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 124, "stem": "在资本主义生产过程中，劳动力的价值是借助于", "options": {"A": "具体劳动转移到新产品中", "B": "抽象劳动转移到新产品中", "C": "具体劳动再生产出来而增殖", "D": "抽象劳动再生产出来而增殖"}, "answer": ["D"], "note": "在资本主义生产过程中，劳动力的价值是借助于：抽象劳动再生产出来而增殖", "sourcePages": [18], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-126", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 126, "stem": "与其他商品相比，劳动力商品价值的决定的一个重要特点是", "options": {"A": "由生产它所需要的社会必要劳动时间决定", "B": "可以还原为劳动者维持自己及其家属生存所必需的生活资料的价值", "C": "由劳动力市场的供求关系决定", "D": "劳动力价值的构成包含历史和道德的因素"}, "answer": ["D"], "note": "与其他商品相比，劳动力商品价值的决定的一个重要特点是：劳动力价值的构成包含历史和道德的因素", "sourcePages": [18], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-127", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 127, "stem": "在不同的国家或在同一国家的不同历史时期，劳动力价值的最低界限是有区别的。一旦劳动力价值降低到这个最低界限以下，劳动力就只能在萎缩的状态下维持。劳动力价值的最低界限是由", "options": {"A": "资本家主观的剥削意愿决定的", "B": "劳动者的最低劳动强度决定的", "C": "资本循环中能够维持生产的不变资本的价值决定的", "D": "生活上不可缺少的生活资料的价值决定的"}, "answer": ["D"], "note": "劳动力价值的最低界限是由：生活上不可缺少的生活资料的价值决定的", "sourcePages": [18], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-128", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 128, "stem": "在不同的剥削制度下，劳动者与生产资料的结合方式不同。在资本主义制度下，资本家与工人的关系是", "options": {"A": "掌握先进技术和生产资料的资本家对工人的完全占有", "B": "工人在丧失土地和生产资料之后不得不对资本家的人身依附", "C": "基于劳动者人身自由基础上的“平等”关系", "D": "基于资产阶级“社会契约论”基础上的私人占有关系"}, "answer": ["C"], "note": "在资本主义制度下，资本家与工人的关系是：基于劳动者人身自由基础上的“平等”关系", "sourcePages": [18], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-129", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 129, "stem": "马克思主义政治经济学是经济学上的一场深刻革命，它站在无产阶级立场，运用辩证唯物主义和历史唯物主义的科学方法，批判继承了英国古典政治经济学的合理成分，揭露了无产阶级与资产阶级之间阶级对立和斗争的经济根源，论证了资本主义必然灭亡和社会主义必然胜利的客观规律。马克思经济学说的核心内容和基石是", "options": {"A": "劳动二重性理论", "B": "商品二因素理论", "C": "剩余价值理论", "D": "资本有机构成理论"}, "answer": ["C"], "note": "马克思经济学说的核心内容和基石是：剩余价值理论", "sourcePages": [18], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-130", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 130, "stem": "资本主义生产过程不仅是生产使用价值的劳动过程，同时是生产剩余价值的价值增殖过程。价值增殖过程是剩余价值的生产过程，这是资本主义生产过程的主要方面。所谓价值增殖过程，是超过了一定点而延长了的价值形成过程，这里的“一定点”指的是雇佣工人", "options": {"A": "转移生产资料价值的时间", "B": "转移劳动力价值的时间", "C": "创造使用价值的时间", "D": "再生产自己劳动力价值的时间"}, "answer": ["D"], "note": "所谓价值增殖过程，是超过了一定点而延长了的价值形成过程，这里的“一定点”指的是雇佣工人：再生产自己劳动力价值的时间", "sourcePages": [18], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-132", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 132, "stem": "剩余价值产生的唯一源泉是", "options": {"A": "雇佣劳动者的剩余劳动", "B": "雇佣劳动者的必要劳动", "C": "雇佣劳动者的具体劳动", "D": "雇佣劳动者的抽象劳动"}, "answer": ["A"], "note": "剩余价值产生的唯一源泉是：雇佣劳动者的剩余劳动", "sourcePages": [19], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-133", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 133, "stem": "剩余价值率反映的是", "options": {"A": "预付资本的价值增殖程度", "B": "资本家对雇佣工人的剥削程度", "C": "固定资本的价值增殖程度", "D": "不变资本的价值增殖程度"}, "answer": ["B"], "note": "剩余价值率反映的是：资本家对雇佣工人的剥削程度", "sourcePages": [19], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-135", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 135, "stem": "资本在资本主义生产过程中采取生产资料和劳动力两种形态。马克思将资本划分为不变资本与可变资本的根据是", "options": {"A": "资本不同部分在剩余价值生产中的不同作用", "B": "资本不同部分在周转中的不同方式", "C": "资本在循环中的不同职能", "D": "资本不同部分的物质形态是否改变"}, "answer": ["A"], "note": "马克思将资本划分为不变资本与可变资本的根据是：资本不同部分在剩余价值生产中的不同作用", "sourcePages": [19], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-137", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 137, "stem": "马克思在谈到资本主义生产方式时指出：“生产剩余价值或赚钱，是这个生产方式的绝对规律。”生产剩余价值有两种基本方法：绝对剩余价值生产和相对剩余价值生产。资本家普遍获得相对剩余价值是", "options": {"A": "各个资本家普遍延长雇佣工人工作日的结果", "B": "各个资本家普遍提高雇佣工人劳动强度的结果", "C": "各个资本家追求超额剩余价值的结果", "D": "个别企业提高劳动生产率的结果"}, "answer": ["C"], "note": "资本家普遍获得相对剩余价值是：各个资本家追求超额剩余价值的结果", "sourcePages": [19], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-139", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 139, "stem": "马克思关于资本积累的学说深刻地阐明了资本主义制度必然灭亡的历史命运。资本积累是指", "options": {"A": "剩余价值的资本化", "B": "货币的资本化", "C": "资本集中", "D": "商品的资本化"}, "answer": ["A"], "note": "资本积累是指：剩余价值的资本化", "sourcePages": [19], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-140", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 140, "stem": "资本家为了进一步扩大和加强对工人的剥削和统治，不断地利用无偿占有的工人创造的剩余价值来扩大自已的资本规模，这就是资本积累的本质。马克思关于资本积累的学说认为，资本积累的源泉是", "options": {"A": "资本积聚和资本集中", "B": "工人创造的剩余价值", "C": "用暴力手段掠夺货币财富", "D": "资本主义扩大再生产"}, "answer": ["B"], "note": "资本积累的源泉是：工人创造的剩余价值", "sourcePages": [19, 20], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-141", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 141, "stem": "资本的价值构成是指", "options": {"A": "固定资本与流动资本这两部分资本价值之间的比例", "B": "货币资本与生产资本之间的比例", "C": "劳动力和劳动对象之间的比例", "D": "不变资本和可变资本这两部分资本价值之间的比例"}, "answer": ["D"], "note": "资本的价值构成是指：不变资本和可变资本这两部分资本价值之间的比例", "sourcePages": [20], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-143", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 143, "stem": "产业资本划分为货币资本、生产资本、商品资本的依据是资本各个部分", "options": {"A": "在价值增殖过程中的作用不同", "B": "价值周转的方式不同", "C": "存在的物质形态不同", "D": "在循环中执行的职能不同"}, "answer": ["D"], "note": "产业资本划分为货币资本、生产资本、商品资本的依据是资本各个部分：在循环中执行的职能不同", "sourcePages": [20], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-149", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 149, "stem": "在生产技术水平不断提高的条件下，随着资本积累的增长，必然伴随着资本的积聚和集中，使个别资本的规模日益增大。资本集中是指个别资本通过结合而形成较大的资本。资本集中最强有力的杠杆是", "options": {"A": "竞争和信用", "B": "投资和借贷", "C": "资本原始积累", "D": "生产自动化"}, "answer": ["A"], "note": "资本集中最强有力的杠杆是：竞争和信用", "sourcePages": [20], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-150", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 150, "stem": "资本主义再生产的特点是扩大再生产。资本家将获得剩余价值的一部分转化为资本，使生产在扩大的规模上重复进行，这就是资本主义扩大再生产。资本主义扩大再生产的源泉是", "options": {"A": "资本集中", "B": "资本积累", "C": "资本循环", "D": "资本周转"}, "answer": ["B"], "note": "资本主义扩大再生产的源泉是：资本积累", "sourcePages": [20], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-151", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 151, "stem": "资本家瓜分到剩余价值后，如果将其完全用于个人消费，则生产就在原有规模的基础上重复进行，这叫资本主义简单再生产。资本主义简单再生产，就其实质而言，是", "options": {"A": "劳动过程和价值形成过程的统一", "B": "劳动过程和价值增殖过程的统一", "C": "物质资料再生产与资本主义生产关系再生产的统一", "D": "再生产物质资料价值与转移劳动力价值的统一"}, "answer": ["C"], "note": "资本主义简单再生产，就其实质而言，是：物质资料再生产与资本主义生产关系再生产的统一", "sourcePages": [20], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-152", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 152, "stem": "社会生产是连续不断地进行的，这种连续不断重复的生产就是再生产。社会再生产的核心问题是", "options": {"A": "两大部类在总量上的比例问题", "B": "社会总产品的价值补偿和实物补偿问题", "C": "工资与剩余价值的分配问题", "D": "劳动过程和价值增殖过程的统一问题"}, "answer": ["B"], "note": "社会再生产的核心问题是：社会总产品的价值补偿和实物补偿问题", "sourcePages": [21], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-153", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 153, "stem": "恩格斯指出：“马克思一有机会就提醒读者注意，决不要把他所说的剩余价值同利润或资本赢利相混淆。”之所以不要把剩余价值同利润或资本赢利相混淆，是因为利润", "options": {"A": "与剩余价值无本质联系", "B": "掩盖了剩余价值与全部预付资本的关系", "C": "与剩余价值的来源不同", "D": "掩盖了剩余价值与可变资本的关系"}, "answer": ["D"], "note": "之所以不要把剩余价值同利润或资本赢利相混淆，是因为利润：掩盖了剩余价值与可变资本的关系", "sourcePages": [21], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-154", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 154, "stem": "利润平均化规律，反映了在瓜分剩余价值上，资本家之间虽然存在竞争和矛盾，但在加强对工人阶级的剥削以榨取更大量的剩余价值这一点上，资本家之间有着共同的阶级利益。平均利润的出现是", "options": {"A": "同一部门内不同企业之间竞争的结果", "B": "不同部门之间竞争的结果", "C": "国际上同类企业之间竞争的结果", "D": "不同行业之间工人联合斗争的结果"}, "answer": ["B"], "note": "平均利润的出现是：不同部门之间竞争的结果", "sourcePages": [21], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-155", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 155, "stem": "随着资本主义大工业的出现和发展，价值规律的实现形式也发生了变化，商品不再以价值而是以生产价格为基础进行交换。作为商品价值的转化形式，生产价格是", "options": {"A": "生产成本与平均利润之和", "B": "生产中实际耗费的不变资本和可变资本之和", "C": "商品价值与劳动力成本之和", "D": "所用资本与所费资本之和"}, "answer": ["A"], "note": "作为商品价值的转化形式，生产价格是：生产成本与平均利润之和", "sourcePages": [21], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-156", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 156, "stem": "在资本主义社会里，资本家雇佣工人进行劳动并支付相应的工资。资本主义工资的本质是", "options": {"A": "工人全部劳动的报酬", "B": "劳动力的价值或价格", "C": "资本家预付的不变资本的一部分", "D": "工人所创造的剩余价值的一部分"}, "answer": ["B"], "note": "资本主义工资的本质是：劳动力的价值或价格", "sourcePages": [21], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-158", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 158, "stem": "资本主义经济危机爆发的根本原因是资本主义的基本矛盾。经济危机的抽象的一般的可能性首先是由", "options": {"A": "社会的绝对的消费能力引起的", "B": "货币作为流通手段和支付手段引起的", "C": "商品价格和价值之间量的不一致引起的", "D": "社会总产品两大部类比例失衡引起的"}, "answer": ["B"], "note": "经济危机的抽象的一般的可能性首先是由：货币作为流通手段和支付手段引起的", "sourcePages": [21], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-159", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 159, "stem": "2025年10月，美国联邦政府时隔近7年再度“停摆”。随着联邦政府“停摆”持续，其对美国社会的影响已从政府系统蔓延至民众日常生活，多项公共服务陷入停滞，弱势群体首当其冲。在发达资本主义的美国出现的种种社会问题，从一个侧面反映了资本主义固有的、内在的基本矛盾，即", "options": {"A": "生产社会化和生产资料资本主义私人占有之间的矛盾", "B": "无产阶级与资产阶级之间的矛盾", "C": "个别企业内部生产的有组织性和整个社会生产的无政府状态之间的矛盾", "D": "生产无限扩大的趋势与劳动人民有支付能力的需求相对缩小的矛盾"}, "answer": ["A"], "note": "在发达资本主义的美国出现的种种社会问题，从一个侧面反映了资本主义固有的、内在的基本矛盾，即：生产社会化和生产资料资本主义私人占有之间的矛盾", "sourcePages": [21], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-160", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 160, "stem": "当前，百年变局加速演进，世界进入新的动荡变革期。近年来，国际金融市场动荡不安，世界经济复苏脆弱乏力。有分析指出，经济衰退与扩张交替出现，过去50年里每8年就发生一轮全球经济衰退，而每一次经济危机都会造成社会财富的巨大浪费。资本主义经济危机的本质特征是", "options": {"A": "虚拟经济脱离实体经济", "B": "社会生产结构严重失调", "C": "周期性爆发", "D": "生产相对过剩"}, "answer": ["D"], "note": "资本主义经济危机的本质特征是：生产相对过剩", "sourcePages": [21], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-161", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 161, "stem": "经济危机实际上是资本主义条件下以强制的方式解决社会再生产的实现问题的途径。资本主义经济危机具有周期性，这是由", "options": {"A": "社会资本再生产的周期性决定的", "B": "资本主义基本矛盾运动的阶段性决定的", "C": "工人运动进入低潮和重新高涨的周期运动决定的", "D": "货币资本、生产资本、商品资本三种职能形式在时间上的继起性决定的"}, "answer": ["B"], "note": "资本主义经济危机具有周期性，这是由：资本主义基本矛盾运动的阶段性决定的", "sourcePages": [22], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-162", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 162, "stem": "资本主义国家的对内职能，主要是", "options": {"A": "社会管理职能", "B": "政治统治的职能", "C": "管理通信、交通、水利等事业的职能", "D": "管理文教、卫生保健、社会福利等事业的职能"}, "answer": ["B"], "note": "资本主义国家的对内职能，主要是：政治统治的职能", "sourcePages": [22], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-163", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "单选", "number": 163, "stem": "据媒体报道，美国教育部下属机构国家教育统计中心网站曾经在“每日语录”一栏中引用毛泽东“对自己，‘学而不厌”；对人家，‘诲而不倦’”的名言，国家教育统计中心因此遭到猛烈击。有美国参议员出面表示，教育部必须解释为何引用“共产主义者”的话。该中心网站被迫删除毛泽东的这句话，换成了林肯的一个警句。美国如此“言论自由”的国家，容不下毛泽东的一句有关学习的语录，不仅显示了美国政治制度在世界多元文化面前的“小气”，也表明了资本主义国家的社会管理职能与政治统治职能的紧密联系。从根本上说，资本主义国家的社会管理职能是", "options": {"A": "与政治统治职能并重的", "B": "服务于政治统治职能的", "C": "高于政治统治职能的", "D": "政治统治职能的核心"}, "answer": ["B"], "note": "从根本上说，资本主义国家的社会管理职能是：服务于政治统治职能的", "sourcePages": [22], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-114", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "多选", "number": 114, "stem": "马克思指出：“资本主义生产方式占统治地位的社会财富，表现为‘庞大的商品堆积”，单个的商品表现为这种财富的元素形式。”商品是", "options": {"A": "用来交换的、能满足人们某种需要的劳动产品", "B": "使用价值和价值的矛盾统一体", "C": "价值和交换价值的矛盾统一体", "D": "伴随人类社会始终的"}, "answer": ["A", "B"], "note": "商品是：用来交换的能满足人们某种需要的劳动产品；使用价值和价值的矛盾统一体", "sourcePages": [46], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-116", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "多选", "number": 116, "stem": "以下正确反映商品使用价值、交换价值、价值之间关系的有", "options": {"A": "使用价值是交换价值的物质承担者", "B": "价值是交换价值的基础", "C": "使用价值是商品的价值实体", "D": "交换价值是价值的表现形式"}, "answer": ["A", "B", "D"], "note": "正确反映商品使用价值、交换价值、价值之间关系的有：使用价值是交换价值的物质承担者；价值是交换价值的基础；交换价值是价值的表现形式", "sourcePages": [46], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-118", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "多选", "number": 118, "stem": "生产商品所需要的社会必要劳动时间随着劳动生产率的变化而变化。劳动生产率的高低可以用", "options": {"A": "单位劳动时间内生产的商品数量来测量", "B": "单位劳动时间内劳动者所耗费的劳动量来测量", "C": "单位劳动时间内生产的价值总量来测量", "D": "单位商品中所耗费的劳动时间来测量"}, "answer": ["A", "D"], "note": "劳动生产率的高低可以用：单位劳动时间内生产的商品数量来测量；单位商品中所耗费的劳动时间来测量", "sourcePages": [46], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-119", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "多选", "number": 119, "stem": "劳动生产率指的是劳动者生产使用价值的效率。影响劳动生产率的主要因素有", "options": {"A": "劳动者的平均劳动熟练程度", "B": "科学技术的发展水平及其在生产中的应用程度", "C": "生产过程的社会结合", "D": "生产资料的规模和效能以及自然条件"}, "answer": ["A", "B", "C", "D"], "note": "影响劳动生产率的主要因素有：劳动者的平均劳动熟练程度；科学技术的发展水平及其在生产中的应用程度；生产过程的社会结合；生产资料的规模和效能以及自然条件", "sourcePages": [46], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-123", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "多选", "number": 123, "stem": "在市场上，不同的商品有不同的价格，同一种商品的价格也经常变动。实际上，在令人眼花缭乱的价格运动背后有一个规律在起着支配的作用，这就是价值规律。价值规律", "options": {"A": "既支配商品生产，又支配商品流通", "B": "是资本主义社会特有的经济规律", "C": "起作用的形式在一定条件下可以发生变化", "D": "是在市场配置资源的过程中体现它的客观要求和作用的"}, "answer": ["A", "C", "D"], "note": "价值规律：既支配商品生产，又支配商品流通；起作用的形式在一定条件下可以发生变化；是在市场配置资源的过程中体现它的客观要求和作用的", "sourcePages": [47], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-124", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "多选", "number": 124, "stem": "价值规律是商品经济的基本经济规律，它贯穿于商品经济的全部过程。价值规律的作用表现在", "options": {"A": "自发地调节生产资料和劳动力在社会各生产部门之间的分配比例", "B": "自发地调节雇佣工人与资本家之间的利益再分配", "C": "自发地刺激社会生产力的发展", "D": "自发地调节社会收入的分配"}, "answer": ["A", "C", "D"], "note": "价值规律的作用表现在：自发地调节生产资料和劳动力在社会各生产部门之间的分配比例；自发地刺激社会生产力的发展；自发地调节社会收入的分配", "sourcePages": [47], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-126", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "多选", "number": 126, "stem": "在以私有制为基础的商品经济中，商品生产者的劳动具有两重性：既是具有社会性质的社会劳动，又是具有私人性质的私人劳动。私人劳动和社会劳动的矛盾", "options": {"A": "构成私有制基础上商品经济的基本矛盾", "B": "决定着商品经济的本质及发展过程", "C": "是商品经济其他一切矛盾的基础", "D": "决定着商品生产者的命运"}, "answer": ["A", "B", "C", "D"], "note": "私人劳动和社会劳动的矛盾：构成私有制基础上商品经济的基本矛盾；决定着商品经济的本质及发展过程；是商品经济其他一切矛盾的基础；决定着商品生产者的命运", "sourcePages": [47], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-127", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "多选", "number": 127, "stem": "通过对商品关系的深刻分析，马克思阐明了商品的二因素和生产商品的劳动的二重性及其相互关系、价值的质和量的规定性及其变化规律、价值形式的发展和货币的起源、商品经济的基本矛盾和基本规律及其作用，形成了科学的劳动价值论。马克思劳动价值论的重大意义在于", "options": {"A": "首次提出了劳动创造价值的观点", "B": "揭示了私有制条件下商品经济的基本矛盾", "C": "为剩余价值论的创立奠定了基础", "D": "揭示了商品经济的一般规律，对理解社会主义市场经济具有指导意义"}, "answer": ["B", "C", "D"], "note": "马克思劳动价值论的重大意义在于：揭示了私有制条件下商品经济的基本矛盾；为剩余价值论的创立奠定了基础；揭示了商品经济的一般规律，对理解社会主义市场经济具有指导意义", "sourcePages": [47], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-128", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "多选", "number": 128, "stem": "马克思指出：“资本主义社会的经济结构是从封建社会的经济结构中产生的。后者的解体使前者的要素得到解放。”随着社会生产力的提高特别是封建社会后期商品经济的迅速发展，封建生产关系越来越成为生产力发展的障碍。资本主义萌芽于14世纪末15世纪初地中海沿岸的一些城市。资本主义产生的途径有", "options": {"A": "从小商品经济中分化出来", "B": "从商人和高利贷者转化而来", "C": "用暴力手段剥夺农民的土地", "D": "用暴力手段掠夺货币财富"}, "answer": ["A", "B"], "note": "资本主义产生的途径有：从小商品经济中分化出来；从商人和高利贷者转化而来", "sourcePages": [48], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-129", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "多选", "number": 129, "stem": "劳动力是特殊的商品。除了其自身独有的特点以外，劳动力商品与其他商品的共同点有", "options": {"A": "它们都具有使用价值和价值", "B": "它们的价值都是由工人在劳动过程中再生产出来的", "C": "它们都具有价值增殖的功能", "D": "它们都属于历史范畴"}, "answer": ["A", "D"], "note": "劳动力商品与其他商品的共同点有：它们都具有使用价值和价值；它们都属于历史范畴", "sourcePages": [48], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-134", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "多选", "number": 134, "stem": "在资本主义生产过程中，工人的劳动作为具体劳动的作用是", "options": {"A": "创造商品的使用价值", "B": "转移劳动力自身的价值", "C": "新创造劳动力自身的价值", "D": "转移生产资料的价值"}, "answer": ["A", "D"], "note": "在资本主义生产过程中，工人的劳动作为具体劳动的作用是：创造商品的使用价值；转移生产资料的价值", "sourcePages": [48], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-135", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "多选", "number": 135, "stem": "在资本主义条件下，资本家剥削剩余价值具有隐蔽性。马克思分析揭示了剩余价值的真正来源，阐明了资本的实质。以下选项中属于价值源泉的有", "options": {"A": "劳动力商品的使用价值", "B": "雇佣工人的劳动", "C": "全部预付资本中的流动资本部分", "D": "生产资料的价值"}, "answer": ["A", "B"], "note": "属于价值源泉的有：劳动力商品的使用价值；雇佣工人的劳动", "sourcePages": [48], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-139", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "多选", "number": 139, "stem": "在资本主义商品生产条件下，每个资本家总是力图不断改进技术，改善经营管理，提高劳动生产率。率先提高劳动生产率的企业", "options": {"A": "其个别劳动时间少于社会必要劳动时间", "B": "生产商品的个别价值低于社会价值", "C": "可以获得超额剩余价值", "D": "在商品交换时不受价值规律制约"}, "answer": ["A", "B", "C"], "note": "率先提高劳动生产率的企业：其个别劳动时间少于社会必要劳动时间；生产商品的个别价值低于社会价值；可以获得超额剩余价值", "sourcePages": [49], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-140", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "多选", "number": 140, "stem": "在资本主义商品生产的条件下，每个资本家总是力图不断改进技术，改善经营管理，从而获得超额剩余价值。各个资本家追求超额剩余价值的结果是", "options": {"A": "整个资本家阶级普遍获得相对剩余价值", "B": "劳动力商品的价值增加", "C": "全社会劳动生产率的提高", "D": "剩余劳动时间缩短"}, "answer": ["A", "C"], "note": "各个资本家追求超额剩余价值的结果是：整个资本家阶级普遍获得相对剩余价值；全社会劳动生产率的提高", "sourcePages": [49], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-141", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "多选", "number": 141, "stem": "第二次世界大战以后，资本主义生产中的自动化程度加强。自动化生产线的广泛使用，使直接从事生产操作的工人大大减少，甚至出现了少数所谓的“无人工厂”。这意味着，在生产自动化条件下", "options": {"A": "剩余价值生产所使用的生产工具更加先进", "B": "技术和科学成为独立的剩余价值源泉", "C": "资本的有机构成进一步降低", "D": "劳动的复杂程度和强度日益提高"}, "answer": ["A", "D"], "note": "在生产自动化条件下：：剩余价值生产所使用的生产工具更加先进；劳动的复杂程度和强度日益提高", "sourcePages": [49], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-142", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "多选", "number": 142, "stem": "马克思关于资本积累的学说是剩余价值理论的重要组成部分。资本积累是", "options": {"A": "资本主义扩大再生产的源泉", "B": "资本主义经济危机爆发的根本原因", "C": "社会财富占有两极分化的重要原因", "D": "资本主义社会失业现象产生的根源"}, "answer": ["A", "C", "D"], "note": "资本积累是：资本主义扩大再生产的源泉；社会财富占有两极分化的重要原因；资本主义社会失业现象产生的根源", "sourcePages": [49], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-143", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "多选", "number": 143, "stem": "把剩余价值转化为资本，或者说，剩余价值的资本化，就是资本积累。马克思关于资本积累的学说是剩余价值理论的重要组成部分，它", "options": {"A": "揭露了资本主义制度下贫富两极分化的原因", "B": "揭示了资本主义失业现象的本质", "C": "揭露和批判了商品拜物教观念", "D": "深刻地阐明了资本主义制度必然走向灭亡的历史命运"}, "answer": ["A", "B", "D"], "note": "马克思关于资本积累的学说是剩余价值理论的重要组成部分，它：揭露了资本主义制度下贫富两极分化的原因；揭示了资本主义失业现象的本质；深刻地阐明了资本主义制度必然走向灭亡的历史命运", "sourcePages": [49], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-144", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "多选", "number": 144, "stem": "资本积累的源泉是剩余价值，资本积累规模的大小取决于", "options": {"A": "资本家对工人的剥削程度", "B": "劳动生产率的高低", "C": "所用资本和所费资本之间的差额", "D": "资本家预付资本的大小"}, "answer": ["A", "B", "C", "D"], "note": "资本积累规模的大小取决于：资本家对工人的剥削程度；劳动生产率的高低；所用资本和所费资本之间的差额；资本家预付资本的大小", "sourcePages": [49], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-147", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "多选", "number": 147, "stem": "产业资本循环不断进行的基本前提条件是", "options": {"A": "三种职能形式在时间上继起", "B": "三种职能形式在空间上并存", "C": "商品资本循环顺利进行", "D": "生产资本循环顺利进行"}, "answer": ["A", "B"], "note": "产业资本循环不断进行的基本前提条件是：三种职能形式在时间上继起；三种职能形式在空间上并存", "sourcePages": [50], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-148", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "多选", "number": 148, "stem": "资本是在运动中增殖的，必须不断地、周而复始地循环，才能不断地带来剩余价值。这种周而复始、不断反复着的资本循环，就叫作资本的周转。影响资本周转快慢的因素有许多，关键的因素有", "options": {"A": "资本周转的时间", "B": "所用资本和所费资本之间的差额", "C": "生产资本的固定资本和流动资本的构成", "D": "资本家预付资本的大小"}, "answer": ["A", "C"], "note": "影响资本周转快慢的关键的因素有：资本周转的时间；生产资本的固定资本和流动资本的构成", "sourcePages": [50], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-153", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "多选", "number": 153, "stem": "资本主义生产的目的是获得利润。不同生产部门的资本家之间为了得到尽可能多的利润必然展开激烈的竞争从而导致利润平均化。平均利润形成后", "options": {"A": "商品价值就转化为生产价格", "B": "价值规律的实现形式发生了变化", "C": "生产价格不再随着商品价值的变化而变动", "D": "每一个部门获得的利润都等于该部门生产的剩余价值"}, "answer": ["A", "B"], "note": "平均利润形成后：商品价值就转化为生产价格；价值规律的实现形式发生了变化", "sourcePages": [50], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-154", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "多选", "number": 154, "stem": "马克思通过分析剩余价值的生产、积累、流通以及分配过程，揭示了剩余价值的运动规律及其作用，创立了剩余价值理论。剩余价值理论", "options": {"A": "深刻揭露了资本主义生产关系的剥削本质", "B": "阐明了资产阶级与无产阶级之间阶级斗争的经济根源", "C": "指出了无产阶级革命的历史必然性", "D": "是“理解政治经济学的枢纽”"}, "answer": ["A", "B", "C"], "note": "剩余价值理论：：深刻揭露了资本主义生产关系的剥削本质；阐明了资产阶级与无产阶级之间阶级斗争的经济根源；指出了无产阶级革命的历史必然性", "sourcePages": [51], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-156", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "多选", "number": 156, "stem": "资本主义国家法律制度的核心是宪法，资本主义宪法所依据的基本原则有", "options": {"A": "私有制原则", "B": "主权在民原则", "C": "分权制衡原则", "D": "人权原则"}, "answer": ["A", "B", "C", "D"], "note": "资本主义宪法所依据的基本原则有：私有制原则；主权在民原则；分权制衡原则；人权原则", "sourcePages": [51], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-157", "subject": "马原", "chapter": 4, "chapterTitle": "第四章资本主义的本质及其规律", "type": "多选", "number": 157, "stem": "资产阶级在长期的反对封建专制主义和宗教神学的斗争中逐步形成和发展起来的各种资产阶级的思想理论和观念，在资本主义国家产生之后由统治阶级根据自己政治统治的需要，形成了资本主义国家的意识形态。资本主义国家的意识形态", "options": {"A": "是全体社会成员的共同意识", "B": "大部分内容是没有阶级性的", "C": "为资本主义的经济基础服务", "D": "是资产阶级的阶级意识的集中体现"}, "answer": ["C", "D"], "note": "资本主义国家的意识形态：为资本主义的经济基础服务；是资产阶级的阶级意识的集中体现", "sourcePages": [51], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-164", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "单选", "number": 164, "stem": "列宁根据他所处时代的实践曾指出，资本主义发展到垄断资本主义，进而发展到帝国主义，便具有其基本特征。这些基本特征中，在经济生活中起决定作用的是", "options": {"A": "金融寡头", "B": "资本家国际垄断同盟", "C": "资本输出", "D": "垄断组织"}, "answer": ["D"], "note": "资本主义发展到垄断资本主义，进而发展到帝国主义，便具有其基本特征这些基本特征中，在经济生活中起决定作用的是：垄断组织", "sourcePages": [22], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-165", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "单选", "number": 165, "stem": "在资本主义的自由竞争中，在剩余价值规律、竞争规律和资本积累规律的作用下，必然引起生产集中和资本集中，生产集中和资本集中发展到一定阶段必然引起垄断，这是资本主义发展的客观规律。资本集中是指", "options": {"A": "国家政权和私人垄断资本融合在一起的过程", "B": "大资本吞并小资本，或由许多小资本合并而成大资本的过程", "C": "工业垄断资本和银行垄断资本融合在一起的过程", "D": "个别资本通过剩余价值的资本化来增大资本的总量"}, "answer": ["B"], "note": "资本集中是指：大资本吞并小资本，或由许多小资本合并而成大资本的过程", "sourcePages": [22], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-166", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "单选", "number": 166, "stem": "垄断是通过一定的垄断组织形式实现的。垄断组织是指在一个或几个经济部门中占据垄断地位的大企业联合。垄断组织的形式多种多样，而且在各个国家、各个时期也不同。尽管垄断组织的形式多种多样，且不断变化发展，但它们在本质上是一样的，都是", "options": {"A": "通过联合来操纵垄断价格以撰取高额垄断利润", "B": "通过签订各种协定阻止其他企业进入高利润行业", "C": "通过消除竞争达到独自占有市场的目的", "D": "通过兼并小企业以达到生产集中和资本集中的目的"}, "answer": ["A"], "note": "尽管垄断组织的形式多种多样，且不断变化发展，但在本质上是一样的，都是：通过联合来操纵垄断价格以援取高额垄断利润", "sourcePages": [22], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-168", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "单选", "number": 168, "stem": "金融寡头是指操纵国民经济命脉，并在实际上控制国家政权的少数垄断资本家或垄断资本家集团。金融寡头在经济领域中的统治主要是通过“参与制”实现的。所谓“参与制”是指金融寡头", "options": {"A": "通过把自己的代理人送进政府或议会来为其垄断统治服务", "B": "通过建立政策咨询机构等方式参与政府的政策制定", "C": "通过掌握一定数量的股票来层层控制企业", "D": "私人与国家共同投资开办合营企业"}, "answer": ["C"], "note": "所谓“参与制”是指金融寡头：通过掌握一定数量的股票来层层控制企业", "sourcePages": [23], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-169", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "单选", "number": 169, "stem": "垄断资本的实质在于获取垄断利润，垄断利润是垄断资本家凭借其在社会生产和流通中的垄断地位而获得的超过平均利润的高额利润。垄断利润的形成，关键在于", "options": {"A": "垄断组织能够把包罗万象的社会生产全部包下来", "B": "垄断消除了产生竞争的经济条件", "C": "垄断条件下的竞争采取的完全是非经济的手段", "D": "垄断组织在经济生活中起了决定性作用"}, "answer": ["D"], "note": "垄断利润的形成，关键在于：垄断组织在经济生活中起了决定性作用", "sourcePages": [23], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-170", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "单选", "number": 170, "stem": "第二次世界大战后，在所有发达资本主义国家，国家垄断资本主义无论在广度上还是在深度上都有了更迅速、更普遍的发展，国家干预深入到资本主义的生产、流通、分配和消费的各个环节。国家垄断资本主义尽管有各种不同的具体形式，其实质都是", "options": {"A": "国家政权取代私人垄断资本的一种新型垄断资本主义", "B": "国家运用财政政策、货币政策等经济手段，对社会总供求进行调节", "C": "私人垄断资本利用国家机器来为其发展服务的手段", "D": "国家与私人共有、合营企业"}, "answer": ["C"], "note": "国家垄断资本主义尽管有各种不同的具体形式，其实质都是：私人垄断资本利用国家机器来为其发展服务的手段", "sourcePages": [23], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-171", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "单选", "number": 171, "stem": "随着资本输出的不断增加和垄断资本势力范围的迅速扩大，各国之间的经济联系日益密切，同时，彼此间的竞争更为激烈，矛盾和冲突也更为突出。在这一背景下，各资本主义国家的垄断组织，通过订立协议建立起国际垄断资本的联盟，即国际垄断同盟，以便在世界范围形成垄断，并在经济上瓜分世界。当代国际垄断同盟的主要形式是", "options": {"A": "国家垄断资本主义的国际联盟", "B": "国际卡特尔", "C": "国际托拉斯", "D": "国际康采恩"}, "answer": ["A"], "note": "当代国际垄断同盟的主要形式是：国家垄断资本主义的国际联盟", "sourcePages": [23], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-172", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "单选", "number": 172, "stem": "经济全球化是当代世界经济的重要特征之一，也是世界经济发展的重要趋势。为经济全球化提供了坚实的物质基础和根本的推动力的是", "options": {"A": "科学技术的进步和生产力的发展", "B": "跨国公司在全球范围内的迅速发展", "C": "各国经济体制的变革和国际经济组织的发展", "D": "金融自由化与金融创新"}, "answer": ["A"], "note": "为经济全球化提供了坚实的物质基础和根本的推动力的是：科学技术的进步和生产力的发展", "sourcePages": [23], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-174", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "单选", "number": 174, "stem": "进入21世纪以来，随着经济全球化的深入发展，新一轮科技革命和产业变革进入空前密集活跃期，社会化大生产在世界范围内更大规模、更广范围、更深层次展开，世界格局深度调整，资本主义呈现出一些新变化、新特征。当代资本主义最突出、最鲜明、最主要的特征是", "options": {"A": "社会阶级层级结构呈现复杂性、多样化", "B": "科技创新加速资本主义生产方式变化", "C": "国际金融资本的垄断", "D": "发达资本主义国家在世界范围内推行霸权主义和强权政治"}, "answer": ["C"], "note": "当代资本主义最突出、最鲜明、最主要的特征是：国际金融资本的垄断", "sourcePages": [24], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-160", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "多选", "number": 160, "stem": "垄断条件下的竞争同自由竞争相比，具有的新特点包括", "options": {"A": "目的是获得更多利润或超额利润，不断扩大资本的积累", "B": "除了采取各种形式的经济手段外，还采取非经济的手段", "C": "不仅在国内市场上进行竞争，国际市场上的竞争也越来越激烈", "D": "不仅经济领域的竞争多种多样，而且还扩大到经济领域以外"}, "answer": ["B", "C", "D"], "note": "垄断条件下的竞争同自由竞争相比，具有的新特点包括：除了采取各种形式的经济手段外，还采取非经济的手段；不仅在国内市场上进行竞争，国际市场上的竞争也越来越激烈；不仅经济领域的竞争多种多样，而且还扩大到经济领域以外", "sourcePages": [51], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-162", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "多选", "number": 162, "stem": "金融资本是由工业垄断资本和银行垄断资本融合在一起而形成的一种垄断资本。金融资本形成的主要途径包括", "options": {"A": "金融联系", "B": "资本参与", "C": "行政干预", "D": "人事参与"}, "answer": ["A", "B", "D"], "note": "金融资本形成的主要途径包括：金融联系；资本参与；人事参与", "sourcePages": [52], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-163", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "多选", "number": 163, "stem": "垄断资本所获得的高额利润，归根到底来自无产阶级和其他劳动人民所创造的剩余价值，具体来说，垄断利润的来源包括", "options": {"A": "加强对本国无产阶级和其他劳动人民的剥削", "B": "通过控制市场获得一些其他企业特别是非垄断企业的利润", "C": "加强对其他国家劳动人民的剥削和掠夺", "D": "通过资本主义国家政权进行有利于垄断资本的再分配"}, "answer": ["A", "B", "C", "D"], "note": "垄断利润的来源包括：加强对本国无产阶级和其他劳动人民的剥削；通过控制市场获得一些其他企业特别是非垄断企业的利润；加强对其他国家劳动人民的剥削和掠夺；通过资本主义国家政权进行有利于垄断资本的再分配", "sourcePages": [52], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-167", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "多选", "number": 167, "stem": "国家垄断资本主义的主要形式有", "options": {"A": "国家所有并直接经营企业", "B": "国家与私人共有、合营企业", "C": "国家通过多种形式参与私人垄断资本的再生产过程", "D": "宏观调节和微观规制"}, "answer": ["A", "B", "C", "D"], "note": "国家垄断资本主义的主要形式有：国家所有并直接经营企业；国家与私人共有、合营企业；国家通过多种形式参与私人垄断资本的再生产过程；宏观调节和微观规制", "sourcePages": [52], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-168", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "多选", "number": 168, "stem": "国家垄断资本主义是国家政权和私人垄断资本融合在一起的垄断资本主义。第二次世界大战后，在所有发达资本主义国家，国家垄断资本主义无论在广度上还是深度上都有了更迅速、更普遍的发展。国家通过多种形式参与私人垄断资本的再生产过程是国家垄断资本主义的主要形式之一，其方式主要包括", "options": {"A": "国家运用财政政策、货币政策等经济手段，对社会总供给和总需求进行调节", "B": "国家向私人垄断企业大量订货，为私人垄断企业提供有保证的国家市场", "C": "国家通过各种形式的津贴和补助，直接、间接地资助私人垄断企业", "D": "国家通过社会福利开支扩大消费需求，为私人垄断企业创造市场条件"}, "answer": ["B", "C", "D"], "note": "国家通过多种形式参与私人垄断资本的再生产过程是国家垄断资本主义的主要形式之一，其方式主要包括：国家向私人垄断企业大量订货，为私人垄断企业提供有保证的国家市场；国家通过各种形式的津贴和补助，直接、间接地资助私人垄断企业；国家通过社会福利开支扩大消费需求，为私人垄断企业创造市场条件", "sourcePages": [52], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-170", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "多选", "number": 170, "stem": "垄断资本在国内建立了垄断统治后，必然要把其统治势力扩展到国外，建立国际垄断统治。垄断资本向世界范围扩展的基本形式有", "options": {"A": "技术资本输出", "B": "借贷资本输出", "C": "生产资本输出", "D": "商品资本输出"}, "answer": ["B", "C", "D"], "note": "垄断资本向世界范围扩展的基本形式有：借贷资本输出、生产资本输出、商品资本输出", "sourcePages": [53], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-171", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "多选", "number": 171, "stem": "垄断资本在国内建立了垄断统治后，必然要把其统治势力扩展到国外，建立国际垄断统治。垄断资本向世界范围扩展的主要经济动因是", "options": {"A": "将国内过剩的资本输出，以便在国外谋求高额利润", "B": "将部分非要害的技术转移到国外，以取得在别国的垄断优势", "C": "争夺商品销售市场，确保原材料和能源的可靠来源", "D": "转移经济危机风险，化解生产社会化与生产资料资本主义私人占有之间的矛盾"}, "answer": ["A", "B", "C"], "note": "垄断资本向世界范围扩展的主要经济动因是：将国内过剩的资本输出，以便在国外谋求高额利润；将部分非要害的技术转移到国外，以取得在别国的垄断优势；争夺商品销售市场，确保原材料和能源的可靠来源", "sourcePages": [53], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-173", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "多选", "number": 173, "stem": "导致经济全球化迅猛发展的因素主要有", "options": {"A": "科学技术的进步和生产力的发展", "B": "跨国公司的发展", "C": "各国经济体制的变革和国际经济组织的发展", "D": "发展中国家的斗争"}, "answer": ["A", "B", "C"], "note": "导致经济全球化迅猛发展的因素主要有：科学技术的进步和生产力的发展；跨国公司的发展；各国经济体制的变革和国际经济组织的发展", "sourcePages": [53], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-176", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "多选", "number": 176, "stem": "第二次世界大战后，资本主义生产资料所有制发生了新的变化，国家资本所有制形成并发挥重要作用。国家资本所有制", "options": {"A": "取代法人资本所有制成为居主导地位的资本所有制形式", "B": "主要存在于基础设施和公共事业部门", "C": "对整个社会经济的发展有着重要的影响", "D": "体现着总资本家剥削雇佣劳动者的关系"}, "answer": ["B", "C", "D"], "note": "国家资本所有制：主要存在于基础设施和公共事业部门；对整个社会经济的发展有着重要的影响；体现着总资本家剥削雇佣劳动者的关系", "sourcePages": [54], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-177", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "多选", "number": 177, "stem": "第二次世界大战后，资本主义生产资料所有制发生了新的变化，法人资本所有制崛起并成为居主导地位的资本所有制形式。法人资本所有制", "options": {"A": "主要存在于当代资本主义经济生活中居支配地位的巨型公司中", "B": "主要特点是资本占有主体多元化，公司资本的所有权与控制权不再统一", "C": "在性质上是一种基于资本雇佣劳动的垄断资本集体所有制", "D": "体现了资本剥削雇佣劳动的关系"}, "answer": ["A", "C", "D"], "note": "法人资本所有制：主要存在于当代资本主义经济生活中居支配地位的巨型公司中；在性质上是一种基于资本雇佣劳动的垄断资本集体所有制；体现了资本剥削雇佣劳动的关系", "sourcePages": [54], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-178", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "多选", "number": 178, "stem": "第二次世界大战后资本主义国家在劳资关系和分配关系上出现的变化有", "options": {"A": "职工参与决策", "B": "终身雇佣、职工持股", "C": "建立并实施了普及化、全民化的社会福利制度", "D": "建立职工选举管理者制度"}, "answer": ["A", "B", "C"], "note": "第二次世界大战后资本主义国家在劳资关系和分配关系上出现的变化有：职工参与决策；终身雇佣、职工持股；建立并实施了普及化、全民化的社会福利制度", "sourcePages": [54], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-179", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "多选", "number": 179, "stem": "第二次世界大战后，资本主义国家为尽快恢复国民经济，在继续发挥市场机制主导性作用的同时，开始对经济进行全面干预。但是，从20世纪70年代起，随着资本主义经济陷入滞胀和新自由主义思潮的泛滥，西方国家普遍走上强化市场调节、弱化政府干预的道路，即", "options": {"A": "通过国有企业私有化来提升经济竞争力", "B": "通过福利制度改革，减少政府的财政负担", "C": "通过政治制度多元化，扩大公民权利", "D": "通过放松对经济和金融的管制，释放经济活力"}, "answer": ["A", "B", "D"], "note": "从20世纪70年代起，西方国家普遍走上强化市场调节、弱化政府干预的道路，即：通过国有企业私有化来提升经济竞争力；通过福利制度改革，减少政府的财政负担；通过放松对经济和金融的管制，释放经济活力", "sourcePages": [54], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-180", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "多选", "number": 180, "stem": "从20世纪70年代起，随着资本主义经济陷入滞胀和新自由主义思潮的泛滥，西方国家普遍走上强化市场机制、弱化政府干预的道路。与此同时，经济危机呈现新的特点，包括", "options": {"A": "去工业化和产业空心化日趋严重", "B": "两极分化和社会对立加剧", "C": "周期性危机与结构性危机交织在一起", "D": "虚拟经济与实体经济严重脱节"}, "answer": ["A", "B", "C", "D"], "note": "经济危机呈现新的特点：去工业化和产业空心化日趋严重；两极分化和社会对立加剧；周期性危机与结构性危机交织在一起；虚拟经济与实体经济严重脱节", "sourcePages": [54], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-181", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "多选", "number": 181, "stem": "第二次世界大战后，由于多种社会因素的影响，资本主义发生了一系列变化。其中在政治制度上的变化有", "options": {"A": "政治制度出现多元化的趋势，公民权利有所扩大", "B": "通过建立政策咨询机构等方式允许民众直接参与政策的制定和执行", "C": "普遍加强了法治建设，以便协调社会各阶级、阶层的利益", "D": "改良主义政党在政治舞台上的影响日益扩大"}, "answer": ["A", "C", "D"], "note": "第二次世界大战后，资本主义在政治制度上的变化有：政治制度出现多元化的趋势，公民权利有所扩大；普遍加强了法治建设，以便协调社会各阶级、阶层的利益；改良主义政党在政治舞台上的影响日益扩大", "sourcePages": [54], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-184", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "多选", "number": 184, "stem": "进入21世纪以来，资本主义呈现出一些新变化、新特征，表现在", "options": {"A": "科技创新加速资本主义生产方式变化", "B": "国际金融垄断资本主义影响日益显现", "C": "社会阶级层级结构呈现复杂性、多样化", "D": "发达资本主义国家凭借经济、科技、文化传播等超级优势，在世界范围内推行霸权主义和强权政治"}, "answer": ["A", "B", "C", "D"], "note": "进入21世纪以来，资本主义呈现出一些新变化、新特征，表现在：科技创新加速资本主义生产方式变化；国际金融垄断资本主义影响日益显现；社会阶级层级结构呈现复杂性、多样化；发达资本主义国家凭借经济、科技、文化传播等超级优势，在世界范围内推行霸权主义和强权政治", "sourcePages": [55], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-185", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "多选", "number": 185, "stem": "进入21世纪以来，资本主义呈现出一些新变化、新特征。科技创新加速资本主义生产方式变化，这表现在", "options": {"A": "产业结构的调整", "B": "生产组织和劳动形式的变化", "C": "社会阶级层级结构呈现复杂性、多样化", "D": "新经济形态的出现"}, "answer": ["A", "B", "D"], "note": "进入21世纪以来，科技创新加速资本主义生产方式变化，这表现在：产业结构的调整；生产组织和劳动形式的变化；新经济形态的出现", "sourcePages": [55], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-186", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "多选", "number": 186, "stem": "进入21世纪以来，资本主义呈现出一些新变化、新特征。国际金融垄断资本主义影响日益显现，国际金融资本的垄断成为当代资本主义最突出、最鲜明、最主要的特征，这表现在", "options": {"A": "金融垄断寡头化", "B": "金融垄断国际化", "C": "经济虚拟化", "D": "产业空心化"}, "answer": ["A", "B", "C", "D"], "note": "国际金融资本的垄断成为当代资本主义最突出、最鲜明、最主要的特征，这表现在：金融垄断寡头化；金融垄断国际化；经济虚拟化；产业空心化", "sourcePages": [55], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-187", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "多选", "number": 187, "stem": "当前，百年变局加速演进，国际格局和国际体系深刻调整，全球治理体系深刻变革，国际力量对比正在发生近代以来最具革命性的变化，世界进入新的动荡变革期。资本主义社会问题加速积累，资本主义国家内部的矛盾和冲突日益明显，表现为", "options": {"A": "经济发展失调", "B": "政治体制失灵", "C": "社会融合机制失效", "D": "生态领域失控"}, "answer": ["A", "B", "C"], "note": "资本主义社会问题加速积累，资本主义国家内部的矛盾和冲突日益明显，表现为：经济发展失调；政治体制失灵；社会融合机制失效", "sourcePages": [55], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-189", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "多选", "number": 189, "stem": "长期以来，西方国家标榜民主并不遗余力地向外输出民主，但近年来移植西式民主的国家陷入动荡，西方国家本身也出现了某些治理危机，暴露出西式民主的弊端和局限，具体表现在", "options": {"A": "西式选举往往难以选贤", "B": "政党利益可能凌驾于国家利益之上", "C": "“民主陷阱”会阻碍国家治理", "D": "传统精英政治走向衰落"}, "answer": ["A", "B", "C", "D"], "note": "西式民主的端和局限，具体表现在：西式选举往往难以选贤；政党利益可能凌驾于国家利益之上；“民主陷阱”会阻碍国家治理；传统精英政治走向衰落", "sourcePages": [55], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-190", "subject": "马原", "chapter": 5, "chapterTitle": "第五章资本主义的发展及其趋势", "type": "多选", "number": 190, "stem": "资本积累的本质，就是资本家不断地利用无偿占有的工人创造的剩余价值来扩大自己的资本规模，从而进一步扩大和加强对工人的剥削和统治。资本的不断积累", "options": {"A": "必然提高生产的社会化程度", "B": "在客观上势必导致生产集中和资本集中", "C": "为否定资本主义制度自身准备了物质条件", "D": "必然不断增强资本家个人在管理中的地位和作用"}, "answer": ["A", "B", "C"], "note": "资本的不断积累：必然提高生产的社会化程度；在客观上势必导致生产集中和资本集中；为否定资本主义制度自身准备了物质条件", "sourcePages": [55], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-175", "subject": "马原", "chapter": 6, "chapterTitle": "第六章社会主义的发展及其规律", "type": "单选", "number": 175, "stem": "从空想社会主义诞生到《共产党宣言》问世，其间空想社会主义经历了330多年的发展历程。空想社会主义的开山之作是", "options": {"A": "《太阳城》", "B": "《乌托邦》", "C": "《自然法典》", "D": "《论法制或法律的原则》"}, "answer": ["B"], "note": "空想社会主义的开山之作是：《乌托邦》", "sourcePages": [24], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-176", "subject": "马原", "chapter": 6, "chapterTitle": "第六章社会主义的发展及其规律", "type": "单选", "number": 176, "stem": "从莫尔1516年发表《乌托邦》到现在，社会主义已经有500多年的历史了。社会主义发展史上的第一次历史性飞跃是指", "options": {"A": "19世纪中叶，社会主义从空想发展到科学", "B": "20世纪初，社会主义从理论发展到建立社会主义制度的实践", "C": "社会主义从一国实践发展到多国实践", "D": "20世纪70年代末开始的社会主义改革"}, "answer": ["A"], "note": "社会主义发展史上的第一次历史性飞跃是指：19世纪中叶，社会主义从空想发展到科学", "sourcePages": [24], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-177", "subject": "马原", "chapter": 6, "chapterTitle": "第六章社会主义的发展及其规律", "type": "单选", "number": 177, "stem": "空想社会主义的发展经历了三个阶段，其中成为科学社会主义的直接思想来源的是", "options": {"A": "16一17世纪的早期空想社会主义", "B": "18世纪的空想平均共产主义", "C": "19世纪初期批判的空想社会主义", "D": "20世纪的空想社会主义"}, "answer": ["C"], "note": "空想社会主义的发展经历了三个阶段，其中成为科学社会主义的直接思想来源的是：19世纪初期批判的空想社会主义", "sourcePages": [24], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-178", "subject": "马原", "chapter": 6, "chapterTitle": "第六章社会主义的发展及其规律", "type": "单选", "number": 178, "stem": "无产阶级夺取政权的第一次伟大尝试是", "options": {"A": "1848年欧洲革命", "B": "1864年国际工人协会（第一国际）的成立", "C": "1871年爆发的巴黎公社革命", "D": "1889年第二国际的诞生"}, "answer": ["C"], "note": "无产阶级夺取政权的第一次伟大尝试是：1871年爆发的巴黎公社革命", "sourcePages": [24], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-179", "subject": "马原", "chapter": 6, "chapterTitle": "第六章社会主义的发展及其规律", "type": "单选", "number": 179, "stem": "经济和政治发展的不平衡是资本主义的绝对规律，由此应当得出的结论是", "options": {"A": "无产阶级革命至少将在几个主要的资本主义国家同时发生", "B": "社会主义可能在经济文化相对落后的俄国首先取得胜利", "C": "社会主义可能首先在少数甚至在单独一个资本主义国家内获得胜利", "D": "社会主义可能在经济文化相对发达的国家首先取得胜利"}, "answer": ["C"], "note": "经济和政治发展的不平衡是资本主义的绝对规律，由此应当得出的结论是：社会主义可能首先在少数甚至在单独一个资本主义国家内获得胜利", "sourcePages": [24], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-180", "subject": "马原", "chapter": 6, "chapterTitle": "第六章社会主义的发展及其规律", "type": "单选", "number": 180, "stem": "1921年3月，俄共（布）召开十大，毅然决定从战时共产主义政策过渡到新经济政策。新经济政策的主要特征是", "options": {"A": "开展农业合作化", "B": "发展商品经济", "C": "优先发展重工业", "D": "多种经济成分并存"}, "answer": ["B"], "note": "新经济政策的主要特征是：发展商品经济", "sourcePages": [24], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-181", "subject": "马原", "chapter": 6, "chapterTitle": "第六章社会主义的发展及其规律", "type": "单选", "number": 181, "stem": "马克思、恩格斯在创立科学社会主义理论并用以指导国际工人运动的过程中，逐步形成了科学社会主义基本原则。这些原则在后来的社会主义革命和建设中得到了证实、丰富和发展。科学社会主义的核心命题是", "options": {"A": "无产阶级是最先进、最革命的阶级，肩负着推翻旧世界、建设新世界的历史使命", "B": "无产阶级政党是无产阶级的先锋队，社会主义事业必须始终坚持无产阶级政党的领导", "C": "共产主义是人类最美好的社会制度，实现共产主义是共产党人的最高理想", "D": "资本主义必然灭亡，社会主义必然胜利"}, "answer": ["D"], "note": "科学社会主义的核心命题是：资本主义必然灭亡，社会主义必然胜利", "sourcePages": [24], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-182", "subject": "马原", "chapter": 6, "chapterTitle": "第六章社会主义的发展及其规律", "type": "单选", "number": 182, "stem": "社会主义的发展道路必然呈现出多样性的特点。造成社会主义发展道路多样性的现实原因是", "options": {"A": "无产阶级政党自身成熟程度的不同", "B": "历史文化传统的差异性", "C": "时代和实践的不断发展", "D": "自然地理环境的影响"}, "answer": ["C"], "note": "造成社会主义发展道路多样性的现实原因是：时代和实践的不断发展", "sourcePages": [25], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-191", "subject": "马原", "chapter": 6, "chapterTitle": "第六章社会主义的发展及其规律", "type": "多选", "number": 191, "stem": "社会主义从空想发展到科学，是因为马克思、恩格斯在新的历史条件下创立了", "options": {"A": "唯物史观", "B": "剩余价值学说", "C": "无产阶级革命学说", "D": "无产阶级政党学说"}, "answer": ["A", "B"], "note": "社会主义从空想发展到科学，是因为马克思、恩格斯在新的历史条件下创立了：唯物史观；剩余价值学说", "sourcePages": [56], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-193", "subject": "马原", "chapter": 6, "chapterTitle": "第六章社会主义的发展及其规律", "type": "多选", "number": 193, "stem": "科学社会主义自产生之后，逐步与工人运动相结合，指导无产阶级政党的革命斗争，并在这个过程中不断完善和发展。1864年，国际工人协会（第一国际）应运而生。1871年巴黎公社革命爆发。巴黎公社革命", "options": {"A": "是第一国际精神的产儿", "B": "是无产阶级夺取政权的第一次伟大尝试", "C": "证明了社会主义革命可以首先在一个或者几个国家获得胜利", "D": "使社会主义从理想变为现实"}, "answer": ["A", "B"], "note": "巴黎公社革命：是第一国际精神的产儿；是无产阶级夺取政权的第一次伟大尝试", "sourcePages": [56], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-194", "subject": "马原", "chapter": 6, "chapterTitle": "第六章社会主义的发展及其规律", "type": "多选", "number": 194, "stem": "1848年欧洲革命后，资本主义在各国得到了迅速发展，无产阶级力量不断壮大。到19世纪50年代末60年代初，各国工人运动重新活跃起来，并表现出加强国际联系的愿望。1864年，国际工人协会（第一国际）应运而生。马克思是第一国际的灵魂。在马克思指导下，第一国际", "options": {"A": "大力支援各国的工人运动，支持反封建的民主运动和民族解放运动", "B": "促进了马克思主义的传播及其与国际工人运动的结合", "C": "初步确立了马克思主义在工人运动中的指导地位", "D": "发动并领导了巴黎公社革命"}, "answer": ["A", "B", "C"], "note": "在马克思指导下，第一国际：大力支援各国的工人运动，支持反封建的民主运动和民族解放运动：促进了马克思主义的传播及其与国际工人运动的结合；初步确立了马克思主义在工人运动中的指导地位", "sourcePages": [56], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-195", "subject": "马原", "chapter": 6, "chapterTitle": "第六章社会主义的发展及其规律", "type": "多选", "number": 195, "stem": "1871年爆发的巴黎公社革命，是无产阶级夺取政权的第一次伟大尝试。巴黎公社采取的用以防止国家机关工作人员由社会公仆变为社会主人的重要措施是", "options": {"A": "废除资产阶级议会制，建立苏维埃代表大会制度", "B": "建立无产阶级政党，发挥党的政治领导作用", "C": "规定所有公职人员无论职位高低，实行全面的选举制和撤换制", "D": "取消高薪制，规定任何工作人员年薪不得超过熟练工人的工薪水平"}, "answer": ["C", "D"], "note": "巴黎公社采取的用以防止国家机关工作人员由社会公仆变为社会主人的重要措施是规定所有公职人员无论职位高低，实行全面的选举制和撤换制；取消高薪制，规定任何工作人员年薪不得超过熟练工人的工薪水平", "sourcePages": [56], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-196", "subject": "马原", "chapter": 6, "chapterTitle": "第六章社会主义的发展及其规律", "type": "多选", "number": 196, "stem": "从1918年夏到1921年春，列宁领导的苏维埃政权实行了战时共产主义政策。这一政策的主要特征是", "options": {"A": "实行余粮收集制", "B": "实行粮食税制", "C": "取消商品货币关系", "D": "实行租让制"}, "answer": ["A", "C"], "note": "战时共产主义政策的主要特征是：实行余粮收集制；取消商品货币关系", "sourcePages": [56], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-199", "subject": "马原", "chapter": 6, "chapterTitle": "第六章社会主义的发展及其规律", "type": "多选", "number": 199, "stem": "1921年3月，俄共（布）召开十大，毅然决定从战时共产主义政策过渡到实行以发展商品经济为主要特征的新经济政策。新经济政策的实施", "options": {"A": "完成了农业合作化，在广大农村建立起了社会主义的制度基础", "B": "扭转了国家的严重危机，改善了工人、农民和其他劳动者的物质文化生活", "C": "活跃了苏维埃的城乡经济，发展了生产，大大加强了苏维埃的社会主义经济基础", "D": "标志着苏联模式开始形成"}, "answer": ["B", "C"], "note": "新经济政策的实施：扭转了国家的严重危机，改善了工人、农民和其他劳动者的物质文化生活；活跃了苏维埃的城乡经济，发展了生产，大大加强了苏维埃的社会主义经济基础", "sourcePages": [57], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-201", "subject": "马原", "chapter": 6, "chapterTitle": "第六章社会主义的发展及其规律", "type": "多选", "number": 201, "stem": "在俄国社会主义革命取得胜利的初期，特别是实行新经济政策期间，列宁对苏维埃俄国如何建设社会主义进行了深刻的理论思考，提出了许多精辟的论述。列宁对马克思主义的重大贡献，也是他留给后人的最宝贵的思想遗产是", "options": {"A": "能够正视国情，面对一系列新情况和新问题，不拘泥于书本上已有的结论，而是“根据经验来谈论社会主义”", "B": "一切从实际出发，尊重千百万群众的实践，勇于探索，大胆创新", "C": "努力把马克思主义基本原理同俄国的具体实际相结合，探索出一条适合俄国国情的社会主义道路", "D": "实现了工业化和农业集体化，形成了建设社会主义的苏联模式"}, "answer": ["A", "B", "C"], "note": "列宁对马克思主义的重大贡献，也是他留给后人的最宝贵的思想遗产是：能够正视国情，面对一系列新情况和新问题，不拘泥于书本上已有的结论，而是“根据经验来谈论社会主义”；一切从实际出发，尊重千百万群众的实践，勇于探索，大胆创新；努力把马克思主义基本原理同俄国的具体实际相结合，探索出一条适合俄国国情的社会主义道路", "sourcePages": [57], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-203", "subject": "马原", "chapter": 6, "chapterTitle": "第六章社会主义的发展及其规律", "type": "多选", "number": 203, "stem": "从16世纪初期兴起的社会主义思潮算起，社会主义运动至今已经有500多年的历史。社会主义是在曲折中发展、在开拓中前进的。站在新时代中国特色社会主义新的历史起点上，学习掌握科学社会主义基本原则，深入总结社会主义运动的历史经验，对于我们推进世界社会主义事业具有重要意义。科学社会主义基本原则", "options": {"A": "是社会主义事业发展规律的集中体现", "B": "是马克思主义政党领导人民进行社会主义革命、建设、改革的基本遵循", "C": "规定了各个国家的无产阶级政党与自己国家实际相结合的具体制度和革命方法", "D": "在后来的社会主义革命和建设中得到了证实、丰富和发展"}, "answer": ["A", "B", "D"], "note": "科学社会主义基本原则：是社会主义事业发展规律的集中体现；是马克思主义政党领导人民进行社会主义革命、建设、改革的基本遵循；在后来的社会主义革命和建设中得到了证实、丰富和发展", "sourcePages": [57], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-205", "subject": "马原", "chapter": 6, "chapterTitle": "第六章社会主义的发展及其规律", "type": "多选", "number": 205, "stem": "“由于历史进程的曲折而不得不开始社会主义革命的那个国家愈落后，它由旧的资本主义关系过渡到社会主义关系就愈困难。”列宁的这段话说明，无产阶级及其政党可以在经济文化相对落后的国家取得政权，建立起崭新的社会主义制度，但是，在这样的国家建设社会主义必然具有长期性。其原因主要有", "options": {"A": "生产力发展状况的制约", "B": "经济基础和上层建筑发展状况的制约", "C": "国际环境的严峻挑战", "D": "改良主义政党在政治舞台上的影响日益扩大"}, "answer": ["A", "B", "C"], "note": "无产阶级及其政党可以在经济文化相对落后的国家取得政权，建立起崭新的社会主义制度，但是，具有长期性，原因主要有：生产力发展状况的制约；经济基础和上层建筑发展状况的制约；国际环境的严峻挑战", "sourcePages": [58], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-206", "subject": "马原", "chapter": 6, "chapterTitle": "第六章社会主义的发展及其规律", "type": "多选", "number": 206, "stem": "“‘履不必同，期于适足；治不必同，期于利民。’世界上没有放之四海而皆准的发展道路。只有能够持续造福人民的发展道路，才是最有生命力的。”社会主义发展道路多样性的原因有", "options": {"A": "各国人口因素和自然地理环境的不同是造成社会主义发展道路多样性的决定因素", "B": "历史文化传统的差异性是造成不同国家社会主义发展道路多样性的重要条件", "C": "各国生产力发展状况和社会发展阶段决定了社会主义发展道路具有不同的特点", "D": "时代和实践的不断发展是造成社会主义发展道路多样性的现实原因"}, "answer": ["B", "C", "D"], "note": "社会主义发展道路多样性的原因有：历史文化传统的差异性是造成不同国家社会主义发展道路多样性的重要条件；各国生产力发展状况和社会发展阶段决定了社会主义发展道路具有不同的特点；时代和实践的不断发展是造成社会主义发展道路多样性的现实原因", "sourcePages": [58], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-183", "subject": "马原", "chapter": 7, "chapterTitle": "第七章共产主义最高理想及其最终实现", "type": "单选", "number": 183, "stem": "马克思主义与空想社会主义在展望未来社会的问题上的根本区别在于", "options": {"A": "是否坚持科学的立场观点方法", "B": "是否正确预见未来", "C": "是否提出未来社会的具体方案", "D": "是否批判资本主义旧世界"}, "answer": ["A"], "note": "马克思主义与空想社会主义在展望未来社会的问题上的根本区别在于：是否坚持科学的立场观点方法", "sourcePages": [25], "answerSource": "帽子题配套资料"}, {"id": "马原-单选-184", "subject": "马原", "chapter": 7, "chapterTitle": "第七章共产主义最高理想及其最终实现", "type": "单选", "number": 184, "stem": "共产主义是人类解放的实现。共产主义社会的根本特征是", "options": {"A": "物质财富极大丰富，消费资料按需分配", "B": "社会关系高度和谐", "C": "人们精神境界极大提高", "D": "实现人的自由而全面的发展"}, "answer": ["D"], "note": "共产主义社会的根本特征是：实现人的自由而全面的发展", "sourcePages": [25], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-210", "subject": "马原", "chapter": 7, "chapterTitle": "第七章共产主义最高理想及其最终实现", "type": "多选", "number": 210, "stem": "马克思、恩格斯关于未来社会的预测，是在科学地批判和剖析资本主义社会的过程中作出的。马克思、恩格斯对资本主义批判的高明之处在于", "options": {"A": "不是只看到资本主义社会的弊端，而是进一步揭示出弊端的根源和资本主义发展中自我否定的力量", "B": "发现资本主义的矛盾运动中孕育着的新社会因素，并以此对未来社会特点作出预见", "C": "既从资本主义社会中寻找灵感，更从社会主义社会的建设与发展中寻找启示", "D": "先指出未来社会的一般特征，再对各种细节作具体描绘"}, "answer": ["A", "B"], "note": "马克思、恩格斯对资本主义批判的高明之处在于：不是只看到资本主义社会的端，而是进一步揭示出整端的根源和资本主义发展中自我否定的力量；发现资本主义的矛盾运动中孕育着的新社会因素，并以此对未来社会特点作出预见", "sourcePages": [59], "answerSource": "配套资料与题目核对"}, {"id": "马原-多选-211", "subject": "马原", "chapter": 7, "chapterTitle": "第七章共产主义最高理想及其最终实现", "type": "多选", "number": 211, "stem": "实现人的自由而全面的发展，是马克思主义追求的根本价值目标，也是共产主义社会的根本特征。共产主义社会中人的自由而全面的发展指的是", "options": {"A": "全体社会成员的发展，即每一个人的发展", "B": "社会不存在矛盾，人与人之间形成事实上的平等", "C": "社会发展与个人发展实现了真正的统一", "D": "社会发展不再以牺牲某些个人的发展为代价"}, "answer": ["A", "C", "D"], "note": "共产主义社会中人的自由而全面的发展指的是：全体社会成员的发展，即每一个人的发展；社会发展与个人发展实现了真正的统一；社会发展不再以牺牲某些个人的发展为代价", "sourcePages": [59], "answerSource": "帽子题配套资料"}, {"id": "马原-多选-212", "subject": "马原", "chapter": 7, "chapterTitle": "第七章共产主义最高理想及其最终实现", "type": "多选", "number": 212, "stem": "1894年，恩格斯在回答意大利人卡内帕提出的要求尽量用简短的字句来表述未来的社会主义纪元的基本思想时指出，除了从《共产党宣言》中摘出下面一段话外，再也找不出合适的了，这就是：“代替那存在着阶级和阶级对立的资产阶级旧社会的，将是这样一个联合体，在那里，每个人的自由发展是一切人的自由发展的条件。”这里所说的自由发展是指", "options": {"A": "建立在个体高度自由自觉基础上的全面发展", "B": "实现了人的“自由个性”的发展", "C": "摆脱了自然经济条件下对“人的依赖关系”和商品经济条件下对“物的依赖性”", "D": "随心所欲、不受任何限制的发展"}, "answer": ["A", "B", "C"], "note": "“每个人的自由发展是一切人的自由发展的条件”自由发展是指：建立在个体高度自由自觉基础上的全面发展；实现了人的“自由个性”的发展；摆脱了自然经济条件下对“人的依赖关系”和商品经济条件下对“物的依赖性”", "sourcePages": [59], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-1", "subject": "毛中特", "chapter": 0, "chapterTitle": "导论", "type": "单选", "number": 1, "stem": "中国共产党的历史，是一部不断推进马克思主义中国化时代化的历史，是一部不断推进理论创新、进行理论创造的历史。标志着“马克思主义的中国化”这一命题正式提出的是", "options": {"A": "遵义会议", "B": "党的六届六中全会", "C": "瓦窑堡会议", "D": "党的七大"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [65], "answerSource": "待核对"}, {"id": "毛中特-单选-2", "subject": "毛中特", "chapter": 0, "chapterTitle": "导论", "type": "单选", "number": 2, "stem": "马克思主义中国化时代化的理论成果是一脉相承又与时俱进的关系。它们都是\n\n①关于中国革命、建设、改革的正确的理论原则和经验总结\n\n②马克思列宁主义在中国的运用和发展\n\n③全国各族人民团结奋斗的共同思想基础\n\n④党和国家必须长期坚持的指导思想", "options": {"A": "①②③", "B": "①②④", "C": "①③④", "D": "②③④"}, "answer": ["D"], "note": "马克思主义中国化时代化的理论成果是一脉相承又与时俱进的关系。它们都是：马克思列宁主义在中国的运用和发展、全国各族人民团结奋斗的共同思想基础、党和国家必须长期坚持的指导思想", "sourcePages": [65], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-1", "subject": "毛中特", "chapter": 0, "chapterTitle": "导论", "type": "多选", "number": 1, "stem": "1938年，毛泽东在党的六届六中全会上所作的《论新阶段》的政治报告中最先提出了“马克思主义的中国化”这个命题。这是党首次明确提出“马克思主义的中国化”的重大命题。既然马克思主义是科学的理论，是当时中国人选择的救国救民的真理，那么按他的理论照着做就行了，为什么还要提出马克思主义中国化时代化呢？这是因为找到了马克思主义这个崭新的思想武器，并不意味着就能够自然而然地解决中国革命所面临的问题。推进马克思主义中国化时代化", "options": {"A": "是马克思主义理论本身发展的内在要求", "B": "是解决中国实际问题和时代问题的客观需要", "C": "才能真正解决教条主义和经验主义的问题", "D": "才能找到放之四海而皆准的革命和建设模式"}, "answer": ["A", "B", "C"], "note": "推进马克思主义中国化：是马克思主义理论本身发展的内在要求；是解决中国实际问题的客观需要；才能真正解决教条主义和经验主义的问题", "sourcePages": [72], "answerSource": "配套资料与题目核对"}, {"id": "毛中特-单选-3", "subject": "毛中特", "chapter": 1, "chapterTitle": "第一章毛泽东思想及其历史地位", "type": "单选", "number": 3, "stem": "毛泽东思想是在我国新民主主义革命、社会主义革命和社会主义建设的实践过程中，在总结我国革命和建设正反两方面历史经验的基础上，逐步形成和发展起来的。标志着毛泽东思想开始萌芽的是", "options": {"A": "关于新民主主义革命基本思想的提出", "B": "关于农村包围城市、武装夺取政权的思想的提出", "C": "反对本本主义的提出", "D": "马克思主义中国化命题的明确提出"}, "answer": ["A"], "note": "标志着毛泽东思想开始萌芽的是：关于新民主主义革命基本思想的提出", "sourcePages": [65], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-4", "subject": "毛中特", "chapter": 1, "chapterTitle": "第一章毛泽东思想及其历史地位", "type": "单选", "number": 4, "stem": "毛泽东思想是在总结我国革命和建设正反两方面历史经验的基础上，逐步形成和发展起来的。毛泽东思想初步形成的标志是提出并深入阐述", "options": {"A": "实事求是的思想路线", "B": "农村包围城市、武装夺取政权的思想", "C": "新民主主义理论", "D": "中国革命的首要问题"}, "answer": ["B"], "note": "毛泽东思想初步形成的标志是提出并深入阐述：农村包围城市、武装夺取政权的思想", "sourcePages": [65], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-5", "subject": "毛中特", "chapter": 1, "chapterTitle": "第一章毛泽东思想及其历史地位", "type": "单选", "number": 5, "stem": "毛泽东思想是马克思主义中国化时代化第一次历史性飞跃的理论成果，以独创性的理论丰富和发展了马克思列宁主义。最能体现毛泽东思想理论本质特点的思想内容是", "options": {"A": "贯穿于毛泽东思想科学体系中的立场、观点和方法", "B": "毛泽东思想在表达方式上具有的鲜明民族特色", "C": "毛泽东思想所确立的马克思主义中国化时代化的前进方向", "D": "全心全意为人民服务的根本宗旨和自力更生、艰苦奋斗的革命精神"}, "answer": ["A"], "note": "最能体现毛泽东思想理论本质特点的思想内容是贯穿于毛泽东思想科学体系中的立场、观点和方法", "sourcePages": [65], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-6", "subject": "毛中特", "chapter": 1, "chapterTitle": "第一章毛泽东思想及其历史地位", "type": "单选", "number": 6, "stem": "毛泽东思想不是在个别的方面，而是在许多方面以其独创性理论丰富和发展了马克思列宁主义，构成一个博大精深的科学思想体系。它紧紧围绕的主题是", "options": {"A": "战争与革命", "B": "什么是社会主义、怎样建设社会主义", "C": "中国特色社会主义", "D": "中国革命和建设"}, "answer": ["D"], "note": "毛泽东思想紧紧围绕的主题是：中国革命和建设", "sourcePages": [66], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-7", "subject": "毛中特", "chapter": 1, "chapterTitle": "第一章毛泽东思想及其历史地位", "type": "单选", "number": 7, "stem": "独立自主是毛泽东思想的活的灵魂三个基本方面的内容之一。坚持独立自主也是中国共产党百年奋斗的十大历史经验之一。独立自主是", "options": {"A": "中华民族精神之魂", "B": "中国共产党的最大政治优势", "C": "一个国家、一个民族发展进步的不竭动力", "D": "中国共产党区别于其他政党的显著标志"}, "answer": ["A"], "note": "独立自主是：中华民族精神之魂", "sourcePages": [66], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-8", "subject": "毛中特", "chapter": 1, "chapterTitle": "第一章毛泽东思想及其历史地位", "type": "单选", "number": 8, "stem": "独立自主是中国共产党、中华人民共和国立党立国的重要原则，是我们党从中国实际出发、依靠党和人民力量进行革命、建设、改革的必然结论。毛泽东独立自主思想最初的明确表述来自", "options": {"A": "《星星之火，可以燎原》", "B": "《反对本本主义》", "C": "《中国社会各阶级的分析》", "D": "《湖南农民运动考察报告》"}, "answer": ["B"], "note": "毛泽东独立自主思想最初的明确表述来自：《反对本本主义》", "sourcePages": [66], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-3", "subject": "毛中特", "chapter": 1, "chapterTitle": "第一章毛泽东思想及其历史地位", "type": "多选", "number": 3, "stem": "大革命时期，毛泽东关于新民主主义革命的基本思想的提出，标志着毛泽东思想开始萌芽。毛泽东关于新民主主义革命的基本思想的内容是", "options": {"A": "分析了中国社会各阶级在革命中的地位和作用", "B": "明确指出无产阶级领导农民斗争的极端重要性", "C": "解决了无产阶级领导权的中心问题，即如何领导农民斗争的问题", "D": "提出了“工农武装割据”的思想"}, "answer": ["A", "B", "C"], "note": "毛泽东关于新民主主义革命的基本思想的内容是：分析了中国社会各阶级在革命中的地位和作用；明确指出无产阶级领导农民斗争的极端重要性；解决了无产阶级领导权的中心问题，即如何领导农民斗争的问题", "sourcePages": [72], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-5", "subject": "毛中特", "chapter": 1, "chapterTitle": "第一章毛泽东思想及其历史地位", "type": "多选", "number": 5, "stem": "新中国成立的开国大典前，围绕军乐团演奏什么曲目，一度众说纷坛，提议用德国乐曲、苏联乐曲、美国乐曲的意见都有。最终，毛泽东拍板：要听自己的乐曲，走自己的路。走自己的路，也就是独立自主。独立自主是毛泽东思想活的灵魂的三个基本方面的内容之一，是", "options": {"A": "中华民族的优良传统", "B": "中国共产党、中华人民共和国立党立国的重要原则", "C": "党从中国实际出发、依靠党和人民力量进行革命、建设、改革的必然结论", "D": "党的生命线和根本工作路线"}, "answer": ["A", "B", "C"], "note": "独立自主是：中华民族的优良传统；中国共产党、中华人民共和国立党立国的重要原则；党从中国实际出发、依靠党和人民力量进行革命、建设、改革的必然结论", "sourcePages": [73], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-6", "subject": "毛中特", "chapter": 1, "chapterTitle": "第一章毛泽东思想及其历史地位", "type": "多选", "number": 6, "stem": "邓小平在谈到毛泽东思想的时候指出：“这个思想，从历史上证明了是好的。中国的革命，不是由别的思想引导到胜利的，而是由毛泽东思想引导到胜利的。革命胜利以后，也正是在毛泽东思想的指导下，我们的社会主义建设才获得了这样伟大的成就，并且继续胜利地前进着。”毛泽东思想是", "options": {"A": "马克思主义中国化时代化的第一个重大理论成果", "B": "中国革命和建设的科学指南", "C": "中国共产党和中国人民宝贵的精神财富", "D": "党必须长期坚持的指导思想"}, "answer": ["A", "B", "C", "D"], "note": "毛泽东思想是：马克思主义中国化时代化的第一个重大理论成果；中国革命和建设的科学指南；中国共产党和中国人民宝贵的精神财富；党必须长期坚持的指导思想", "sourcePages": [73], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-9", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "单选", "number": 9, "stem": "认清中国国情，是解决中国革命问题的基本前提。近代中国最基本的国情是", "options": {"A": "中国是一个半殖民地半封建的社会", "B": "中国的政治经济发展不平衡", "C": "中国是东方的大国", "D": "中国是一个农民占人口多数的国家"}, "answer": ["A"], "note": "近代中国最基本的国情是：中国是一个半殖民地半封建的社会", "sourcePages": [66], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-11", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "单选", "number": 11, "stem": "解放战争时期，毛泽东在《在晋绥干部会议上的讲话》中对新民主主义革命的总路线作了完整的概括。这里所说的“完整”是指在革命对象中增加了", "options": {"A": "帝国主义", "B": "封建主义", "C": "民族资本主义", "D": "官僚资本主义"}, "answer": ["D"], "note": "毛泽东在《在晋绥干部会议上的讲话》中对新民主主义革命的总路线作了完整的概括。这里所说的“完整”是指在革命对象中增加了：官僚资本主义", "sourcePages": [66], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-12", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "单选", "number": 12, "stem": "中国民主主义革命经历了旧民主主义革命和新民主主义革命两个阶段，“旧”阶段转变到“新”阶段的根本标志是", "options": {"A": "中国革命领导阶级的变化", "B": "中国革命主要对象的变化", "C": "中国革命基本性质的变化", "D": "中国社会主要矛盾的变化"}, "answer": ["A"], "note": "中国民主主义革命经历了旧民主主义革命和新民主主义革命两个阶段，“旧”阶段转变到“新”阶段的根本标志是：中国革命领导阶级的变化", "sourcePages": [66], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-13", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "单选", "number": 13, "stem": "中国革命的中心问题是", "options": {"A": "农民土地问题", "B": "统一战线问题", "C": "武装斗争问题", "D": "领导权问题"}, "answer": ["D"], "note": "中国革命的中心问题是：领导权问题", "sourcePages": [66], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-15", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "单选", "number": 15, "stem": "“统帅革命的资产阶级，联合革命的无产阶级，实行资产阶级民主革命。”这一观点的错误实质在于", "options": {"A": "抹杀农民阶级的革命性", "B": "夸大资产阶级的作用", "C": "放弃无产阶级的领导权", "D": "忽视武装斗争的重要性"}, "answer": ["C"], "note": "“统帅革命的资产阶级，联合革命的无产阶级，实行资产阶级民主革命。”这一观点的错误实质在于放弃无产阶级的领导权", "sourcePages": [67], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-17", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "单选", "number": 17, "stem": "新民主主义革命理论的核心问题是", "options": {"A": "分清敌友", "B": "农民问题", "C": "无产阶级领导权", "D": "土地问题"}, "answer": ["C"], "note": "新民主主义革命理论的核心问题是无产阶级领导权", "sourcePages": [67], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-18", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "单选", "number": 18, "stem": "新民主主义革命时期，党内犯“左”倾错误的人提出“毕其功于一役”的主张，搞所谓的“无间断”革命，这种错误倾向实质上是", "options": {"A": "混淆了新民主主义革命和社会主义革命的界限", "B": "割裂了新民主主义革命和社会主义革命的联系", "C": "混淆了新民主主义革命和资产阶级革命的界限", "D": "割裂了新民主主义革命和资产阶级革命的联系"}, "answer": ["A"], "note": "党内犯“左”倾错误的人提出“毕其功于一役”的主张，搞所谓的“无间断”革命，这种错误倾向实质上是混淆了新民主主义革命和社会主义革命的界限", "sourcePages": [67], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-19", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "单选", "number": 19, "stem": "新民主主义革命的主要内容是", "options": {"A": "从根本上推翻反动腐朽的政治上层建筑，变革阻碍生产力发展的生产关系", "B": "没收官僚资产阶级的垄断资本归新民主主义国家所有", "C": "没收封建地主阶级的土地归农民所有", "D": "推翻帝国主义、封建主义和官僚资本主义的统治"}, "answer": ["C"], "note": "新民主主义革命的主要内容是：没收封建地主阶级的土地归农民所有", "sourcePages": [67], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-20", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "单选", "number": 20, "stem": "在半殖民地半封建的中国，地主占有土地、将土地出租给农民，通过收取地租来剥削农民，土地制度极不合理。因此，要改变中国贫穷落后的面貌，必须进行土地革命。土地改革的主要和直接任务，就是", "options": {"A": "限制富农剥削，发展农村生产力", "B": "没收地主土地归国家所有，分配给农民使用", "C": "把农民组织起来，开展互助合作", "D": "满足贫雇农群众的要求"}, "answer": ["D"], "note": "土地改革的主要和直接任务，就是：满足贫雇农群众的要求", "sourcePages": [67], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-21", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "单选", "number": 21, "stem": "1940年，毛泽东在《新民主主义论》中，阐述了新民主主义的政治、经济和文化。1945年，他在党的七大所作的政治报告《论联合政府》中，进一步把新民主主义的政治、经济和文化与党的基本纲领联系起来，进行了具体阐述，形成了新民主主义的基本纲领。新民主主义经济纲领中极具特色的一项内容是", "options": {"A": "没收封建地主阶级的土地归农民所有", "B": "没收官僚资产阶级的垄断资本归新民主主义的国家所有", "C": "没收帝国主义在华资本归新民主主义的国家所有", "D": "保护民族工商业"}, "answer": ["D"], "note": "新民主主义经济纲领中极具特色的一项内容是：保护民族工商业", "sourcePages": [67], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-22", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "单选", "number": 22, "stem": "新民主主义文化就是无产阶级领导的人民大众的反帝反封建的文化，即民族的科学的大众的文化。其中“民族的”，就其内容说，是指", "options": {"A": "具有鲜明的民族风格、民族形式和民族特色", "B": "具有中国作风和中国气派", "C": "反对帝国主义压迫，主张中华民族的尊严和独立", "D": "反对封建思想和迷信思想"}, "answer": ["C"], "note": "民族的科学的大众的文化。其中“民族的”」就其内容说，是指：反对帝国主义压迫，主张中华民族的尊严和独立", "sourcePages": [67], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-23", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "单选", "number": 23, "stem": "中国革命走农村包围城市、武装夺取政权的道路，根本在于处理好", "options": {"A": "土地革命、武装斗争、农村革命根据地建设三者之间的关系", "B": "统一战线、武装斗争、党的建设三者之间的关系", "C": "工人阶级、农民阶级、民族资产阶级三者之间的关系", "D": "进步势力、中间势力、顽固势力三者之间的关系"}, "answer": ["A"], "note": "中国革命走农村包围城市、武装夺取政权的道路，根本在于处理好：土地革命、武装斗争、农村革命根据地建设三者之间的关系", "sourcePages": [68], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-24", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "单选", "number": 24, "stem": "半殖民地半封建社会的社会性质，决定了近代中国不可能是一个独立的民主国家，外部没有民族独立，而受帝国主义压迫；内部没有起码的资产阶级民主，反动统治阶级凭借强大的反革命武装对人民实行独裁恐怖统治。这种社会性质决定了中国革命的主要形式是", "options": {"A": "争取民主", "B": "农民运动", "C": "武装斗争", "D": "工人运动"}, "answer": ["C"], "note": "半殖民地半封建社会的社会性质决定了中国革命的主要形式是：武装斗争", "sourcePages": [68], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-25", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "单选", "number": 25, "stem": "1939年7月7日，是卢沟桥事变爆发2周年纪念日，华北联大在延安举行开学典礼，校长成仿吾请毛泽东作报告。毛泽东以他特有的广征博引方式发表讲话，他说：“当年姜子牙下昆仑山，元始天尊赠了他杏黄旗、四不象和打神鞭三样法宝。现在你们出发上前线，我也赠给你们三样法宝。”毛泽东赠给的“三样法宝”是指", "options": {"A": "土地革命、武装斗争、农村革命根据地建设", "B": "统一战线、武装斗争、党的建设", "C": "实事求是、群众路线、独立自主", "D": "理论联系实际、密切联系群众、批评与自我批评"}, "answer": ["B"], "note": "毛泽东赠给的“三样法宝”是：统一战线、武装斗争、党的建设", "sourcePages": [68], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-26", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "单选", "number": 26, "stem": "中国革命建立最广泛的统一战线不仅是必要的，而且是可能的，这种可能是由", "options": {"A": "中国半殖民地半封建社会的阶级状况所决定的", "B": "半殖民地半封建的中国社会的交织在一起的诸多矛盾所决定的", "C": "中国革命的长期性、残酷性及其发展的不平衡性所决定的", "D": "战争与革命的时代主题所决定的"}, "answer": ["B"], "note": "中国革命建立最广泛的统一战线不仅是必要的，而且是可能的，这种可能是由半殖民地半封建的中国社会的交织在一起的诸多矛盾所决定的", "sourcePages": [68], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-27", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "单选", "number": 27, "stem": "新民主主义革命时期，党领导的革命统一战线包含着两个联盟。其中作为统一战线的基础的联盟是", "options": {"A": "工人阶级同城市小资产阶级的联盟", "B": "工人阶级同农民阶级、广大知识分子及其他劳动者的联盟", "C": "工人阶级同农民阶级、小资产阶级和民族资产阶级的联盟", "D": "工人阶级同可以合作的非劳动人民的联盟"}, "answer": ["B"], "note": "作为统一战线的基础的联盟是：工人阶级同农民阶级、广大知识分子及其他劳动者的联盟", "sourcePages": [68], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-28", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "单选", "number": 28, "stem": "毛泽东思想关于党的建设理论中，始终放在党的建设的首位的是", "options": {"A": "加强党的思想建设", "B": "加强党的组织建设", "C": "加强党员的党性修养", "D": "保持党的优良作风"}, "answer": ["A"], "note": "毛泽东思想关于党的建设理论中，始终放在党的建设的首位的是：加强党的思想建设", "sourcePages": [68], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-7", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "多选", "number": 7, "stem": "新民主主义革命与旧民主主义革命相比有新的内容和特点，集中表现在新民主主义革命", "options": {"A": "处于世界无产阶级社会主义革命的时代，是世界无产阶级社会主义革命的一部分", "B": "革命的领导力量是中国无产阶级及其先锋队一一中国共产党", "C": "革命的指导思想是马克思列宁主义", "D": "革命的前途是社会主义而不是资本主义"}, "answer": ["A", "B", "C", "D"], "note": "新民主主义革命相比旧民主主义革命的新的内容和特点集中表现在：处于世界无产阶级社会主义革命的时代，是世界无产阶级社会主义革命的一部分；革命的领导力量是中国无产阶级及其先锋队一一中国共产党；革命的指导思想是马克思列宁主义；革命的前途是社会主义而不是资本主义", "sourcePages": [73], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-8", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "多选", "number": 8, "stem": "无产阶级及其政党对中国革命的领导权不是自然而然得来的，而是在与资产阶级争夺领导权的斗争中实现的。毛泽东指出，无产阶级及其政党要实现对同盟者的领导必须具备的条件有", "options": {"A": "率领同盟者向着共同的敌人作坚决斗争并取得胜利", "B": "坚持发展进步势力、争取中间势力、孤立顽固势力的策略方针", "C": "对同盟者给以物质利益，至少不损害其利益，同时给以政治教育", "D": "对同盟者采取有理、有利、有节的策略原则"}, "answer": ["A", "C"], "note": "毛泽东指出，无产阶级及其政党要实现对同盟者的领导必须具备的条件有：率领同盟者向着共同的敌人作坚决斗争并取得胜利；对同盟者给以物质福利，至少不损害其利益，同时给以政治教育", "sourcePages": [73], "answerSource": "配套资料与题目核对"}, {"id": "毛中特-多选-9", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "多选", "number": 9, "stem": "毛泽东把新民主主义革命和社会主义革命比喻为文章的上篇和下篇。“两篇文章，上篇与下篇，只有上篇做好，下篇才能做好”。毛泽东这段话的含义是", "options": {"A": "民主主义革命是社会主义革命的必要准备", "B": "社会主义革命是民主主义革命的必然趋势", "C": "在民主主义革命和社会主义革命中间要经历一个独立的资本主义发展阶段", "D": "“一次革命论”是错误的，“二次革命论”是正确的"}, "answer": ["A", "B"], "note": "“两篇文章，上篇与下篇，只有上篇做好，下篇才能做好”。毛泽东这段话的含义是民主主义革命是社会主义革命的必要准备；社会主义革命是民主主义革命的必然趋势", "sourcePages": [73], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-11", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "多选", "number": 11, "stem": "新民主主义经济纲领的内容是", "options": {"A": "没收封建地主阶级的土地归农民所有", "B": "没收官僚资产阶级的垄断资本归新民主主义的国家所有", "C": "保护民族工商业", "D": "没收外国在华资本归新民主主义的国家所有"}, "answer": ["A", "B", "C"], "note": "新民主主义经济纲领的内容是：没收封建地主阶级的土地归农民所有；没收官僚资产阶级的垄断资本归新民主主义的国家所有；保护民族工商业", "sourcePages": [74], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-14", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "多选", "number": 14, "stem": "当年，蒋介石在南京宣称，谁控制了北平、上海、广州等城市，谁就控制了中国；毛泽东在井冈山说，谁赢得了农民，谁就会赢得中国。1926年，毛泽东曾在广州农民运动讲习所任所长，培养了300多名学员，他们奔赴各地领导农民运动。仿佛是巧合一一讲习所内展示的红色锦旗依旧赫然：“农为党本”。按当时体例从右向左书写的四个大字，今天从左向右读来就是“本党为农”。党之所以如此重视农民，是因为", "options": {"A": "农民是中国革命的主力军", "B": "新民主主义革命实质上就是党领导下的农民革命", "C": "中国革命战争实质上就是党领导下的农民战争", "D": "农民阶级是近代中国最革命最进步的阶级"}, "answer": ["A", "B", "C"], "note": "党之所以如此重视农民，是因为农民是中国革命的主力军；新民主主义革命实质上就是党领导下的农民革命；中国革命战争实质上就是党领导下的农民战争", "sourcePages": [74], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-15", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "多选", "number": 15, "stem": "1938年11月，毛泽东在《战争和战略问题》中明确指出：“共产党的任务，基本地不是经过长期合法斗争以进入起义和战争，也不是先占城市后取乡村，而是走相反的道路。”中国走农村包围城市、武装夺取政权道路的依据是", "options": {"A": "无产阶级是革命的领导阶级", "B": "农民占全国人口的绝大多数，是无产阶级可靠的同盟军和革命的主力军", "C": "当时的中国内无民主制度而受封建主义的压迫，外无民族独立而受帝国主义的压迫", "D": "在半殖民地半封建的近代中国，封建主义和人民大众的矛盾是各种矛盾中最主要的矛盾"}, "answer": ["B", "C"], "note": "中国走农村包围城市、武装夺取政权道路的依据是：农民占全国人口的绝大多数，是无产阶级可靠的同盟军和革命的主力军；当时的中国内无民主制度而受封建主义的压迫，外无民族独立而受帝国主义的压迫", "sourcePages": [74], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-16", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "多选", "number": 16, "stem": "土地革命战争时期，毛泽东指出：“一国之内，在四周白色政权的包围中，有一小块或若干小块红色政权的区域长期地存在，这是世界各国从来没有的事。这种奇事的发生，有其独特的原因。”党之所以能够深入农村积蓄革命力量，建设农村革命根据地，最终实现农村包围城市并夺取政权，其原因是", "options": {"A": "近代中国是多个帝国主义间接统治的半殖民地国家，社会政治经济发展极端不平衡", "B": "经历过大革命的洗礼，革命的群众基础好", "C": "全国革命形势的继续向前发展", "D": "相当力量正式红军的存在，以及党的领导的有力量及其政策的不错误"}, "answer": ["A", "B", "C", "D"], "note": "党之所以能够深入农村积蓄革命力量，建设农村革命根据地，最终实现农村包围城市并夺取政权，其原因是近代中国是多个帝国主义间接统治的半殖民地国家，社会政治经济发展极端不平衡；经历过大革命的洗礼，革命的群众基础好；全国革命形势的继续向前发展；相当力量正式红军的存在，以及党的领导的有力量及其政策的不错误", "sourcePages": [74, 75], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-18", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "多选", "number": 18, "stem": "近代中国社会的阶级结构是“两头小中间大”，“中间”是指", "options": {"A": "无产阶级", "B": "农民阶级", "C": "民族资产阶级", "D": "城市小资产阶级"}, "answer": ["B", "C", "D"], "note": "近代中国社会的阶级结构是“两头小中间大”“中间”是指：农民阶级；民族资产阶级；城市小资产阶级", "sourcePages": [75], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-19", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "多选", "number": 19, "stem": "新民主主义革命时期，以国共合作为基础所建立的统一战线有", "options": {"A": "国民革命联合战线", "B": "工农民主统一战线", "C": "抗日民族统一战线", "D": "人民民主统一战线"}, "answer": ["A", "C"], "note": "新民主主义革命时期，以国共合作为基础所建立的统一战线有：国民革命联合战线；抗日民族统一战线", "sourcePages": [75], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-20", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "多选", "number": 20, "stem": "武装斗争是中国革命的特点和优点之一。总结党在新民主主义革命时期开展武装斗争的革命经验，建设人民军队，要", "options": {"A": "坚持党对军队的绝对领导", "B": "建设全心全意为人民服务的人民军队", "C": "开展革命的政治工作", "D": "坚持正确的战略战术原则"}, "answer": ["A", "B", "C", "D"], "note": "总结党在新民主主义革命时期开展武装斗争的革命经验，建设人民军队，要坚持党对军队的绝对领导；建设全心全意为人民服务的人民军队；开展革命的政治工作：坚持正确的战略战术原则", "sourcePages": [75], "answerSource": "配套资料与题目核对"}, {"id": "毛中特-多选-21", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "多选", "number": 21, "stem": "开展革命的政治工作是党在新民主主义革命时期建设人民军队的经验之一。人民军队政治工作的基本原则包括", "options": {"A": "支部建在连上的原则", "B": "官兵一致的原则", "C": "军民一致的原则", "D": "瓦解敌军和优待俘虏的原则"}, "answer": ["B", "C", "D"], "note": "人民军队政冶工作的基本原则包括：官兵一致的原则；军民一致的原则；瓦解敌军和优待俘虏的原则", "sourcePages": [75], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-22", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "多选", "number": 22, "stem": "毛泽东在中共七大上总结的中国共产党区别于其他任何政党的显著标志有", "options": {"A": "谦虚、谨慎、不骄、不躁的作风", "B": "理论和实践相结合的作风", "C": "自我批评的作风", "D": "和人民群众紧密地联系在一起的作风"}, "answer": ["B", "C", "D"], "note": "毛泽东在中共七大上总结的中国共产党区别于其他任何政党的显著标志有：理论和实践相结合的作风；自我批评的作风；和人民群众紧密地联系在一起的作风", "sourcePages": [75], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-23", "subject": "毛中特", "chapter": 2, "chapterTitle": "第二章新民主主义革命理论", "type": "多选", "number": 23, "stem": "中国共产党要领导革命取得胜利，必须不断加强党的思想建设、组织建设和作风建设。新民主主义革命时期党的建设的主要经验有", "options": {"A": "必须把思想建设始终放在党的建设的首位，以无产阶级思想克服和改造各种非无产阶级思想", "B": "必须重视党的组织建设和作风建设", "C": "必须联系党的政治路线加强党的建设", "D": "注意党的执政能力建设"}, "answer": ["A", "B", "C"], "note": "新民主主义革命时期党的建设的主要经验有：必须把思想建设始终放在党的建设的首位，以无产阶级思想克服和改造各种非无产阶级思想；必须重视党的组织建设和作风建设；必须联系党的政治路线加强党的建设", "sourcePages": [75], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-29", "subject": "毛中特", "chapter": 3, "chapterTitle": "第三章社会主义改造理论", "type": "单选", "number": 29, "stem": "新民主主义社会在经济上实行国营经济、合作社经济、个体经济、私人资本主义经济和国家资本主义经济五种经济成分并存的经济制度。五种经济成分中，在国民经济中居于领导地位的是", "options": {"A": "国营经济", "B": "个体经济", "C": "国家资本主义经济", "D": "私人资本主义经济"}, "answer": ["A"], "note": "新民主主义社会的五种经济成分中，在国民经济中居于领导地位的是：国营经济", "sourcePages": [68], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-30", "subject": "毛中特", "chapter": 3, "chapterTitle": "第三章社会主义改造理论", "type": "单选", "number": 30, "stem": "建国初期，随着全国土地改革的基本完成，国内的主要矛盾是", "options": {"A": "人民大众同帝国主义、封建主义和国民党反动派残余势力之间的矛盾", "B": "工人阶级和资产阶级的矛盾", "C": "生产力与生产关系的矛盾和经济基础与上层建筑的矛盾", "D": "人民日益增长的物质文化需要同落后的社会生产之间的矛盾"}, "answer": ["B"], "note": "建国初期，随着全国土地改革的基本完成，国内的主要矛盾是：工人阶级和资产阶级的矛盾“，。“，“，曼“一，", "sourcePages": [68, 69], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-31", "subject": "毛中特", "chapter": 3, "chapterTitle": "第三章社会主义改造理论", "type": "单选", "number": 31, "stem": "党在过渡时期总路线的主要内容被概括为“一化三改”，也曾被比喻为鸟的“主体”和“两翼”。“主体”是指", "options": {"A": "对农业的社会主义改造", "B": "对手工业的社会主义改造", "C": "对资本主义工商业的社会主义改造", "D": "社会主义工业化"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [69], "answerSource": "待核对"}, {"id": "毛中特-单选-32", "subject": "毛中特", "chapter": 3, "chapterTitle": "第三章社会主义改造理论", "type": "单选", "number": 32, "stem": "对农业的社会主义改造，是三大改造中首先进行的。以毛泽东同志为主要代表的中国共产党人根据马克思列宁主义关于农业社会主义改造的基本原理，从我国农村实际出发，制定并实行了一整套适合中国特点的对农业进行社会主义改造的方针、政策和办法。农业社会主义改造遵循的原则是", "options": {"A": "积极领导、稳步前进", "B": "区别对象、积极引导、逐步过渡", "C": "自愿互利、典型示范和国家帮助", "D": "既反保守又反冒进"}, "answer": ["C"], "note": "农业社会主义改造遵循的原则是：自愿互利、典型示范和国家帮助", "sourcePages": [69], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-33", "subject": "毛中特", "chapter": 3, "chapterTitle": "第三章社会主义改造理论", "type": "单选", "number": 33, "stem": "在农业合作化进程中，具有半社会主义性质的组织形式是", "options": {"A": "临时互助组", "B": "常年互助组", "C": "初级合作社", "D": "高级合作社"}, "answer": ["C"], "note": "在农业合作化进程中，具有半社会主义性质的组织形式是：初级合作社", "sourcePages": [69], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-34", "subject": "毛中特", "chapter": 3, "chapterTitle": "第三章社会主义改造理论", "type": "单选", "number": 34, "stem": "我国对资本主义工商业的社会主义改造经历了三个步骤。其中，在实行个别企业的公私合营中，企业利润分配上采取的办法是", "options": {"A": "定股定息", "B": "“四马分肥”", "C": "和平赎买", "D": "公私兼顾"}, "answer": ["B"], "note": "我国在对资本主义工商业进行社会主义改造的过程中，在实行个别企业的公私合营中，企业利润分配上采取的办法是：四马分肥", "sourcePages": [69], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-35", "subject": "毛中特", "chapter": 3, "chapterTitle": "第三章社会主义改造理论", "type": "单选", "number": 35, "stem": "我国对资本主义工商业的社会主义改造，采取了从低级到高级的国家资本主义的过渡形式。其中第二步主要实行个别企业的公私合营，这些企业的性质", "options": {"A": "仍然是资本主义性质的企业", "B": "是具有了社会主义因素的企业", "C": "是半社会主义性质的企业", "D": "是社会主义国营性质的企业"}, "answer": ["C"], "note": "实行个别企业的公私合营，这些企业的性质：是半社会主义性质的企业", "sourcePages": [69], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-36", "subject": "毛中特", "chapter": 3, "chapterTitle": "第三章社会主义改造理论", "type": "单选", "number": 36, "stem": "我国对资本主义工商业的社会主义改造经历了三个步骤。第一步实行初级形式的国家资本主义；第二步实行个别企业的公私合营；第三步实行全行业的公私合营。在这些步骤中，同资本家在企业外部的合作是指", "options": {"A": "实行初级形式的国家资本主义", "B": "实行个别企业的公私合营", "C": "实行全行业的公私合营", "D": "实行“四马分肥”"}, "answer": ["A"], "note": "同资本家在企业外部的合作是指：实行初级形式的国家资本主义", "sourcePages": [69], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-24", "subject": "毛中特", "chapter": 3, "chapterTitle": "第三章社会主义改造理论", "type": "多选", "number": 24, "stem": "新民主主义社会是", "options": {"A": "中国由新民主主义转变到社会主义的过渡性社会形态", "B": "无产阶级推翻资产阶级建立政权过程中必然经历的一个独立的社会形态", "C": "属于社会主义体系的逐步过渡到社会主义社会的过渡性质的社会", "D": "既有社会主义因素又有非社会主义因素存在的社会"}, "answer": ["A", "C", "D"], "note": "新民主主义社会是：中国由新民主主义转变到社会主义的过渡性社会形态；属于社会主义体系的逐步过渡到社会主义社会的过渡性质的社会；既有社会主义因素又有非社会主义因素存在的社会", "sourcePages": [75], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-25", "subject": "毛中特", "chapter": 3, "chapterTitle": "第三章社会主义改造理论", "type": "多选", "number": 25, "stem": "新中国成立初期，中国处于新民主主义社会。新民主主义社会有五种经济成分，其中主要的经济成分是", "options": {"A": "社会主义经济", "B": "个体经济", "C": "资本主义经济", "D": "封建地主经济"}, "answer": ["A", "B", "C"], "note": "新民主主义社会有五种经济成分，其中主要的经济成分是：社会主义经济；个体经济；资本主义经济", "sourcePages": [75], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-26", "subject": "毛中特", "chapter": 3, "chapterTitle": "第三章社会主义改造理论", "type": "多选", "number": 26, "stem": "新民主主义时期三种不同性质的经济成分及与之相联系的三种基本的阶级力量之间的矛盾，集中表现为", "options": {"A": "社会主义和资本主义两条道路的矛盾", "B": "工人阶级和资产阶级两个阶级的矛盾", "C": "计划经济和市场经济的矛盾", "D": "人民对于经济文化迅速发展的需要同当前经济文化不能满足人民需要的状况之间的矛盾"}, "answer": ["A", "B"], "note": "新民主主义时期三种不同性质的经济成分及与之相联系的三种基本的阶级力量之间的矛盾，集中表现为：社会主义和资本主义两条道路的矛盾；工人阶级和资产阶级两个阶级的矛盾", "sourcePages": [76], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-27", "subject": "毛中特", "chapter": 3, "chapterTitle": "第三章社会主义改造理论", "type": "多选", "number": 27, "stem": "对于新民主主义向社会主义的过渡，毛泽东及党的其他领导人经历了从“一举过渡”到“并举过渡”的转变。1952年底，中共中央开始酝酿并于1953年正式提出了党在过渡时期的总路线。党提出过渡时期的总路线，不仅有理论依据，而且有充分的现实依据。党提出过渡时期总路线的现实依据有", "options": {"A": "社会主义的国营经济在国家经济生活中实际上已居于相对强大的地位", "B": "广大农民有走互助合作道路的要求，以及农业互助合作组织显示出增产的优越性", "C": "国家在利用和限制资本主义工商业的过程中积累了经验", "D": "当时的国际形势有利于中国向社会主义过渡"}, "answer": ["A", "B", "C", "D"], "note": "党提出过渡时期总路线的现实依据有：社会主义的国营经济在国家经济生活中实际上已居于相对强大的地位；广大农民有走互助合作道路的要求，以及农业互助合作组织显示出增产的优越性；国家在利用和限制资本主义工商业的过程中积累了经验；当时的国际形势有利于中国向社会主义过渡", "sourcePages": [76], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-28", "subject": "毛中特", "chapter": 3, "chapterTitle": "第三章社会主义改造理论", "type": "多选", "number": 28, "stem": "党在过渡时期的总路线，将马克思列宁主义关于过渡时期的理论在中国进一步具体化了，形成了中国化的过渡时期理论，为中国社会主义改造提供了行动指南。党在过渡时期的总路线", "options": {"A": "是社会主义建设和社会主义改造同时并举的路线", "B": "体现了社会主义工业化和社会主义改造的紧密结合", "C": "体现了解放生产力与发展生产力的有机统一", "D": "体现了变革生产关系与发展生产力的有机统一"}, "answer": ["A", "B", "C", "D"], "note": "党在过渡时期的总路线：是社会主义建设和社会主义改造同时并举的路线；体现了社会主义工业化和社会主义改造的紧密结合；体现了解放生产力与发展生产力的有机统一；体现了变革生产关系与发展生产力的有机统一", "sourcePages": [76], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-29", "subject": "毛中特", "chapter": 3, "chapterTitle": "第三章社会主义改造理论", "type": "多选", "number": 29, "stem": "在社会主义改造中，我国创造性地开辟了一条适合中国情况的对资本主义工商业进行社会主义改造的道路，主要有", "options": {"A": "用和平赎买的方法改造资本主义工商业", "B": "采取从低级到高级的国家资本主义的过渡形式", "C": "把资本主义工商业者改造成为自食其力的社会主义劳动者", "D": "遵循自愿互利、典型示范和国家帮助的原则"}, "answer": ["A", "B", "C"], "note": "在社会主义改造中，我国创造性地开辟了一条适合中国情况的对资本主义工商业进行社会主义改造的道路，主要有：用和平赎买的方法改造资本主义工商业；采取从低级到高级的国家资本主义的过渡形式；把资本主义工商业者改造成为自食其力的社会主义劳动者", "sourcePages": [76], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-31", "subject": "毛中特", "chapter": 3, "chapterTitle": "第三章社会主义改造理论", "type": "多选", "number": 31, "stem": "我国之所以能够采取赎买的方式对资本主义工商业进行和平改造，其原因在于", "options": {"A": "民族资产阶级具有两面性", "B": "中国共产党与民族资产阶级长期保持着统一战线的关系", "C": "我国已经有了人民民主专政的国家政权和掌握了国家经济命脉的强大的社会主义国营经济", "D": "国家对粮食和工业原料的统购统销，以及资本主义企业中工人群众对资本家的监督"}, "answer": ["A", "B", "C", "D"], "note": "我国之所以能够采取赎买的方式对资本主义工商业进行和平改造，其原因在于民族资产阶级具有两面性；中国共产党与民族资产阶级长期保持着统一战线的关系；我国已经有了人民民主专政的国家政权和掌握了国家经济命脉的强大的社会主义国营经济；国家对粮食和工业原料的统购统销，以及资本主义企业中工人群众对资本家的监督", "sourcePages": [76], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-32", "subject": "毛中特", "chapter": 3, "chapterTitle": "第三章社会主义改造理论", "type": "多选", "number": 32, "stem": "在党的七届二中全会上，毛泽东将“国家和私人合作的国家资本主义经济”作为新中国的几种主要的经济成分之一。在新中国社会主义改造过程中，中国共产党采用国家资本主义的方式开展对资本主义工商业的社会主义改造，即通过在一定的时期内有步骤地、有区别地把一切对国计民生有利的、而又为国家所需要的资本主义企业基本上改造为国家资本主义企业，并有计划地稳步地使低级形式的国家资本主义向高级形式的国家资本主义发展。国家资本主义", "options": {"A": "是与社会主义直接相联系的、国家直接控制和支配下的资本主义经济", "B": "不是一种独立的经济形态", "C": "其性质取决于生产力的发展水平", "D": "是个体经济向社会主义集体经济过渡的形式"}, "answer": ["A", "B"], "note": "国家资本主义：是与社会主义直接相联系的、国家直接控制和支配下的资本主义经济；不是一种独立的经济形态", "sourcePages": [76, 77], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-33", "subject": "毛中特", "chapter": 3, "chapterTitle": "第三章社会主义改造理论", "type": "多选", "number": 33, "stem": "我国对资本主义工商业的改造采取赎买的方针，所谓赎买就是", "options": {"A": "国家有偿地将私营企业改变为国营企业", "B": "由国家支付一笔巨额补偿资金", "C": "让资本家在一定年限内从企业经营所得中获取一部分利润", "D": "国家把私营企业改变为集体企业"}, "answer": ["A", "C"], "note": "我国对资本主义工商业的改造采取赎买的方针，所谓赎买就是：国家有偿地将私营企业改变为国营企业；让资本家在一定年限内从企业经营所得中获取一部分利润", "sourcePages": [77], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-34", "subject": "毛中特", "chapter": 3, "chapterTitle": "第三章社会主义改造理论", "type": "多选", "number": 34, "stem": "我国对资本主义工商业的社会主义改造经历了三个步骤：第一步实行初级形式的国家资本主义；第二步实行个别企业的公私合营；第三步实行全行业的公私合营。从个别企业的公私合营到全行业公私合营，是", "options": {"A": "党和国家对资本主义工商业采取利用、限制、改造政策的必然趋势", "B": "经济运行中计划不断强化的必然结果", "C": "保证国家重点建设顺利进行的必然要求", "D": "彻底完成民主革命遗留任务的必要前提"}, "answer": ["A", "B", "C"], "note": "从个别企业公私合营到全行业公私合营，是利用、限制、改造政策的必然趋势，是经济运行中计划不断强化的必然结果，是保证国家重点建设顺利进行的必然要求。", "sourcePages": [77], "answerSource": "配套资料与题目核对"}, {"id": "毛中特-多选-35", "subject": "毛中特", "chapter": 3, "chapterTitle": "第三章社会主义改造理论", "type": "多选", "number": 35, "stem": "把资本主义工商业者改造成为自食其力的社会主义劳动者，是适合中国情况的对资本主义工商业进行社会主义改造的道路的主要内容之一，它的优点在于", "options": {"A": "通过改造阶级成分的方式达到从整体上消灭资产阶级的目的", "B": "对企业的改造和对人的改造相结合", "C": "改造资本家个人与消灭他们所属的资产阶级相结合", "D": "既避免了激烈的阶级对抗，减少了改造的阻力，又推动了生产力的发展和社会的进步"}, "answer": ["A", "B", "C", "D"], "note": "把资本主义工商业者改造成为自食其力的社会主义劳动者，它的优点在于：通过改造阶级成分的方式达到从整体上消灭资产阶级的目的；对企业的改造和对人的改造相结合；改造资本家个人与消灭他们所属的资产阶级相结合；既避免了激烈的阶级对抗，减少了改造的阻力，又推动了生产力的发展和社会的进步", "sourcePages": [77], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-36", "subject": "毛中特", "chapter": 3, "chapterTitle": "第三章社会主义改造理论", "type": "多选", "number": 36, "stem": "我国在对个体农业进行社会主义改造的过程中，成功地开辟了一条适合我国情况的农业社会主义改造道路，其内容主要有", "options": {"A": "积极引导农民组织起来，走互助合作道路", "B": "遵循自愿互利、典型示范、国家帮助的原则", "C": "坚持积极领导、稳步前进的方针，采取循序渐进的步骤", "D": "在有条件的地区推广农业生产责任制"}, "answer": ["A", "B", "C"], "note": "适合我国情况的农业社会主义改造道路，其内容主要有：积极引导农民组织起来，走互助合作道路；遵循自愿互利、典型示范、国家帮助的原则；坚持积极领导、稳步前进的方针，采取循序渐进的步骤", "sourcePages": [77], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-37", "subject": "毛中特", "chapter": 3, "chapterTitle": "第三章社会主义改造理论", "type": "多选", "number": 37, "stem": "在一个几亿人口的大国中比较顺利地实现了如此复杂、困难和深刻的社会主义改造，不仅没有造成生产力的破坏，反而促进了工农业和整个国民经济的发展；不仅没有引起巨大的社会动荡，反而极大地加强了人民的团结，并且是在人民普遍拥护的情况下完成的。这些情况说明，我国社会主义改造的基本完成的确是一个伟大的历史性胜利。我国社会主义改造的成功经验在于", "options": {"A": "坚持“一举过渡”", "B": "坚持社会主义工业化建设与社会主义改造同时并举", "C": "采取积极引导、逐步过渡的方式", "D": "用和平方法进行改造"}, "answer": ["B", "C", "D"], "note": "我国社会主义改造的成功经验在于：坚持社会主义工业化建设与社会主义改造同时并举；采取积极引导、逐步过渡的方式；用和平方法进行改造", "sourcePages": [77], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-38", "subject": "毛中特", "chapter": 3, "chapterTitle": "第三章社会主义改造理论", "type": "多选", "number": 38, "stem": "1956年底，我国对农业、手工业和资本主义工商业的社会主义改造基本完成，我国社会经济结构发生了根本变化，社会主义公有制已成为我国社会的经济基础，标志着中国历史上长达数千年的阶级剥削制度的结束和社会主义基本制度的确立。在中国确立社会主义基本制度是中国共产党百年奋斗的伟大成就之一。社会主义基本制度的确立", "options": {"A": "是中国历史上最深刻最伟大的社会变革，为当代中国一切发展进步奠定了制度基础", "B": "实现了马克思主义同中国实际的“第二次结合”", "C": "极大地促进了我国社会生产力的发展", "D": "使广大劳动人民真正成为国家的主人，这是中国几千年来阶级关系的最根本变革"}, "answer": ["A", "C", "D"], "note": "社会主义基本制度的确立：是中国历史上最深刻最伟大的社会变革，为当代中国一切发展进步奠定了制度基础；极大地促进了我国社会生产力的发展；使广大劳动人民真正成为国家的主人，这是中国几千年来阶级关系的最根本变革", "sourcePages": [77], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-38", "subject": "毛中特", "chapter": 4, "chapterTitle": "第四章社会主义建设道路初步探索的理论成果", "type": "单选", "number": 38, "stem": "成为党探索中国社会主义建设道路良好开端的文章，是毛泽东发表的", "options": {"A": "《论人民民主专政》", "B": "《论十大关系》", "C": "《纪念孙中山先生》", "D": "《关于正确处理人民内部矛盾的问题》"}, "answer": ["B"], "note": "成为党探索中国社会主义建设道路良好开端的文章，是毛泽东发表的：《论士大关系》", "sourcePages": [69], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-39", "subject": "毛中特", "chapter": 4, "chapterTitle": "第四章社会主义建设道路初步探索的理论成果", "type": "单选", "number": 39, "stem": "1956年，毛泽东先后在中央政治局扩大会议和最高国务会议上，作了《论十大关系》的报告，初步总结了我国社会主义建设的经验，明确了建设社会主义的根本思想是", "options": {"A": "正确处理人民内部矛盾", "B": "调动一切积极因素为社会主义服务", "C": "根据本国情况走自己的道路", "D": "自力更生与对外开放相结合"}, "answer": ["C"], "note": "《论十大关系》的报告明确了建设社会主义的根本思想是：根据本国情况走自己的道路", "sourcePages": [70], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-40", "subject": "毛中特", "chapter": 4, "chapterTitle": "第四章社会主义建设道路初步探索的理论成果", "type": "单选", "number": 40, "stem": "毛泽东在《论十大关系》中提出的中国社会主义建设的基本方针是", "options": {"A": "不要四面出击", "B": "积极引导，稳步前进", "C": "调动一切积极因素为社会主义事业服务", "D": "实现工业、农业、国防和科学技术的现代化"}, "answer": ["C"], "note": "毛泽东在《论十大关系》中提出的中国社会主义建设的基本方针是：调动一切积极因素为社会主义事业服务", "sourcePages": [70], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-41", "subject": "毛中特", "chapter": 4, "chapterTitle": "第四章社会主义建设道路初步探索的理论成果", "type": "单选", "number": 41, "stem": "1957年2月，毛泽东作了《关于正确处理人民内部矛盾的问题》的报告，系统论述了社会主义社会矛盾的理论。毛泽东强调，社会主义国家政治生活的主题是", "options": {"A": "正确区分和处理两类不同性质矛盾的问题", "B": "正确处理人民内部矛盾的问题", "C": "正确处理敌我矛盾的问题", "D": "正确认识和处理阶级斗争的问题"}, "answer": ["B"], "note": "毛泽东强调，社会主义国家政治生活的主题是：正确处理人民内部矛盾的问题", "sourcePages": [70], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-42", "subject": "毛中特", "chapter": 4, "chapterTitle": "第四章社会主义建设道路初步探索的理论成果", "type": "单选", "number": 42, "stem": "1957年2月，毛泽东作了《关于正确处理人民内部矛盾的问题》的报告，指出：“在社会主义社会中，基本的矛盾仍然是生产关系和生产力之间的矛盾，上层建筑和经济基础之间的矛盾。”社会主义社会的基本矛盾同以往社会的基本矛盾“具有根本不同的性质和情况”。这里所说的“不同的”“情况”是指", "options": {"A": "社会主义社会的矛盾反映在政治上可以划分为敌我矛盾和人民内部矛盾", "B": "社会主义社会基本矛盾运动是“又相适应又相矛盾”", "C": "社会主义社会的基本矛盾既是对抗性的又是非对抗性的", "D": "社会主义社会的所有矛盾都必须采用民主的方法来解决"}, "answer": ["B"], "note": "社会主义社会的基本矛盾同以往社会的基本矛盾“具有根本不同的性质和情况”。这里所说的“不同的”“情况”是指社会主义社会基本矛盾运动是“又相适应又相矛盾”", "sourcePages": [70], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-43", "subject": "毛中特", "chapter": 4, "chapterTitle": "第四章社会主义建设道路初步探索的理论成果", "type": "单选", "number": 43, "stem": "1957年2月，毛泽东作了《关于正确处理人民内部矛盾的问题》的报告，阐明社会主义社会的重大理论问题。毛泽东指出，用民主的方法解决人民内部矛盾，这是一个总方针。针对人民内部矛盾在具体实践中的不同情况，毛泽东提出了一系列具体方针、原则。在政治思想领域，毛泽东提出的解决人民内部矛盾的具体方针是", "options": {"A": "“团结一批评一团结”", "B": "“惩前后、治病救人”", "C": "“长期共存、互相监督”", "D": "统筹兼顾、适当安排"}, "answer": ["A"], "note": "在政治思想领域，毛泽东提出的解决人民内部矛盾的具体方针是：“团结一批评一团结”", "sourcePages": [70], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-44", "subject": "毛中特", "chapter": 4, "chapterTitle": "第四章社会主义建设道路初步探索的理论成果", "type": "单选", "number": 44, "stem": "20世纪50年代中期，毛泽东明确提出要走一条有别于苏联的中国工业化道路。走中国工业化道路主要是强调要正确处理", "options": {"A": "信息化和工业化的关系", "B": "工业化和农业现代化的关系", "C": "农业现代化和城镇化的关系", "D": "重工业和轻工业、农业的关系"}, "answer": ["D"], "note": "走中国工业化道路主要是强调要正确处理：重工业和轻工业、农业的关系", "sourcePages": [70], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-40", "subject": "毛中特", "chapter": 4, "chapterTitle": "第四章社会主义建设道路初步探索的理论成果", "type": "多选", "number": 40, "stem": "1956年4月和5月，毛泽东先后在中央政治局扩大会议和最高国务会议上，作了《论十大关系》的报告。《论十大关系》提出", "options": {"A": "以苏为鉴，独立自主地探索适合中国情况的社会主义建设道路", "B": "调动一切积极因素为社会主义事业服务", "C": "探索在中国实行改革开放的道路", "D": "“向外国学习”的口号"}, "answer": ["A", "B", "D"], "note": "《论十大关系》提出：以苏为鉴，独立自主地探索适合中国情况的社会主义建设道路；调动一切口牌积极因素为社会主义事业服务；“向外国学习”的口号", "sourcePages": [78], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-42", "subject": "毛中特", "chapter": 4, "chapterTitle": "第四章社会主义建设道路初步探索的理论成果", "type": "多选", "number": 42, "stem": "1957年2月，毛泽东在《关于正确处理人民内部矛盾的问题》的报告中提出了一系列正确处理人民内部矛盾的具体方针、原则，主要有", "options": {"A": "统筹兼顾、适当安排", "B": "有理、有利、有节", "C": "“百花齐放、百家争鸣”", "D": "“长期共存、互相监督”"}, "answer": ["A", "C", "D"], "note": "正确处理人民内部矛盾的具体方针、原则，主要有：统筹兼顾、适当安排；“百花齐放、百家争鸣”；“长期共存、互相监督”", "sourcePages": [78], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-43", "subject": "毛中特", "chapter": 4, "chapterTitle": "第四章社会主义建设道路初步探索的理论成果", "type": "多选", "number": 43, "stem": "走中国工业化道路的思想是党在社会主义建设道路初步探索中取得的理论成果之一。毛泽东所说的中国工业化道路，就是正确处理重工业和轻工业、农业的关系，也就是他在《论十大关系》中论述的第一大关系。为此，毛泽东提出了以农业为基础，以工业为主导，以农轻重为序发展国民经济的总方针，以及一整套“两条腿走路”的工业化发展思路，即", "options": {"A": "重工业和轻工业同时并举", "B": "中央工业和地方工业同时并举", "C": "沿海工业和内地工业同时并举", "D": "外资企业和内资企业同时并举"}, "answer": ["A", "B", "C"], "note": "毛泽东提出了以农业为基础，以工业为主导，以农轻重为序发展国民经济的总方针，以及一整套“两条腿走路”的工业化发展思路，即：重工业和轻工业同时并举；中央工业和地方工业同时并举；沿海工业和内地工业同时并举", "sourcePages": [78], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-45", "subject": "毛中特", "chapter": 4, "chapterTitle": "第四章社会主义建设道路初步探索的理论成果", "type": "多选", "number": 45, "stem": "以毛泽东同志为主要代表的中国共产党人对社会主义建设道路的初步探索", "options": {"A": "彻底摆脱了苏联模式的影响", "B": "巩固和发展了我国的社会主义制度", "C": "丰富了科学社会主义的理论和实践", "D": "为开创中国特色社会主义提供了宝贵经验、理论准备、物质基础"}, "answer": ["B", "C", "D"], "note": "中国共产党人对社会主义建设道路的初步探索巩固和发展了我国的社会主义制度；丰富了科学社会主义的理论和实践；为开创中国特色社会主义提供了宝贵经验、理论准备、物质基础", "sourcePages": [79], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-45", "subject": "毛中特", "chapter": 5, "chapterTitle": "第五章中国特色社会主义理论体系的形成发展", "type": "单选", "number": 45, "stem": "在中国特色社会主义理论体系的形成过程中，邓小平在党的十二大上提出的一个具有里程碑意义的重大命题是", "options": {"A": "什么是社会主义、怎样建设社会主义", "B": "建设有中国特色的社会主义", "C": "改革是中国的第二次革命", "D": "中国问题的关键在于党"}, "answer": ["B"], "note": "邓小平在党的十二大上提出的一个具有里程碑意义的重大命题是：建设有中国特色的社会主义", "sourcePages": [70], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-46", "subject": "毛中特", "chapter": 5, "chapterTitle": "第五章中国特色社会主义理论体系的形成发展", "type": "单选", "number": 46, "stem": "邓小平理论是逐步形成和发展起来的。邓小平理论逐步走向成熟始于", "options": {"A": "党的十一届三中全会", "B": "党的十二大", "C": "党的十三大", "D": "1992年南方谈话"}, "answer": ["D"], "note": "邓小平理论逐步走向成熟始于：1992年南方谈话", "sourcePages": [70], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-46", "subject": "毛中特", "chapter": 5, "chapterTitle": "第五章中国特色社会主义理论体系的形成发展", "type": "多选", "number": 46, "stem": "实践没有止境，理论创新也没有止境。改革开放以来，我们党继续推进马克思主义中国化时代化，形成和发展了中国特色社会主义理论体系。中国特色社会主义理论体系逐步形成和发展的社会历史条件是", "options": {"A": "对国际形势深刻变化和世界发展新趋势的深刻把握", "B": "对建设社会主义正反两方面经验的认真总结", "C": "对我国发展历史方位的科学判断", "D": "对中国特色社会主义建设实践经验的科学总结"}, "answer": ["A", "B", "C", "D"], "note": "中国特色社会主义理论体系逐步形成和发展的社会历史条件是：对国际形势深刻变化和世界发展新趋势的深刻把握；对建设社会主义正反两方面经验的认真总结；对我国发展历史方位的科学判断；对中国特色社会主义建设实践经验的科学总结", "sourcePages": [79], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-47", "subject": "毛中特", "chapter": 5, "chapterTitle": "第五章中国特色社会主义理论体系的形成发展", "type": "多选", "number": 47, "stem": "中国特色社会主义理论体系是中国共产党长期探索的伟大理论创造，开辟了马克思主义中国化时代化新境界。中国特色社会主义理论体系是", "options": {"A": "全党全国各族人民团结奋斗的共同思想基础", "B": "战胜来自政治、经济、社会和自然界等一切风险和挑战的精神支柱", "C": "全面推进中华民族伟大复兴的根本指针", "D": "我们党最可宝贵的政治和精神财富"}, "answer": ["A", "B", "C", "D"], "note": "中国特色社会主义理论体系是：全党全国各族人民团结奋斗的共同思想基础；战胜来自政治、经济、社会和自然界等一切风险和挑战的精神支柱；全面推进中华民族伟大复兴的根本指针；我们党最可宝贵的政治和精神财富", "sourcePages": [79], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-47", "subject": "毛中特", "chapter": 6, "chapterTitle": "第六章邓小平理论", "type": "单选", "number": 47, "stem": "邓小平在领导改革开放和现代化建设这一新的革命过程中，不断提出和反复思考的首要的基本的理论问题是", "options": {"A": "什么是社会主义、怎样建设社会主义", "B": "建设什么样的党、怎样建设党", "C": "实现什么样的发展、怎样发展", "D": "坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义"}, "answer": ["A"], "note": "邓小平在领导改革开放和现代化建设这一新的革命过程中，不断提出和反复思考的首要的基本的理论问题是：什么是社会主义、怎样建设社会主义", "sourcePages": [71], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-48", "subject": "毛中特", "chapter": 6, "chapterTitle": "第六章邓小平理论", "type": "单选", "number": 48, "stem": "所谓精髓，对于理论而言，指的是能使这一理论得以形成和发展并贯穿始终，同时又体现在这一理论中最本质的东西。邓小平理论的精髓是", "options": {"A": "解放思想、实事求是", "B": "发展是硬道理", "C": "什么是社会主义、怎样建设社会主义", "D": "社会主义市场经济理论"}, "answer": ["A"], "note": "邓小平理论的精髓是：解放思想、实事求是", "sourcePages": [71], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-49", "subject": "毛中特", "chapter": 6, "chapterTitle": "第六章邓小平理论", "type": "单选", "number": 49, "stem": "在邓小平指导下，党的十一届三中全会重新确立解放思想、实事求是的思想路线，停止使用“以阶级斗争为纲”的错误提法，作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策，开启了改革开放和社会主义现代化建设新时期，实现了党的历史上具有深远意义的伟大转折。党在改革开放和社会主义现代化建设新时期实现的最根本的拨乱反正是", "options": {"A": "坚持四项基本原则", "B": "坚持改革开放", "C": "坚持以经济建设为中心", "D": "坚持中国特色社会主义"}, "answer": ["C"], "note": "党在改革开放和社会主义现代化建设新时期实现的最根本的拨乱反正是坚持以经济建设为中心", "sourcePages": [71], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-50", "subject": "毛中特", "chapter": 6, "chapterTitle": "第六章邓小平理论", "type": "单选", "number": 50, "stem": "邓小平明确指出：“改革是中国的第二次革命。”所谓第二次革命，是与中国共产党领导的第次革命相对而言的。社会主义改革的性质是", "options": {"A": "社会主义基本制度的改革", "B": "社会主义经济运行方式的改变", "C": "社会主义原有体制的修补", "D": "社会主义制度的自我完善和发展"}, "answer": ["D"], "note": "社会主义改革的性质是：社会主义制度的自我完善和发展", "sourcePages": [71], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-51", "subject": "毛中特", "chapter": 6, "chapterTitle": "第六章邓小平理论", "type": "单选", "number": 51, "stem": "1992年党的十四大之所以能够明确地把建立社会主义市场经济体制作为我国经济体制改革目标，是因为在社会主义可以实行市场经济的理论上有了重大突破。这个重大突破就是认识到", "options": {"A": "市场经济是有国家宏观调控的经济", "B": "市场经济是法治经济", "C": "市场经济与计划经济是可以结合的", "D": "市场经济本身不具有制度属性"}, "answer": ["D"], "note": "党的十四大在社会主义可以实行市场经济的理论上有了重大突破。这个重大突破就是认识到：市场经济本身不具有制度属性", "sourcePages": [71], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-52", "subject": "毛中特", "chapter": 6, "chapterTitle": "第六章邓小平理论", "type": "单选", "number": 52, "stem": "社会主义市场经济理论认为，计划经济与市场经济属于", "options": {"A": "不同的资源配置手段", "B": "不同的经济增长方式", "C": "不同的经济制度的范畴", "D": "不同的生产关系的范畴"}, "answer": ["A"], "note": "社会主义市场经济理论认为，计划经济与市场经济属于：不同的资源配置手段", "sourcePages": [71], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-48", "subject": "毛中特", "chapter": 6, "chapterTitle": "第六章邓小平理论", "type": "多选", "number": 48, "stem": "邓小平关于社会主义本质的科学概括，对于我们在坚持社会主义基本制度的基础上推进改革，指导改革沿着合乎社会主义本质要求的方向发展，对于建设中国特色社会主义，具有重大的政治意义、理论意义和实践意义。这一科学概括", "options": {"A": "既坚持了科学社会主义的基本原则，又赋予其鲜明的时代特色", "B": "反映了人民的利益和时代的要求", "C": "廓清了不合乎时代进步和社会发展规律的模糊观念", "D": "摆脱了长期以来拘泥于具体模式而忽略社会主义本质的错误倾向"}, "answer": ["A", "B", "C", "D"], "note": "邓小平关于社会主义本质的科学概括：既坚持了科学社会主义的基本原则，又赋予其鲜明的时代特色；反映了人民的利益和时代的要求；廓清了不合乎时代进步和社会发展规律的模糊观念；摆脱了长期以来拘泥于具体模式而忽略社会主义本质的错误倾向", "sourcePages": [79], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-49", "subject": "毛中特", "chapter": 6, "chapterTitle": "第六章邓小平理论", "type": "多选", "number": 49, "stem": "党的十一届三中全会以后，以邓小平同志为主要代表的中国共产党人重新确立并丰富发展了实事求是的思想路线，提出了一系列有利于增强党的团结和调动一切积极因素的方针政策。党的思想路线的重新确立，解决了一系列重大理论和实践问题。具体来说就是，坚持解放思想、实事求是", "options": {"A": "有力推动和保证了拨乱反正的进行", "B": "破除了僵化的社会主义模式观念，坚持走自己的路", "C": "一切从社会主义初级阶段的实际出发", "D": "坚持以“三个有利于”作为检验一切工作是非得失的根本标准"}, "answer": ["A", "B", "C", "D"], "note": "坚持解放思想、实事求是有力推动和保证了拨乱反正的进行；破除了僵化的社会主义模式观念，坚持走自已的路；一切从社会主义初级阶段的实际出发；坚持以“三个有利于”作为检验一切工作是非得失的根本标准", "sourcePages": [79], "answerSource": "配套资料与题目核对"}, {"id": "毛中特-多选-50", "subject": "毛中特", "chapter": 6, "chapterTitle": "第六章邓小平理论", "type": "多选", "number": 50, "stem": "社会主义制度建立以后，也有一个如何认清国情、正确判断我国社会所处历史方位的问题。社会主义初级阶段理论", "options": {"A": "揭示了当代中国的历史方位，为建设中国特色社会主义提供了总依据", "B": "是对马克思主义关于社会主义发展阶段理论的重大发展和重大突破", "C": "使我们党对社会主义建设的长期性、复杂性、艰巨性有了更加清醒的认识", "D": "正确回答了邓小平理论首要的基本的理论问题"}, "answer": ["A", "B", "C"], "note": "社会主义初级阶段理论：揭示了当代中国的历史方位，为建设中国特色社会主义提供了总依据；是对马克思主义关于社会主义发展阶段理论的重大发展和重大突破；使我们党对社会主义建设的长期性、复杂性、艰巨性有了更加清醒的认识", "sourcePages": [79], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-51", "subject": "毛中特", "chapter": 6, "chapterTitle": "第六章邓小平理论", "type": "多选", "number": 51, "stem": "改革是一项崭新的事业，是一个大试验。判断改革和各方面工作的是非得失，归根到底，主要看是否有利于", "options": {"A": "发展社会主义社会的生产力", "B": "增强社会主义国家的综合国力", "C": "提高人民生活水平", "D": "完善社会主义的生产关系"}, "answer": ["A", "B", "C"], "note": "判断改革和各方面工作的是非得失，归根到底，主要看是否有利于：发展社会主义社会的生产力；增强社会主义国家的综合国力；提高人民生活水平", "sourcePages": [80], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-52", "subject": "毛中特", "chapter": 6, "chapterTitle": "第六章邓小平理论", "type": "多选", "number": 52, "stem": "在南方谈话中，邓小平明确提出：“计划经济不等于社会主义，资本主义也有计划；市场经济不等于资本主义，社会主义也有市场。”邓小平这一重要论断蕴含着的社会主义市场经济理论的内涵有", "options": {"A": "计划经济和市场经济不是划分社会制度的标志", "B": "计划和市场都是经济手段", "C": "市场经济作为资源配置手段本身不具有制度属性", "D": "市场经济和不同的社会制度结合所表现出的性质是相同的"}, "answer": ["A", "B", "C"], "note": "社会主义市场经济理论的内涵有计划经济和市场经济不是划分社会制度的标志；计划和市场都是经济手段；市场经济作为资源配置手段本身不具有制度属性", "sourcePages": [80], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-54", "subject": "毛中特", "chapter": 6, "chapterTitle": "第六章邓小平理论", "type": "多选", "number": 54, "stem": "邓小平理论是马克思列宁主义基本原理同当代中国实际和时代特征相结合的产物，是对马克思列宁主义、毛泽东思想的继承和发展，是全党全国人民集体智慧的结晶。邓小平理论是", "options": {"A": "中国特色社会主义理论体系的开篇之作", "B": "中国共产党和中国人民宝贵的精神财富", "C": "中国革命、建设、改革的科学指南", "D": "党和国家必须长期坚持的指导思想"}, "answer": ["A", "B", "D"], "note": "邓小平理论是：中国特色社会主义理论体系的开篇之作；中国共产党和中国人民宝贵的精神财富；党和国家必须长期坚持的指导思想", "sourcePages": [80], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-53", "subject": "毛中特", "chapter": 7, "chapterTitle": "第七章“三个代表”重要思想", "type": "单选", "number": 53, "stem": "“三个代表”重要思想创造性回答了", "options": {"A": "什么是社会主义、怎样建设社会主义的问题", "B": "建设什么样的党、怎样建设党的问题", "C": "实现什么样的发展、怎样发展的问题", "D": "实现什么样的现代化、怎样实现现代化的问题"}, "answer": ["B"], "note": "“三个代表”重要思想创造性回答了：建设什么样的党、怎样建设党的问题", "sourcePages": [71], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-54", "subject": "毛中特", "chapter": 7, "chapterTitle": "第七章“三个代表”重要思想", "type": "单选", "number": 54, "stem": "要正确认识和处理改革、发展、稳定的关系，改革是动力，发展是目的，稳定是前提。处理改革、发展、稳定关系的重要结合点是", "options": {"A": "把改革的力度、发展的速度和社会可承受的程度统一起来", "B": "不断改善人民生活", "C": "在社会稳定中推进改革发展", "D": "通过改革发展促进社会稳定"}, "answer": ["B"], "note": "处理改革、发展、稳定关系的重要结合点是：不断改善人民生活", "sourcePages": [71], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-55", "subject": "毛中特", "chapter": 7, "chapterTitle": "第七章“三个代表”重要思想", "type": "多选", "number": 55, "stem": "发展是党执政兴国的第一要务。关于正确认识和处理改革、发展、稳定的关系，以下说法正确的有", "options": {"A": "改革是动力，发展是目的，稳定是前提", "B": "要把改革的力度、发展的速度和社会可承受的程度统一起来", "C": "把不断改善人民生活作为处理改革、发展、稳定关系的重要结合点", "D": "在社会稳定中推进改革发展，通过改革发展促进社会稳定"}, "answer": ["A", "B", "C", "D"], "note": "正确认识和处理改革、发展、稳定的关系，改革是动力，发展是目的，稳定是前提；要把改革的力度、发展的速度和社会可承受的程度统一起来；把不断改善人民生活作为处理改革、发展、稳定关系的重要结合点；在社会稳定中推进改革发展，通过改革发展促进社会稳定", "sourcePages": [80], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-55", "subject": "毛中特", "chapter": 8, "chapterTitle": "第八章科学发展观", "type": "单选", "number": 55, "stem": "科学发展观的基本要求是", "options": {"A": "推动经济社会发展", "B": "以人为本", "C": "全面协调可持续", "D": "统筹兼顾"}, "answer": ["C"], "note": "科学发展观的基本要求是：全面协调可持续", "sourcePages": [72], "answerSource": "帽子题配套资料"}, {"id": "毛中特-单选-56", "subject": "毛中特", "chapter": 8, "chapterTitle": "第八章科学发展观", "type": "单选", "number": 56, "stem": "坚持中国特色社会主义政治发展道路，最根本的是要", "options": {"A": "坚持党的领导、人民当家作主、依法治国有机统一", "B": "坚持政治安全、人民安全、国家利益至上有机统一", "C": "坚持历史和现实、理论和实践、形式和内容有机统一", "D": "坚持人民民主和国家意志有机统一"}, "answer": ["A"], "note": "坚持中国特色社会主义政治发展道路，最根本的是要：坚持党的领导、人民当家作主、依法治国有机统一", "sourcePages": [72], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-58", "subject": "毛中特", "chapter": 8, "chapterTitle": "第八章科学发展观", "type": "多选", "number": 58, "stem": "科学发展观创造性回答了新形势下实现什么样的发展、怎样发展等重大问题。科学发展观的集中概括是", "options": {"A": "第一要义是发展", "B": "核心立场是以人为本", "C": "基本要求是全面协调可持续", "D": "根本方法是统筹兼顾"}, "answer": ["A", "B", "C", "D"], "note": "科学发展观的集中概括是：第一要义是发展；核心立场是以人为本；基本要求是全面协调可持续；根本方法是统筹兼顾", "sourcePages": [81], "answerSource": "帽子题配套资料"}, {"id": "毛中特-多选-59", "subject": "毛中特", "chapter": 8, "chapterTitle": "第八章科学发展观", "type": "多选", "number": 59, "stem": "科学发展观最鲜明的精神实质是", "options": {"A": "解放思想", "B": "实事求是", "C": "与时俱进", "D": "求真务实"}, "answer": ["A", "B", "C", "D"], "note": "科学发展观最鲜明的精神实质是：解放思想；实事求是；与时俱进；求真务实", "sourcePages": [81], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-1", "subject": "新思想", "chapter": 0, "chapterTitle": "导论", "type": "单选", "number": 1, "stem": "“十个明确”“十四个坚持”“十三个方面成就”“六个必须坚持”内在贯通、有机统一，共同构成了习近平新时代中国特色社会主义思想的科学体系。其中，构成了这一思想体系的四梁八柱，发挥着统摄作用的是", "options": {"A": "“十个明确”", "B": "“十四个坚持”", "C": "“十三个方面成就”", "D": "“六个必须坚持”"}, "answer": ["A"], "note": "构成了新思想体系的四梁八柱，发挥着统摄作用的是：“十个明确”", "sourcePages": [82], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-2", "subject": "新思想", "chapter": 0, "chapterTitle": "导论", "type": "单选", "number": 2, "stem": "党的二十大提出的“六个必须坚持”，是习近平新时代中国特色社会主义思想的世界观、方法论和贯穿其中的立场观点方法的重要体现。在这“六个必须坚持”中，必须坚持自信自立是", "options": {"A": "根本价值立场", "B": "内在精神特质", "C": "鲜明理论品格", "D": "重要实践要求"}, "answer": ["B"], "note": "在“六个必须坚持”中，必须坚持自信自立是：内在精神特质", "sourcePages": [82], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-1", "subject": "新思想", "chapter": 0, "chapterTitle": "导论", "type": "多选", "number": 1, "stem": "习近平新时代中国特色社会主义思想是马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合的重大成果，是坚持“两个结合”的光辉典范。“两个结合”", "options": {"A": "是我们党在探索中国特色社会主义道路中得出的规律性认识", "B": "让中国特色社会主义道路有了更加宏阔深远的历史纵深", "C": "拓展了中国特色社会主义道路的文化根基", "D": "开辟了广阔的理论和实践创新空间"}, "answer": ["A", "B", "C", "D"], "note": "“两个结合”是我们党在探索中国特色社会主义道路中得出的规律性认识；让中国特色社会主义道路有了更加宏阔深远的历史纵深；拓展了中国特色社会主义道路的文化根基；开辟了广阔的理论和实践创新空间。", "sourcePages": [93], "answerSource": "配套资料与题目核对"}, {"id": "新思想-多选-2", "subject": "新思想", "chapter": 0, "chapterTitle": "导论", "type": "多选", "number": 2, "stem": "习近平新时代中国特色社会主义思想是马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合的重大成果，是坚持“两个结合”的光辉典范。“两个结合”是", "options": {"A": "开辟和发展中国特色社会主义的必由之路", "B": "推进马克思主义中国化时代化的根本途径", "C": "我们取得成功的最大法宝", "D": "我们党坚定信仰信念、把握历史主动的根本所在"}, "answer": ["A", "B", "C"], "note": "“两个结合”是：开辟和发展中国特色社会主义的必由之路；推进马克思主义中国化时代化的根本途径；我们取得成功的最大法宝", "sourcePages": [93], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-3", "subject": "新思想", "chapter": 0, "chapterTitle": "导论", "type": "多选", "number": 3, "stem": "历史正反两方面的经验表明，“两个结合”是我们取得成功的最大法宝。“结合”不是“拼盘”，不是简单的“物理反应”，而是深刻的“化学反应”。“结合”的结果是", "options": {"A": "造就了一个有机统一的新的文化生命体", "B": "让马克思主义成为中国的", "C": "让中华优秀传统文化成为现代的", "D": "让经由“结合”而形成的新文化成为中国式现代化的文化形态"}, "answer": ["A", "B", "C", "D"], "note": "“结合”的结果是：造就了一个有机统一的新的文化生命体；让马克思主义成为中国的；让中华优秀传统文化成为现代的；让经由“结合”而形成的新文化成为中国式现代化的文化形态", "sourcePages": [93], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-4", "subject": "新思想", "chapter": 0, "chapterTitle": "导论", "type": "多选", "number": 4, "stem": "习近平总书记总结党百年来的理论创新经验，在强调坚持“第一个结合”的基础上，明确提出把马克思主义基本原理同中华优秀传统文化相结合的重大命题，这是又一次的思想解放。“两个结合”", "options": {"A": "是对坚持和发展马克思主义作出的重大理论贡献", "B": "表明我们党对中国道路、理论、制度的认识达到了新高度", "C": "表明我们党的历史自信、文化自信达到了新高度", "D": "表明我们党在传承中华优秀传统文化中推进理论创新的自觉性达到了新高度"}, "answer": ["A", "B", "C", "D"], "note": "“两个结合”：是对坚持和发展马克思主义作出的重大理论贡献；表明我们党对中国道路、理论、制度的认识达到了新高度；表明我们党的历史自信、文化自信达到了新高度；表明我们党在传承中华优秀传统文化中推进理论创新的自觉性达到了新高度", "sourcePages": [94], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-5", "subject": "新思想", "chapter": 0, "chapterTitle": "导论", "type": "多选", "number": 5, "stem": "习近平新时代中国特色社会主义思想坚持科学社会主义基本原则，深刻总结和充分运用党百年奋斗的历史经验，根据时代和实践发展变化，科学回答了重大时代课题，以全新的视野深化了对共产党执政规律、社会主义建设规律、人类社会发展规律的认识。习近平新时代中国特色社会主义思想科学回答的重大时代课题是", "options": {"A": "新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义", "B": "建设什么样的社会主义现代化强国、怎样建设社会主义现代化强国", "C": "建设什么样的长期执政的马克思主义政党、怎样建设长期执政的马克思主义政党", "D": "实现什么样的发展、怎样发展"}, "answer": ["A", "B", "C"], "note": "新思想科学回答的重大时代课题是：新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义；建设什么样的社会主义现代化强国、怎样建设社会主义现代化强国；建设什么样的长期执政的马克思主义政党、怎样建设长期执政的马克思主义政党", "sourcePages": [94], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-7", "subject": "新思想", "chapter": 0, "chapterTitle": "导论", "type": "多选", "number": 7, "stem": "以习近平同志为主要代表的中国共产党人，坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，坚持毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观，深刻总结并充分运用党成立以来的历史经验，从新的实际出发，创立了习近平新时代中国特色社会主义思想。习近平新时代中国特色社会主义思想", "options": {"A": "是当代中国马克思主义、21世纪马克思主义", "B": "是中华文化和中国精神的时代精华", "C": "实现了马克思主义中国化时代化新的飞跃", "D": "是新时代党和国家事业发展的根本遵循"}, "answer": ["A", "B", "C", "D"], "note": "新思想：是当代中国马克思主义、21世纪马克思主义；是中华文化和中国精神的时代精华；实现了马克思主义中国化时代化新的飞跃；是新时代党和国家事业发展的根本遵循", "sourcePages": [94], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-9", "subject": "新思想", "chapter": 0, "chapterTitle": "导论", "type": "多选", "number": 9, "stem": "党的十八届六中全会明确了习近平同志党中央的核心、全党的核心地位，党的十九大把习近平新时代中国特色社会主义思想确立为党必须长期坚持的指导思想。“两个确立”对新时代党和国家事业发展、对推进中华民族伟大复兴历史进程具有决定性意义。“两个确立”", "options": {"A": "是党在新时代取得的重大政治成果", "B": "反映了全党全军全国各族人民共同心愿", "C": "是新时代党和国家事业取得历史性成就、发生历史性变革的决定性因素", "D": "是党和人民应对一切不确定性的最大确定性、最大底气、最大保证"}, "answer": ["A", "B", "C", "D"], "note": "两个确立”：是党在新时代取得的重大政治成果；反映了全党全军全国各族人民共同心愿；是新时代党和国家事业取得历史性成就、发生历史性变革的决定性因素；是党和人民应对一切不确定性的最大确定性、最大底气、最大保证", "sourcePages": [94], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-3", "subject": "新思想", "chapter": 1, "chapterTitle": "第一章新时代坚持和发展中国特色社会主义", "type": "单选", "number": 3, "stem": "新时代坚持和发展中国特色社会主义，必须坚定道路自信、理论自信、制度自信、文化自信。我们坚定“四个自信”的理论支撑和根本依据是", "options": {"A": "世界百年变局加速演进", "B": "江山就是人民，人民就是江山", "C": "实现中华民族伟大复兴进入不可逆转的历史进程", "D": "社会主义必然代替资本主义的客观规律"}, "answer": ["D"], "note": "坚定“四个自信”的理论支撑和根本依据是：社会主义必然代替资本主义的客观规律", "sourcePages": [82], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-4", "subject": "新思想", "chapter": 1, "chapterTitle": "第一章新时代坚持和发展中国特色社会主义", "type": "单选", "number": 4, "stem": "坚定中国特色社会主义道路自信、理论自信、制度自信，说到底是要坚定", "options": {"A": "政治自信", "B": "历史自信", "C": "战略自信", "D": "文化自信"}, "answer": ["D"], "note": "坚定中国特色社会主义道路自信、理论自信、制度自信，说到底是要坚定：文化自信", "sourcePages": [82], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-5", "subject": "新思想", "chapter": 1, "chapterTitle": "第一章新时代坚持和发展中国特色社会主义", "type": "单选", "number": 5, "stem": "中国特色社会主义进入新时代，是长期以来特别是党的十八大以来我们党领导人民不懈奋斗的必然结果，是我们党在科学把握形势和实践发展变化基础上作出的重大判断。新时代是我国发展新的历史方位，标志着中国特色社会主义事业进入了新的发展阶段。中国特色社会主义进入新时代重大判断的基本依据是", "options": {"A": "我国社会主要矛盾发生新变化", "B": "党的主要任务发生新变化", "C": "中国和世界关系发生新变化", "D": "发展理念和思路发生新变化"}, "answer": ["A"], "note": "中国特色社会主义进入新时代重大判断的基本依据是：我国社会主要矛盾发生新变化", "sourcePages": [82], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-6", "subject": "新思想", "chapter": 1, "chapterTitle": "第一章新时代坚持和发展中国特色社会主义", "type": "单选", "number": 6, "stem": "“四个全面”战略布局，是新的时代条件下坚持和发展中国特色社会主义、推进改革开放和社会主义现代化建设的战略执择。“四个全面”战略布局既有战略目标又有战略举措，每个“全面”之间具有紧密的内在逻辑，是一个整体战略部署的有序展开。在“四个全面”中居于引领地位的是", "options": {"A": "全面深化改革", "B": "全面依法治国", "C": "全面从严治党", "D": "全面建设社会主义现代化国家"}, "answer": ["D"], "note": "在“四个全面”中居于引领地位的是：全面建设社会主义现代化国家", "sourcePages": [82], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-10", "subject": "新思想", "chapter": 1, "chapterTitle": "第一章新时代坚持和发展中国特色社会主义", "type": "多选", "number": 10, "stem": "改革开放以来，我们取得一切成绩和进步的根本原因，归结起来就是", "options": {"A": "开辟了中国特色社会主义道路", "B": "形成了中国特色社会主义理论体系", "C": "确立了中国特色社会主义制度", "D": "发展了中国特色社会主义文化"}, "answer": ["A", "B", "C", "D"], "note": "改革开放以来，我们取得一切成绩和进步的根本原因，归结起来就是：开辟了中国特色社会主义道路；形成了中国特色社会主义理论体系；确立了中国特色社会主义制度；发展了中国特色社会主义文化", "sourcePages": [95], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-11", "subject": "新思想", "chapter": 1, "chapterTitle": "第一章新时代坚持和发展中国特色社会主义", "type": "多选", "number": 11, "stem": "新时代坚持和发展中国特色社会主义，必须坚定道路自信、理论自信、制度自信、文化自信。坚定文化自信，就是坚信中国特色社会主义文化", "options": {"A": "积淀着中华民族最深层的精神追求", "B": "代表着中华民族独特的精神标识", "C": "反映了世界各国人民普遍认同的价值理念的最大公约数", "D": "是激励全党全国各族人民奋勇前进的强大精神力量"}, "answer": ["A", "B", "D"], "note": "坚定文化自信，就是坚信中国特色社会主义文化积淀着中华民族最深层的精神追求；代表着中华民族独特的精神标识；是激励全党全国各族人民奋勇前进的强大精神力量", "sourcePages": [95], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-12", "subject": "新思想", "chapter": 1, "chapterTitle": "第一章新时代坚持和发展中国特色社会主义", "type": "多选", "number": 12, "stem": "坚定中国特色社会主义道路自信、理论自信、制度自信，说到底是要坚定文化自信。文化自信是", "options": {"A": "更基础、更广泛、更深厚的自信", "B": "改革开放以来我们取得一切成绩和进步的根本原因", "C": "我们坚定“四个自信”的理论支撑和根本依据", "D": "一个国家、一个民族发展中最基本、最深沉、最持久的力量"}, "answer": ["A", "D"], "note": "文化自信是：更基础、更广泛、更深厚的自信；一个国家、一个民族发展中最基本、最深沉、最持久的力量", "sourcePages": [95], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-13", "subject": "新思想", "chapter": 1, "chapterTitle": "第一章新时代坚持和发展中国特色社会主义", "type": "多选", "number": 13, "stem": "经过长期努力，中国特色社会主义进入了新时代，这是我国发展新的历史方位。中国特色社会主义进入了新时代有着充分的依据，它是", "options": {"A": "我国社会主要矛盾发生新变化的反映", "B": "党的主要任务发生新变化的反映", "C": "中国和世界关系发生新变化的反映", "D": "我国进入新发展阶段的反映"}, "answer": ["A", "B", "C"], "note": "中国特色社会主义进入了新时代有着充分的依据，它是我国社会主要矛盾发生新变化的反映；党的主要任务发生新变化的反映；中国和世界关系发生新变化的反映", "sourcePages": [95], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-14", "subject": "新思想", "chapter": 1, "chapterTitle": "第一章新时代坚持和发展中国特色社会主义", "type": "多选", "number": 14, "stem": "中国特色社会主义进入新时代，我国社会主要矛盾已经转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾。新时代我国社会主要矛盾的变化", "options": {"A": "是在社会主义初级阶段中发生的变化", "B": "是关系全局的历史性变化", "C": "没有改变我国仍处于并将长期处于社会主义初级阶段的基本国情", "D": "正确反映了我国全面建成小康社会之后的新特点"}, "answer": ["A", "B", "C"], "note": "新时代我国社会主要矛盾的变化：是在社会主义初级阶段中发生的变化；是关系全局的历史性变化；没有改变我国仍处于并将长期处于社会主义初级阶段的基本国情", "sourcePages": [95], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-15", "subject": "新思想", "chapter": 1, "chapterTitle": "第一章新时代坚持和发展中国特色社会主义", "type": "多选", "number": 15, "stem": "新时代的伟大变革，在党史、新中国史、改革开放史、社会主义发展史、中华民族发展史上具有的里程碑意义主要有", "options": {"A": "中国共产党在革命性锻造中更加坚强有力", "B": "中国人民的前进动力更加强大、奋斗精神更加昂扬、必胜信念更加坚定", "C": "实现中华民族伟大复兴进入不可逆转的历史进程", "D": "科学社会主义在21世纪的中国焕发出新的蓬勃生机"}, "answer": ["A", "B", "C", "D"], "note": "新时代的伟大变革，在“四史”上具有的里程碑意义主要有中国共产党在革命性锻造中更加坚强有力；中国人民的前进动力更加强大、奋斗精神更加昂扬、必胜信念更加坚定；实现中华民族伟大复兴进入不可逆转的历史进程；科学社会主义在21世纪的中国焕发出新的蓬勃生机", "sourcePages": [95], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-8", "subject": "新思想", "chapter": 2, "chapterTitle": "第二章以中国式现代化全面推进中华民族伟大复兴", "type": "单选", "number": 8, "stem": "在长期实践过程中，党领导人民不懈探索现代化道路，取得了社会主义现代化建设的伟大成就，用几十年时间走完了发达国家几百年走过的工业化历程。我国现代化建设的出发点和落脚点是", "options": {"A": "完善和发展中国特色社会主义制度", "B": "增进民生福祉、促进社会公平", "C": "实现人民对美好生活的向往", "D": "实现高质量发展"}, "answer": ["C"], "note": "我国现代化建设的出发点和落脚点是：实现人民对美好生活的向往", "sourcePages": [83], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-16", "subject": "新思想", "chapter": 2, "chapterTitle": "第二章以中国式现代化全面推进中华民族伟大复兴", "type": "多选", "number": 16, "stem": "中国共产党团结带领中国人民追求民族复兴的历史，也是一部不断探索现代化道路的历史。在新中国成立特别是改革开放以来长期探索和实践基础上，经过党的十八大以来在理论和实践上的创新突破，我们成功推进和拓展了中国式现代化。中国式现代化", "options": {"A": "既基于自身国情、又借鉴各国经验", "B": "既传承历史文化、又融合现代文明", "C": "是具有中国特色、符合中国实际的现代化", "D": "是强国建设、民族复兴的唯一正确道路"}, "answer": ["A", "B", "C", "D"], "note": "中国式现代化：：既基于自身国情、又借鉴各国经验；既传承历史文化、又融合现代文明；是具有中国特色、符合中国实际的现代化；是强国建设、民族复兴的唯一正确道路", "sourcePages": [95], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-17", "subject": "新思想", "chapter": 2, "chapterTitle": "第二章以中国式现代化全面推进中华民族伟大复兴", "type": "多选", "number": 17, "stem": "中国式现代化是中国共产党领导的社会主义现代化。中国共产党领导的社会主义现代化，是对中国式现代化的定性，是管总、管根本的。党的领导直接关系中国式现代化的根本方向、前途命运、最终成败。党的领导", "options": {"A": "决定中国式现代化的根本性质", "B": "确保中国式现代化锚定奋斗目标行稳致远", "C": "激发建设中国式现代化的强劲动力", "D": "凝聚建设中国式现代化的磅礴力量"}, "answer": ["A", "B", "C", "D"], "note": "党的领导直接关系中国式现代化的根本方向、前途命运、最终成败。党的领导决定中国式现代化的根本性质；确保中国式现代化锚定奋斗目标行稳致远；激发建设中国式现代化的强劲动力；凝聚建设中国式现代化的磅礴力量", "sourcePages": [96], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-20", "subject": "新思想", "chapter": 2, "chapterTitle": "第二章以中国式现代化全面推进中华民族伟大复兴", "type": "多选", "number": 20, "stem": "习近平指出：“中国式现代化，是我们为如何唤醒‘睡狮”、实现民族复兴这个重大历史课题所给出的答案，是选择自己的道路、做自己的事情。”中国式现代化创造了人类文明新形态，是一种全新的人类文明形态。中国式现代化", "options": {"A": "打破了“现代化=西方化”的迷思，展现了不同于西方现代化模式的新图景", "B": "是对西方式现代化理论和实践的重大超越", "C": "为广大发展中国家提供了全新选择", "D": "是当代中国共产党人回答和解决关乎人类前途命运的时代之问的中国方案"}, "answer": ["A", "B", "C"], "note": "中国式现代化：打破了“现代化=西方化”的迷思，展现了不同于西方现代化模式的新图景；是对西方式现代化理论和实践的重大超越；为广大发展中国家提供了全新选择", "sourcePages": [96], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-9", "subject": "新思想", "chapter": 3, "chapterTitle": "第三章坚持党的全面领导", "type": "单选", "number": 9, "stem": "中国特色社会主义有很多特点和特征，其中最本质的特征是", "options": {"A": "以人民为中心", "B": "中国特色社会主义道路", "C": "中国特色社会主义制度", "D": "中国共产党领导"}, "answer": ["D"], "note": "中国特色社会主义最本质的特征是：中国共产党领导", "sourcePages": [83], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-10", "subject": "新思想", "chapter": 3, "chapterTitle": "第三章坚持党的全面领导", "type": "单选", "number": 10, "stem": "加强党的全面领导为新时代党和国家事业发展提供了坚强保证。坚持和加强党的全面领导，使党的政治领导力、思想引领力、群众组织力、社会号召力显著增强。马克思主义政党第一位的能力是", "options": {"A": "思想引领力", "B": "政治领导力", "C": "社会号召力", "D": "群众组织力"}, "answer": ["B"], "note": "马克思主义政党第一位的能力是：政治领导力", "sourcePages": [83], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-11", "subject": "新思想", "chapter": 3, "chapterTitle": "第三章坚持党的全面领导", "type": "单选", "number": 11, "stem": "党的领导是党和国家的根本所在、命脉所在，是全国各族人民的利益所系、命运所系。党的领导的最高原则是", "options": {"A": "党中央集中统一领导", "B": "制度治党、依规治党", "C": "坚定理想信念", "D": "勇于自我革命"}, "answer": ["A"], "note": "党的领导的最高原则是：党中央集中统一领导", "sourcePages": [83], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-12", "subject": "新思想", "chapter": 3, "chapterTitle": "第三章坚持党的全面领导", "type": "单选", "number": 12, "stem": "中国特色社会主义制度是一个严密完整的科学制度体系，起四梁八柱作用的是根本制度、基本制度、重要制度。其中，具有统领地位的是", "options": {"A": "人民代表大会制度这一根本政治制度", "B": "马克思主义在意识形态领域指导地位的根本制度", "C": "社会主义基本经济制度", "D": "党的领导制度"}, "answer": ["D"], "note": "中国特色社会主义制度中，具有统领地位的是：党的领导制度", "sourcePages": [83], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-21", "subject": "新思想", "chapter": 3, "chapterTitle": "第三章坚持党的全面领导", "type": "多选", "number": 21, "stem": "中国最大的国情就是中国共产党的领导。中国共产党领导", "options": {"A": "是中国人民和中华民族能够扭转近代以后的历史命运、取得今天伟大成就的最根本原因", "B": "是人民当家作主的可靠保障", "C": "关系中国特色社会主义的性质、方向和命运", "D": "是实现中华民族伟大复兴的根本保证"}, "answer": ["A", "B", "C", "D"], "note": "中国共产党领导：是中国人民和中华民族能够扭转近代以后的历史命运、取得今天伟大成就的最根本原因；是人民当家作主的可靠保障；关系中国特色社会主义的性质、方向和命运；是实现中华民族伟大复兴的根本保证", "sourcePages": [96], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-22", "subject": "新思想", "chapter": 3, "chapterTitle": "第三章坚持党的全面领导", "type": "多选", "number": 22, "stem": "中国共产党领导是中国特色社会主义制度的最大优势，这是因为", "options": {"A": "党的自身优势是中国特色社会主义制度优势的主要来源", "B": "党能够集中全党全国力量、凝聚全民族共同意志，确保中国特色社会主义制度的显著优势充分彰显", "C": "党的领导是全面的、系统的、整体的，事无巨细都去管", "D": "党在实践中不断推进马克思主义中国化时代化，为坚持和完善中国特色社会主义制度提供强大理论优势"}, "answer": ["A", "B", "D"], "note": "中国共产党领导是中国特色社会主义制度的最大优势，这是因为党的自身优势是中国特色社会主义制度优势的主要来源；党能够集中全党全国力量、凝聚全民族共同意志，确保中国特色社会主义制度的显著优势充分彰显；党在实践中不断推进马克思主义中国化时代化，为坚持和完善中国特色社会主义制度提供强大理论优势", "sourcePages": [96], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-23", "subject": "新思想", "chapter": 3, "chapterTitle": "第三章坚持党的全面领导", "type": "多选", "number": 23, "stem": "党的领导是党和国家的根本所在、命脉所在，是全国各族人民的利益所系、命运所系。中国共产党是最高政治领导力量，这是", "options": {"A": "在历史发展中形成的", "B": "由我国国家性质决定的", "C": "由我国的政治制度体系决定的", "D": "由中华民族伟大复兴事业决定的"}, "answer": ["A", "B", "C", "D"], "note": "中国共产党是最高政治领导力量，这是在历史发展中形成的；由我国国家性质决定的；由我国的政治制度体系决定的；由中华民族伟大复兴事业决定的", "sourcePages": [96], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-24", "subject": "新思想", "chapter": 3, "chapterTitle": "第三章坚持党的全面领导", "type": "多选", "number": 24, "stem": "坚持党的全面领导，必须依靠制度来保障。党的领导制度是", "options": {"A": "我国的根本政治制度", "B": "党的领导核心地位的必然反映和内在要求", "C": "中国特色社会主义制度体系的核心", "D": "国家治理体系和治理能力现代化的关键"}, "answer": ["B", "C", "D"], "note": "党的领导制度是：党的领导核心地位的必然反映和内在要求；中国特色社会主义制度体系的核心；国家治理体系和治理能力现代化的关键", "sourcePages": [96], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-13", "subject": "新思想", "chapter": 4, "chapterTitle": "第四章坚持以人民为中心", "type": "单选", "number": 13, "stem": "习近平指出：“时代是出卷人，我们是答卷人，人民是阅卷人。”我们党做好一切工作的价值取向和根本标准是", "options": {"A": "促进国民经济发展", "B": "维护国家长治久安", "C": "增强国际影响力", "D": "让群众满意"}, "answer": ["D"], "note": "党做好一切工作的价值取向和根本标准是：让群众满意", "sourcePages": [83], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-14", "subject": "新思想", "chapter": 4, "chapterTitle": "第四章坚持以人民为中心", "type": "单选", "number": 14, "stem": "发展是党执政兴国的第一要务。发展的出发点和落脚点是", "options": {"A": "满足人民对美好生活的新期待", "B": "不断实现理论和实践上的创新突破", "C": "完善中国特色社会主义制度", "D": "推进国家治理体系和治理能力现代化"}, "answer": ["A"], "note": "发展的出发点和落脚点是：满足人民对美好生活的新期待", "sourcePages": [84], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-15", "subject": "新思想", "chapter": 4, "chapterTitle": "第四章坚持以人民为中心", "type": "单选", "number": 15, "stem": "实现现代化是近代以来中国人民孜孜以求的宏愿。中国共产党团结带领中国人民追求民族复兴的历史，也是一部不断探索现代化道路的历史。现代化的最终目标是实现", "options": {"A": "中华民族伟大复兴", "B": "物质财富极大丰富", "C": "社会关系高度和谐", "D": "人自由而全面的发展"}, "answer": ["D"], "note": "现代化的最终目标是实现：人自由而全面的发展", "sourcePages": [84], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-26", "subject": "新思想", "chapter": 4, "chapterTitle": "第四章坚持以人民为中心", "type": "多选", "number": 26, "stem": "2024年10月，习近平在福建东山县考察期间，专门参观了谷文昌纪念馆，了解谷文昌同志感人事迹。习近平指出：“‘先祭谷公，后拜祖宗’，这是老百姓发自内心的敬仰。人民心里有一本账，金杯银杯不如老百姓的口碑。”“‘为官一任，造福一方’，只有走这条路，才是人间正道。”必须牢固树立和践行为民造福的政绩观，这是因为", "options": {"A": "让群众满意是我们党做好一切工作的价值取向和根本标准", "B": "人民是党的工作的最高裁决者和最终评判者", "C": "中国共产党把为民办事、为民造福作为最重要的政绩", "D": "全心全意为人民服务是党的根本宗旨"}, "answer": ["A", "B", "C", "D"], "note": "必须牢固树立和践行为民造福的政绩观，这是因为让群众满意是我们党做好一切工作的价值取向和根本标准；人民是党的工作的最高裁决者和最终评判者；中国共产党把为民办事、为民造福作为最重要的政绩；全心全意为人民服务是党的根本宗旨", "sourcePages": [97], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-28", "subject": "新思想", "chapter": 4, "chapterTitle": "第四章坚持以人民为中心", "type": "多选", "number": 28, "stem": "共同富裕是中国特色社会主义的本质要求，是中国式现代化的重要特征。要从全局角度来把握共同富裕。共同富裕是", "options": {"A": "全体人民共同富裕", "B": "人民群众物质生活和精神生活都富裕", "C": "所有人都同时富裕", "D": "所有地区同时达到一个富裕水准"}, "answer": ["A", "B"], "note": "共同富裕是：全体人民共同富裕；人民群众物质生活和精神生活都富裕", "sourcePages": [97], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-29", "subject": "新思想", "chapter": 4, "chapterTitle": "第四章坚持以人民为中心", "type": "多选", "number": 29, "stem": "坚持以人民为中心的发展思想，真正做到发展成果由人民共享，就必须落实到扎实推进全体人民共同富裕上，在推动共同富裕过程中促进人的全面发展。扎实推进共同富裕必须坚持的原则是", "options": {"A": "鼓励勤劳创新致富", "B": "坚持基本经济制度", "C": "尽力而为、量力而行", "D": "坚持循序渐进"}, "answer": ["A", "B", "C", "D"], "note": "扎实推进共同富裕必须坚持的原则是：鼓励勤劳创新致富；坚持基本经济制度；尽力而为、量力而行；坚持循序渐进", "sourcePages": [97], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-16", "subject": "新思想", "chapter": 5, "chapterTitle": "第五章全面深化改革开放", "type": "单选", "number": 16, "stem": "改革开放是当代中国最显著的特征、最壮丽的气象。习近平强调：“改革开放是决定当代中国命运的关键一招，也是决定实现‘两个一百年’奋斗目标、实现中华民族伟大复兴的关键一招。”改革开放的鲜明特征和首要任务是", "options": {"A": "解放思想", "B": "解放和发展社会生产力", "C": "解放和增强社会活力", "D": "以创新的思维和办法解决前进中的问题"}, "answer": ["B"], "note": "改革开放的鲜明特征和首要任务是：解放和发展社会生产力", "sourcePages": [84], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-17", "subject": "新思想", "chapter": 5, "chapterTitle": "第五章全面深化改革开放", "type": "单选", "number": 17, "stem": "全面深化改革开放，不是某个领域某个方面的变革，而是涉及党和国家事业发展全局的体制机制变革。全面深化改革开放的主线是", "options": {"A": "重要领域和关键环节改革", "B": "经济体制改革", "C": "制度建设", "D": "统筹改革、发展、稳定"}, "answer": ["C"], "note": "全面深化改革开放的主线是：制度建设", "sourcePages": [84], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-18", "subject": "新思想", "chapter": 5, "chapterTitle": "第五章全面深化改革开放", "type": "单选", "number": 18, "stem": "全面深化改革必须牢牢把握总目标，实施好“六个紧紧围绕”的路线图。统筹推进各领域各方面改革开放的突破口是", "options": {"A": "制度建设", "B": "重要领域和关键环节改革", "C": "经济体制改革", "D": "文化体制改革"}, "answer": ["B"], "note": "统筹推进各领域各方面改革开放的突破口是：重要领域和关键环节改革", "sourcePages": [84], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-19", "subject": "新思想", "chapter": 5, "chapterTitle": "第五章全面深化改革开放", "type": "单选", "number": 19, "stem": "在全面深化改革开放中，我们坚持了正确方法论，这是改革取得成就的原因之一。在改革方法论中，富有中国特色、符合中国国情的改革方法是", "options": {"A": "摸着石头过河", "B": "加强顶层设计", "C": "统筹改革发展稳定", "D": "重大改革于法有据"}, "answer": ["A"], "note": "在改革方法论中，富有中国特色、符合中国国情的改革方法是：摸着石头过河", "sourcePages": [84], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-20", "subject": "新思想", "chapter": 5, "chapterTitle": "第五章全面深化改革开放", "type": "单选", "number": 20, "stem": "正确处理好改革、发展、稳定的关系，是我国改革开放的一条重要经验。正确处理改革、发展、稳定关系的结合点是", "options": {"A": "不断开辟发展新领域、新赛道", "B": "人的自由而全面的发展", "C": "坚持守正创新", "D": "改善人民生活"}, "answer": ["D"], "note": "正确处理改革、发展、稳定关系的结合点是：改善人民生活", "sourcePages": [84], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-22", "subject": "新思想", "chapter": 5, "chapterTitle": "第五章全面深化改革开放", "type": "单选", "number": 22, "stem": "面对纷繁复杂的国际国内形势，面对新一轮科技革命和产业变革，面对人民群众新期待，必须继续把改革推向前进。进一步全面深化改革的出发点和落脚点是", "options": {"A": "促进社会公平正义、增进人民福社", "B": "解放和发展社会生产力", "C": "解放和增强社会活力", "D": "推动生产关系和生产力、上层建筑和经济基础、国家治理和社会发展更好相适应"}, "answer": ["A"], "note": "进一步全面深化改革的出发点和落脚点是：促进社会公平正义、增进人民福祉", "sourcePages": [84], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-23", "subject": "新思想", "chapter": 5, "chapterTitle": "第五章全面深化改革开放", "type": "单选", "number": 23, "stem": "党的二十届四中全会审议通过的《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》，对“扩大高水平对外开放，开创合作共赢新局面”作了专章部署，强调“稳步扩大制度型开放”“积极扩大自主开放”。其中，扩大市场准入和开放领域的重点是", "options": {"A": "新兴产业", "B": "服务业", "C": "农业", "D": "先进制造业"}, "answer": ["B"], "note": "扩大市场准入和开放领域的重点是服务业", "sourcePages": [85], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-30", "subject": "新思想", "chapter": 5, "chapterTitle": "第五章全面深化改革开放", "type": "多选", "number": 30, "stem": "改革开放是党和人民大踏步赶上时代的重要法宝，是当代中国最显著的特征、最壮丽的气象。改革开放是", "options": {"A": "我们党的一次伟大觉醒", "B": "坚持和发展中国特色社会主义的必由之路", "C": "决定当代中国命运的关键一步", "D": "决定实现“两个一百年”奋斗目标、实现中华民族伟大复兴的关键一招"}, "answer": ["A", "B", "D"], "note": "改革开放是：我们党的一次伟大觉醒；坚持和发展中国特色社会主义的必由之路；决定实现“两个一百年”奋斗目标、实现中华民族伟大复兴的关键一招", "sourcePages": [97], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-31", "subject": "新思想", "chapter": 5, "chapterTitle": "第五章全面深化改革开放", "type": "多选", "number": 31, "stem": "党的十一届三中全会是划时代的，党的十八届三中全会也是划时代的。党的十八届三中全会", "options": {"A": "开启了改革开放和社会主义现代化建设新时期", "B": "对全面深化改革进行总体璧画，确定了全面深化改革的总目标和时间表、路线图", "C": "实现改革由局部探索、破冰突围到系统集成、全面深化的转变", "D": "实现了改革理论和政策的一系列新的重大突破"}, "answer": ["B", "C", "D"], "note": "党的十八届三中全会对全面深化改革进行总体璧画，确定了全面深化改革的总目标和时间表、路线图；实现改革由局部探索、破冰突围到系统集成、全面深化的转变；实现了改革理论和政策的一系列新的重大突破", "sourcePages": [98], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-33", "subject": "新思想", "chapter": 5, "chapterTitle": "第五章全面深化改革开放", "type": "多选", "number": 33, "stem": "党的十八届三中全会通过的《中共中央关于全面深化改革若干重大问题的决定》，提出全面深化改革的总目标是完善和发展中国特色社会主义制度、推进国家治理体系和治理能力现代化。国家治理体系和国家治理能力的关系是", "options": {"A": "国家治理体系和国家治理能力是相辅相成的", "B": "国家治理体系越完备国家治理能力就一定越强", "C": "通过好的国家治理体系能够提高国家治理能力", "D": "通过提高国家治理能力能够充分发挥国家治理体系的效能"}, "answer": ["A", "C", "D"], "note": "国家治理体系和国家治理能力的关系是：国家治理体系和国家治理能力是相辅相成的；通过好的国家治理体系能够提高国家治理能力；通过提高国家治理能力能够充分发挥国家治理体系的效能", "sourcePages": [98], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-24", "subject": "新思想", "chapter": 6, "chapterTitle": "第六章推动高质量发展", "type": "单选", "number": 24, "stem": "党的十八大以来，我们党对经济社会发展提出了许多重大理论和战略，其中最重要、最主要的是", "options": {"A": "供给侧结构性改革", "B": "以人民为中心的发展思想", "C": "新发展理念", "D": "推动高质量发展"}, "answer": ["C"], "note": "党的十八大以来，我们党对经济社会发展提出的重大理论和战略中最重要、最主要的是：新发展理念", "sourcePages": [85], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-25", "subject": "新思想", "chapter": 6, "chapterTitle": "第六章推动高质量发展", "type": "单选", "number": 25, "stem": "发展理念是发展行动的先导，是发展思路、发展方式、发展着力点的集中体现。发展理念从根本上决定着发展成效乃至成败。新发展阶段必须坚定不移贯彻创新、协调、绿色、开放、共享的新发展理念。其中，创新是", "options": {"A": "引领发展的第一动力", "B": "国家繁荣发展的必由之路", "C": "持续健康发展的内在要求", "D": "中国特色社会主义的本质要求"}, "answer": ["A"], "note": "创新是：引领发展的第一动力", "sourcePages": [85], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-26", "subject": "新思想", "chapter": 6, "chapterTitle": "第六章推动高质量发展", "type": "单选", "number": 26, "stem": "高质量发展是新时代我国经济社会发展的鲜明主题，是全面建设社会主义现代化国家的首要任务。推动高质量发展的主线是", "options": {"A": "改革创新", "B": "实施扩大内需战略", "C": "深化供给侧结构性改革", "D": "加快构建新发展格局"}, "answer": ["C"], "note": "推动高质量发展的主线是：深化供给侧结构性改革", "sourcePages": [85], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-27", "subject": "新思想", "chapter": 6, "chapterTitle": "第六章推动高质量发展", "type": "单选", "number": 27, "stem": "高质量发展是全面建设社会主义现代化国家的首要任务。推动高质量发展的战略基点是", "options": {"A": "加快实现高水平科技自立自强", "B": "加快构建新发展格局", "C": "推进农业现代化", "D": "更好统筹质的有效提升和量的合理增长"}, "answer": ["B"], "note": "推动高质量发展的战略基点是：加快构建新发展格局", "sourcePages": [85], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-28", "subject": "新思想", "chapter": 6, "chapterTitle": "第六章推动高质量发展", "type": "单选", "number": 28, "stem": "《中华人民共和国国民经济和社会发展第十五个五年规划纲要》全面部署了“十五五”时期改革发展任务，其中一项就是“加快构建高水平社会主义市场经济体制，增强高质量发展动力”。构建高水平社会主义市场经济体制，关键是要处理好", "options": {"A": "政府和市场的关系", "B": "企业和市场的关系", "C": "中央和地方的关系", "D": "消费者和生产者的关系"}, "answer": ["A"], "note": "构建高水平社会主义市场经济体制，关键是要处理好：政府和市场的关系", "sourcePages": [85], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-29", "subject": "新思想", "chapter": 6, "chapterTitle": "第六章推动高质量发展", "type": "单选", "number": 29, "stem": "全面建成新发展格局任重道远，必须坚持问题导向和系统观念，着力破除制约加快构建新发展格局的主要矛盾和问题，不断扬优势、补短板、强弱项。要坚持把发展经济的着力点放在", "options": {"A": "制度创新上", "B": "乡村振兴上", "C": "对外开放上", "D": "实体经济上"}, "answer": ["D"], "note": "要坚持把发展经济的着力点放在：实体经济上", "sourcePages": [85], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-30", "subject": "新思想", "chapter": 6, "chapterTitle": "第六章推动高质量发展", "type": "单选", "number": 30, "stem": "构建新发展格局，是根据我国发展阶段、发展环境、条件变化，特别是基于我国比较优势变化，审时度势作出的重大决策，是关系我国发展全局的重大战略任务。构建新发展格局最本质的特征是", "options": {"A": "实现高水平的自立自强", "B": "推动实施扩大内需战略同深化供给侧结构性改革有机结合", "C": "推动产业链供应链优化升级", "D": "建设现代化经济体系"}, "answer": ["A"], "note": "构建新发展格局最本质的特征是：实现高水平的自立自强", "sourcePages": [85], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-31", "subject": "新思想", "chapter": 6, "chapterTitle": "第六章推动高质量发展", "type": "单选", "number": 31, "stem": "构建新发展格局是事关全局的系统性、深层次变革，是立足当前、着眼长远的战略谋划，是适应我国发展新阶段要求、塑造国际合作和竞争新优势的必然选择。构建新发展格局的重要前提和保障是", "options": {"A": "充分挖掘内需潜力", "B": "夯实我国经济发展的根基", "C": "促进区域协调发展", "D": "牢牢守住安全发展这条底线"}, "answer": ["D"], "note": "构建新发展格局的重要前提和保障是牢牢守住安全发展这条底线", "sourcePages": [85], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-32", "subject": "新思想", "chapter": 6, "chapterTitle": "第六章推动高质量发展", "type": "单选", "number": 32, "stem": "新质生产力是创新起主导作用，摆脱传统经济增长方式、生产力发展路径，具有高科技、高效能、高质量特征，符合新发展理念的先进生产力质态。新质生产力的显著特点是创新，这种创新包括\n\n①生产资料所有制和产品分配层面的创新\n\n②技术和业态模式层面的创新\n\n③管理和制度层面的创新\n\n④价值观和意识形态层面的创新", "options": {"A": "①②", "B": "①③", "C": "②④", "D": "②③"}, "answer": ["D"], "note": "新质生产力的显著特点是创新，这种创新包括技术和业态模式层面的创新、管理和制度层面的创新。", "sourcePages": [86], "answerSource": "配套资料与题目核对"}, {"id": "新思想-单选-33", "subject": "新思想", "chapter": 6, "chapterTitle": "第六章推动高质量发展", "type": "单选", "number": 33, "stem": "新质生产力由技术革命性突破、生产要素创新性配置、产业深度转型升级而催生，以劳动者、劳动资料、劳动对象及其优化组合的跃升为基本内涵。新质生产力的核心标志是", "options": {"A": "全要素生产率大幅提升", "B": "创新和质优", "C": "稳定的产业链供应链", "D": "催生新产业、新模式、新动能"}, "answer": ["A"], "note": "新质生产力的核心标志是：全要素生产率大幅提升", "sourcePages": [86], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-34", "subject": "新思想", "chapter": 6, "chapterTitle": "第六章推动高质量发展", "type": "单选", "number": 34, "stem": "加快建设以实体经济为支撑的现代化产业体系，关系我们在未来发展和国际竞争中赢得战略主动。支撑我国国际竞争力的基石是", "options": {"A": "大力发展战略性新兴产业", "B": "保持优势产业的领先地位", "C": "构建优质高效的服务业新体系", "D": "构建现代化基础设施体系"}, "answer": ["B"], "note": "支撑我国国际竞争力的基石是：保持优势产业的领先地位", "sourcePages": [86], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-35", "subject": "新思想", "chapter": 6, "chapterTitle": "第六章推动高质量发展", "type": "单选", "number": 35, "stem": "脱贫摘帽不是终点，而是新生活、新奋斗的起点。接下来要做好乡村振兴这篇大文章，让乡亲们生活越来越美好。实施乡村振兴战略的总方针是", "options": {"A": "农业农村现代化", "B": "坚持农业农村优先发展", "C": "产业兴旺、生态宜居、乡风文明、治理有效、生活富裕", "D": "建立健全城乡融合发展体制机制和政策体系"}, "answer": ["B"], "note": "实施乡村振兴战略的总方针是：坚持农业农村优先发展", "sourcePages": [86], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-36", "subject": "新思想", "chapter": 6, "chapterTitle": "第六章推动高质量发展", "type": "单选", "number": 36, "stem": "我国发展最大的不平衡是城乡发展不平衡，最大的不充分是农村发展不充分。必须坚持把解决好“三农”问题作为全党工作重中之重，扎实推进乡村全面振兴。推进乡村全面振兴的基础是", "options": {"A": "农业农村现代化", "B": "发展乡村特色产业", "C": "持续深化农村科技和改革创新", "D": "建立健全城乡融合发展体制"}, "answer": ["B"], "note": "推进乡村全面振兴的基础是发展乡村特色产业", "sourcePages": [86], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-38", "subject": "新思想", "chapter": 6, "chapterTitle": "第六章推动高质量发展", "type": "单选", "number": 38, "stem": "城镇化是现代化的必由之路，是解决农业、农村、农民问题的重要途径，是推动区域协调发展的有力支撑，是扩大内需和促进产业升级的重要抓手。新型城镇化的首要任务是", "options": {"A": "进一步深化户籍制度改革", "B": "推进公共服务共建共享", "C": "推进农业转移人口市民化", "D": "强化产业分工协作"}, "answer": ["C"], "note": "新型城镇化的首要任务是：推进农业转移人口市民化", "sourcePages": [86], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-39", "subject": "新思想", "chapter": 6, "chapterTitle": "第六章推动高质量发展", "type": "多选", "number": 39, "stem": "党的十九届五中全会提出，全面建成小康社会、实现第一个百年奋斗目标之后，我们要乘势而上开启全面建设社会主义现代化国家新征程、向第二个百年奋斗目标进军，这标志着我国进入了一个新发展阶段。新发展阶段是", "options": {"A": "我国社会主义初级阶段历史进程中的一个重要阶段", "B": "全面建设社会主义现代化国家、向第二个百年奋斗目标进军的重要阶段", "C": "我们党带领人民迎来从站起来、富起来到强起来历史性跨越的新阶段", "D": "所有国家实现社会主义现代化必须经历的阶段"}, "answer": ["A", "B", "C"], "note": "新发展阶段是：我国社会主义初级阶段历史进程中的一个重要阶段；全面建设社会主义现代化国家、向第二个百年奋斗目标进军的重要阶段；我们党带领人民迎来从站起来、富起来到强起来历史性跨越的新阶段", "sourcePages": [99], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-41", "subject": "新思想", "chapter": 6, "chapterTitle": "第六章推动高质量发展", "type": "多选", "number": 41, "stem": "高质量发展是全面建设社会主义现代化国家的首要任务。高质量发展，就是", "options": {"A": "能够很好满足人民日益增长的美好生活需要的发展", "B": "体现新发展理念的发展", "C": "创新成为第一动力、协调成为内生特点、绿色成为普遍形态、开放成为必由之路、共享成为根本目的的发展", "D": "从“有没有”转向“好不好”的发展"}, "answer": ["A", "B", "C", "D"], "note": "高质量发展，就是：能够很好满足人民日益增长的美好生活需要的发展；体现新发展理念的发展；创新成为第一动力、协调成为内生特点、绿色成为普遍形态、开放成为必由之路、共享成为根本目的的发展；从“有没有”转向“好不好”的发展", "sourcePages": [99], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-42", "subject": "新思想", "chapter": 6, "chapterTitle": "第六章推动高质量发展", "type": "多选", "number": 42, "stem": "新质生产力是创新起主导作用，摆脱传统经济增长方式、生产力发展路径，具有高科技、高效能、高质量特征，符合新发展理念的先进生产力质态。催生新质生产力的是", "options": {"A": "技术革命性突破", "B": "上层建筑的大幅跃升", "C": "产业深度转型升级", "D": "生产要素创新性配置"}, "answer": ["A", "C", "D"], "note": "1催生新质生产力的是：技术革命性突破；产业深度转型升级；生产要素创新性配置", "sourcePages": [99], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-45", "subject": "新思想", "chapter": 6, "chapterTitle": "第六章推动高质量发展", "type": "多选", "number": 45, "stem": "坚持和完善社会主义基本经济制度是实现高质量发展的保障。社会主义基本经济制度", "options": {"A": "是我国生产关系在制度上的体现", "B": "在经济制度体系中具有基础性决定性地位", "C": "是中国特色社会主义制度的重要支柱", "D": "是解放和发展社会生产力、改善人民生活、维护社会公平正义、推进共同富裕的制度基础"}, "answer": ["A", "B", "C", "D"], "note": "坚持和完善社会主义基本经济制度是实现高质量发展的保障。社会主义基本经济制度：是我国生产关系在制度上的体现；在经济制度体系中具有基础性决定性地位；是中国特色社会主义制度的重要支柱；是解放和发展社会生产力、改善人民生活、维护社会公平正义、推进共同富裕的制度基础", "sourcePages": [100], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-46", "subject": "新思想", "chapter": 6, "chapterTitle": "第六章推动高质量发展", "type": "多选", "number": 46, "stem": "公有制经济是全体人民的宝贵财富，公有制主体地位不能动摇，国有经济主导作用不能动摇，这是我国各族人民共享发展成果的制度性保证，也是巩固党的执政地位、坚持我国社会主义制度的重要保证。国有企业是", "options": {"A": "中国特色社会主义的重要物质基础", "B": "中国特色社会主义的政治基础", "C": "我们党执政兴国的重要支柱", "D": "我们党执政兴国的依靠力量"}, "answer": ["A", "B", "C", "D"], "note": "国有企业是：中国特色社会主义的重要物质基础；中国特色社会主义的政治基础；我们党执政兴国的重要支柱；我们党执政兴国的依靠力量", "sourcePages": [100], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-47", "subject": "新思想", "chapter": 6, "chapterTitle": "第六章推动高质量发展", "type": "多选", "number": 47, "stem": "我国非公有制经济是改革开放以来在中国共产党的方针政策指引下发展起来的，我们要毫不动摇鼓励、支持、引导非公有制经济发展。非公有制经济是", "options": {"A": "社会主义经济的重要组成部分和我国经济社会发展的重要基础", "B": "国家税收的重要来源和就业创业的重要领域", "C": "稳定经济的重要基础和金融发展的重要依托", "D": "技术创新的重要主体和经济持续健康发展的重要力量"}, "answer": ["B", "C", "D"], "note": "非公有制经济是：国家税收的重要来源和就业创业的重要领域；稳定经济的重要基础和金融发展的重要依托；技术创新的重要主体和经济持续健康发展的重要力量", "sourcePages": [100], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-49", "subject": "新思想", "chapter": 6, "chapterTitle": "第六章推动高质量发展", "type": "多选", "number": 49, "stem": "迈上新征程，我国民营经济只能壮大，不能弱化，而且要走向更加广阔的舞台。民营经济是", "options": {"A": "非公有制经济的主要经济组织形式", "B": "推进中国式现代化的生力军", "C": "高质量发展的重要基础", "D": "推动我国全面建成社会主义现代化强国、实现第二个百年奋斗目标的重要力量"}, "answer": ["A", "B", "C", "D"], "note": "民营经济是：非公有制经济的主要经济组织形式；推进中国式现代化的生力军；高质量发展的重要基础；推动我国全面建成社会主义现代化强国、实现第二个百年奋斗目标的重要力量", "sourcePages": [100], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-51", "subject": "新思想", "chapter": 6, "chapterTitle": "第六章推动高质量发展", "type": "多选", "number": 51, "stem": "构建以国内大循环为主体、国内国际双循环相互促进的新发展格局，是推动高质量发展的战略基点，是关系我国发展全局的重大战略任务。构建新发展格局，是", "options": {"A": "适应我国发展新阶段要求的必然选择", "B": "塑造国际合作和竞争新优势的必然选择", "C": "基于我国比较优势变化，审时度势作出的重大决策", "D": "把握未来发展主动权的先手棋"}, "answer": ["A", "B", "C", "D"], "note": "构建新发展格局，是：适应我国发展新阶段要求的必然选择；塑造国际合作和竞争新优势的必然选择；基于我国比较优势变化，审时度势作出的重大决策；把握未来发展主动权的先手棋", "sourcePages": [101], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-53", "subject": "新思想", "chapter": 6, "chapterTitle": "第六章推动高质量发展", "type": "多选", "number": 53, "stem": "建设农业强国，必须走中国特色社会主义乡村振兴道路，大力实施乡村振兴战略，全面推进乡村振兴。实施乡村振兴战略", "options": {"A": "农业农村现代化是总目标", "B": "坚持农业农村优先发展是总方针", "C": "产业兴旺、生态宜居、乡风文明、治理有效、生活富裕是总要求", "D": "建立健全城乡融合发展体制机制和政策体系是制度保障"}, "answer": ["A", "B", "C", "D"], "note": "实施乡村振兴战略：农业农村现代化是总目标；坚持农业农村优先发展是总方针；产业兴旺、生态宜居、乡风文明、治理有效、生活富裕是总要求；建立健全城乡融合发展体制机制和政策体系是制度保障", "sourcePages": [101], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-54", "subject": "新思想", "chapter": 6, "chapterTitle": "第六章推动高质量发展", "type": "多选", "number": 54, "stem": "强国必先强农，农强方能国强。农业强国是社会主义现代化强国的根基。加快建设农业强国，必须巩固和完善农村基本经营制度，牢牢守住底线。这个底线就是", "options": {"A": "土地公有制性质不改变", "B": "耕地红线不突破", "C": "农民利益不受损", "D": "农村土地经营权不流转"}, "answer": ["A", "B", "C"], "note": "加快建设农业强国，必须巩固和完善农村基本经营制度，牢牢守住底线。这个底线就是土地公有制性质不改变；耕地红线不突破；农民利益不受损", "sourcePages": [101], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-39", "subject": "新思想", "chapter": 7, "chapterTitle": "第七章社会主义现代化建设的教育、科技、人才战略", "type": "单选", "number": 39, "stem": "教育是国之大计、党之大计，是功在当代、利在千秋的德政工程。建成教育强国是近代以来中华民族梦寐以求的美好愿望，是实现以中国式现代化全面推进强国建设、民族复兴伟业的\n\n①先导任务\n\n②坚实基础\n\n③战略支撑\n\n④鲜明标识", "options": {"A": "①②④", "B": "②③④", "C": "①③④", "D": "①②③"}, "answer": ["D"], "note": "建成教育强国是近代以来中华民族梦以求的美好愿望，是实现以中国式现代化全面推进强国建设、民族复兴伟业的：先导任务、坚实基础、战略支撑", "sourcePages": [86], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-40", "subject": "新思想", "chapter": 7, "chapterTitle": "第七章社会主义现代化建设的教育、科技、人才战略", "type": "单选", "number": 40, "stem": "教育是国之大计、党之大计，是功在当代、利在千秋的德政工程。教育的根本任务是", "options": {"A": "人民满意", "B": "价值观塑造", "C": "立德树人", "D": "为国育才"}, "answer": ["C"], "note": "教育根本任务是：立德树人", "sourcePages": [87], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-41", "subject": "新思想", "chapter": 7, "chapterTitle": "第七章社会主义现代化建设的教育、科技、人才战略", "type": "单选", "number": 41, "stem": "教育是国家经济社会发展的支撑力量，在国家发展中始终具有基础性、先导性、全局性地位。建设高质量教育体系，办好人民满意的教育，根本在于", "options": {"A": "深化教育综合改革", "B": "确立科学的教育评价体系", "C": "落实学校办学自主权", "D": "建立健全更加合理高效的教育资源配置机制"}, "answer": ["A"], "note": "建设高质量教育体系，办好人民满意的教育，根本在于深化教育综合改革", "sourcePages": [87], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-42", "subject": "新思想", "chapter": 7, "chapterTitle": "第七章社会主义现代化建设的教育、科技、人才战略", "type": "单选", "number": 42, "stem": "科技是国之利器，国家赖之以强，企业赖之以赢，人民生活赖之以好。中国要强，中国人民生活要好，必须有强大科技。创新始终是一个国家、一个民族发展的不竭动力。科技创新的源头是", "options": {"A": "国家战略科技力量", "B": "现代工程技术、颠覆性技术创新", "C": "关键共性技术、前沿引领技术创新", "D": "基础研究"}, "answer": ["D"], "note": "科技创新的源头是：基础研究", "sourcePages": [87], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-58", "subject": "新思想", "chapter": 7, "chapterTitle": "第七章社会主义现代化建设的教育、科技、人才战略", "type": "多选", "number": 58, "stem": "教育是国之大计、党之大计，是民族振兴、社会进步的基石。建设教育强国是", "options": {"A": "全面建成社会主义现代化强国的战略先导", "B": "实现高水平科技自立自强的重要支撑", "C": "促进全体人民共同富裕的有效途径", "D": "以中国式现代化全面推进中华民族伟大复兴的基础工程"}, "answer": ["A", "B", "C", "D"], "note": "教育是国之大计、党之大计，是民族振兴、社会进步的基石。建设教育强国是：全面建成社会主义现代化强国的战略先导；实现高水平科技自立自强的重要支撑；促进全体人民共同富裕的有效途径；以中国式现代化全面推进中华民族伟大复兴的基础工程", "sourcePages": [102], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-60", "subject": "新思想", "chapter": 7, "chapterTitle": "第七章社会主义现代化建设的教育、科技、人才战略", "type": "多选", "number": 60, "stem": "自力更生是中华民族自立于世界民族之林的奋斗基点，自主创新是我们攀登世界科技高峰的必由之路。实现高水平科技自立自强，必须增强自主创新能力。自主创新，就是从增强国家创新能力出发，加强", "options": {"A": "原始创新", "B": "集成创新", "C": "开放创新", "D": "改革创新"}, "answer": ["A", "B", "C"], "note": "自主创新，就是从增强国家创新能力出发，加强原始创新；集成创新；开放创新", "sourcePages": [102], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-61", "subject": "新思想", "chapter": 7, "chapterTitle": "第七章社会主义现代化建设的教育、科技、人才战略", "type": "多选", "number": 61, "stem": "千秋基业，人才为先。全面建设社会主义现代化国家，要聚天下英才而用之，推动我国由人才大国迈向人才强国。人才是", "options": {"A": "人力资源中能力和素质较高的劳动者", "B": "实现民族振兴、赢得国际竞争主动的战略资源", "C": "我们党执政的最大底气和最深厚的根基", "D": "引领发展的第一动力"}, "answer": ["A", "B"], "note": "人才是：人力资源中能力和素质较高的劳动者；实现民族振兴、赢得国际竞争主动的战略资源", "sourcePages": [102], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-43", "subject": "新思想", "chapter": 8, "chapterTitle": "第八章发展全过程人民民主", "type": "单选", "number": 43, "stem": "制度优势是一个政党、一个国家的最大优势。坚定中国特色社会主义制度自信，首先要", "options": {"A": "坚定对社会主义基本经济制度的自信", "B": "坚定对中国特色社会主义政治制度的自信", "C": "坚定对中国传统文化的自信", "D": "坚定对马克思主义在意识形态领域指导地位的根本制度的自信"}, "answer": ["B"], "note": "坚定中国特色社会主义制度自信，首先要：坚定对中国特色社会主义政治制度的自信", "sourcePages": [87], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-44", "subject": "新思想", "chapter": 8, "chapterTitle": "第八章发展全过程人民民主", "type": "单选", "number": 44, "stem": "中国特色社会主义政治发展道路，是近代以来中国人民长期奋斗历史逻辑、理论逻辑、实践逻辑的必然结果，是坚持党的本质属性、践行党的根本宗旨的必然要求。走中国特色社会主义政治发展道路，最根本的是", "options": {"A": "坚持人民当家作主", "B": "坚持党的领导", "C": "坚持以人民为中心", "D": "坚持独立自主"}, "answer": ["B"], "note": "走中国特色社会主义政治发展道路，最根本的是：坚持党的领导", "sourcePages": [87], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-45", "subject": "新思想", "chapter": 8, "chapterTitle": "第八章发展全过程人民民主", "type": "单选", "number": 45, "stem": "新时代我国民主政治领域具有重大创新意义的标志性成果是", "options": {"A": "协商民主", "B": "中国特色社会主义政治发展道路", "C": "党内民主", "D": "全过程人民民主"}, "answer": ["D"], "note": "新时代我国民主政治领域具有重大创新意义的标志性成果是：全过程人民民主", "sourcePages": [87], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-46", "subject": "新思想", "chapter": 8, "chapterTitle": "第八章发展全过程人民民主", "type": "单选", "number": 46, "stem": "多民族是我国的一大特色，也是我国发展的一大有利因素。中华民族和各民族的关系，是一个大家庭和家庭成员的关系，各民族的关系是一个大家庭里不同成员的关系。民族团结之本是", "options": {"A": "民族区域自治制度", "B": "各民族共同团结奋斗、共同繁荣发展", "C": "保障少数民族当家作主，管理本民族、本地区事务的权利", "D": "中华民族共同体意识"}, "answer": ["D"], "note": "民族团结之本是：中华民族共同体意识", "sourcePages": [87], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-47", "subject": "新思想", "chapter": 8, "chapterTitle": "第八章发展全过程人民民主", "type": "单选", "number": 47, "stem": "统一战线是中国共产党夺取革命、建设、改革事业胜利的重要法宝，也是实现中华民族伟大复兴的重要法宝。统战工作的本质要求是", "options": {"A": "大团结大联合", "B": "围绕中心、服务大局", "C": "在尊重多样性中寻求一致性", "D": "统一思想"}, "answer": ["A"], "note": "统战工作的本质要求是：大团结大联合", "sourcePages": [87], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-48", "subject": "新思想", "chapter": 8, "chapterTitle": "第八章发展全过程人民民主", "type": "单选", "number": 48, "stem": "统一战线是凝聚人心、汇聚力量的强大法宝。统一战线最鲜明的特征（或：统一战线最核心最根本的问题）是", "options": {"A": "人民至上", "B": "求同存异", "C": "党的领导", "D": "团结奋斗"}, "answer": ["C"], "note": "统一战线最鲜明的特征(或：统一战线最核心最根本的问题)是：党的领导", "sourcePages": [87], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-49", "subject": "新思想", "chapter": 8, "chapterTitle": "第八章发展全过程人民民主", "type": "单选", "number": 49, "stem": "新时代，统一战线面临的时和势、肩负的使命和任务发生了重大变化。新时代爱国统一战线的历史责任是", "options": {"A": "高举爱国主义、社会主义旗帜", "B": "促进中华儿女大团结", "C": "坚持和完善中国特色社会主义制度", "D": "巩固和维护国家安全的民心基础"}, "answer": ["B"], "note": "新时代爱国统一战线的历史责任是：促进中华儿女大团结", "sourcePages": [87], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-63", "subject": "新思想", "chapter": 8, "chapterTitle": "第八章发展全过程人民民主", "type": "多选", "number": 63, "stem": "人民民主是社会主义的生命，全过程人民民主", "options": {"A": "植根于我国社会主义民主的长期实践", "B": "是社会主义民主政治的本质属性", "C": "是人民当家作主和依法治国的根本保证", "D": "是新时代我国民主政治领域具有重大创新意义的标志性成果"}, "answer": ["A", "B", "D"], "note": "人民民主是社会主义的生命，全过程人民民主：植根于我国社会主义民主的长期实践；是社会主义民主政治的本质属性；是新时代我国民主政治领域具有重大创新意义的标志性成果", "sourcePages": [102, 103], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-64", "subject": "新思想", "chapter": 8, "chapterTitle": "第八章发展全过程人民民主", "type": "多选", "number": 64, "stem": "全过程人民民主的提出、实践和发展，鲜明展示了我们党始终高举人民民主旗帜、实现人民当家作主的坚定立场，深刻彰显了我国人民民主的鲜明特色和显著优势，实现了", "options": {"A": "过程民主和成果民主相统一", "B": "程序民主和实质民主相统一", "C": "直接民主和间接民主相统一", "D": "人民民主和国家意志相统一"}, "answer": ["A", "B", "C", "D"], "note": "全过程人民民主实现了过程民主和成果民主相统一：程序民主和实质民主相统一；直接民主和间接民主相统一；人民民主和国家意志相统一", "sourcePages": [103], "answerSource": "配套资料与题目核对"}, {"id": "新思想-多选-65", "subject": "新思想", "chapter": 8, "chapterTitle": "第八章发展全过程人民民主", "type": "多选", "number": 65, "stem": "全过程人民民主，既有完整的制度程序，也有完整的参与实践，把民主选举、民主协商、民主决策、民主管理、民主监督贯通起来，涵盖经济、政治、文化、社会、生态文明等各个方面，聚焦国家发展大事、社会治理难事、百姓日常琐事，具有", "options": {"A": "时间上的连续性", "B": "内容上的整体性", "C": "运行上的协同性", "D": "人民参与上的广泛性和持续性"}, "answer": ["A", "B", "C", "D"], "note": "全过程人民民主具有时间上的连续性；内容上的整体性；运行上的协同性；人民参与上的广泛性和持续性", "sourcePages": [103], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-66", "subject": "新思想", "chapter": 8, "chapterTitle": "第八章发展全过程人民民主", "type": "多选", "number": 66, "stem": "全过程人民民主，是中国共产党团结带领人民追求民主、发展民主、实现民主的伟大创造，是新时代我国民主政治领域具有重大创新意义的标志性成果。全过程人民民主是", "options": {"A": "全链条、全方位、全覆盖的民主", "B": "最广泛、最真实、最管用的民主", "C": "最纯粹、最先进、最好的民主", "D": "协商民主、选举民主、人人民主的统一"}, "answer": ["A", "B"], "note": "全过程人民民主是：全链条、全方位、全覆盖的民主；最广泛、最真实、最管用的民主", "sourcePages": [103], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-69", "subject": "新思想", "chapter": 8, "chapterTitle": "第八章发展全过程人民民主", "type": "多选", "number": 69, "stem": "改革开放40多年来，人民代表大会制度为党领导人民创造经济快速发展奇迹和社会长期稳定奇迹提供了重要制度保障。实践证明，人民代表大会制度是我们党领导人民在人类政治制度史上的伟大创造，是在我国政治发展史乃至世界政治发展史上具有重大意义的全新政治制度。人民代表大会制度", "options": {"A": "有效保证国家沿着社会主义道路前进", "B": "有效保证国家治理跳出治乱兴衰的历史周期率", "C": "有效保证全体人民直接参与国家管理", "D": "有效保证国家政治生活既充满活力又安定有序"}, "answer": ["A", "B", "D"], "note": "人民代表大会制度有效保证国家沿着社会主义道路前进；有效保证国家治理跳出治乱兴衰的历史周期率；有效保证国家政治生活既充满活力又安定有序", "sourcePages": [103], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-71", "subject": "新思想", "chapter": 8, "chapterTitle": "第八章发展全过程人民民主", "type": "多选", "number": 71, "stem": "人大代表作用的发挥，直接关系人民代表大会制度的运行，直接关系人大工作质量和水平。人大代表参加行使国家权力的主要形式是", "options": {"A": "出席人民代表大会会议", "B": "参与重要法律法规的制定修改、计划预算的审查批准和重大事项的审议决定", "C": "依法参加选举、表决重要人事任免事项", "D": "提出议案和建议"}, "answer": ["A", "B", "C", "D"], "note": "人大代表参加行使国家权力的主要形式是出席人民代表大会会议；参与重要法律法规的制定修改、计划预算的审查批准和重大事项的审议决定；依法参加选举、表决重要人事任免事项；提出议案和建议", "sourcePages": [104], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-72", "subject": "新思想", "chapter": 8, "chapterTitle": "第八章发展全过程人民民主", "type": "多选", "number": 72, "stem": "中国共产党领导的多党合作和政治协商制度、民族区域自治制度、基层群众自治制度构成了我国的基本政治制度，反映了我国社会主义民主政治的独特优势，是保障各政党、各阶层、各民族和基层人民群众当家作主的重要基础。中国人民政治协商会议是", "options": {"A": "实行中国共产党领导的多党合作和政治协商制度的重要机构", "B": "我国政治生活中发扬社会主义民主、实践全过程人民民主的重要形式", "C": "社会主义协商民主的重要渠道和专门协商机构", "D": "国家治理体系的重要组成部分"}, "answer": ["A", "B", "C", "D"], "note": "中国人民政治协商会议是：实行中国共产党领导的多党合作和政治协商制度的重要机构；我国政治生活中发扬社会主义民主、实践全过程人民民主的重要形式；社会主义协商民主的重要渠道和专门协商机构；国家治理体系的重要组成部分", "sourcePages": [104], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-74", "subject": "新思想", "chapter": 8, "chapterTitle": "第八章发展全过程人民民主", "type": "多选", "number": 74, "stem": "习近平指出：“有事好商量，众人的事情由众人商量，找到全社会意愿和要求的最大公约数，是人民民主的真谛。”协商民主是实践全过程人民民主的重要形式，是", "options": {"A": "我国社会主义民主政治的特有形式和独特优势", "B": "党的群众路线在政治领域的重要体现", "C": "中国共产党领导人民有效治理国家、保证人民当家作主的重要制度安排", "D": "新时代我国民主政治领域具有重大创新意义的标志性成果"}, "answer": ["A", "B", "C"], "note": "协商民主是实践全过程人民民主的重要形式，是：我国社会主义民主政治的特有形式和独特优势；党的群众路线在政治领域的重要体现；中国共产党领导人民有效治理国家、保证人民当家作主的重要制度安排", "sourcePages": [104], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-75", "subject": "新思想", "chapter": 8, "chapterTitle": "第八章发展全过程人民民主", "type": "多选", "number": 75, "stem": "基层民主是全过程人民民主的重要体现。我国基层民主有多种多样的形式，如以村民委员会为组织形态的农村村民自治、以社区居民委员会为组织形态的城市居民自治、以职工代表大会为组织依托的企事业单位职工自治等。发展基层民主", "options": {"A": "是实现人民有效政治参与的重要渠道", "B": "是人民当家作主的有效途径", "C": "是社会主义民主最广泛的实践", "D": "彰显了人民当家作主的广泛性、真实性、有效性"}, "answer": ["A", "B", "C", "D"], "note": "发展基层民主：是实现人民有效政治参与的重要渠道；是人民当家作主的有效途径；是社会主义民主最广泛的实践；彰显了人民当家作主的广泛性、真实性、有效性", "sourcePages": [104], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-76", "subject": "新思想", "chapter": 8, "chapterTitle": "第八章发展全过程人民民主", "type": "多选", "number": 76, "stem": "新时代统战工作取得的最大成果，就是在实践中形成了关于做好新时代党的统一战线工作的重要思想，就加强和改进统战工作提出了一系列新理念新思想新战略。必须充分发挥统一战线的重要法宝作用。统一战线是", "options": {"A": "中国共产党区别于其他任何政党的显著标志", "B": "党克敌制胜、执政兴国的重要法宝", "C": "团结海内外全体中华儿女实现中华民族伟大复兴的重要法宝", "D": "党的总路线总政策的重要组成部分"}, "answer": ["B", "C", "D"], "note": "统一战线是：党克敌制胜、执政兴国的重要法宝；团结海内外全体中华儿女实现中华民族伟大复兴的重要法宝；党的总路线总政策的重要组成部分", "sourcePages": [104], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-50", "subject": "新思想", "chapter": 9, "chapterTitle": "第九章全面依法治国", "type": "单选", "number": 50, "stem": "习近平指出：“全面推进依法治国，必须走对路。如果路走错了，南辕北辙了，那再提什么要求和举措也都没有意义了。”我们党领导人民长期探索走出的中国特色社会主义法治道路，是全面依法治国的唯一正确道路。中国特色社会主义法治之魂是", "options": {"A": "依法治国和以德治国相结合", "B": "以人民为中心", "C": "党的领导", "D": "法律面前人人平等"}, "answer": ["C"], "note": "中国特色社会主义法治之魂是：党的领导", "sourcePages": [88], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-51", "subject": "新思想", "chapter": 9, "chapterTitle": "第九章全面依法治国", "type": "单选", "number": 51, "stem": "全面依法治国是“四个全面”战略布局的重要内容之一。推进全面依法治国，根本目的是", "options": {"A": "依法保障人民权益", "B": "努力让人民群众在每一个司法案件中感受到公平正义", "C": "提高依法执政水平", "D": "保证法律面前人人平等"}, "answer": ["A"], "note": "推进全面依法治国，根本目的是：依法保障人民权益", "sourcePages": [88], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-52", "subject": "新思想", "chapter": 9, "chapterTitle": "第九章全面依法治国", "type": "单选", "number": 52, "stem": "走中国特色社会主义法治道路，必须坚持法律面前人人平等。平等是", "options": {"A": "推进全面依法治国的根本目的", "B": "我们的法治同西方资本主义国家的法治最大的区别", "C": "社会主义法律的基本属性", "D": "全面依法治国的关键"}, "answer": ["C"], "note": "平等是：社会主义法律的基本属性", "sourcePages": [88], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-53", "subject": "新思想", "chapter": 9, "chapterTitle": "第九章全面依法治国", "type": "单选", "number": 53, "stem": "全面推进依法治国涉及很多方面，在实际工作中必须有一个总揽全局、牵引各方的总抓手，这个总抓手就是", "options": {"A": "建设中国特色社会主义法治体系", "B": "建设社会主义法治国家", "C": "坚持依法治国、依法执政、依法行政共同推进", "D": "坚持法治国家、法治政府、法治社会一体建设"}, "answer": ["A"], "note": "全面推进依法治国的总抓手是：建设中国特色社会主义法治体系", "sourcePages": [88], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-54", "subject": "新思想", "chapter": 9, "chapterTitle": "第九章全面依法治国", "type": "单选", "number": 54, "stem": "坚持依法治国首先要坚持依宪治国，坚持依法执政首先要坚持依宪执政。坚持依宪治国、依宪执政，作为首要任务的是", "options": {"A": "全面贯彻实施宪法", "B": "法治国家建设", "C": "法治社会建设", "D": "法治政府建设"}, "answer": ["A"], "note": "坚持依宪治国、依宪执政，作为首要任务的是：全面贯彻实施宪法", "sourcePages": [88], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-55", "subject": "新思想", "chapter": 9, "chapterTitle": "第九章全面依法治国", "type": "单选", "number": 55, "stem": "全面依法治国是国家治理的一场深刻革命，关系党执政兴国，关系人民幸福安康，关系党和国家长治久安。全面依法治国的重点任务和主体工程是", "options": {"A": "法治国家建设", "B": "法治政府建设", "C": "法治社会建设", "D": "依法行政"}, "answer": ["B"], "note": "全面依法治国的重点任务和主体工程是：法治政府建设", "sourcePages": [88], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-79", "subject": "新思想", "chapter": 9, "chapterTitle": "第九章全面依法治国", "type": "多选", "number": 79, "stem": "法律是治国之重器，法治是国家治理体系和治理能力的重要依托。历史和现实告诉我们，法治兴则国兴，法治强则国强。全面依法治国，是", "options": {"A": "完善和发展中国特色社会主义制度的重要方面", "B": "推进国家治理体系和治理能力现代化的重要方面", "C": "坚持和发展中国特色社会主义的本质要求", "D": "坚持和发展中国特色社会主义的重要保障"}, "answer": ["A", "B", "C", "D"], "note": "全面依法治国，是：完善和发展中国特色社会主义制度的重要方面；推进国家治理体系和治理能力现代化的重要方面；坚持和发展中国特色社会主义的本质要求；坚持和发展中国特色社会主义的重要保障", "sourcePages": [105], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-80", "subject": "新思想", "chapter": 9, "chapterTitle": "第九章全面依法治国", "type": "多选", "number": 80, "stem": "我们党领导人民长期探索走出的中国特色社会主义法治道路，是全面依法治国的唯一正确道路。我国法治建设的成就可以列举出十几条、几十条，但归结起来就是开辟了中国特色社会主义法治道路这一条。中国特色社会主义法治道路的核心要义是", "options": {"A": "坚持党的领导", "B": "坚持以人民为中心", "C": "坚持中国特色社会主义制度", "D": "贯彻中国特色社会主义法治理论"}, "answer": ["A", "C", "D"], "note": "中国特色社会主义法治道路的核心要义是：坚持党的领导；坚持中国特色社会主义制度；贯彻中国特色社会主义法治理论", "sourcePages": [105], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-81", "subject": "新思想", "chapter": 9, "chapterTitle": "第九章全面依法治国", "type": "多选", "number": 81, "stem": "中国特色社会主义法治道路是全面依法治国的唯一正确道路。坚持和拓展中国特色社会主义法治道路，必须毫不动摇坚持的原则有", "options": {"A": "坚持中国共产党的领导", "B": "坚持以人民为中心", "C": "坚持法律面前人人平等", "D": "坚持依法治国和以德治国相结合"}, "answer": ["A", "B", "C", "D"], "note": "坚持和拓展中国特色社会主义法治道路，必须毫不动摇坚持的原则有坚持中国共产党的领导；坚持以人民为中心；坚持法律面前人人平等；坚持依法治国和以德治国相结合", "sourcePages": [105], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-82", "subject": "新思想", "chapter": 9, "chapterTitle": "第九章全面依法治国", "type": "多选", "number": 82, "stem": "建设法治中国，是全面建设社会主义现代化国家的重要组成部分。加快建设法治中国，必须坚持统筹兼顾、把握重点、整体谋划，更加注重系统性、整体性、协同性。法治中国建设的工作布局是", "options": {"A": "坚持依法治国、依法执政、依法行政共同推进", "B": "坚持法治国家、法治政府、法治社会一体建设", "C": "坚持科学立法、严格执法、公正司法、全民守法", "D": "坚持统筹推进国内法治和涉外法治"}, "answer": ["A", "B", "D"], "note": "法治中国建设的工作布局是：坚持依法治国、依法执政、依法行政共同推进；坚持法治国家、法治政府、法治社会一体建设；坚持统筹推进国内法治和涉外法治", "sourcePages": [105], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-56", "subject": "新思想", "chapter": 10, "chapterTitle": "第十章建设社会主义文化强国", "type": "单选", "number": 56, "stem": "文化是一个国家、一个民族的灵魂。国家的富强，民族的振兴，无不伴随着文化的历史性进步。建设社会主义文化强国，推动社会主义文化繁荣兴盛，关键在于", "options": {"A": "坚定中国特色社会主义文化自信", "B": "坚持马克思主义在意识形态领域的指导地位", "C": "以社会主义核心价值观引领文化建设", "D": "缩小城乡公共文化服务差距"}, "answer": ["A"], "note": "建设社会主义文化强国，推动社会主义文化繁荣兴盛，关键在于：坚定中国特色社会主义文化自信", "sourcePages": [88], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-57", "subject": "新思想", "chapter": 10, "chapterTitle": "第十章建设社会主义文化强国", "type": "单选", "number": 57, "stem": "哲学社会科学是人们认识世界、改造世界的重要工具，是推动历史发展和社会进步的重要力量。当代中国哲学社会科学区别于其他哲学社会科学的根本标志是", "options": {"A": "坚持以马克思主义为指导", "B": "坚持正确的政治方向", "C": "坚持党性原则", "D": "坚持以人民为中心"}, "answer": ["A"], "note": "当代中国哲学社会科学区别于其他哲学社会科学的根本标志是：坚持以马克思主义为指导", "sourcePages": [88], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-58", "subject": "新思想", "chapter": 10, "chapterTitle": "第十章建设社会主义文化强国", "type": "单选", "number": 58, "stem": "新闻舆论工作是治国理政、定国安邦的大事。做好新闻舆论工作的第一位要求是", "options": {"A": "做大做强主流舆论阵地", "B": "管好用好互联网", "C": "提高新闻舆论传播力、引导力、影响力、公信力", "D": "坚持正确的政治方向"}, "answer": ["D"], "note": "做好新闻舆论工作的第一位要求是：坚持正确的政治方向", "sourcePages": [88, 89], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-60", "subject": "新思想", "chapter": 10, "chapterTitle": "第十章建设社会主义文化强国", "type": "单选", "number": 60, "stem": "中华文明具有突出的连续性，是世界上唯一绵延不断且以国家形态发展至今的伟大文明。中华文明的连续性，从根本上决定了", "options": {"A": "国家统一永远是中国核心利益的核心", "B": "国土不可分、国家不可乱、民族不可散、文明不可断的共同信念", "C": "中华民族不惧新挑战、勇于接受新事物的无畏品格", "D": "中华民族必然走自己的路"}, "answer": ["D"], "note": "中华文明的连续性，从根本上决定了：中华民族必然走自己的路", "sourcePages": [89], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-61", "subject": "新思想", "chapter": 10, "chapterTitle": "第十章建设社会主义文化强国", "type": "单选", "number": 61, "stem": "随着我国社会主要矛盾的转化，人民对美好生活的向往越来越强烈，对精神文化生活更加看重，文化需求高品质、个性化的特点更加明显。满足人民精神文化需求、保障人民文化权益的基本途径是", "options": {"A": "繁荣发展文化事业和文化产业", "B": "推动中华优秀传统文化创造性转化、创新性发展", "C": "提升国家文化软实力", "D": "保护好、传承好文化遗产"}, "answer": ["A"], "note": "满足人民精神文化需求、保障人民文化权益的基本途径是：繁荣发展文化事业和文化产业", "sourcePages": [89], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-83", "subject": "新思想", "chapter": 10, "chapterTitle": "第十章建设社会主义文化强国", "type": "多选", "number": 83, "stem": "文化是一个国家、一个民族的灵魂。国家的富强，民族的振兴，无不伴随着文化的历史性进步。国家强大、民族兴盛、社会发展，不仅需要高度发达的物质文明，也需要高度繁荣的精神文明。文化繁荣兴盛是", "options": {"A": "实现中华民族伟大复兴的精神支撑", "B": "建设社会主义现代化强国的应有之义", "C": "满足人民日益增长的美好生活需要的内在要求", "D": "在世界文化激荡中站稳脚跟的前提基础"}, "answer": ["A", "B", "C", "D"], "note": "文化繁荣兴盛是：实现中华民族伟大复兴的精神支撑；建设社会主义现代化强国的应有之义；满足人民日益增长的美好生活需要的内在要求；在世界文化激荡中站稳脚跟的前提基础", "sourcePages": [106], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-84", "subject": "新思想", "chapter": 10, "chapterTitle": "第十章建设社会主义文化强国", "type": "多选", "number": 84, "stem": "中国式现代化是物质文明和精神文明相协调的现代化，全面建成社会主义现代化强国必然要求建设社会主义文化强国。文化是", "options": {"A": "统筹推进“五位一体”总体布局、协调推进“四个全面”战略布局的重要内容", "B": "推动高质量发展的重要支点", "C": "满足人民日益增长的美好生活需要的重要因素", "D": "战胜前进道路上各种风险挑战的重要力量源泉"}, "answer": ["A", "B", "C", "D"], "note": "文化是：统筹推进“五位一体”总体布局、协调推进“四个全面”战略布局的重要内容；推动高质量发展的重要支点；满足人民日益增长的美好生活需要的重要因素；战胜前进道路上各种风险挑战的重要力量源泉", "sourcePages": [106], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-85", "subject": "新思想", "chapter": 10, "chapterTitle": "第十章建设社会主义文化强国", "type": "多选", "number": 85, "stem": "2024年8月21日，在外交部发言人主持的例行记者会上，有记者问，中国游戏《黑神话：悟空》全球火爆推出，其中的中国文化元素令玩家印象深刻，请问发言人有何评论？外交部发言人表示：“我不了解电子游戏，但是感谢你让我关注到这款游戏。从名字看，这款游戏取材于中国古典文学名著《西游记》，我想这也反映了中国文化的吸引力。”中华优秀传统文化是", "options": {"A": "我们坚定文化自信的深厚基础", "B": "中华民族的根和魂", "C": "最深厚的文化软实力", "D": "我们在世界文化激荡中站稳脚跟的根基"}, "answer": ["A", "B", "C", "D"], "note": "中华优秀传统文化是：我们坚定文化自信的深厚基础；中华民族的根和魂；最深厚的文化软实力；我们在世界文化激荡中站稳脚跟的根基", "sourcePages": [106], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-86", "subject": "新思想", "chapter": 10, "chapterTitle": "第十章建设社会主义文化强国", "type": "多选", "number": 86, "stem": "中华文明源远流长、博大精深，是世界上唯一绵延不断且以国家形态发展至今的伟大文明。中华文明是", "options": {"A": "中华民族独特的精神标识", "B": "当代中国文化的根基", "C": "维系全世界华人的精神纽带", "D": "中国文化创新的宝藏"}, "answer": ["A", "B", "C", "D"], "note": "中华文明是：中华民族独特的精神标识；当代中国文化的根基；维系全世界华人的精神纽带；中国文化创新的宝藏", "sourcePages": [106], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-87", "subject": "新思想", "chapter": 10, "chapterTitle": "第十章建设社会主义文化强国", "type": "多选", "number": 87, "stem": "2025年春节档，《哪吒之魔童闹海》燃爆大银幕。影片自上映以来，屡屡刷新中国影史、世界影史多项纪录。2025年是中国电影诞生120周年。《哪吒之魔童闹海》作为全球电影票房排行榜前10名中唯一的非好莱坞影片，为中国电影诞生120周年献上了一份沉甸甸的厚礼，也激发了中华儿女的民族自豪感和文化自信心。《哪吒之魔童闹海》国际版海报上那句“我偏要踏出一条自己的路”，正是今天中国人坚定文化自信的写照。我们坚定文化自信的底气在于", "options": {"A": "中华优秀传统文化是我们坚定文化自信的深厚基础", "B": "党带领人民在伟大斗争中孕育的革命文化和社会主义先进文化是我们坚定文化自信的坚强基石", "C": "中国特色社会主义伟大实践是我们坚定文化自信的现实基础", "D": "全人类共同价值是我们坚定文化自信的价值基础"}, "answer": ["A", "B", "C"], "note": "我们坚定文化自信的底气在于中华优秀传统文化是我们坚定文化自信的深厚基础：党带领人民在伟大斗争中孕育的革命文化和社会主义先进文化是我们坚定文化自信的坚强基石；中国特色社会主义伟大实践是我们坚定文化自信的现实基础", "sourcePages": [106], "answerSource": "配套资料与题目核对"}, {"id": "新思想-多选-88", "subject": "新思想", "chapter": 10, "chapterTitle": "第十章建设社会主义文化强国", "type": "多选", "number": 88, "stem": "中国特色社会主义文化发展道路，是推动社会主义文化繁荣兴盛的唯一正确道路。全面建设社会主义现代化国家，必须坚持中国特色社会主义文化发展道路。决定社会主义文化事业前途命运的关键是", "options": {"A": "坚持为人民服务", "B": "坚持为社会主义服务", "C": "坚持百花齐放", "D": "坚持百家争鸣"}, "answer": ["A", "B"], "note": "决定社会主义文化事业前途命运的关键是：坚持为人民服务；坚持为社会主义服务", "sourcePages": [106], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-90", "subject": "新思想", "chapter": 10, "chapterTitle": "第十章建设社会主义文化强国", "type": "多选", "number": 90, "stem": "核心价值观是一个民族赖以维系的精神纽带，是一个国家共同的思想道德基础。社会主义核心价值观", "options": {"A": "体现了社会主义本质要求", "B": "继承了中华优秀传统文化", "C": "吸收了世界文明有益成果", "D": "体现了时代精神"}, "answer": ["A", "B", "C", "D"], "note": "社会主义核心价值观：体现了社会主义本质要求；继承了中华优秀传统文化；吸收了世界文明有益成果；体现了时代精神", "sourcePages": [107], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-91", "subject": "新思想", "chapter": 10, "chapterTitle": "第十章建设社会主义文化强国", "type": "多选", "number": 91, "stem": "海纳百川，有容乃大。文明的繁荣、人类的进步，离不开求同存异、开放包容，离不开文明交流、互学互鉴。中华文明自古就以开放包容闻名于世。中华文明具有突出的包容性，从根本上决定了", "options": {"A": "中华民族交往交流交融的历史取向", "B": "中国各宗教信仰多元并存的和谐格局", "C": "中华文化对世界文明兼收并蓄的开放胸怀", "D": "中国不断追求文明交流互鉴而不搞文化霸权"}, "answer": ["A", "B", "C"], "note": "中华文明具有突出的包容性，从根本上决定了：中华民族交往交流交融的历史取向；中国各宗教信仰多元并存的和谐格局；中华文化对世界文明兼收并蓄的开放胸怀", "sourcePages": [107], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-92", "subject": "新思想", "chapter": 10, "chapterTitle": "第十章建设社会主义文化强国", "type": "多选", "number": 92, "stem": "英国哲学家罗素这样评价中国文化中的和平传统：“中国至高无上的伦理品质中的一些东西，现代世界极为需要”，“若能够被世界采纳，地球上肯定比现在有更多的欢乐祥和”。中华文明历来崇尚“以和邦国” “和而不同” “以和为贵”，中华民族的血液中没有侵略他人、称王称霸的基因。中华文明具有的和平性，从根本上决定了中国", "options": {"A": "始终是世界和平的建设者、全球发展的贡献者、国际秩序的维护者", "B": "不断追求文明交流互鉴而不搞文化霸权", "C": "不会把自己的价值观念与政治体制强加于人", "D": "坚持合作、不搞对抗，决不搞“党同伐异”的小圈子"}, "answer": ["A", "B", "C", "D"], "note": "中华文明具有的和平性，从根本上决定了中国：始终是世界和平的建设者、全球发展的贡献者、国际秩序的维护者；不断追求文明交流互鉴而不搞文化霸权；不会把自己的价值观念与政治体制强加于人；坚持合作、不搞对抗，决不搞“党同伐异”的小圈子", "sourcePages": [107], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-62", "subject": "新思想", "chapter": 11, "chapterTitle": "第十一章以保障和改善民生为重点加强社会建设", "type": "单选", "number": 62, "stem": "全面建设社会主义现代化国家，是一项伟大而艰巨的事业，前途光明，任重道远。全面建设社会主义现代化国家，出发点和落脚点是", "options": {"A": "让人民生活越过越好", "B": "国家富强、民族振兴", "C": "国家长治久安、社会安定有序", "D": "解放和增强社会活力"}, "answer": ["A"], "note": "全面建设社会主义现代化国家，出发点和落脚点是：让人民生活越过越好", "sourcePages": [89], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-63", "subject": "新思想", "chapter": 11, "chapterTitle": "第十一章以保障和改善民生为重点加强社会建设", "type": "单选", "number": 63, "stem": "改革、发展、稳定是我国社会主义现代化建设的三个重要支点。其中，发展是解决一切经济社会问题的关键。发展的根本目的是", "options": {"A": "消除绝对贫困", "B": "增进民生福祉", "C": "跳出历史周期率", "D": "促进社会稳定"}, "answer": ["B"], "note": "发展的根本目的是：增进民生福祉", "sourcePages": [89], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-64", "subject": "新思想", "chapter": 11, "chapterTitle": "第十一章以保障和改善民生为重点加强社会建设", "type": "单选", "number": 64, "stem": "民生事关人民的生存生活生计，事关民心所向、民情所系、民意所指，决定党的事业成败和国家命运兴衰。保障和改善民生的重要方针是", "options": {"A": "坚持尽力而为、量力而行", "B": "坚守底线、突出重点", "C": "完善制度、引导预期", "D": "坚持人人尽责、人人享有"}, "answer": ["A"], "note": "保障和改善民生的重要方针是：坚持尽力而为、量力而行", "sourcePages": [89], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-65", "subject": "新思想", "chapter": 11, "chapterTitle": "第十一章以保障和改善民生为重点加强社会建设", "type": "单选", "number": 65, "stem": "改善民生、实现发展成果由人民共享最重要最直接的方式是", "options": {"A": "稳就业", "B": "城镇化", "C": "社会保障", "D": "收入分配"}, "answer": ["D"], "note": "改善民生、实现发展成果由人民共享最重要最直接的方式是：收入分配", "sourcePages": [89], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-66", "subject": "新思想", "chapter": 11, "chapterTitle": "第十一章以保障和改善民生为重点加强社会建设", "type": "单选", "number": 66, "stem": "实现共同富裕不仅是经济问题，而且是关系党的执政基础的重大政治问题。促进共同富裕的基础性制度是", "options": {"A": "社会保障制度", "B": "分配制度", "C": "基本养老保险制度", "D": "以人民为中心的法律制度"}, "answer": ["B"], "note": "促进共同富裕的基础性制度是：分配制度", "sourcePages": [90], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-67", "subject": "新思想", "chapter": 11, "chapterTitle": "第十一章以保障和改善民生为重点加强社会建设", "type": "单选", "number": 67, "stem": "经过接续奋斗，我国社会建设全面加强，人民安居乐业、社会安定有序的良好局面不断巩固发展，人民对美好生活的向往不断变为现实。新时代加强社会建设的重要着力点是", "options": {"A": "健全和完善社会保障体系", "B": "正确把握民生和发展的关系", "C": "全面推进健康中国建设", "D": "防范化解重大风险"}, "answer": ["A"], "note": "新时代加强社会建设的重要着力点是：健全和完善社会保障体系", "sourcePages": [90], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-95", "subject": "新思想", "chapter": 11, "chapterTitle": "第十一章以保障和改善民生为重点加强社会建设", "type": "多选", "number": 95, "stem": "治国有常，利民为本。民生是老百姓最关心的问题，涉及分配、就业、教育、医疗、住房、社会保障等方面。随着经济社会的发展进步，人民生活品质的不断提高，民生内涵也在不断丰富。民生", "options": {"A": "事关人民的生存生活生计", "B": "事关民心所向、民情所系、民意所指", "C": "是国家强盛之基、安全之要", "D": "决定党的事业成败和国家命运兴衰"}, "answer": ["A", "B", "D"], "note": "民生事关人民的生存生活生计；事关民心所向、民情所系、民意所指；决定党的事业成败和国家命运兴衰", "sourcePages": [107], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-96", "subject": "新思想", "chapter": 11, "chapterTitle": "第十一章以保障和改善民生为重点加强社会建设", "type": "多选", "number": 96, "stem": "习近平指出，以人民为中心是我们党的根本执政理念，让人民生活幸福是“国之大者”。全面建设社会主义现代化国家，出发点和落脚点是让人民生活越过越好。要增进民生福祉，扎实推进各项民生事业，使改革发展成果更多更公平惠及全体人民。增进民生福社是", "options": {"A": "坚持立党为公、执政为民的本质要求", "B": "社会主义生产的根本目的", "C": "全面建设社会主义现代化国家的应有之义", "D": "推动高质量发展的战略基点"}, "answer": ["A", "B", "C"], "note": "增进民生福社是：坚持立党为公、执政为民的本质要求；社会主义生产的根本目的；全面建设社会主义现代化国家的应有之义", "sourcePages": [108], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-97", "subject": "新思想", "chapter": 11, "chapterTitle": "第十一章以保障和改善民生为重点加强社会建设", "type": "多选", "number": 97, "stem": "党的十八大以来，党中央坚持把就业工作摆在治国理政的突出位置，强化就业优先政策，健全就业促进机制，有效应对各种压力挑战，为民生改善和经济发展提供了重要支撑。国家如此重视就业，是因为就业是", "options": {"A": "民生改善的“温度计”", "B": "经济发展的“晴雨表”", "C": "劳动者获得收入、提高生活水平的基本途径", "D": "支撑宏观经济和微观经济运行的“基本盘”"}, "answer": ["A", "B", "C", "D"], "note": "就业是：民生改善的“温度计”；经济发展的“晴雨表”；劳动者获得收入、提高生活水平的基本途径；支撑宏观经济和微观经济运行的“基本盘”", "sourcePages": [108], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-98", "subject": "新思想", "chapter": 11, "chapterTitle": "第十一章以保障和改善民生为重点加强社会建设", "type": "多选", "number": 98, "stem": "新时代的10多年，我国建成了世界上规模最大的社会保障体系。2012年到2025年，基本养老保险参保人数从7.9亿人增加到10.76亿人，基本医疗保险参保人数从5.4亿人增加到13.31亿人，社会保障网越织越密。社会保障", "options": {"A": "是保障和改善民生、维护社会公平、增进人民福社的基本制度保障", "B": "是促进经济社会发展、实现广大人民群众共享改革发展成果的重要制度安排", "C": "是第三次分配制度的重要组成部分", "D": "发挥着民生保障安全网、收入分配调节器、经济运行减震器的作用"}, "answer": ["A", "B", "D"], "note": "社会保障：是保障和改善民生、维护社会公平、增进人民福社的基本制度保障；是促进经济社会发展、实现广大人民群众共享改革发展成果的重要制度安排；发挥着民生保障安全网、收入分配调节器、经济运行减震器的作用", "sourcePages": [108], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-99", "subject": "新思想", "chapter": 11, "chapterTitle": "第十一章以保障和改善民生为重点加强社会建设", "type": "多选", "number": 99, "stem": "社会治理是国家治理的重要领域，推进社会治理现代化是推进国家治理体系和治理能力现代化的重要内容。新时代加强和创新社会治理，要求坚持", "options": {"A": "系统治理", "B": "依法治理", "C": "综合治理", "D": "源头治理"}, "answer": ["A", "B", "C", "D"], "note": "新时代加强和创新社会治理，要求坚持系统治理；依法治理；综合治理；源头治理", "sourcePages": [108], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-68", "subject": "新思想", "chapter": 12, "chapterTitle": "第十二章建设社会主义生态文明", "type": "单选", "number": 68, "stem": "生态环境变化直接影响文明的兴衰演替。生态环境问题归根到底是", "options": {"A": "政府与市场的关系问题", "B": "人与社会的关系问题", "C": "人与人的关系问题", "D": "经济发展方式和生活方式问题"}, "answer": ["D"], "note": "生态环境问题归根到底是：经济发展方式和生活方式问题", "sourcePages": [90], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-69", "subject": "新思想", "chapter": 12, "chapterTitle": "第十二章建设社会主义生态文明", "type": "单选", "number": 69, "stem": "生态兴则文明兴，生态衰则文明衰。生态环境是人类生存最为基础的条件，生态文明建设是关系中华民族永续发展的根本大计。解决生态环境问题的治本之策是", "options": {"A": "资源循环利用", "B": "绿色低碳发展", "C": "产业结构优化升级", "D": "严守生态保护红线"}, "answer": ["B"], "note": "解决生态环境问题的治本之策是绿色低碳发展", "sourcePages": [90], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-70", "subject": "新思想", "chapter": 12, "chapterTitle": "第十二章建设社会主义生态文明", "type": "单选", "number": 70, "stem": "实现碳达峰碳中和，是中国站在对人类文明负责的高度，基于实现可持续发展的内在要求作出的重大决策部署。实现碳达峰碳中和的关键是", "options": {"A": "大力推进循环经济", "B": "实施节能降碳增效行动", "C": "能源绿色低碳转型", "D": "巩固提升碳汇能力"}, "answer": ["C"], "note": "实现碳达峰碳中和的关键是能源绿色低碳转型", "sourcePages": [90], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-101", "subject": "新思想", "chapter": 12, "chapterTitle": "第十二章建设社会主义生态文明", "type": "多选", "number": 101, "stem": "保护自然就是保护人类，建设生态文明就是造福人类。生态文明之所以重要，是因为", "options": {"A": "生态环境变化直接影响文明的兴衰演替", "B": "生态文明是人类文明发展的历史趋势", "C": "生态文明建设是重大经济问题", "D": "生态文明建设是关系党的使命宗旨的重大政治问题、关系民生福祉的重大社会问题"}, "answer": ["A", "B", "C", "D"], "note": "生态文明之所以重要，是因为生态环境变化直接影响文明的兴衰演替；生态文明是人类文明发展的历史趋势；生态文明建设是重大经济问题；生态文明建设是关系党的使命宗旨的重大政治问题、关系民生福社的重大社会问题", "sourcePages": [108], "answerSource": "配套资料与题目核对"}, {"id": "新思想-多选-103", "subject": "新思想", "chapter": 12, "chapterTitle": "第十二章建设社会主义生态文明", "type": "多选", "number": 103, "stem": "绿水青山就是金山银山理念是立足自身国情和发展实践形成的中国自主生态文明建设理论，符合人类社会发展规律和生态文明建设规律，在实践中展现出强大的真理力量和独特的思想魅力。绿水青山就是金山银山理念", "options": {"A": "创新和突破了现代环境经济理论", "B": "推进和拓展了中国式现代化道路", "C": "传承和发展了中华优秀传统生态文化", "D": "推动和创造了人类文明新形态"}, "answer": ["A", "B", "C", "D"], "note": "绿水青山就是金山银山理念创新和突破了现代环境经济理论；推进和拓展了中国式现代化道路；传承和发展了中华优秀传统生态文化；推动和创造了人类文明新形态", "sourcePages": [109], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-105", "subject": "新思想", "chapter": 12, "chapterTitle": "第十二章建设社会主义生态文明", "type": "多选", "number": 105, "stem": "新时代我国生态文明建设的重大成就表现在", "options": {"A": "生态文明建设战略地位更加凸显", "B": "生态文明制度体系更加健全", "C": "污染防治和生态保护更加有力", "D": "生态环境保护结构性、根源性、趋势性压力得到根本缓解"}, "answer": ["A", "B", "C"], "note": "新时代我国生态文明建设的重大成就表现在生态文明建设战略地位更加凸显；生态文明制度体系更加健全；污染防治和生态保护更加有力", "sourcePages": [109], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-71", "subject": "新思想", "chapter": 13, "chapterTitle": "第十三章维护和塑造国家安全", "type": "单选", "number": 71, "stem": "总体国家安全观，既回答了如何解决好大国发展进程中面临的共性安全问题，同时又回答了如何解决好中华民族伟大复兴关键时期面临的特殊安全问题，系统提出了一系列具有原创性、时代性的重要观点，为破解我国国家安全面临的难题、推进新时代国家安全工作提供了基本遵循。新时代中国国家安全的生命线是", "options": {"A": "人民安全", "B": "政治安全", "C": "坚守维护国家利益准则", "D": "防范化解国家安全风险"}, "answer": ["B"], "note": "新时代中国国家安全的生命线是政治安全", "sourcePages": [90], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-72", "subject": "新思想", "chapter": 13, "chapterTitle": "第十三章维护和塑造国家安全", "type": "单选", "number": 72, "stem": "构建新发展格局是事关全局的系统性、深层次变革，是立足当前、着眼长远的战略谋划，是适应我国发展新阶段要求、塑造国际合作和竞争新优势的必然选择。构建新发展格局的重要前提和保障是", "options": {"A": "主动塑造于我有利的外部安全环境", "B": "夯实我国经济发展的根基", "C": "统筹维护国家安全各类要素、各个领域、各方资源、各种手段", "D": "牢牢守住安全发展这条底线"}, "answer": ["D"], "note": "构建新发展格局的重要前提和保障是：牢牢守住安全发展这条底线", "sourcePages": [90], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-73", "subject": "新思想", "chapter": 13, "chapterTitle": "第十三章维护和塑造国家安全", "type": "单选", "number": 73, "stem": "构建新安全格局是应对国家安全形势新变化、新趋势的战略选择。要坚定不移走中国特色国家安全道路，加快构建统筹各领域安全的新安全格局。应对各领域安全风险挑战的首要任务是", "options": {"A": "维护国土安全", "B": "维护政治安全", "C": "维护社会安全", "D": "维护粮食安全"}, "answer": ["B"], "note": "应对各领域安全风险挑战的首要任务是：维护政治安全", "sourcePages": [90], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-74", "subject": "新思想", "chapter": 13, "chapterTitle": "第十三章维护和塑造国家安全", "type": "单选", "number": 74, "stem": "总体国家安全观以人民安全为宗旨，以政治安全为根本，实现政治安全、人民安全、国家利益至上有机统一。其中，居于中心地位的是", "options": {"A": "政治安全", "B": "人民安全", "C": "国家利益至上", "D": "确保实现党的长期执政、人民安居乐业、国家长治久安"}, "answer": ["B"], "note": "总体国家安全观以人民安全为宗旨，以政治安全为根本，实现政治安全、人民安全、国家利益至上有机统一。其中，居于中心地位的是：人民安全", "sourcePages": [91], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-75", "subject": "新思想", "chapter": 13, "chapterTitle": "第十三章维护和塑造国家安全", "type": "单选", "number": 75, "stem": "构建新安全格局是全面贯彻落实总体国家安全观的重大举措。构建统筹各领域安全的新安全格局的主阵地、主战场是", "options": {"A": "维护意识形态安全", "B": "维护制度安全", "C": "维护政权安全", "D": "维护重点领域国家安全"}, "answer": ["D"], "note": "构建统筹各领域安全的新安全格局的主阵地、主战场是：维护重点领域国家安全", "sourcePages": [91], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-109", "subject": "新思想", "chapter": 13, "chapterTitle": "第十三章维护和塑造国家安全", "type": "多选", "number": 109, "stem": "构建统筹各领域安全的新安全格局，必须把维护政治安全作为应对各领域安全风险挑战的首要任务。这是因为", "options": {"A": "政治安全是国家安全的根本", "B": "政治安全是一切国家生存和发展的基础条件", "C": "政治安全决定和影响着国家其他各个领域的安全", "D": "只要维护好了政治安全，其他领域的安全问题就会自动解决"}, "answer": ["A", "B", "C"], "note": "构建统筹各领域安全的新安全格局，必须把维护政治安全作为应对各领域安全风险挑战的首要任务。这是因为政治安全是国家安全的根本；政治安全是一切国家生存和发展的基础条件；政治安全决定和影响着国家其他各个领域的安全", "sourcePages": [110], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-76", "subject": "新思想", "chapter": 14, "chapterTitle": "第十四章建设巩固国防和强大人民军队", "type": "单选", "number": 76, "stem": "2025年9月3日，纪念中国人民抗日战争暨世界反法西斯战争胜利80周年大会在首都北京隆重举行。人民军队光荣接受党和人民检阅。阅兵场上，一系列先进装备震撼亮相：新型坦克、步兵战车等新一代传统陆战兵器，无人、水下、网电等领域新型作战装备，高超声速导弹、战略导弹等国之重器…：“以武止戈、砥定乾坤”，彰显的是新时代中国发展进步的硬核实力，展现的是人民军队捍卫和平的强大能力。“能战方能止战，准备打才可能不必打，越不能打越可能挨打。”这说明，强军兴军，核心是", "options": {"A": "听党指挥", "B": "能打胜仗", "C": "作风优良", "D": "艰苦奋斗"}, "answer": ["B"], "note": "强军兴军，核心是能打胜仗", "sourcePages": [91], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-77", "subject": "新思想", "chapter": 14, "chapterTitle": "第十四章建设巩固国防和强大人民军队", "type": "单选", "number": 77, "stem": "坚持党对人民军队绝对领导的根本制度和根本实现形式是", "options": {"A": "支部建在连上", "B": "政治委员制", "C": "军委主席负责制", "D": "首长分工负责制"}, "answer": ["C"], "note": "坚持党对人民军队绝对领导的根本制度和根本实现形式是：军委主席负责制", "sourcePages": [91], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-78", "subject": "新思想", "chapter": 14, "chapterTitle": "第十四章建设巩固国防和强大人民军队", "type": "单选", "number": 78, "stem": "党的十八大以来，我们深入推进政治建军理论探索和实践创造，形成了新时代政治建军方略，明确政治建军是", "options": {"A": "掌握一切领导的基础", "B": "人民军队立军之本", "C": "我军胜利法宝", "D": "我军的生命线"}, "answer": ["B"], "note": "政治建军是：人民军队立军之本", "sourcePages": [91], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-112", "subject": "新思想", "chapter": 14, "chapterTitle": "第十四章建设巩固国防和强大人民军队", "type": "多选", "number": 112, "stem": "进入新时代，以习近平同志为核心的党中央着眼实现中华民族伟大复兴这个国家和民族最高利益，对人民军队使命任务作出新定位、提出新要求，概括起来就是", "options": {"A": "为巩固中国共产党领导和我国社会主义制度提供战略支撑", "B": "为捍卫国家主权、统一和领土完整提供战略支撑", "C": "为维护我国海外利益提供战略支撑", "D": "为促进世界和平与发展提供战略支撑"}, "answer": ["A", "B", "C", "D"], "note": "进入新时代，以主席为核心的党中央着眼实现中华民族伟大复兴这个国家和民族最高利益，对人民军队使命任务作出新定位、提出新要求，概括起来就是：为巩固中国共产党领导和我国社会主义制度提供战略支撑；为捍卫国家主权、统一和领土完整提供战略支撑；为维护我国海外利益提供战略支撑；为促进世界和平与发展提供战略支撑", "sourcePages": [110], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-113", "subject": "新思想", "chapter": 14, "chapterTitle": "第十四章建设巩固国防和强大人民军队", "type": "多选", "number": 113, "stem": "中华民族实现伟大复兴，中国人民实现更加美好生活，必须加快把人民军队建设成为世界一流军队。新时代加强军队建设的聚焦点和着力点是", "options": {"A": "军民融合", "B": "听党指挥", "C": "能打胜仗", "D": "作风优良"}, "answer": ["B", "C", "D"], "note": "新时代加强军队建设的聚焦点和着力点是听党指挥；能打胜仗；作风优良", "sourcePages": [110], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-114", "subject": "新思想", "chapter": 14, "chapterTitle": "第十四章建设巩固国防和强大人民军队", "type": "多选", "number": 114, "stem": "90多年来，人民军队之所以能够始终保持强大的凝聚力、向心力、战斗力，经受住各种考验，不断从胜利走向胜利，最根本的就是靠党的坚强领导。实践证明，听党指挥是", "options": {"A": "人民军队建设的首要", "B": "人民军队的命脉所在", "C": "人民军队的鲜明特色和政治优势", "D": "新时代强军目标的核心"}, "answer": ["A", "B"], "note": "实践证明，听党指挥是人民军队建设的首要；人民军队的命脉所在", "sourcePages": [110], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-79", "subject": "新思想", "chapter": 15, "chapterTitle": "第十五章坚持“一国两制”和推进祖国完全统一", "type": "单选", "number": 79, "stem": "“一国两制”是中国共产党领导人民实现祖国和平统一的伟大构想。“一国两制”方针的最高原则是", "options": {"A": "维护国家主权、安全、发展利益", "B": "实现祖国和平统一", "C": "确保中华民族伟大复兴进程不被迟滞甚至中断", "D": "政权必须掌握在爱国者手中"}, "answer": ["A"], "note": "“一国两制”方针的最高原则是：维护国家主权、安全、发展利益", "sourcePages": [91], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-80", "subject": "新思想", "chapter": 15, "chapterTitle": "第十五章坚持“一国两制”和推进祖国完全统一", "type": "单选", "number": 80, "stem": "新时代党解决台湾问题的总体方略内涵丰富、逻辑严密、系统完备，深刻回答了推进祖国统一的一系列重大理论和实践问题，是我们党对台大政方针的继承发展和集大成。其中，作为统一的历史方位的是", "options": {"A": "坚持在祖国大陆发展进步基础上解决台湾问题", "B": "坚持一个中国原则和“九二共识”", "C": "坚持推动两岸关系和平发展、融合发展", "D": "坚持在中华民族伟大复兴进程中推进祖国统一"}, "answer": ["D"], "note": "统一的历史方位的是：坚持在中华民族伟大复兴进程中推进祖国统一", "sourcePages": [91], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-81", "subject": "新思想", "chapter": 15, "chapterTitle": "第十五章坚持“一国两制”和推进祖国完全统一", "type": "单选", "number": 81, "stem": "在新时代党解决台湾问题的总体方略中，作为统一的战略支撑的是", "options": {"A": "坚持决不承诺放弃使用武力", "B": "坚持粉碎“台独”分裂图谋", "C": "坚持团结台湾同胞、争取台湾民心", "D": "坚持反对外部势力干涉"}, "answer": ["A"], "note": "统一的战略支撑的是：坚持决不承诺放弃使用武力", "sourcePages": [92], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-115", "subject": "新思想", "chapter": 15, "chapterTitle": "第十五章坚持“一国两制”和推进祖国完全统一", "type": "多选", "number": 115, "stem": "“一国两制”立足中国国情，把原则性和灵活性、现实性和长远性、一致性和差异性统一起来，凝结了中国共产党人为解决国家统一问题展现出的超凡勇气和卓越智慧，是前无古人的伟大创举。“一国两制”", "options": {"A": "是中国特色社会主义制度创新的重要成果", "B": "是中国共产党领导人民实现祖国和平统一的伟大构想", "C": "包含了中华文化中的和合理念", "D": "为国际社会解决类似问题提供了新思路、新方案"}, "answer": ["A", "B", "C", "D"], "note": "“一国两制：是中国特色社会主义制度创新的重要成果；是中国共产党领导人民实现祖国和平统一的伟大构想；包含了中华文化中的和合理念；为国际社会解决类似问题提供了新思路、新方案", "sourcePages": [110], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-117", "subject": "新思想", "chapter": 15, "chapterTitle": "第十五章坚持“一国两制”和推进祖国完全统一", "type": "多选", "number": 117, "stem": "“一国两制”是党领导人民实现祖国和平统一的一项重要制度，是国家的一项基本国策。“一国两制”的根本宗旨是", "options": {"A": "维护国家主权、安全、发展利益", "B": "保持香港、澳门长期繁荣稳定", "C": "维护台海和平稳定", "D": "增强中华儿女对伟大祖国的认同感"}, "answer": ["A", "B"], "note": "“一国两制”的根本宗旨是：维护国家主权、安全、发展利益；保持香港、澳门长期繁荣稳定", "sourcePages": [111], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-120", "subject": "新思想", "chapter": 15, "chapterTitle": "第十五章坚持“一国两制”和推进祖国完全统一", "type": "多选", "number": 120, "stem": "党的十八大以来，以习近平同志为核心的党中央积极推进对台工作理论和实践创新，形成新时代党解决台湾问题的总体方略，牢牢把握两岸关系主导权和主动权，扎实推进祖国统一进程。解决台湾问题、实现祖国完全统一，是", "options": {"A": "中国共产党矢志不渝的历史任务", "B": "全体中华儿女的共同愿望", "C": "由中华民族伟大复兴的时和势所决定的", "D": "实现中华民族伟大复兴的必然要求"}, "answer": ["A", "B", "C", "D"], "note": "解决台湾问题、实现祖国完全统一，是：中国共产党矢志不渝的历史任务；全体中华儿女的共同愿望；由中华民族伟大复兴的时和势所决定的；实现中华民族伟大复兴的必然要求", "sourcePages": [111], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-82", "subject": "新思想", "chapter": 16, "chapterTitle": "第十六章中国特色大国外交和推动构建人类命运共同体", "type": "单选", "number": 82, "stem": "外交工作是党和国家工作全局的重要组成部分。中国特色大国外交牢牢把握的主线是", "options": {"A": "服务民族复兴、促进人类进步", "B": "相互尊重、合作共赢", "C": "打造全球伙伴关系、维护多边主义", "D": "维护世界和平、促进共同发展"}, "answer": ["A"], "note": "中国特色大国外交牢牢把握的主线是：服务民族复兴、促进人类进步", "sourcePages": [92], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-83", "subject": "新思想", "chapter": 16, "chapterTitle": "第十六章中国特色大国外交和推动构建人类命运共同体", "type": "单选", "number": 83, "stem": "周边是我国安身立命之所、发展繁荣之基。无论从地理方位、自然环境还是相互关系看，周边对我国都具有极为重要的战略意义。我国始终将周边置于外交全局的首要位置，秉持的周边外交理念是", "options": {"A": "与邻为善、以邻为伴", "B": "真实亲诚", "C": "亲诚惠容", "D": "求同存异、相互尊重、互学互鉴"}, "answer": ["C"], "note": "我国始终将周边置于外交全局的首要位置，秉持的周边外交理念是：亲诚惠容", "sourcePages": [92], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-84", "subject": "新思想", "chapter": 16, "chapterTitle": "第十六章中国特色大国外交和推动构建人类命运共同体", "type": "单选", "number": 84, "stem": "新时代新征程，要继续全面推进我国对外工作，不断开创中国特色大国外交新局面。我国对外工作的出发点和落脚点是", "options": {"A": "坚定奉行独立自主的和平外交政策", "B": "维护国家主权、安全、发展利益", "C": "推动构建人类命运共同体", "D": "坚持走和平发展道路"}, "answer": ["B"], "note": "我国对外工作的出发点和落脚点是：维护国家主权、安全、发展利益", "sourcePages": [92], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-122", "subject": "新思想", "chapter": 16, "chapterTitle": "第十六章中国特色大国外交和推动构建人类命运共同体", "type": "多选", "number": 122, "stem": "坚持走和平发展道路，是我们党根据时代发展潮流和我国根本利益作出的战略执择。走和平发展道路", "options": {"A": "是由中国共产党性质宗旨和我国社会主义制度决定的", "B": "是基于中国历史文化传统作出的必然选择", "C": "是新时代对外工作的总目标", "D": "符合历史潮流、顺应世界大势"}, "answer": ["A", "B", "D"], "note": "走和平发展道路：是由中国共产党性质宗旨和我国社会主义制度决定的；是基于中国历史文化传统作出的必然选择；符合历史潮流、顺应世界大势", "sourcePages": [111], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-123", "subject": "新思想", "chapter": 16, "chapterTitle": "第十六章中国特色大国外交和推动构建人类命运共同体", "type": "多选", "number": 123, "stem": "构建人类命运共同体，就是为了造福各国人民，促进世界和平，实现共同繁荣和发展。共建“一带一路”", "options": {"A": "是对中国与世界实现开放共赢路径的顶层设计", "B": "是推动构建人类命运共同体的实践平台", "C": "根植历史、更面向未来，源于中国、更属于世界", "D": "追求的是发展，崇尚的是共赢，传递的是希望"}, "answer": ["A", "B", "C", "D"], "note": "共建“一带一路”：是对中国与世界实现开放共赢路径的顶层设计；是推动构建人类命运共同体的实践平台；根植历史、更面向未来，源于中国、更属于世界；追求的是发展，崇尚的是共赢，传递的是希望", "sourcePages": [112], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-85", "subject": "新思想", "chapter": 17, "chapterTitle": "第十七章全面从严治党", "type": "单选", "number": 85, "stem": "把党的建设作为一项伟大工程来推进，是我们党的一大创举，是我们党领导人民进行伟大社会革命的重要法宝。党的建设的一贯要求和根本方针是", "options": {"A": "坚持思想建党和制度治党相统一", "B": "坚持党内监督和群众监督相统一", "C": "自我净化、自我完善、自我革新、自我提高", "D": "党要管党、从严治党"}, "answer": ["D"], "note": "党的建设的一贯要求和根本方针是：党要管党、从严治党", "sourcePages": [92], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-86", "subject": "新思想", "chapter": 17, "chapterTitle": "第十七章全面从严治党", "type": "单选", "number": 86, "stem": "把党的建设作为一项伟大工程来推进，是我们党的一大创举，是我们党领导人民进行伟大社会革命的重要法宝。深入推进党的建设，作为统领的是", "options": {"A": "政治建设", "B": "思想建设", "C": "作风建设", "D": "制度建设"}, "answer": ["A"], "note": "深入推进党的建设，作为统领的是：政治建设", "sourcePages": [92], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-87", "subject": "新思想", "chapter": 17, "chapterTitle": "第十七章全面从严治党", "type": "单选", "number": 87, "stem": "党内政治生活的首要任务是", "options": {"A": "保证全党服从中央", "B": "维护党中央权威和集中统一领导", "C": "营造良好政治生态、提高政治能力", "D": "加强思想教育和理论武装"}, "answer": ["D"], "note": "党内政治生活的首要任务是：加强思想教育和理论武装", "sourcePages": [92], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-88", "subject": "新思想", "chapter": 17, "chapterTitle": "第十七章全面从严治党", "type": "单选", "number": 88, "stem": "一颗苹果，照鉴党的优良作风，映照为民造福的初心。2025年春节前夕，习近平在辽宁考察时再次提起一个关于苹果的红色故事：辽沈战役期间，锦州乡间的苹果熟了，解放军战士行军路过，虽然饥渴难耐，却一个都没有摘。“毛主席说，‘不吃是很高尚的，而吃了是很卑鄙的，因为这是人民的苹果’。”总书记的话意味深长，“这样的苹果，我们现在也不能吃。”由此可见，作风问题的核心是", "options": {"A": "党同人民群众的关系问题", "B": "“不忘初心、牢记使命”", "C": "抓住领导干部这个“关键少数”", "D": "推进作风建设常态化长效化"}, "answer": ["A"], "note": "作风问题的核心是党同人民群众的关系问题", "sourcePages": [92], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-89", "subject": "新思想", "chapter": 17, "chapterTitle": "第十七章全面从严治党", "type": "单选", "number": 89, "stem": "全面从严治党永远在路上，党的自我革命永远在路上。最彻底的自我革命是", "options": {"A": "党风廉政建设", "B": "让人民来监督政府", "C": "建立不忘初心、牢记使命的长效制度", "D": "反腐败"}, "answer": ["D"], "note": "最彻底的自我革命是：反腐败", "sourcePages": [92], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-90", "subject": "新思想", "chapter": 17, "chapterTitle": "第十七章全面从严治党", "type": "单选", "number": 90, "stem": "治国必先治党，党兴才能国强。党的十八大以来，以习近平同志为核心的党中央以刀刃向内、刮骨疗毒的勇气，打出了一套自我革命的“组合拳”。开启新时代中国共产党人再塑自身形象的“第一行动”是", "options": {"A": "开展反腐败斗争", "B": "全面从严治党", "C": "中央八项规定", "D": "加强党中央对重大工作的领导"}, "answer": ["C"], "note": "开启新时代中国共产党人再塑自身形象的“第一行动”是中央八项规定", "sourcePages": [93], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-91", "subject": "新思想", "chapter": 17, "chapterTitle": "第十七章全面从严治党", "type": "单选", "number": 91, "stem": "中国共产党区别于其他政党的显著标志，也是我们党最大的优势、最鲜明的品格的是", "options": {"A": "勇于自我革命", "B": "密切联系群众", "C": "独立自主", "D": "守正创新"}, "answer": ["A"], "note": "中国共产党区别于其他政党的显著标志，也是我们党最大的优势、最鲜明的品格的是：勇于自我革命", "sourcePages": [93], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-92", "subject": "新思想", "chapter": 17, "chapterTitle": "第十七章全面从严治党", "type": "单选", "number": 92, "stem": "习近平总书记在二十届中央纪委三次全会上发表重要讲话，系统阐述党的自我革命的重要思想，科学回答党的自我革命“为什么要”“为什么能”“怎样推进”的重大问题，特别是明确提出“九个以”的实践要求，为新时代新征程深入推进党的自我革命提供了强大思想武器和科学行动指南。党的自我革命的根本目的是", "options": {"A": "跳出历史周期率", "B": "解决大党独有难题", "C": "引领伟大社会革命", "D": "正风肃纪反腐"}, "answer": ["C"], "note": "党的自我革命的根本目的是：引领伟大社会革命", "sourcePages": [93], "answerSource": "帽子题配套资料"}, {"id": "新思想-单选-93", "subject": "新思想", "chapter": 17, "chapterTitle": "第十七章全面从严治党", "type": "单选", "number": 93, "stem": "以伟大自我革命引领伟大社会革命是新时代中国特色社会主义发展的显著特点。实现伟大自我革命的重要途径是", "options": {"A": "自我净化、自我完善、自我革新、自我提高", "B": "自我管理、自我服务、自我教育、自我监督", "C": "道路自信、理论自信、制度自信、文化自信", "D": "政治意识、大局意识、核心意识、看齐意识"}, "answer": ["A"], "note": "实现伟大自我革命的重要途径是：自我净化、自我完善、自我革新、自我提高", "sourcePages": [93], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-124", "subject": "新思想", "chapter": 17, "chapterTitle": "第十七章全面从严治党", "type": "多选", "number": 124, "stem": "党要管党、从严治党，是党的建设的一贯要求和根本方针。全面从严治党是", "options": {"A": "党永葆生机活力、走好新的赶考之路的必由之路", "B": "新时代党的建设的鲜明主题", "C": "党的政治建设的首要任务", "D": "新时代党的自我革命的伟大实践"}, "answer": ["A", "B", "D"], "note": "全面从严治党是：党永葆生机活力、走好新的赶考之路的必由之路；新时代党的建设的鲜明主题；新时代党的自我革命的伟大实践", "sourcePages": [112], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-125", "subject": "新思想", "chapter": 17, "chapterTitle": "第十七章全面从严治党", "type": "多选", "number": 125, "stem": "全面从严治党是一项管党治党的系统工程，客观上需要一个布局合理、内容科学、要素齐备、统一高效的全面从严治党体系。要落实新时代党的建设总要求，把全的要求、严的基调、治的理念落实到全面从严治党全过程，坚持", "options": {"A": "内容上全涵盖", "B": "对象上全覆盖", "C": "责任上全链条", "D": "制度上全贯通"}, "answer": ["A", "B", "C", "D"], "note": "要落实新时代党的建设总要求，把全的要求、严的基调、治的理念落实到全面从严治党全过程坚持内容上全涵盖；对象上全覆盖；责任上全链条；制度上全贯通", "sourcePages": [112], "answerSource": "帽子题配套资料"}, {"id": "新思想-多选-126", "subject": "新思想", "chapter": 17, "chapterTitle": "第十七章全面从严治党", "type": "多选", "number": 126, "stem": "党的政治建设是党的根本性建设。党的政治建设的首要任务是", "options": {"A": "保证全党服从中央", "B": "时刻保持解决大党独有难题的清醒和坚定", "C": "维护党中央权威和集中统一领导", "D": "以伟大自我革命引领伟大社会革命"}, "answer": ["A", "C"], "note": "党的政治建设是党的根本性建设。党的政治建设的首要任务是：保证全党服从中央；维护党中央权威和集中统一领导", "sourcePages": [112], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-2", "subject": "史纲", "chapter": 1, "chapterTitle": "第一章进入近代后中华民族的磨难与抗争", "type": "单选", "number": 2, "stem": "从鸦片战争开始，到1949年中华人民共和国成立前，中国都属于半殖民地半封建社会。半殖民地半封建社会性质，决定了近代中国社会矛盾呈现错综复杂的状况。在诸多社会矛盾中，贯穿中国半殖民地半封建社会的始终，并对近代中国社会的发展变化起着决定性作用的矛盾是\n\n①帝国主义和中华民族的矛盾\n\n②工人阶级和资产阶级的矛盾\n\n③封建主义和人民大众的矛盾\n\n④各帝国主义国家在中国争夺的矛盾", "options": {"A": "①②", "B": "②③", "C": "①③", "D": "③④"}, "answer": ["C"], "note": "贯穿中国半殖民地半封建社会的始终，并对近代中国社会的发展变化起着决定性作用的矛盾是：帝国主义和中华民族的矛盾；封建主义和人民大众的矛盾", "sourcePages": [117], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-4", "subject": "史纲", "chapter": 1, "chapterTitle": "第一章进入近代后中华民族的磨难与抗争", "type": "单选", "number": 4, "stem": "清朝政府同外国侵略者签订的第一个不平等条约是", "options": {"A": "《南京条约》", "B": "《北京条约》", "C": "《天津条约》", "D": "《马关条约》"}, "answer": ["A"], "note": "清朝政府同外国侵略者签订的第一个不平等条约是：《南京条约》", "sourcePages": [117], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-5", "subject": "史纲", "chapter": 1, "chapterTitle": "第一章进入近代后中华民族的磨难与抗争", "type": "单选", "number": 5, "stem": "中国沦为半殖民地半封建社会的过程中，最早出现的一个新的社会阶级是", "options": {"A": "官僚买办资产阶级", "B": "民族资产阶级", "C": "工人阶级", "D": "资产阶级"}, "answer": ["C"], "note": "中国沦为半殖民地半封建社会的过程中，最早出现的一个新的社会阶级是：工人阶级", "sourcePages": [117], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-7", "subject": "史纲", "chapter": 1, "chapterTitle": "第一章进入近代后中华民族的磨难与抗争", "type": "单选", "number": 7, "stem": "从鸦片战争开始，外国资本-帝国主义不断入侵中国。但是，帝国主义列强始终不能灭亡和瓜分中国。帝国主义列强不能灭亡和瓜分近代中国的根本原因是", "options": {"A": "帝国主义列强之间的矛盾", "B": "晚清政府的军事抵抗", "C": "中华民族进行的不屈不挠的反侵略斗争", "D": "中国资产阶级开始登上历史舞台"}, "answer": ["C"], "note": "帝国主义列强不能灭亡和瓜分近代中国的根本原因是：中华民族进行的不屈不挠的反侵略斗争", "sourcePages": [117], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-8", "subject": "史纲", "chapter": 1, "chapterTitle": "第一章进入近代后中华民族的磨难与抗争", "type": "单选", "number": 8, "stem": "近代以来中华民族面临着争得民族独立、人民解放和实现国家富强、人民幸福两大历史任务。无数的志士仁人，一代又一代的中国人，为此进行了不屈不挠、英勇顽强的斗争。近代以来的历史表明，要争得民族独立和人民解放，必须首先", "options": {"A": "发展民族工商业", "B": "集中力量进行现代化建设", "C": "学习外国先进的军事和科学技术", "D": "进行反帝反封建的民主革命"}, "answer": ["D"], "note": "要争得民族独立和人民解放，必须首先：进行反帝反封建的民主革命", "sourcePages": [118], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-10", "subject": "史纲", "chapter": 1, "chapterTitle": "第一章进入近代后中华民族的磨难与抗争", "type": "单选", "number": 10, "stem": "资本-帝国主义侵略、压迫中国人民的过程，同时也是中国人民反抗它们的侵略、压迫的过程。中国近代史上中国人民第一次大规模的反侵略武装斗争是", "options": {"A": "三元里人民的抗英斗争", "B": "太平天国的抗击洋枪队斗争", "C": "台湾高山族人民的抗日斗争", "D": "义和团的抗击八国联军斗争"}, "answer": ["A"], "note": "中国近代史上中国人民第一次大规模的反侵略武装斗争是：三元里人民的抗英斗争", "sourcePages": [118], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-11", "subject": "史纲", "chapter": 1, "chapterTitle": "第一章进入近代后中华民族的磨难与抗争", "type": "单选", "number": 11, "stem": "从1840年至1919年的80年间，中国人民对外来侵略进行了英勇顽强的反抗。但历次的反侵略战争，都是以中国失败、中国政府被迫签订丧权辱国的条约而告结束的。近代中国反侵略战争屡遭失败的最重要的原因是", "options": {"A": "社会制度腐败", "B": "军事战略错误", "C": "经济技术落后", "D": "思想观念保守"}, "answer": ["A"], "note": "近代中国反侵略战争屡遭失败的最重要的原因是：社会制度腐败", "sourcePages": [118], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-13", "subject": "史纲", "chapter": 1, "chapterTitle": "第一章进入近代后中华民族的磨难与抗争", "type": "单选", "number": 13, "stem": "甲午战争后，严复翻译的《天演论》所宣传的重要思想是", "options": {"A": "“师夷长技以制夷”", "B": "“中学为体，西学为用”", "C": "“物竞天择，适者生存”", "D": "“天下兴亡，匹夫有责”"}, "answer": ["C"], "note": "严复翻译的《天演论》所宣传的重要思想是：“物竞天择，适者生存”", "sourcePages": [118], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-2", "subject": "史纲", "chapter": 1, "chapterTitle": "第一章进入近代后中华民族的磨难与抗争", "type": "多选", "number": 2, "stem": "近代以来中华民族面临的两大历史任务，就是争得民族独立、人民解放和实现国家富强、人民幸福。关于两大历史任务，以下说法正确的是", "options": {"A": "两大历史任务的内容与实现方式都不一样", "B": "前一个任务为后一个任务创造必要的前提", "C": "后一个任务是前一个任务的最终目的和必然要求", "D": "两大历史任务分别由辛亥革命和新民主主义革命实现"}, "answer": ["A", "B", "C"], "note": "近代以来中华民族面临的两大历史任务两大历史任务之间的关系是：两大历史任务的内容与实现方式都不一样；前一个任务为后一个任务创造必要的前提；后一个任务是前一个任务的最终目的和必然要求", "sourcePages": [134], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-3", "subject": "史纲", "chapter": 1, "chapterTitle": "第一章进入近代后中华民族的磨难与抗争", "type": "多选", "number": 3, "stem": "资本-帝国主义列强对中国的侵略，首先和主要的是进行军事侵略。此外，还对中国实行政治控制、经济掠夺和文化渗透。为了统治中国，资本-帝国主义列强在政治上采取的主要方式有", "options": {"A": "控制中国的内政、外交", "B": "镇压中国人民的反抗", "C": "控制中国的通商口岸", "D": "扶植、收买代理人"}, "answer": ["A", "B", "D"], "note": "为了统治中国，资本-帝国主义列强在政治上采取的主要方式有：控制中国的内政、外交；镇压中国人民的反抗；扶植、收买代理人", "sourcePages": [135], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-4", "subject": "史纲", "chapter": 1, "chapterTitle": "第一章进入近代后中华民族的磨难与抗争", "type": "多选", "number": 4, "stem": "电影《南京照相馆》导演、编剧申奥在《人民日报》发表题为《让历史真相不被掩盖和遗忘》的文章，他提到：侵华日军在中国发起的不仅是一场热战，更是一场舆论战、文化战。电影中，孙中山先生题字的牌匾被肆意涂抹，井上大佐的办公室摆满抢夺来的古玩字画·.这些都揭示了列强文化侵略的意图。鸦片战争以后，资本-帝国主义列强在对中国实行军事侵略、政治控制、经济掠夺的同时，还对中国进行文化渗透。其进行文化渗透的目的是", "options": {"A": "宣扬殖民主义奴化思想", "B": "麻醉中国人民的精神", "C": "摧毁中国人的民族自尊心和自信心", "D": "镇压中国人民的反抗"}, "answer": ["A", "B", "C"], "note": "资本-帝国主义对中国进行文化渗透的目的是：宣扬殖民主义奴化思想；麻醉中国人民的精神；摧毁中国人的民族自尊心和自信心", "sourcePages": [135], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-7", "subject": "史纲", "chapter": 1, "chapterTitle": "第一章进入近代后中华民族的磨难与抗争", "type": "多选", "number": 7, "stem": "19世纪70年代以后，王韬、薛福成、马建忠、郑观应等人不仅主张学习西方的科学技术，同时也要求吸纳西方的政治、经济学说。他们的共同特点是具有", "options": {"A": "比较强烈的反对外国侵略的爱国思想", "B": "追求中国独立富强的爱国思想", "C": "追求实行民主共和制度的思想", "D": "一定程度反对封建专制的民主思想"}, "answer": ["A", "B", "D"], "note": "王韬、薛福成、马建忠、郑观应等人的共同特点是具有：比较强烈的反对外国侵略的爱国思想；追求中国独立富强的爱国思想；一定程度反对封建专制的民主思想", "sourcePages": [135], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-9", "subject": "史纲", "chapter": 1, "chapterTitle": "第一章进入近代后中华民族的磨难与抗争", "type": "多选", "number": 9, "stem": "鸦片战争以后，中国还只是少数人有朦胧的民族觉醒意识。中日甲午战争以后，中国人才开始有了普遍的民族意识的觉醒。甲午战争促成中国人民的民族意识开始普遍觉醒的主要原因在于", "options": {"A": "甲午战败和《马关条约》的签订给中国造成了深重的民族灾难", "B": "中国的惨败彻底打破了中国传统的夷夏观念", "C": "甲午战争以后，先进的中国人开始睁眼看世界了", "D": "传统的“天朝上国”的优越感已经荡然无存"}, "answer": ["A", "B", "D"], "note": "甲午战争促成中国人民的民族意识开始普遍觉醒的主要原因在于：甲午战败和《马关条约》的签订给中国造成了深重的民族灾难；中国的惨败彻底打破了中国传统的夷夏观念；传统的“天朝上国”的优越感已经荡然无存", "sourcePages": [135], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-14", "subject": "史纲", "chapter": 2, "chapterTitle": "第二章不同社会力量对国家出路的早期探索", "type": "单选", "number": 14, "stem": "《天朝田亩制度》是太平天国定都天京后颁布的最能体现太平天国社会理想和这次农民起义特色的纲领性文件；《资政新篇》是太平天国后期颁布的社会发展方案。二者的共同点在于", "options": {"A": "都主张向西方学习先进的制度", "B": "都主张在中国发展资本主义", "C": "都在实践中得到贯彻", "D": "都具有反封建的进步性"}, "answer": ["D"], "note": "《天朝田亩制度》和《资政新篇》的共同点在于：都县有反封建的进步性", "sourcePages": [118], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-15", "subject": "史纲", "chapter": 2, "chapterTitle": "第二章不同社会力量对国家出路的早期探索", "type": "单选", "number": 15, "stem": "19世纪60年代到90年代，清朝统治阶级内部的洋务派兴办近代企业，建立新式海陆军，创办新式学堂，派遣留学生。洋务派兴办洋务的主要目的是", "options": {"A": "发展资本主义", "B": "维护封建统治", "C": "对抗顽固派", "D": "迎合帝国主义"}, "answer": ["B"], "note": "洋务派兴办洋务的主要目的是：维护封建统治", "sourcePages": [118], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-17", "subject": "史纲", "chapter": 2, "chapterTitle": "第二章不同社会力量对国家出路的早期探索", "type": "单选", "number": 17, "stem": "洋务派所标榜的洋务运动的目标是", "options": {"A": "“自强”“求富”", "B": "“师夷长技以制夷”", "C": "“中学为体，西学为用”", "D": "“振兴中华”"}, "answer": ["A"], "note": "洋务派所标榜的洋务运动的目标是：“自强”“求富”", "sourcePages": [118], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-19", "subject": "史纲", "chapter": 2, "chapterTitle": "第二章不同社会力量对国家出路的早期探索", "type": "单选", "number": 19, "stem": "中国近代教育开始于", "options": {"A": "洋务运动时期", "B": "戊戌维新运动时期", "C": "辛亥革命时期", "D": "新文化运动时期"}, "answer": ["A"], "note": "中国近代教育开始于：洋务运动时期", "sourcePages": [119], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-20", "subject": "史纲", "chapter": 2, "chapterTitle": "第二章不同社会力量对国家出路的早期探索", "type": "单选", "number": 20, "stem": "甲午战争一役，洋务派经营多年的北洋海军全军覆没，标志着以“自强”“求富”为目标的洋务运动的失败。决定洋务运动必然失败命运的原因是", "options": {"A": "洋务运动具有封建性", "B": "洋务运动对列强具有依赖性", "C": "洋务企业的管理具有腐朽性", "D": "资产阶级维新派的强烈反对"}, "answer": ["A"], "note": "决定洋务运动必然失败命运的原因是：洋务运动具有封建性", "sourcePages": [119], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-21", "subject": "史纲", "chapter": 2, "chapterTitle": "第二章不同社会力量对国家出路的早期探索", "type": "单选", "number": 21, "stem": "近代中国资产阶级思想与封建主义思想的第一次正面交锋是", "options": {"A": "“师夷长技以制夷”主张的提出", "B": "洋务派与顽固派的论战", "C": "维新派与守旧派的论战", "D": "新文化运动倡导者对以孔子为代表的“往圣先贤”的猛烈击"}, "answer": ["C"], "note": "近代中国资产阶级思想与封建主义思想的第一次正面交锋是：维新派与守旧派的论战", "sourcePages": [119], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-23", "subject": "史纲", "chapter": 2, "chapterTitle": "第二章不同社会力量对国家出路的早期探索", "type": "单选", "number": 23, "stem": "甲午战争后，维新运动迅速兴起。针对洋务派提出的“中体西用”的方针，维新派指出，体与用是不可分的。中学有中学的“体”与“用”，西学有西学的“体”与“用”，把中学之“体”与西学之“用”凑在一起，就如同让“牛体”产生“马用”一样荒谬。维新派与洋务派分歧的实质是", "options": {"A": "要不要进行社会革命", "B": "要不要以革命手段推翻清王朝", "C": "要不要在中国兴办近代企业", "D": "要不要学习西方的政治制度与思想文化"}, "answer": ["D"], "note": "维新派与洋务派分歧的实质是：要不要学习西方的政治制度与思想文化", "sourcePages": [119], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-24", "subject": "史纲", "chapter": 2, "chapterTitle": "第二章不同社会力量对国家出路的早期探索", "type": "单选", "number": 24, "stem": "洋务运动是在19世纪60年代初第二次鸦片战争结束后，在清政府镇压太平天国起义与捻军起义的过程中兴起的。维新运动发生于19世纪90年代。维新运动与洋务运动的主要不同点在于", "options": {"A": "洋务运动只学习西方技术，维新运动主张学习西方政治制度", "B": "洋务运动依靠封建统治阶级中的部分成员，维新运动依靠下层群众", "C": "洋务运动维护封建统治，维新运动否定封建主义", "D": "洋务运动实现了预期目标，维新运动昙花一现"}, "answer": ["A"], "note": "维新运动与洋务运动的主要不同点在于：洋务运动只学习西方技术，维新运动主张学习西方政治制度", "sourcePages": [119], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-10", "subject": "史纲", "chapter": 2, "chapterTitle": "第二章不同社会力量对国家出路的早期探索", "type": "多选", "number": 10, "stem": "《天朝田亩制度》是最能体现太平天国社会理想和这次农民起义特色的纲领性文件。《资政新篇》是太平天国后期颁布的社会发展方案。《资政新篇》", "options": {"A": "提出了一个以解决土地问题为中心的比较完整的社会改革方案", "B": "体现了太平天国起义具有不同于以往农民战争的新的历史特点", "C": "是中国近代历史上第一个比较系统的发展资本主义的方案", "D": "反映了太平天国某些领导人在后期试图通过向外国学习来寻求出路的一种努力"}, "answer": ["B", "C", "D"], "note": "《《资政新篇》：体现了太平天国起义具有不同于以往农民战争的新的历史特点；是中国近代历史上第一个比较系统的发展资本主义的方案；反映了太平天国某些领导人在后期试图通过向外国学习来寻求出路的一种努力", "sourcePages": [135, 136], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-13", "subject": "史纲", "chapter": 2, "chapterTitle": "第二章不同社会力量对国家出路的早期探索", "type": "多选", "number": 13, "stem": "洋务运动失败的原因主要是", "options": {"A": "洋务运动具有封建性", "B": "洋务运动对列强具有依赖性", "C": "洋务企业的管理具有腐朽性", "D": "洋务运动的指导思想具有激进性"}, "answer": ["A", "B", "C"], "note": "洋务运动失败的原因主要是：洋务运动具有封建性；洋务运动对列强具有依赖性；洋务企业的管理具有腐朽性", "sourcePages": [136], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-16", "subject": "史纲", "chapter": 2, "chapterTitle": "第二章不同社会力量对国家出路的早期探索", "type": "多选", "number": 16, "stem": "19世纪90年代末中国出现戊戌维新运动不是偶然的，它的发生有着深刻的历史背景，主要是", "options": {"A": "中国民族资本主义已经成为中国经济的主要形式", "B": "新兴的民族资产阶级迫切要求为在中国发展资本主义开辟道路", "C": "甲午战争惨败造成的新的民族危机激发了新的民族觉醒", "D": "资产阶级改良思想在中国迅速传播"}, "answer": ["B", "C", "D"], "note": "戊戌维新运动有着深刻的历史背景，主要是：新兴的民族资产阶级迫切要求为在中国发展资本主义开辟道路；甲午战争惨败造成的新的民族危机激发了新的民族觉醒；资产阶级改良思想在中国迅速传播", "sourcePages": [136], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-18", "subject": "史纲", "chapter": 2, "chapterTitle": "第二章不同社会力量对国家出路的早期探索", "type": "多选", "number": 18, "stem": "19世纪90年代，维新派与守旧派开展了一场实质上是资产阶级思想与封建主义思想在中国的第一次正面交锋的论战。这场论战围绕的主要问题是", "options": {"A": "要不要变法", "B": "要不要实行民主共和", "C": "要不要废八股、改科举和兴西学", "D": "要不要实行君主立宪"}, "answer": ["A", "C", "D"], "note": "维新派与守旧派开展了论战，围绕的主要问题是：要不要变法；要不要废八股、改科举和兴西学；要不要实行君主立宪", "sourcePages": [136], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-25", "subject": "史纲", "chapter": 3, "chapterTitle": "第三章辛亥革命与君主专制制度的终结", "type": "单选", "number": 25, "stem": "清政府于1901年宣布实行“新政”以后，又于1906年宣布“预备仿行宪政”，并于1908年颁布了《钦定宪法大纲》，制定了预备立宪期为9年的君主立宪方案。清政府改革的根本目的在于", "options": {"A": "延续清王朝的反动统治", "B": "发展资本主义", "C": "缓和阶级矛盾", "D": "挽救民族危机"}, "answer": ["A"], "note": "清政府改革的根本目的在于：延续清王朝的反动统治", "sourcePages": [119], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-26", "subject": "史纲", "chapter": 3, "chapterTitle": "第三章辛亥革命与君主专制制度的终结", "type": "单选", "number": 26, "stem": "1905年8月20日，孙中山和黄兴、宋教仁等人在日本东京成立中国同盟会。同盟会以《民报》为机关报，并确定了革命纲领。同盟会的成立，标志着", "options": {"A": "关于革命与改良的辩论以革命派的胜利而告结束", "B": "孙中山组建的第一个革命团体的诞生", "C": "中国人民在精神上由被动变为主动，中国革命的面貌焕然一新", "D": "中国资产阶级民主革命进入了一个新的阶段"}, "answer": ["D"], "note": "同盟会的成立，标志着：中国资产阶级民主革命进入了一个新的阶段", "sourcePages": [120], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-31", "subject": "史纲", "chapter": 3, "chapterTitle": "第三章辛亥革命与君主专制制度的终结", "type": "单选", "number": 31, "stem": "1956年，毛泽东在《纪念孙中山先生》一文中指出：“纪念伟大的革命先行者孙中山先生！纪念他在中国民主革命准备时期，以鲜明的中国革命民主派立场，同中国改良派作了尖锐的斗争。他在这一场斗争中是中国革命民主派的旗帜。”1905年至1907年间资产阶级革命派和改良派论战的焦点是", "options": {"A": "要不要以革命手段推翻清王朝", "B": "要不要推翻帝制，实行共和", "C": "要不要反对外国帝国主义列强的侵略", "D": "要不要进行社会革命"}, "answer": ["A"], "note": "1905年至1907年间资产阶级革命派和改良派论战的焦点是：要不要以革命手段推翻清王朝", "sourcePages": [120], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-32", "subject": "史纲", "chapter": 3, "chapterTitle": "第三章辛亥革命与君主专制制度的终结", "type": "单选", "number": 32, "stem": "中国资产阶级革命派与改良派的根本不同之处在于，资产阶级革命派\n\n①在踏上革命道路之时就高举起民主革命的旗帜\n\n②始终重视广泛动员人民群众的力量\n\n③最先制定了明确的反帝反封建的革命纲领\n\n④选择了以武装起义推翻清王朝统治的斗争方式", "options": {"A": "①②", "B": "②③", "C": "③④", "D": "①④"}, "answer": ["D"], "note": "中国资产阶级革命派与改良派的根本不同之处在于，资产阶级革命派：在踏上革命道路之时就高举起民主革命的旗帜；选择了以武装起义推翻清王朝统治的斗争方式", "sourcePages": [120], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-33", "subject": "史纲", "chapter": 3, "chapterTitle": "第三章辛亥革命与君主专制制度的终结", "type": "单选", "number": 33, "stem": "1840年鸦片战争以后，西方列强在中华大地上恣意妄为，封建统治者屏弱无能，中国逐步成为半殖民地半封建社会，国家蒙辱、人民蒙难、文明蒙尘，中国人民和中华民族遭受了前所未有的劫难。英雄的中国人民始终没有屈服，在救亡图存的道路上一次次抗争、一次次求索，展现了不畏强暴、自强不息的顽强意志。其中，拉开了近代以来中国发生的深刻社会变革序幕的事件是", "options": {"A": "新文化运动", "B": "五四运动", "C": "中国共产党成立", "D": "辛亥革命"}, "answer": ["D"], "note": "拉开了近代以来中国发生的深刻社会变革序幕的事件是：辛亥革命", "sourcePages": [120, 121], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-36", "subject": "史纲", "chapter": 3, "chapterTitle": "第三章辛亥革命与君主专制制度的终结", "type": "单选", "number": 36, "stem": "孙中山指出，辛亥革命之所以失败，“非袁氏兵力之强，实同党人心之涣”。从主观方面讲，辛亥革命之所以失败，在于它的领导者资产阶级革命派本身存在着许多弱点和错误。资产阶级革命派的这些弱点、错误，从根源上讲，在于", "options": {"A": "不能充分发动和依靠人民群众", "B": "中国资产阶级革命派内部组织的松散和分化", "C": "中国民族资产阶级的软弱性和妥协性", "D": "没有提出彻底的反帝反封建的革命纲领"}, "answer": ["C"], "note": "资产阶级革命派的这些弱点、错误，从根源上讲，在于：中国民族资产阶级的软弱性和妥协性", "sourcePages": [121], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-37", "subject": "史纲", "chapter": 3, "chapterTitle": "第三章辛亥革命与君主专制制度的终结", "type": "单选", "number": 37, "stem": "袁世凯窃夺辛亥革命的果实之后，建立了代表大地主和买办资产阶级利益的北洋军阀反动政权。袁世凯当权时，北洋政府统治下的中国在形式上是统一的。在1916年袁世凯称帝败亡之后，中国陷入了军阀割据的局面。这种局面的形成有其深刻的原因，主要是\n\n①中国主要是地方性的农业经济而没有形成统一的资本主义市场\n\n②帝国主义国家在中国采取划分势力范围的分裂剥削政策\n\n③尊孔复古思潮与民主共和思想反复拉锯造成了文化上的混乱\n\n④民族矛盾超过阶级矛盾成为当时中国社会的主要矛盾", "options": {"A": "①②", "B": "①③", "C": "②④", "D": "③④"}, "answer": ["A"], "note": "袁世凯当权时，北洋政府统治下的中国在形式上是统一的在1916年袁世凯称帝败亡之后，中国陷入了军阀割据的局面这种局面的形成有其深刻的原因，主要是：中国主要是地方性的农业经济而没有形成统一的资本主义市场；帝国主义国家在中国采取划分势力范围的分裂剥削政策", "sourcePages": [121], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-21", "subject": "史纲", "chapter": 3, "chapterTitle": "第三章辛亥革命与君主专制制度的终结", "type": "多选", "number": 21, "stem": "鸦片战争以后，西方列强野蛮入侵，封建统治腐朽无能，国家战乱不已，人民饥寒交迫，中国人民和中华民族遭受世所罕见的深重苦难。要实现民族独立、人民解放和国家富强、人民幸福，就必须推翻封建专制统治，对中国社会进行根本变革。辛亥革命的发生，是", "options": {"A": "当时民族危机加深、社会矛盾激化的结果", "B": "当时中国人民争取民族独立、振兴中华深切愿望的集中反映", "C": "中国民族资产阶级登上政治舞台的第一次表演", "D": "当时中国人民为救亡图存而前赴后继顽强斗争的集中体现"}, "answer": ["A", "B", "D"], "note": "辛亥革命的发生，是：当时民族危机加深、社会矛盾激化的结果；当时中国人民争取民族独立、振兴中华深切愿望的集中反映；当时中国人民为救亡图存而前赴后继顽强斗争的集中体现", "sourcePages": [137], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-22", "subject": "史纲", "chapter": 3, "chapterTitle": "第三章辛亥革命与君主专制制度的终结", "type": "多选", "number": 22, "stem": "1905年至1907年间，资产阶级革命派与改良派分别以《民报》《新民丛报》为主要舆论阵地，展开了一场大论战。这场论战的主要内容包括", "options": {"A": "要不要以革命手段推翻清王朝", "B": "要不要废八股、改科举和兴西学", "C": "要不要推翻帝制，实行共和", "D": "要不要进行社会革命"}, "answer": ["A", "C", "D"], "note": "资产阶级革命派与改良派论战，主要内容包括：要不要以革命手段推翻清王朝；要不要推翻帝制，实行共和；要不要进行社会革命", "sourcePages": [137], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-23", "subject": "史纲", "chapter": 3, "chapterTitle": "第三章辛亥革命与君主专制制度的终结", "type": "多选", "number": 23, "stem": "1905年至1907年间革命派与改良派论战的意义是", "options": {"A": "划清了革命与改良的界限", "B": "传播了民主革命思想", "C": "促进了革命形势的发展", "D": "改变了以往只有觉悟的革命者而缺少觉醒的人民大众的斗争状况"}, "answer": ["A", "B", "C"], "note": "革命派与改良派论战的意义是：划清了革命与改良的界限；传播了民主革命思想；促进了革命形势的发展", "sourcePages": [137], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-24", "subject": "史纲", "chapter": 3, "chapterTitle": "第三章辛亥革命与君主专制制度的终结", "type": "多选", "number": 24, "stem": "1905年至1907年间发生的资产阶级革命派与改良派的论战，也暴露了革命派在思想理论方面的弱点，主要表现在革命派", "options": {"A": "对“革命是否会招致帝国主义干涉”的问题不敢作出理直气壮的正面回答", "B": "所说的“国民”，主要还是指资产阶级及其知识分子，而不是广大的劳动群众", "C": "反对贫苦农民“夺富人之田为己有”", "D": "只是希望通过“有秩序的革命”来避免动乱和帝国主义的干涉"}, "answer": ["A", "B", "C", "D"], "note": "革命派在思想理论方面的弱点，主要表现在革命派：对“革命是否会招致帝国主义干涉”的问题不敢作出理直气壮的正面回答；所说的“国民”，主要还是指资产阶级及其知识分子，而不是广大的劳动群众；反对贫苦农民“夺富人之田为己有”；只是希望通过“有秩序的革命”来避免动乱和帝国主义的干涉", "sourcePages": [137], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-28", "subject": "史纲", "chapter": 3, "chapterTitle": "第三章辛亥革命与君主专制制度的终结", "type": "多选", "number": 28, "stem": "辛亥革命与戊戌变法的共同点有", "options": {"A": "都是自上而下的救亡运动", "B": "都主张在中国发展资本主义", "C": "都主张改革君主专制制度", "D": "都未提出彻底的反帝反封建的纲领"}, "answer": ["B", "D"], "note": "辛亥革命与戊戌变法的共同点有：都主张在中国发展资本主义；都未提出彻底的反帝反封建的纲领", "sourcePages": [138], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-29", "subject": "史纲", "chapter": 3, "chapterTitle": "第三章辛亥革命与君主专制制度的终结", "type": "多选", "number": 29, "stem": "辛亥革命之所以失败，从主观方面来说，在于它的领导者资产阶级革命派本身存在着许多弱点和错误，主要是", "options": {"A": "没有提出彻底的反帝反封建的革命纲领", "B": "不能充分发动和依靠人民群众", "C": "不能建立坚强的革命政党", "D": "资本主义的建国方案行不通"}, "answer": ["A", "B", "C"], "note": "辛亥革命之所以失败，从主观方面来说，在于它的领导者资产阶级革命派本身存在着许多弱点和错误，主要是：没有提出彻底的反帝反封建的革命纲领；不能充分发动和依靠人民群众；不能建立坚强的革命政党", "sourcePages": [138], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-38", "subject": "史纲", "chapter": 4, "chapterTitle": "第四章中国共产党成立和中国革命新局面", "type": "单选", "number": 38, "stem": "新文化运动的倡导者猛烈击以孔子为代表的“往圣先贤”，大力提倡新道德、反对旧道德，提倡新文学、反对旧文学，包括提倡白话文、反对文言文。新文化运动的倡导者批判孔学，是为了", "options": {"A": "给中国发展资本主义扫清障碍", "B": "促进马克思主义在中国的传播及其同中国工人运动的结合", "C": "否定中国的全部传统文化", "D": "推翻清政府这个“洋人的朝廷”"}, "answer": ["A"], "note": "新文化运动的倡导者批判孔学，是为了：给中国发展资本主义扫清障碍", "sourcePages": [121], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-39", "subject": "史纲", "chapter": 4, "chapterTitle": "第四章中国共产党成立和中国革命新局面", "type": "单选", "number": 39, "stem": "新文化运动的倡导者猛烈抨击以孔子为代表的“往圣先贤”。通过批判孔学，动摇了封建正统思想的统治地位，在中国社会掀起一股思想解放的潮流。五四前新文化运动的倡导者所使用的主要武器是\n\n①马克思主义的民主与科学理论\n\n②个性解放思想\n\n③中华优秀传统文化的民本思想\n\n④进化论观点", "options": {"A": "①②", "B": "②③", "C": "③④", "D": "②④"}, "answer": ["D"], "note": "五四前新文化运动的倡导者所使用的主要武器是：个性解放思想；进化论观点", "sourcePages": [122], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-40", "subject": "史纲", "chapter": 4, "chapterTitle": "第四章中国共产党成立和中国革命新局面", "type": "单选", "number": 40, "stem": "1919年5月爆发的五四运动，是中国近代史上一个划时代的事件。关于五四运动，以下说法正确的是", "options": {"A": "改变了中国半殖民地半封建社会的性质，中国革命从此进入新民主主义革命时期", "B": "工人阶级开始代替资产阶级成了资产阶级民主革命的主力军", "C": "促进了新思想的传播，为新文化运动的兴起准备了理论基础", "D": "表现了反帝反封建的彻底性"}, "answer": ["D"], "note": "五四运动：表现了反帝反封建的彻底性", "sourcePages": [122], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-42", "subject": "史纲", "chapter": 4, "chapterTitle": "第四章中国共产党成立和中国革命新局面", "type": "单选", "number": 42, "stem": "从1860年到1937年，不到100年的时间里，中国首都三次被外敌攻陷，中国人民身处“覆屋之下、漏舟之中、薪火之上”。民族危机激发了中华民族的觉醒，增强了中华民族的凝聚力。实现了中国人民和中华民族自鸦片战争以来第一次全面觉醒的历史事件是", "options": {"A": "辛亥革命", "B": "甲午战争", "C": "维新运动", "D": "五四运动"}, "answer": ["D"], "note": "实现了中国人民和中华民族自鸦片战争以来第一次全面觉醒的历史事件是：五四运动", "sourcePages": [122], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-43", "subject": "史纲", "chapter": 4, "chapterTitle": "第四章中国共产党成立和中国革命新局面", "type": "单选", "number": 43, "stem": "五四运动是中国近现代史上具有划时代意义的一个重大事件，以磅礴之力鼓动了中国人民和中华民族实现民族复兴的志向和信心。五四运动孕育了五四精神，五四精神的核心是", "options": {"A": "民主和科学", "B": "追求真理", "C": "追求进步", "D": "爱国主义"}, "answer": ["D"], "note": "五四精神的核心是：爱国主义", "sourcePages": [122], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-45", "subject": "史纲", "chapter": 4, "chapterTitle": "第四章中国共产党成立和中国革命新局面", "type": "单选", "number": 45, "stem": "在中国大地上率先举起马克思主义旗帜的，是李大钊。李大钊是从爱国的立场出发，从民主主义者转变为共产主义者的。从1918年7月起，他先后发表《法俄革命之比较观》《庶民的胜利》《Bolshevism的胜利》等文章，热情讴歌十月革命的胜利，指出十月革命是“二十世纪中世界革命的先声”，确信“将来的环球，必是赤旗的世界”。五四运动后，他更加致力于马克思主义的宣传。1919年9月、11月，李大钊发表《我的马克思主义观》一文，在当时思想界产生了重大影响，标志着", "options": {"A": "马克思主义开始与中国工人运动相结合", "B": "马克思主义在中国进入比较系统的传播阶段", "C": "马克思主义成为中国共产党的指导思想", "D": "中国先进分子把目光从资产阶级民主主义转向社会主义"}, "answer": ["B"], "note": "李大钊发表《我的马克思主义观》一文，在当时思想界产生了重大影响，标志着：马克思主义在中国进入比较系统的传播阶段", "sourcePages": [122], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-46", "subject": "史纲", "chapter": 4, "chapterTitle": "第四章中国共产党成立和中国革命新局面", "type": "单选", "number": 46, "stem": "五四运动后，社会主义思潮在中国蓬勃兴起，马克思主义开始在知识界广泛传播。中国早期信仰马克思主义的人物主要有三种类型，其主体部分是", "options": {"A": "五四爱国运动的左翼骨干", "B": "新文化运动的精神领袖", "C": "一部分原中国同盟会会员、辛亥革命时期的活动家", "D": "第一批工人运动的组织者"}, "answer": ["A"], "note": "中国早期信仰马克思主义的人物主要有三种类型，其主体部分是：五四爱国运动的左翼骨王", "sourcePages": [123], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-48", "subject": "史纲", "chapter": 4, "chapterTitle": "第四章中国共产党成立和中国革命新局面", "type": "单选", "number": 48, "stem": "近代以后中国人民的反帝反封建斗争之所以屡遭挫折和失败，最重要的原因就是", "options": {"A": "没能够充分地发动群众", "B": "中国人民的民族意识没有普遍觉醒", "C": "没有先进的坚强的政党作为凝聚力量的领导核心", "D": "没有把阶级矛盾当作中国社会最主要的矛盾"}, "answer": ["C"], "note": "近代以后中国人民的反帝反封建斗争之所以屡遭挫折和失败，最重要的原因就是：没有先进的坚强的政党作为凝聚力量的领导核心", "sourcePages": [123], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-49", "subject": "史纲", "chapter": 4, "chapterTitle": "第四章中国共产党成立和中国革命新局面", "type": "单选", "number": 49, "stem": "中共一大确定党的名称为“中国共产党”。大会通过了中国共产党第一个纲领，明确“革命军队必须与无产阶级一起推翻资本家阶级的政权”，“承认无产阶级专政，直到阶级斗争结束”，“消灭资本家私有制”，以及联合第三国际。大会在讨论实际工作计划时，决定首先", "options": {"A": "集中精力研究和宣传马克思主义", "B": "集中精力组织农民", "C": "集中精力组织工人", "D": "集中精力介绍俄国“十月革命”"}, "answer": ["C"], "note": "中共一大在讨论实际工作计划时，决定首先：集中精力组织工人", "sourcePages": [123], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-50", "subject": "史纲", "chapter": 4, "chapterTitle": "第四章中国共产党成立和中国革命新局面", "type": "单选", "number": 50, "stem": "在1922年召开的中共二大上，中国共产党第一次明确提出了", "options": {"A": "新民主主义革命总路线", "B": "无产阶级领导权", "C": "土地革命的总路线", "D": "反帝反封建的民主革命纲领"}, "answer": ["D"], "note": "在1922年召开的中共二大上，中国共产党第一次明确提出了：反帝反封建的民主革命纲领", "sourcePages": [123], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-53", "subject": "史纲", "chapter": 4, "chapterTitle": "第四章中国共产党成立和中国革命新局面", "type": "单选", "number": 53, "stem": "1924年1月，中国国民党第一次全国代表大会在广州召开，大会通过的宣言对三民主义作出了新的解释。新三民主义成为第一次国共合作的政治基础，究其原因，是由于新三民主义的政纲", "options": {"A": "把民生主义概括为“平均地权”", "B": "把斗争的矛头直接指向北洋军阀", "C": "体现了联俄、联共、扶助农工三大革命政策", "D": "同中国共产党在民主革命阶段的纲领基本一致"}, "answer": ["D"], "note": "新三民主义成为第一次国共合作的政治基础，究其原因，是由于新三民主义的政纲：同中国共产党在民主革命阶段的纲领基本一致", "sourcePages": [124], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-54", "subject": "史纲", "chapter": 4, "chapterTitle": "第四章中国共产党成立和中国革命新局面", "type": "单选", "number": 54, "stem": "1924年国共合作的形成，加快了中国革命前进的步伐，1925年出现了全国范围的大革命高潮。掀起这一大革命高潮的起点是", "options": {"A": "五卅运动", "B": "省港大罢工", "C": "国民政府在广州建立", "D": "北伐战争开始"}, "answer": ["A"], "note": "掀起全国大革命高潮的起点是：五卅运动", "sourcePages": [124], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-56", "subject": "史纲", "chapter": 4, "chapterTitle": "第四章中国共产党成立和中国革命新局面", "type": "单选", "number": 56, "stem": "1924年国共合作的形成，加快了中国革命前进的步伐。1926年7月，以推翻北洋军阀统治为目标的北伐战争开始。1927年3月，国民革命军占领南京。1927年4月12日，蒋介石在上海发动反共政变，同年7月15日，汪精卫在武汉召开“分共”会议，并在其辖区内对共产党员和革命群众实行搜捕和屠杀，国共合作全面破裂，大革命最终失败。所谓大革命的失败，主要是指", "options": {"A": "北洋军阀的统治没有被推翻", "B": "反帝反封建的革命任务没有完成", "C": "国共合作全面破裂", "D": "工人农民运动转入低潮"}, "answer": ["B"], "note": "大革命的失败，主要是指：反帝反封建的革命任务没有完成", "sourcePages": [124], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-42", "subject": "史纲", "chapter": 4, "chapterTitle": "第四章中国共产党成立和中国革命新局面", "type": "多选", "number": 42, "stem": "1920年8月，中国共产党的最早组织在上海成立。之后，在北京、武汉、长沙、济南、广州，都成立了共产党早期组织。在日本、法国成立了由留学生和华侨中先进分子组成的共产党早期组织。早期党的地方组织的形成，为中国共产党的创建准备了组织基础。中国共产党的早期组织之所以首先在上海诞生，是因为", "options": {"A": "上海是中国工人阶级最密集的中心城市", "B": "身居上海的陈独秀在中国大地上率先举起了马克思主义旗帜", "C": "在上海成立了中国最早学习和研究马克思主义的团体一一马克思学说研究会", "D": "上海的工人阶级最早以独立的政治力量登上历史舞台"}, "answer": ["A", "D"], "note": "中国共产党的早期组织之所以首先在上海诞生，是因为：上海是中国工人阶级最密集的中心城市；上海的工人阶级最早以独立的政治力量登上历史舞台", "sourcePages": [140], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-44", "subject": "史纲", "chapter": 4, "chapterTitle": "第四章中国共产党成立和中国革命新局面", "type": "多选", "number": 44, "stem": "中国共产党这个中国近代以来最伟大的创业团队，是1921年在上海的一座石库门小楼里集结出发的。当年这里是望志路106号，1943年至今是兴业路76号。由“望志”而“兴业”，是历史的巧合，也寓意着历史的必然。中国共产党是在特定的社会历史条件下成立的。中国共产党一开始", "options": {"A": "就把党的工作重心放在农村", "B": "就义无反顾地肩负起实现中华民族伟大复兴的历史使命", "C": "就是一个区别于第二国际旧式社会改良党的新型工人阶级革命政党", "D": "就是一个以马克思列宁主义理论为基础的党"}, "answer": ["B", "C", "D"], "note": "中国共产党一开始：就义无反顾地肩负起实现中华民族伟大复兴的历史使命；就是一个区别于第二国际旧式社会改良党的新型工人阶级革命政党；就是一个以马克思列宁主义理论为基础的党", "sourcePages": [141], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-45", "subject": "史纲", "chapter": 4, "chapterTitle": "第四章中国共产党成立和中国革命新局面", "type": "多选", "number": 45, "stem": "中共二大开创了中共创建史上的多个“第一”，其中包括", "options": {"A": "第一次提出党的反帝反封建的民主革命纲领", "B": "第一次提出党的统一战线思想", "C": "第一次公开发表《中国共产党宣言》", "D": "制定了第一部《中国共产党章程》"}, "answer": ["A", "B", "C", "D"], "note": "中共二大开创了中共创建史上的多个“第一”：第一次提出党的反帝反封建的民主革命纲领；第一次提出党的统一战线思想；第一次公开发表《中国共产党宣言》；制定了第一部《中国共产党章程》", "sourcePages": [141], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-46", "subject": "史纲", "chapter": 4, "chapterTitle": "第四章中国共产党成立和中国革命新局面", "type": "多选", "number": 46, "stem": "1922年7月，中共二大制定的民主革命纲领是", "options": {"A": "打倒军阀", "B": "统一中国为真正民主共和国", "C": "推翻国际帝国主义的压迫", "D": "建立劳农专政的政治，铲除私有财产制度"}, "answer": ["A", "B", "C"], "note": "中共二大制定的民主革命纲领是：打倒军阀；统一中国为真正民主共和国；推翻国际帝国主义的压迫", "sourcePages": [141], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-48", "subject": "史纲", "chapter": 4, "chapterTitle": "第四章中国共产党成立和中国革命新局面", "type": "多选", "number": 48, "stem": "为了加强对日益高涨的革命运动的领导，1925年1月，中国共产党第四次全国代表大会在上海举行。中共四大的重大历史功绩在于", "options": {"A": "提出了中国无产阶级在民主革命中的领导权问题", "B": "提出了工农联盟问题", "C": "对中国民主革命的内容作了更加完整的规定", "D": "具体回答了如何正确处理同资产阶级争夺领导权过程中遇到的复杂问题"}, "answer": ["A", "B", "C"], "note": "中共四大的重大历史功绩在于：提出了中国无产阶级在民主革命中的领导权问题；提出了工农联盟问题；对中国民主革命的内容作了更加完整的规定", "sourcePages": [141], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-51", "subject": "史纲", "chapter": 4, "chapterTitle": "第四章中国共产党成立和中国革命新局面", "type": "多选", "number": 51, "stem": "大革命是在国共合作的条件下进行的，没有国共合作，不会在短时间内掀起这样一场革命。在这场革命中，中国共产党起着独特的、不可代替的作用。没有中国共产党，不会有这场大革命。中国共产党在大革命中的独特的、不可代替的作用表现在", "options": {"A": "中国共产党是大革命的政治口号一—反对帝国主义、反对军阀—的提出者", "B": "中国共产党是国共合作的倡导者和统一战线的领导者", "C": "中国共产党是人民群众的主要发动者和组织者", "D": "中国共产党帮助和推动了国民革命军的建立"}, "answer": ["A", "C", "D"], "note": "中国共产党在大革命中的独特的、不可代替的作用表现在：中国共产党是大革命的政治口号一反对帝国主义、反对军阀一一的提出者；中国共产党是人民群众的主要发动者和组织者；中国共产党帮助和推动了国民革命军的建立", "sourcePages": [141], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-58", "subject": "史纲", "chapter": 5, "chapterTitle": "第五章中国革命的新道路", "type": "单选", "number": 58, "stem": "在大革命失败的危急关头，中共八七会议确定的方针是", "options": {"A": "推翻北洋军阀黑暗统治", "B": "开辟农村革命根据地", "C": "土地革命和武装起义", "D": "建立工农民主统一战线"}, "answer": ["C"], "note": "中共八七会议确定的方针是：土地革命和武装起义", "sourcePages": [124], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-59", "subject": "史纲", "chapter": 5, "chapterTitle": "第五章中国革命的新道路", "type": "单选", "number": 59, "stem": "土地革命战争时期，党从残酷的现实中认识到，没有革命的武装就无法战胜武装的反革命，就无法夺取中国革命胜利，就无法改变中国人民和中华民族的命运，必须以武装的革命反对武装的反革命。党领导举行了南昌起义、秋收起义、广州起义和其他许多地区起义。其中，秋收起义不同于南昌起义的特点有\n\n①以攻占敌人控制比较薄弱的农村为目标\n\n②公开打出了“工农革命军”的旗帜\n\n③是中国共产党独立领导的革命战争\n\n④不仅是军队的行动，而且有数量众多的工农武装参加", "options": {"A": "①②", "B": "①③", "C": "②④", "D": "③④"}, "answer": ["C"], "note": "秋收起义不同于南昌起义的特点有：公开打出了“工农革命军”的旗帜；不仅是军队的行动，而且有数量众多的工农武装参加", "sourcePages": [124], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-60", "subject": "史纲", "chapter": 5, "chapterTitle": "第五章中国革命的新道路", "type": "单选", "number": 60, "stem": "大革命失败后，在国民党的统治下，白色恐怖笼罩着全国，中国革命转入低潮。在严峻的考验面前，中国共产党人表现了坚定的革命立场和大无畏的英雄气概，独立高举起反帝反封建的革命旗帜，中国革命由此发展到了一个新的阶段。由大革命失败到土地革命战争兴起的历史性转变是", "options": {"A": "遵义会议", "B": "八七会议", "C": "三湾改编", "D": "党的六大"}, "answer": ["B"], "note": "由大革命失败到土地革命战争兴起的历史性转变是：八七会议", "sourcePages": [125], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-61", "subject": "史纲", "chapter": 5, "chapterTitle": "第五章中国革命的新道路", "type": "单选", "number": 61, "stem": "在新民主主义革命时期，对中国革命具有决定意义的新起点是", "options": {"A": "从领导工人运动转向武装斗争", "B": "从进攻大城市转为向农村进军", "C": "从工农武装割据转为建立全国性政权", "D": "从游击战争转向正面战场"}, "answer": ["B"], "note": "在新民主主义革命时期，对中国革命具有决定意义的新起点是：从进攻大城市转为向农村进军", "sourcePages": [125], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-64", "subject": "史纲", "chapter": 5, "chapterTitle": "第五章中国革命的新道路", "type": "单选", "number": 64, "stem": "在大革命失败、白色恐怖极其严重的条件下，中国革命之所以能够得到坚持和发展，根本原因就在于中国共产党", "options": {"A": "紧紧地依靠农民，领导农民进行了土地制度的革命", "B": "吸取了大革命失败的教训，进行了武装起义", "C": "建立了国民革命联合战线，扩大了革命队伍", "D": "确立了思想建党、政治建军原则"}, "answer": ["A"], "note": "在大革命失败、白色恐怖极其严重的条件下，中国革命之所以能够得到坚持和发展，根本原因就在于中国共产党：紧紧地依靠农民，领导农民进行了土地制度的革命", "sourcePages": [125], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-66", "subject": "史纲", "chapter": 5, "chapterTitle": "第五章中国革命的新道路", "type": "单选", "number": 66, "stem": "在20世纪30年代前期、中期，中国共产党内屡次出现严重的“左”倾错误，其原因是多方面的。主要的原因在于", "options": {"A": "八七会议以后党内一直存在着的浓厚的“左”倾情绪始终没有得到认真的清理", "B": "共产国际对中国革命的错误指导", "C": "党不善于把马克思列宁主义与中国实际全面地、正确地结合起来", "D": "中国国情的复杂性"}, "answer": ["C"], "note": "在20世纪30年代前期、中期，中国共产党内屡次出现严重的“左”倾错误，主要的原因在于：党不善于把马克思列宁主义与中国实际全面地、正确地结合起来", "sourcePages": [125], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-67", "subject": "史纲", "chapter": 5, "chapterTitle": "第五章中国革命的新道路", "type": "单选", "number": 67, "stem": "1934年10月，中共中央、中革军委率中央红军主力等8.6万余人踏上战略转移的漫漫征程，开始了世界历史上前所未有的壮举一一长征。中央红军进行长征的直接原因是\n\n①民族矛盾已经上升为主要矛盾\n\n②停止内战，北上抗日\n\n③红军在第五次反“围剿”作战中遭到失败\n\n④红军已无在原地扭转战局的可能", "options": {"A": "①②", "B": "①③", "C": "②③", "D": "③④"}, "answer": ["D"], "note": "中央红军进行长征的直接原因是：红军在第五次反“围剿”作战中遭到失败；红军已无在原地扭转战局的可能", "sourcePages": [125], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-69", "subject": "史纲", "chapter": 5, "chapterTitle": "第五章中国革命的新道路", "type": "单选", "number": 69, "stem": "中国共产党在长征途中召开的遵义会议，集中解决了在当时具有决定意义的", "options": {"A": "军事问题和组织问题", "B": "政治问题和路线问题", "C": "战略问题和战术问题", "D": "思想问题和作风问题"}, "answer": ["A"], "note": "中国共产党在长征途中召开的遵义会议，集中解决了在当时具有决定意义的：军事问题和组织问题", "sourcePages": [126], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-56", "subject": "史纲", "chapter": 5, "chapterTitle": "第五章中国革命的新道路", "type": "多选", "number": 56, "stem": "1927年9月9日，毛泽东等领导的湘赣边界秋收起义爆发。起义军公开打出了“工农革命军”的旗帜，在攻打中心城市长沙受挫后，毛泽东果断改变计划，决定向敌人控制比较薄弱的农村转移。10月7日，起义部队抵达江西省宁冈县茅坪，开始了创建井冈山农村革命根据地的斗争。井冈山革命根据地的建立", "options": {"A": "集中体现中国革命的正确方向", "B": "点燃了工农武装割据的星星之火", "C": "为中国革命开辟出了农村包围城市、武装夺取政权这样一条前人没有走过的道路", "D": "是由大革命失败到土地革命战争兴起的历史性转变"}, "answer": ["A", "B", "C"], "note": "井冈山革命根据地的建立：集中体现中国革命的正确方向；点燃了工农武装割据的星星之火；为中国革命开辟出了农村包围城市、武装夺取政权这样一条前人没有走过的道路", "sourcePages": [142], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-58", "subject": "史纲", "chapter": 5, "chapterTitle": "第五章中国革命的新道路", "type": "多选", "number": 58, "stem": "1928年10月和11月，毛泽东写了《中国的红色政权为什么能够存在？》和《井冈山的斗争》两篇文章，论证了红色政权能够长期存在并发展的主客观条件，提出了工农武装割据的思想。1930年1月，毛泽东在《星星之火，可以燎原》一文中进一步阐明了中国革命只能走与资本主义国家不同的道路。这些论述，提出了党把工作重心由城市转移到农村，在农村开展游击战争，深入进行土地革命，建立和发展红色政权，待条件成熟时再夺取全国政权的中国革命新道路的思想。农村包围城市、武装夺取政权的理论", "options": {"A": "是对1927年大革命失败后中国共产党领导的红军和根据地斗争经验的科学概括", "B": "是在同当时党内盛行的把马克思主义教条化的错误倾向作坚决斗争的基础上逐步形成的", "C": "是在共产国际的直接指导和借鉴苏联经验的基础上逐步形成的", "D": "标志着中国化的马克思主义即毛泽东思想的初步形成"}, "answer": ["A", "B", "D"], "note": "农村包围城市、武装夺取政权的理论：是对1927年大革命失败后中国共产党领导的红军和根据地斗争经验的科学概括；是在同当时党内盛行的把马克思主义教条化的错误倾向作坚决斗争的基础上逐步形成的；标志着中国化的马克思主义即毛泽东思想的初步形成", "sourcePages": [143], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-59", "subject": "史纲", "chapter": 5, "chapterTitle": "第五章中国革命的新道路", "type": "多选", "number": 59, "stem": "1931年11月，中华苏维埃第一次全国代表大会在江西瑞金召开。大会通过了《中华苏维埃共和国宪法大纲》以及土地法令、劳动法等，选举产生了中华苏维埃共和国中央执行委员会，成立了中华苏维埃共和国临时中央政府，毛泽东当选为主席。中华苏维埃共和国", "options": {"A": "是中国历史上第一个全国性的各个革命阶级联合专政的政权", "B": "是中国共产党在局部地区执政的重要尝试", "C": "扩大了党和红色政权的影响，一定程度上加强了对处于被分割状态的各根据地的中枢指挥作用", "D": "推动了各根据地的政权、经济、文化教育和党的自身建设，开创了土地革命战争新局面"}, "answer": ["B", "C", "D"], "note": "中华苏维埃共和国：是中国共产党在局部地区执政的重要尝试；扩大了党和红色政权的影响，一定程度上加强了对处于被分割状态的各根据地的中枢指挥作用；推动了各根据地的政权、经济、文化教育和党的自身建设，开创了土地革命战争新局面", "sourcePages": [143], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-60", "subject": "史纲", "chapter": 5, "chapterTitle": "第五章中国革命的新道路", "type": "多选", "number": 60, "stem": "1935年1月，中共中央政治局在长征途中举行遵义会议，这在党的历史上是一个生死攸关的转折点。遵义会议", "options": {"A": "标志着中国共产党在政治上开始走向成熟", "B": "使实事求是的思想路线在全党范围确立起来", "C": "确立党中央的正确领导，创造性地制定和实施符合中国革命特点的战略策略", "D": "开启了党独立自主解决中国革命实际问题的新阶段"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [143], "answerSource": "待核对"}, {"id": "史纲-多选-61", "subject": "史纲", "chapter": 5, "chapterTitle": "第五章中国革命的新道路", "type": "多选", "number": 61, "stem": "1934年9月上旬，国民党军队加紧对中央革命根据地腹地发动进攻，红军已无在原地扭转战局的可能。10月，中共中央、中革军委率中央红军主力等8.6万余人踏上战略转移的漫漫征程，开始了世界历史上前所未有的壮举。中国工农红军长征是一次理想信念的伟大远征，是一次检验真理的伟大远征，是一次唤醒民众的伟大远征，是一次开创新局的伟大远征。长征的胜利", "options": {"A": "极大地促进了党在政治上和思想上的成熟", "B": "是中国革命转危为安的关键", "C": "标志着党在政治上、思想上、组织上走向成熟", "D": "是中华民族从近代以来陷入深重危机走向伟大复兴的历史转折点"}, "answer": ["A", "B"], "note": "长征的胜利：极大地促进了党在政治上和思想上的成熟；是中国革命转危为安的关键", "sourcePages": [143], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-72", "subject": "史纲", "chapter": 6, "chapterTitle": "第六章中华民族的抗日战争", "type": "单选", "number": 72, "stem": "华北事变发生后，中国共产党组织领导的一二·九运动标志着", "options": {"A": "中国人民局部抗日战争的开始", "B": "中国人民抗日救亡运动新高潮的到来", "C": "中国抗日民族统一战线的形成", "D": "中国抗日战争进入全民族抗战的新时期"}, "answer": ["B"], "note": "中国共产党组织领导的“一二九”运动标志着：中国人民抗日救亡运动新高潮的到来", "sourcePages": [126], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-73", "subject": "史纲", "chapter": 6, "chapterTitle": "第六章中华民族的抗日战争", "type": "单选", "number": 73, "stem": "1935年，电影《风云儿女》一公映，主题歌《义勇军进行曲》便成为时代的最强音。歌曲发出了中华民族不甘沦亡的怒吼，吹响了中华儿女万众一心、血战到底的战斗号角。《义勇军进行曲》之所以发出“中华民族到了最危险的时候”的呐喊，最重要的原因是", "options": {"A": "国民党政府长期奉行“攘外必先安内”方针，对日本的大举侵略一再退让", "B": "国际联盟和英美等国政府采取对日姑息、纵容的政策", "C": "日本大举侵华，妄图把中国变为其独占的殖民地", "D": "中国长期缺乏有力的国际援助"}, "answer": ["C"], "note": "《义勇军进行曲》之所以发出“中华民族到了最危险的时候”的呐喊，最重要的原因是：且本大举侵华，妄图把中国变为其独占的殖民地", "sourcePages": [126], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-74", "subject": "史纲", "chapter": 6, "chapterTitle": "第六章中华民族的抗日战争", "type": "单选", "number": 74, "stem": "1935年12月，中共中央在陕北瓦窑堡召开政治局扩大会议，提出党的基本策略任务是", "options": {"A": "建立广泛的抗日民族统一战线", "B": "在根据地实行减租减息的土地政策", "C": "在敌后广泛开展游击战和运动战", "D": "保持党在思想上、政治上和组织上的独立性"}, "answer": ["A"], "note": "中共中央在陕北瓦窑堡召开政治局扩大会议，提出党的基本策略任务是：建立广泛的抗日民族统一战线", "sourcePages": [126], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-76", "subject": "史纲", "chapter": 6, "chapterTitle": "第六章中华民族的抗日战争", "type": "单选", "number": 76, "stem": "1937年8月22日至25日，中共中央在陕北洛川召开政治局扩大会议（洛川会议），通过了《中国共产党抗日救国十大纲领》和《中共中央关于目前形势与党的任务的决定》，这标志着", "options": {"A": "党的“逼蒋抗日”总方针的明确提出", "B": "党确立了建立广泛的抗日民族统一战线的策略", "C": "党制定了关于根据地建设的基本方针", "D": "党的全面抗战路线的正式形成"}, "answer": ["D"], "note": "洛川会议通过了《中国共产党抗日救国十大纲领》和《中共中央关于目前形势与党的任务的决定》，这标志着：党的全面抗战路线的正式形成", "sourcePages": [127], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-77", "subject": "史纲", "chapter": 6, "chapterTitle": "第六章中华民族的抗日战争", "type": "单选", "number": 77, "stem": "1937年8月，中国共产党在陕北洛川召开政治局扩大会议，制定了抗日救国十大纲领，强调要打倒日本帝国主义，关键在于", "options": {"A": "坚持统一战线中无产阶级的领导权", "B": "使敌后游击战争成为主要的抗日作战方式", "C": "采取集中优势兵力、各个歼灭敌人的作战原则", "D": "使已经发动的抗战成为全面的全民族抗战"}, "answer": ["D"], "note": "洛川会议强调要打倒日本帝国主义，关键在于：使已经发动的抗战成为全面的全民族抗战", "sourcePages": [127], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-78", "subject": "史纲", "chapter": 6, "chapterTitle": "第六章中华民族的抗日战争", "type": "单选", "number": 78, "stem": "中国抗日战争进入全民族抗战阶段是在", "options": {"A": "九一八事变后", "B": "一·二八事变后", "C": "华北事变后", "D": "卢沟桥事变后"}, "answer": ["D"], "note": "中国抗日战争进入全民族抗战阶段是在：卢沟桥事变后", "sourcePages": [127], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-79", "subject": "史纲", "chapter": 6, "chapterTitle": "第六章中华民族的抗日战争", "type": "单选", "number": 79, "stem": "1938年5月至6月间，毛泽东总结全民族抗战10个月来的经验，批驳了“亡国论”“速胜论”等错误观点，系统地阐明了持久战的战略总方针。毛泽东科学预见了抗日战争的发展进程，指出抗日战争的最关键阶段是", "options": {"A": "战略防御阶段", "B": "战略相持阶段", "C": "战略反攻阶段", "D": "战略决战阶段"}, "answer": ["B"], "note": "抗日战争的最关键阶段是：战略相持阶段", "sourcePages": [127], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-82", "subject": "史纲", "chapter": 6, "chapterTitle": "第六章中华民族的抗日战争", "type": "单选", "number": 82, "stem": "抗日战争时期，为克服根据地面临的严重困难局面，毛泽东提出的经济工作和财政工作总方针是", "options": {"A": "“自己动手，丰衣足食”", "B": "“发展经济，保障供给”", "C": "“减租减息”", "D": "“精兵简政”"}, "answer": ["B"], "note": "抗日战争时期，经济工作和财政工作总方针是：“发展经济，保障供给”", "sourcePages": [127], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-83", "subject": "史纲", "chapter": 6, "chapterTitle": "第六章中华民族的抗日战争", "type": "单选", "number": 83, "stem": "1941年5月，毛泽东作了《改造我们的学习》的报告，整风运动首先在党的高级干部中进行。1942年2月，毛泽东先后作了《整顿党的作风》和《反对党八股》的讲演，整风运动在全党范围普遍展开。整风运动最主要的任务是", "options": {"A": "反对“左”倾机会主义，端正党的政治路线", "B": "反对宗派主义以整顿党风", "C": "反对主观主义以整顿学风", "D": "反对党八股以整顿文风"}, "answer": ["C"], "note": "整风运动最主要的任务是：反对主观主义以整顿学风", "sourcePages": [127], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-85", "subject": "史纲", "chapter": 6, "chapterTitle": "第六章中华民族的抗日战争", "type": "单选", "number": 85, "stem": "中国人民的抗日战争从1931年开始，到1945年结束，前后经历了14年的浴血奋战。在世界反法西斯战争的进程中，中国人民的抗日战争被称为“最早的抗争，最后的胜利”。成为抗日战争取得完全胜利的重要标志的是", "options": {"A": "中国参加联合国制宪会议，成为联合国的创始国和五个常任理事国之一", "B": "日本天皇裕仁发布《终战诏书》，日本无条件投降", "C": "日本代表在东京湾美军军舰密苏里号上签署向同盟国的投降书", "D": "台湾以及澎湖列岛重归中国主权管辖"}, "answer": ["D"], "note": "成为抗日战争取得完全胜利的重要标志的是：台湾以及澎湖列岛重归中国主权管辖", "sourcePages": [128], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-87", "subject": "史纲", "chapter": 6, "chapterTitle": "第六章中华民族的抗日战争", "type": "单选", "number": 87, "stem": "中国人民抗日战争的胜利，是近代以来中国人民反抗外敌入侵第一次取得完全胜利的民族解放斗争。抗日战争取得胜利的决定因素是", "options": {"A": "中国共产党的中流砥柱作用", "B": "以爱国主义为核心的民族精神", "C": "全民族抗战", "D": "坚持持久战方针"}, "answer": ["B"], "note": "抗日战争取得胜利的决定因素是：以爱国主义为核心的民族精神", "sourcePages": [128], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-88", "subject": "史纲", "chapter": 6, "chapterTitle": "第六章中华民族的抗日战争", "type": "单选", "number": 88, "stem": "中华民族从近代以来陷入深重危机走向伟大复兴的历史转折点是", "options": {"A": "红军长征的胜利", "B": "抗日战争的胜利", "C": "解放战争的胜利", "D": "抗美援朝战争的胜利"}, "answer": ["B"], "note": "中华民族从近代以来陷入深重危机走向伟大复兴的历史转折点是：抗日战争的胜利", "sourcePages": [128], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-62", "subject": "史纲", "chapter": 6, "chapterTitle": "第六章中华民族的抗日战争", "type": "多选", "number": 62, "stem": "1931年9月18日深夜，日本关东军按照精心策划，炸毁沈阳柳条湖“南满铁路”路轨，并嫁祸于中国军队，日军以此为借口，炮轰中国东北军北大营，制造了震惊中外的九一八事变。面对日本的野蛮侵略，中国人民奋起抵抗。中国人民在白山黑水间的奋起抵抗", "options": {"A": "揭开了世界反法西斯战争的序幕", "B": "标志着中国由此进入全民族抗战阶段", "C": "成为中国人民抗日战争的起点", "D": "直接促成了国共两党的第二次合作"}, "answer": ["A", "C"], "note": "中国人民在白山黑水间的奋起抵抗：揭开了世界反法西斯战争的序幕；成为中国人民抗日战争的起点", "sourcePages": [143], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-65", "subject": "史纲", "chapter": 6, "chapterTitle": "第六章中华民族的抗日战争", "type": "多选", "number": 65, "stem": "以国共两党合作为基础的抗日民族统一战线正式形成的标志是", "options": {"A": "西安事变的和平解决", "B": "国民党中央通讯社发表《中共中央为公布国共合作宣言》", "C": "蒋介石发表实际上承认中国共产党合法地位的谈话", "D": "国民党五届三中全会"}, "answer": ["B", "C"], "note": "以国共两党合作为基础的抗日民族统一战线正式形成的标志是：国民党中央通讯社发表《中共中央为公布国共合作宣言》；蒋介石发表实际上承认中国共产党合法地位的谈话", "sourcePages": [144], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-66", "subject": "史纲", "chapter": 6, "chapterTitle": "第六章中华民族的抗日战争", "type": "多选", "number": 66, "stem": "日本发动全面侵华战争后，中华民族面临空前危机，全国人民最关心的问题是：这场战争能不能胜利？怎样争取胜利？毛泽东同志科学地回答了这个问题，他在1938年发表的《论持久战》一文，使全国人民对抗战的进程和前途有了清晰的认识，极大坚定了全国军民坚持抗战的信心。《论持久战》一文", "options": {"A": "分析了中日双方存在着的互相矛盾的四个基本特点", "B": "批驳了“亡国论”“速胜论”，明确指出抗日战争是持久的，最后胜利属于中国", "C": "科学预见了抗日战争由防御到相持、最后到反攻的三个阶段", "D": "强调“兵民是胜利之本”，战胜日本的侵略，必须进行人民战争"}, "answer": ["A", "B", "C", "D"], "note": "《论持久战》：分析了中日双方存在着的互相矛盾的四个基本特点；批驳了“亡国论”“速胜论”，明确指出抗日战争是持久的，最后胜利属于中国；科学预见了抗日战争由防御到相持、最后到反攻的三个阶段；强调“兵民是胜利之本”，战胜日本的侵略，必须进行人民战争", "sourcePages": [144], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-67", "subject": "史纲", "chapter": 6, "chapterTitle": "第六章中华民族的抗日战争", "type": "多选", "number": 67, "stem": "从传统的战争理论看来，游击战争是个战术问题。但是，在中国人民抗日战争中，游击战被提到战略地位，具有全局性意义。以下说法正确的有", "options": {"A": "在战略防御阶段，游击战争担负了抗击日军战略进攻的主要任务", "B": "游击战争主要是在外线单独作战，而不是在内线配合正规军的战役作战", "C": "在民族战争条件下，游击战争能够大规模地进行", "D": "在长期的不断削弱敌人、壮大自己的斗争中，游击军和游击战必将向正规军和运动战发展"}, "answer": ["B", "C", "D"], "note": "在中国人民抗日战争中，游击战被提到战略地位，具有全局性意义：游击战争主要是在外线单独作战，而不是在内线配合正规军的战役作战；在民族战争条件下，游击战争能够大规模地进行；在长期的不断削弱敌人、壮大自己的斗争中，游击军和游击战必将向正规军和运动战发展", "sourcePages": [144], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-68", "subject": "史纲", "chapter": 6, "chapterTitle": "第六章中华民族的抗日战争", "type": "多选", "number": 68, "stem": "为了实现全面抗战路线和持久战战略总方针，毛泽东首次将游击战提高到战略地位。在极为艰苦的反“扫荡”、反“清乡”斗争中，敌后军民创造了很多极为有效、灵活多样的歼敌方法，如伏击战、破袭战、地雷战、地道战、麻雀战等，使日军犹如困兽，陷入人民战争的汪洋大海。独立自主的游击战争", "options": {"A": "实质上是抗日战争中时间最长、战斗战役持续不断的一场特殊战略大会战", "B": "是人民军队发挥政治优势和军事优势最好的作战形式", "C": "是坚持持久抗战、最终彻底战胜日本侵略者的唯一正确的政治军事方针", "D": "始终是国民党正面战场正规战的重要辅助力量"}, "answer": ["A", "B", "C"], "note": "独立自主的游击战争：实质上是抗日战争中时间最长、战斗战役持续不断的一场特殊战略大会战；是人民军队发挥政治优势和军事优势最好的作战形式；是坚持持久抗战、最终彻底战胜日本侵略者的唯一正确的政治军事方针", "sourcePages": [144], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-71", "subject": "史纲", "chapter": 6, "chapterTitle": "第六章中华民族的抗日战争", "type": "多选", "number": 71, "stem": "中国共产党在抗日民族统一战线中坚持的策略总方针是", "options": {"A": "发展进步势力", "B": "争取中间势力", "C": "消灭反动势力", "D": "孤立顽固势力"}, "answer": ["A", "B", "D"], "note": "中国共产党在抗日民族统一战线中坚持的策略总方针是：发展进步势力；争取中间势力；孤立顽固势力", "sourcePages": [145], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-75", "subject": "史纲", "chapter": 6, "chapterTitle": "第六章中华民族的抗日战争", "type": "多选", "number": 75, "stem": "1938年，在党的六届六中全会上，毛泽东明确提出“马克思主义的中国化”命题。他强调：“马克思主义的中国化，使之在其每一表现中带着中国的特性，即是说，按照中国的特点去应用它，成为全党函待了解并函须解决的问题。”为了推进马克思主义中国化的事业，毛泽东向全党提出的任务是", "options": {"A": "普遍地、深入地学习马克思列宁主义的理论", "B": "学习我们的历史遗产并给以批判的总结", "C": "调查研究当前运动的特点及其规律性", "D": "反对主观主义、宗派主义和党八股"}, "answer": ["A", "B", "C"], "note": "为了推进马克思主义中国化的事业，毛泽东向全党提出的任务是：普遍地、深入地学习马克思列宁主义的理论；学习我们的历史遗产并给以批判的总结；调查研究当前运动的特点及其规律性", "sourcePages": [145], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-76", "subject": "史纲", "chapter": 6, "chapterTitle": "第六章中华民族的抗日战争", "type": "多选", "number": 76, "stem": "1942年2月，毛泽东先后作了《整顿党的作风》和《反对党八股》的讲演，整风运动在全党范围普遍展开。在全党开展整风运动，原因在于", "options": {"A": "由于条件的限制，遵义会议以来对曾经给党的事业造成严重危害的主观主义、教条主义，没有来得及从思想上进行认真的清理", "B": "随着党的队伍的扩大，一大批出身农民和其他小资产阶级的新党员身上存在着各种非无产阶级思想", "C": "共产国际解散给党带来的不利影响也需要应对", "D": "老党员要适应新形势，也需要进一步提高自己"}, "answer": ["A", "B", "D"], "note": "在全党开展整风运动，原因在于：由于条件的限制，遵义会议以来对曾经给党的事业造成严重危害的主观主义、教条主义，没有来得及从思想上进行认真的清理；随着党的队伍的扩大，一大批出身农民和其他小资产阶级的新党员身上存在着各种非无产阶级思想；老党员要适应新形势，也需要进一步提高自己", "sourcePages": [145], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-77", "subject": "史纲", "chapter": 6, "chapterTitle": "第六章中华民族的抗日战争", "type": "多选", "number": 77, "stem": "1941年5月，毛泽东作了《改造我们的学习》的报告。整风运动首先在党的高级干部中进行。1942年2月，毛泽东先后作了《整顿党的作风》和《反对党八股》的讲演，整风运动在全党范围普遍展开。任弼时在《学习毛泽东整顿三风报告的笔记》中记录了参加整风运动的体会：“毛泽东同志整顿三风报告中，关于反对主观主义的主要精神，是正确地提出了对待马列主义态度问题。告诉我们学习马列主义，不是学它的字句，而是要学会用它的立场、观点和方法去解决革命中的实际问题，找出革命的发展规律，来便于我们具体决定政策。”整风运动", "options": {"A": "使实事求是的思想路线在全党范围确立起来", "B": "以党的六届七中全会原则通过《关于若干历史问题的决议》而胜利结束", "C": "开始了马克思主义与中国实际的“第一次结合”", "D": "是一次深刻的马克思主义思想教育运动和思想解放运动"}, "answer": ["A", "B", "D"], "note": "整风运动：使实事求是的思想路线在全党范围确立起来；以党的六届七中全会原则通过《关于若干历史问题的决议》而胜利结束；是一次深刻的马克思主义思想教育运动和思想解放运动", "sourcePages": [146], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-78", "subject": "史纲", "chapter": 6, "chapterTitle": "第六章中华民族的抗日战争", "type": "多选", "number": 78, "stem": "在深入总结历史经验的基础上，1944年5月21日至1945年4月20日，中共扩大的六届七中全会在延安召开。会议原则通过了《关于若干历史问题的决议》，对建党以后特别是党的六届四中全会至遵义会议前这一段党的历史及其经验教训进行了总结，对党的若干重大历史问题作出结论。《关于若干历史问题的决议》", "options": {"A": "使全党特别是党的高级干部对中国革命基本问题的认识达到了一致，增强了全党团结", "B": "充分肯定了确立毛泽东在全党领导地位的重大意义", "C": "为党的七大胜利召开创造了充分条件，有力促进了中国革命事业发展", "D": "开启了党独立自主解决中国革命实际问题的新阶段"}, "answer": ["A", "B", "C"], "note": "《关于若干历史问题的决议》：使全党特别是党的高级于部对中国革命基本问题的认识达到了一致，增强了全党团结；充分肯定了确立毛泽东在全党领导地位的重大意义；为党的七大胜利召开创造了充分条件，有力促进了中国革命事业发展", "sourcePages": [146], "answerSource": "配套资料与题目核对"}, {"id": "史纲-多选-79", "subject": "史纲", "chapter": 6, "chapterTitle": "第六章中华民族的抗日战争", "type": "多选", "number": 79, "stem": "1945年4月23日至6月11日，中国共产党第七次全国代表大会在延安举行。这次大会以“团结的大会，胜利的大会”载入党的史册。中共七大", "options": {"A": "制定了党的政治路线和新民主主义国家在政治、经济、文化方面的纲领", "B": "标志着我们党在政治上、思想上、组织上走向了成熟", "C": "把党成立以来的历史经验概括为三大法宝", "D": "把毛泽东思想确立为党的指导思想并写入党章"}, "answer": ["A", "B", "D"], "note": "中共七大：制定了党的政治路线和新民主主义国家在政治、经济、文化方面的纲领；标志着我们党在政治上、思想上、组织上走向了成熟；把毛泽东思想确立为党的指导思想并写入党章", "sourcePages": [146], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-81", "subject": "史纲", "chapter": 6, "chapterTitle": "第六章中华民族的抗日战争", "type": "多选", "number": 81, "stem": "1945年，包括台湾同胞在内的全体中华儿女前仆后继、浴血奋战，取得中国人民抗日战争暨世界反法西斯战争的伟大胜利，台湾随之光复，重回祖国怀抱。台湾光复是", "options": {"A": "中国人民抗日战争胜利的重要成果", "B": "中国政府恢复对台湾行使主权的重要铁证", "C": "台湾作为中国一部分的历史事实和法理链条的重要一环", "D": "两岸同胞的共同荣光和全体中华儿女的民族记忆"}, "answer": ["A", "B", "C", "D"], "note": "台湾光复是：中国人民抗日战争胜利的重要成果；中国政府恢复对台湾行使主权的重要铁证；台湾作为中国一部分的历史事实和法理链条的重要一环；两岸同胞的共同荣光和全体中华儿女的民族记忆心的民族精神是中国人民抗日战争胜利的决定因素；中国共产党的中流砥柱作用是中国人民抗日战争胜利的关键；全民族抗战是中国人民抗日战争胜利的重要法宝；世界反法西斯力量为中国人民提供了宝贵的人力物力支持", "sourcePages": [146], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-85", "subject": "史纲", "chapter": 6, "chapterTitle": "第六章中华民族的抗日战争", "type": "多选", "number": 85, "stem": "中国共产党的中流砥柱作用是中国人民抗日战争胜利的关键。中国共产党的中流砥柱作用体现在", "options": {"A": "在日本帝国主义加紧侵略我国、民族危机空前严重的关头，率先高举武装抗日旗帜", "B": "促成西安事变和平解决，对推动国共再次合作、团结抗日起了重大历史作用", "C": "坚持全面抗战路线，提出和实施持久战的战略总方针和一整套人民战争的战略战术", "D": "开辟广大敌后战场和抗日根据地，领导八路军、新四军、东北抗日联军和其他人民抗日武装英勇作战"}, "answer": ["A", "B", "C", "D"], "note": "中国共产党的中流砥柱作用体现在：在日本帝国主义加紧侵略我国、民族危机空前严重的关头，率先高举武装抗日旗帜；促成西安事变和平解决，对推动国共再次合作、团结抗日起了重大历史作用；坚持全面抗战路线，提出和实施持久战的战略总方针和一整套人民战争的战略战术；开辟广大敌后战场和抗日根据地，领导八路军、新四军、东北抗日联军和其他人民抗日武装英勇作战", "sourcePages": [147], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-90", "subject": "史纲", "chapter": 7, "chapterTitle": "第七章为建立新中国而奋斗", "type": "单选", "number": 90, "stem": "1945年10月10日，重庆谈判双方签署《政府与中共代表会谈纪要》，即双十协定，确认和平建国的基本方针，同意“长期合作，坚决避免内战”。1946年1月10日，政治协商会议在重庆开幕。会议通过了政府组织案等五项协议。政协会议闭幕的第二天，中共中央发出党内指示，要求全党准备为坚决实现政协协议而奋斗。同时提出，必须提高警惕，注意“阵地的保持与继续取得”，做好进行自卫战争的准备，并指出，目前解放区的中心工作是", "options": {"A": "放手发动群众，壮大人民力量", "B": "进行土地改革", "C": "发展生产，保障供给", "D": "练兵、减租与生产"}, "answer": ["D"], "note": "解放区的中心工作是：练兵、减租与生产", "sourcePages": [128], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-91", "subject": "史纲", "chapter": 7, "chapterTitle": "第七章为建立新中国而奋斗", "type": "单选", "number": 91, "stem": "1947年6月底，根据中共中央的决策和部署，刘伯承、邓小平率领的晋冀鲁豫野战军主力，实施中央突破，千里跃进大别山。随后，陈毅、粟裕指挥的华东野战军主力为东路，挺进苏鲁豫皖地区。陈、谢富治指挥的晋冀鲁豫野战军一部为西路，挺进豫西。三路大军相互策应，机动歼敌，这标志着", "options": {"A": "蒋介石20年反革命统治由发展到消灭的转折点", "B": "人民解放军在数量上已经超过国民党军队", "C": "100多年来帝国主义在中国的统治由发展到消灭的转折点", "D": "人民解放战争战略进攻的序幕由此揭开"}, "answer": ["D"], "note": "三路大军相互策应，机动歼敌，这标志着：人民解放战争战略进攻的序幕由此揭开", "sourcePages": [128], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-92", "subject": "史纲", "chapter": 7, "chapterTitle": "第七章为建立新中国而奋斗", "type": "单选", "number": 92, "stem": "1947年12月，中共中央在陕北米脂县杨家沟召开会议，制定了夺取全国胜利的行动纲领。毛泽东指出，中国革命已经发展到了一个历史的转折点，这是", "options": {"A": "中国革命重心从农村转向城市的标志", "B": "中国共产党和中国革命事业从挫折走向胜利的伟大转折", "C": "中华民族从近代以来陷入深重危机走向伟大复兴的历史转折点", "D": "100多年来帝国主义在中国的统治由发展到消灭的转折点"}, "answer": ["D"], "note": "中国革命已经发展到了一个历史的转折点，这是：100多年来帝国主义在中国的统治由发展到消灭的转折点", "sourcePages": [129], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-95", "subject": "史纲", "chapter": 7, "chapterTitle": "第七章为建立新中国而奋斗", "type": "单选", "number": 95, "stem": "1949年1月22日，李济深、沈钧儒等民主党派的领导人和著名的无党派民主人士55人联合发表《对时局的意见》，一致认定中共提出的关于召开政治协商会议、成立联合政府的主张“符合于全国人民大众的要求”，恳切表示“愿在中共领导下，献其绵薄，共策进行，以期中国人民民主革命之迅速成功，独立、自由、和平、幸福的新中国之早日实现”。1949年春，毛泽东在同有关人士谈话时提出，民主党派应“积极参政，共同建设新中国”，这", "options": {"A": "揭开了中国共产党同各党派、各团体、各族各界人士协商建国的序幕", "B": "奠定了中国共产党领导的多党合作和政治协商制度的基础", "C": "标志着民主党派地位的根本变化", "D": "表明中国各民主党派和无党派民主人士公开自愿接受中国共产党的领导"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [129], "answerSource": "待核对"}, {"id": "史纲-单选-96", "subject": "史纲", "chapter": 7, "chapterTitle": "第七章为建立新中国而奋斗", "type": "单选", "number": 96, "stem": "1949年9月21日，中国人民政治协商会议第一届全体会议在北平（北京）隆重开幕。这次会议与1946年1月在重庆召开的政治协商会议的不同在于", "options": {"A": "中国共产党居于领导地位", "B": "多党派参加", "C": "民主党派是执政党", "D": "通过的《共同纲领》属于社会主义性质"}, "answer": ["A"], "note": "中国人民政治协商会议第一届全体会议与1946年1月在重庆召开的政治协商会议的不同在于中国共产党居于领导地位", "sourcePages": [129], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-98", "subject": "史纲", "chapter": 7, "chapterTitle": "第七章为建立新中国而奋斗", "type": "单选", "number": 98, "stem": "中国革命的胜利，结束了100多年来中华民族遭受资本-帝国主义侵略和中国各族人民遭受资本-帝国主义同封建统治阶级联合压迫与剥削的历史，结束了国家战乱频仍、四分五裂的局面。中国革命之所以能够走上胜利发展的道路，从根本上说，是由于有了", "options": {"A": "一支人民的军队", "B": "广泛的统一战线", "C": "一条正确的革命道路", "D": "中国共产党的领导"}, "answer": ["D"], "note": "中国革命之所以能够走上胜利发展的道路，从根本上说，是由于有了：中国共产党的领导", "sourcePages": [130], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-101", "subject": "史纲", "chapter": 7, "chapterTitle": "第七章为建立新中国而奋斗", "type": "单选", "number": 101, "stem": "《论人民民主专政》是毛泽东在中国新民主主义革命取得决定性胜利、全国性政权即将建立的时刻，为纪念中国共产党成立28周年而撰写的文章。文章论述了即将成立的中华人民共和国的国家性质，各阶级在国家中的地位及其相互关系，国家对内、对外政策等。《论人民民主专政》这篇文章\n\n①奠定了新中国国家政权的理论基础和一定发展阶段上的政策基础\n\n②为即将成立的新中国作了政治理论准备\n\n③与中共七届二中全会的决议一起构成了《中国人民政治协商会议共同纲领》的基础\n\n④是中国共产党人开始探索适合中国国情的社会主义建设道路的标志", "options": {"A": "①②③", "B": "①②④", "C": "①③④", "D": "②③④"}, "answer": ["A"], "note": "《论人民民主专政》奠定了新中国国家政权的理论基础和一定发展阶段上的政策基础，为即将成立的新中国作了政治理论准备，与中共七届二中全会的决议一起构成了《中国人民政治协商会议共同纲领》的基础。", "sourcePages": [130], "answerSource": "配套资料与题目核对"}, {"id": "史纲-多选-87", "subject": "史纲", "chapter": 7, "chapterTitle": "第七章为建立新中国而奋斗", "type": "多选", "number": 87, "stem": "1945年8月，蒋介石连发三电，邀请毛泽东赴重庆谈判。其目的在于", "options": {"A": "满足全国人民强烈要求和平的愿望，建立和平、民主的新中国", "B": "以此敷衍国内外舆论，掩盖其正在进行的内战准备", "C": "诱使中共交出人民军队和解放区政权，以期不战而控制全中国", "D": "如果谈判不成，即放手发动内战，并把战争责任转嫁给中国共产党"}, "answer": ["B", "C", "D"], "note": "蒋介石连发三电，邀请毛泽东赴重庆谈判，目的在于：以此敷衍国内外舆论，掩盖其正在进行的内战准备；诱使中共交出人民军队和解放区政权，以期不战而控制全中国；如果谈判不成，即放手发动内战，并把战争责任转嫁给中共", "sourcePages": [147], "answerSource": "配套资料与题目核对"}, {"id": "史纲-多选-91", "subject": "史纲", "chapter": 7, "chapterTitle": "第七章为建立新中国而奋斗", "type": "多选", "number": 91, "stem": "毛泽东指出：“如果我们能够普遍地彻底地解决土地问题，我们就获得了足以战胜一切敌人的最基本的条件。”解放战争时期，为推动解放区土改运动进一步发展，1947年7月至9月，中国共产党在西柏坡召开全国土地会议，制定和通过了《中国土地法大纲》。土地制度改革", "options": {"A": "是中国共产党领导广大农民从根本上摧毁中国封建制度根基的社会大变革", "B": "使人民解放战争获得源源不断的人力、物力支援", "C": "为打败蒋介石、建立新中国奠定了深厚的群众基础", "D": "为当代中国的一切发展进步提供了根本政治保障"}, "answer": ["A", "B", "C"], "note": "土地制度改革：是中国共产党领导广大农民从根本上摧毁中国封建制度根基的社会大变革；使人民解放战争获得源源不断的人力、物力支援；为打败蒋介石、建立新中国奠定了深厚的群众基础", "sourcePages": [148], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-92", "subject": "史纲", "chapter": 7, "chapterTitle": "第七章为建立新中国而奋斗", "type": "多选", "number": 92, "stem": "1949年3月召开的中共七届二中全会是新中国成立前中国共产党召开的一次十分重要的会议。毛泽东在会议上提出了“两个务必”的思想，即“务必使同志们继续地保持谦虚、谨慎、不骄、不躁的作风，务必使同志们继续地保持艰苦奋斗的作风”。这次会议", "options": {"A": "规定了党在全国胜利后在政治、经济、外交方面应当采取的基本政策", "B": "指出了中国由农业国转变为工业国、由新民主主义社会转变为社会主义社会的发展方向", "C": "提出要掌握斗争的方向，不要四面出击", "D": "标志着中国革命重心从农村转向城市"}, "answer": ["A", "B"], "note": "中共七届二中全会：规定了党在全国胜利后在政治、经济、外交方面应当采取的基本政策；指出了中国由农业国转变为工业国、由新民主主义社会转变为社会主义社会的发展方向", "sourcePages": [148], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-95", "subject": "史纲", "chapter": 7, "chapterTitle": "第七章为建立新中国而奋斗", "type": "多选", "number": 95, "stem": "随着国民党反动统治的覆灭和中华人民共和国的成立，中国新民主主义革命赢得了基本的胜利。中国革命胜利具有的伟大意义在于", "options": {"A": "实现了中国人民梦寐以求的民族独立和人民解放", "B": "从根本上改变了中国社会的发展方向，为实现中华民族伟大复兴开辟了广阔道路", "C": "是继俄国十月社会主义革命和世界反法西斯战争胜利后世界历史中最重大的事件", "D": "毛泽东思想和中国革命道路对于马克思列宁主义的发展是一个重大的贡献"}, "answer": ["A", "B", "C", "D"], "note": "中国革命胜利具有的伟大意义在于：实现了中国人民梦寐以求的民族独立和人民解放；从根本上改变了中国社会的发展方向，为实现中华民族伟大复兴开辟了广阔道路；是继俄国十月社会主义革命和世界反法西斯战争胜利后世界历史中最重大的事件；毛泽东思想和中国革命道路对于马克思列宁主义的发展是一个重大的贡献", "sourcePages": [148, 149], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-103", "subject": "史纲", "chapter": 8, "chapterTitle": "第八章中华人民共和国的成立与中国社会主义建设道路的探索", "type": "单选", "number": 103, "stem": "1950年6月，中国共产党召开七届三中全会。这是中国共产党在新中国成立后召开的第一次中央全会。会议向全党提出当前阶段的中心任务是", "options": {"A": "完成新解放区的土地改革", "B": "争取国家财政经济状况的基本好转", "C": "现有工商业的合理调整", "D": "不要四面出击"}, "answer": ["B"], "note": "七届三中全会提出当前阶段的中心任务是：争取国家财政经济状况的基本好转", "sourcePages": [130], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-105", "subject": "史纲", "chapter": 8, "chapterTitle": "第八章中华人民共和国的成立与中国社会主义建设道路的探索", "type": "单选", "number": 105, "stem": "新中国成立初期，以毛泽东为主要代表的中国共产党人提出了三大外交方针，为独立自主的新中国外交关系奠定了基础。三大外交方针是指\n\n①“另起炉灶”\n\n②“一边倒”\n\n③“真正不结盟”\n\n④“打扫干净屋子再请客”", "options": {"A": "①②③", "B": "②③④", "C": "①②④", "D": "①③④"}, "answer": ["C"], "note": "新中国成立初期，三大外交方针是指：“另起炉灶”；“一边倒”；“打扫于净屋子再请客”", "sourcePages": [130], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-106", "subject": "史纲", "chapter": 8, "chapterTitle": "第八章中华人民共和国的成立与中国社会主义建设道路的探索", "type": "单选", "number": 106, "stem": "经过艰苦卓绝的战斗，中朝军队战胜武装到牙齿的强敌，打破了美军不可战胜的神话，迫使不可一世的侵略者于1953年7月27日在停战协定上签字。抗美援朝战争的伟大胜利", "options": {"A": "是中华民族从近代以来陷入深重危机走向伟大复兴的历史转折点，", "B": "是近代以来中国人民反抗外敌入侵第一次取得完全胜利的民族解放斗争", "C": "彻底结束了旧中国一盘散沙的局面", "D": "是中国人民站起来后屹立于世界东方的宣言书"}, "answer": ["D"], "note": "抗美援朝战争的伟大胜利：是中国人民站起来后屹立于世界东方的宣言书", "sourcePages": [131], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-112", "subject": "史纲", "chapter": 8, "chapterTitle": "第八章中华人民共和国的成立与中国社会主义建设道路的探索", "type": "单选", "number": 112, "stem": "1954年9月15日，第一届全国人民代表大会第一次会议顺利开幕。9月28日，会议在完成预定的议程后胜利闭幕。这次会议是我国人民民主建设的重要里程碑，标志着新中国", "options": {"A": "人民民主专政制度的确立", "B": "根本政治制度的正式确立", "C": "新型政党制度的正式确立", "D": "国家结构形式的正式确立"}, "answer": ["B"], "note": "第一届全国人民代表大会第一次会议是我国人民民主建设的重要里程碑，标志着新中国：根本政治制度的正式确立", "sourcePages": [131], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-113", "subject": "史纲", "chapter": 8, "chapterTitle": "第八章中华人民共和国的成立与中国社会主义建设道路的探索", "type": "单选", "number": 113, "stem": "制定一部切实可行的发展国民经济的中期计划，是完成过渡时期总路线规定的工业化主体任务的重要步骤。为准备进行有计划的经济建设，我国从1951年着手编制第一个五年计划。1955年7月召开的一届全国人大二次会议通过了这个计划。“一五”计划确定的经济建设指导方针突出的核心要点是集中主要力量", "options": {"A": "发展重工业，建立国家工业化和国防现代化的初步基础", "B": "发展交通运输业、轻工业、农业和商业，相应地培养建设人才", "C": "保证国民经济中社会主义成分的比重稳步增长", "D": "保证在发展生产的基础上逐步提高人民的物质生活和文化生活的水平"}, "answer": ["A"], "note": "“一五”计划确定的经济建设指导方针突出的核心要点是集中主要力量：发展重工业，建立国家工业化和国防现代化的初步基础", "sourcePages": [131, 132], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-114", "subject": "史纲", "chapter": 8, "chapterTitle": "第八章中华人民共和国的成立与中国社会主义建设道路的探索", "type": "单选", "number": 114, "stem": "中国进入社会主义社会的最主要的标志是", "options": {"A": "社会主义经济制度的确立", "B": "中华人民共和国的成立", "C": "党在过渡时期总路线的提出", "D": "国民经济第一个五年计划的实施"}, "answer": ["A"], "note": "中国进入社会主义社会的最主要的标志是：社会主义经济制度的确立", "sourcePages": [132], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-115", "subject": "史纲", "chapter": 8, "chapterTitle": "第八章中华人民共和国的成立与中国社会主义建设道路的探索", "type": "单选", "number": 115, "stem": "以毛泽东为主要代表的中国共产党人开始探索适合中国国情的社会主义建设道路的标志是", "options": {"A": "《论十大关系》的报告", "B": "中共八大路线的制定", "C": "《关于正确处理人民内部矛盾的问题》的发表", "D": "国民经济第一个五年计划的实施"}, "answer": ["A"], "note": "中国共产党人开始探索适合中国国情的社会主义建设道路的标志是：《论十大关系》的报告", "sourcePages": [132], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-116", "subject": "史纲", "chapter": 8, "chapterTitle": "第八章中华人民共和国的成立与中国社会主义建设道路的探索", "type": "单选", "number": 116, "stem": "1957年2月，毛泽东作了《关于正确处理人民内部矛盾的问题》的报告，阐明社会主义社会的重大理论问题。毛泽东提出，必须区分社会主义社会两类不同性质的社会矛盾，把正确处理人民内部矛盾作为国家政治生活的主题。解决人民内部矛盾用民主的方法，说服教育的方法。对于物质利益、分配方面的人民内部矛盾，毛泽东提出的方针是", "options": {"A": "统筹兼顾、适当安排", "B": "“惩前后、治病救人”", "C": "“长期共存、互相监督”", "D": "“团结一批评一团结”"}, "answer": ["A"], "note": "对于物质利益、分配方面的人民内部矛盾，毛泽东提出的方针是：统筹兼顾、适当安排", "sourcePages": [132], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-117", "subject": "史纲", "chapter": 8, "chapterTitle": "第八章中华人民共和国的成立与中国社会主义建设道路的探索", "type": "单选", "number": 117, "stem": "1956年社会主义改造基本完成以后，中国进入社会主义初级阶段。社会主义初级阶段在发展过程中会呈现不同的阶段性特征。1956年召开的中共八大指出，社会主义基本制度在我国已经基本上建立起来了，我国国内的主要矛盾是", "options": {"A": "无产阶级和资产阶级的矛盾", "B": "人民对于经济文化迅速发展的需要同当前经济文化不能满足人民需要的状况之间的矛盾", "C": "人民日益增长的物质文化需要同落后的社会生产之间的矛盾", "D": "人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾"}, "answer": ["B"], "note": "社会主义基本制度在我国已经基本上建立起来了，我国国内的主要矛盾是：人民对于经济文化迅速发展的需要同当前经济文化不能满足人民需要的状况之间的矛盾", "sourcePages": [132], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-118", "subject": "史纲", "chapter": 8, "chapterTitle": "第八章中华人民共和国的成立与中国社会主义建设道路的探索", "type": "单选", "number": 118, "stem": "1956年9月15日至27日，中国共产党第八次全国代表大会在北京举行。中共八大正确分析了国内形势和主要矛盾的变化，明确提出新形势下党和人民的主要任务。大会宣布，社会主义制度在我国已经基本上建立起来，国内主要矛盾已经是人民对于经济文化迅速发展的需要同当前经济文化不能满足人民需要的状况之间的矛盾；还有阶级斗争，还要加强人民民主专政，但根本任务已经是", "options": {"A": "实现马克思主义同中国具体实际的“第二次结合”", "B": "在新的生产关系下保护和发展生产力", "C": "正确处理人民内部矛盾", "D": "探索什么是社会主义，怎样建设社会主义"}, "answer": ["B"], "note": "中共八大正确明确提出新形势下党和人民的根本任务已经是：在新的生产关系下保护和发展生产力", "sourcePages": [132], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-119", "subject": "史纲", "chapter": 8, "chapterTitle": "第八章中华人民共和国的成立与中国社会主义建设道路的探索", "type": "单选", "number": 119, "stem": "中共八大确定的我国社会主义经济建设的方针是", "options": {"A": "在综合平衡中稳步前进", "B": "统筹兼顾、适当安排", "C": "调整、巩固、充实、提高", "D": "以农业为基础、以工业为主导"}, "answer": ["A"], "note": "中共八大确定的我国社会主义经济建设的方针是：在综合平衡中稳步前进", "sourcePages": [132], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-96", "subject": "史纲", "chapter": 8, "chapterTitle": "第八章中华人民共和国的成立与中国社会主义建设道路的探索", "type": "多选", "number": 96, "stem": "社会主义革命和建设时期，党面临的主要任务是", "options": {"A": "实现从新民主主义到社会主义的转变", "B": "进行社会主义革命", "C": "推进社会主义建设", "D": "为实现中华民族伟大复兴奠定根本政治前提和制度基础"}, "answer": ["A", "B", "C", "D"], "note": "社会主义革命和建设时期，党面临的主要任务是：实现从新民主主义到社会主义的转变；进行社会主义革命；推进社会主义建设；为实现中华民族伟大复兴奠定根本政治前提和制度基础", "sourcePages": [149], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-104", "subject": "史纲", "chapter": 8, "chapterTitle": "第八章中华人民共和国的成立与中国社会主义建设道路的探索", "type": "多选", "number": 104, "stem": "20世纪50年代中期，社会主义改造基本完成，标志着", "options": {"A": "社会主义基本制度在我国已经确立", "B": "我国进入了社会主义初级阶段", "C": "我国步入了社会主义改革时期", "D": "我国完成了从新民主主义向社会主义的过渡"}, "answer": ["A", "B", "D"], "note": "社会主义改造基本完成，标志着：社会主义基本制度在我国已经确立；我国进入了社会主义初级阶段；我国完成了从新民主主义向社会主义的过渡", "sourcePages": [150], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-105", "subject": "史纲", "chapter": 8, "chapterTitle": "第八章中华人民共和国的成立与中国社会主义建设道路的探索", "type": "多选", "number": 105, "stem": "中华人民共和国成立、社会主义制度的建立", "options": {"A": "是中国历史上最深刻最伟大的社会变革", "B": "为当代中国一切发展进步奠定了根本政治前提和制度基础", "C": "为中国发展富强、中国人民生活富裕奠定了坚实基础", "D": "实现了中华民族由不断衰落到根本扭转命运、持续走向繁荣富强的伟大飞跃"}, "answer": ["A", "B", "C", "D"], "note": "中华人民共和国成立、社会主义制度的建立：是中国历史上最深刻最伟大的社会变革；为当代中国一切发展进步奠定了根本政治前提和制度基础；为中国发展富强、中国人民生活富裕奠定了坚实基础；实现了中华民族由不断衰落到根本扭转命运、持续走向繁荣富强的伟大飞跃", "sourcePages": [150], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-106", "subject": "史纲", "chapter": 8, "chapterTitle": "第八章中华人民共和国的成立与中国社会主义建设道路的探索", "type": "多选", "number": 106, "stem": "1954年9月，中华人民共和国第一届全国人民代表大会第一次会议通过《中华人民共和国宪法》，标志着人民代表大会制度这一国家根本政治制度正式建立。人民代表大会制度是", "options": {"A": "中国共产党领导中国人民艰辛探索长期奋斗的成果", "B": "从中国土壤中生长起来的全新政治制度", "C": "人类政治制度史上的伟大创造", "D": "实现我国全过程人民民主的重要制度载体"}, "answer": ["A", "B", "C", "D"], "note": "人民代表大会制度是：中国共产党领导中国人民艰辛探索长期奋斗的成果；从中国土壤中生长起来的全新政治制度；人类政治制度史上的伟大创造；实现我国全过程人民民主的重要制度载体", "sourcePages": [150], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-107", "subject": "史纲", "chapter": 8, "chapterTitle": "第八章中华人民共和国的成立与中国社会主义建设道路的探索", "type": "多选", "number": 107, "stem": "1954年9月，中华人民共和国的缔造者们，同经过普选产生的1200多名全国人大代表一道，召开了第一届全国人民代表大会第一次会议，讨论并通过了《中华人民共和国宪法》。《中华人民共和国宪法》", "options": {"A": "巩固了中国人民革命胜利的历史成果和新中国成立以来政治上、经济上的新胜利", "B": "把实际生活中已经发生的重大社会变革用法律的形式肯定下来", "C": "是中国走向社会主义民主和法制建设的一个良好开端", "D": "是中国进入社会主义社会最主要的标志"}, "answer": ["A", "B", "C"], "note": "《中华人民共和国宪法》：巩固了中国人民革命胜利的历史成果和新中国成立以来政治上、经济上的新胜利；把实际生活中已经发生的重大社会变革用法律的形式肯定下来；是中国走向社会主义民主和法制建设的一个良好开端", "sourcePages": [150], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-108", "subject": "史纲", "chapter": 8, "chapterTitle": "第八章中华人民共和国的成立与中国社会主义建设道路的探索", "type": "多选", "number": 108, "stem": "毛泽东提出，处理中国共产党与民主党派的关系，应坚持的方针是", "options": {"A": "长期共存", "B": "互相监督", "C": "肝胆相照", "D": "荣辱与共"}, "answer": ["A", "B"], "note": "处理中国共产党与民主党派的关系，应坚持的方针是：长期共存；互相监督", "sourcePages": [151], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-121", "subject": "史纲", "chapter": 9, "chapterTitle": "第九章改革开放与中国特色社会主义的开创和发展", "type": "单选", "number": 121, "stem": "1978年5月10日，中央党校内部刊物《理论动态》刊登《实践是检验真理的唯一标准》一文。第二天，《光明日报》以特约评论员名义公开发表这篇文章，新华社向全国转发。文章发表后产生强烈反响，引发了关于真理标准问题的大讨论。这场深刻而广泛的马克思主义思想解放运动", "options": {"A": "成为正本清源、拨乱反正和改革开放的思想先导", "B": "重新确立了实事求是的思想路线", "C": "是解放思想、开辟新时期新道路的宣言书", "D": "标志着党在指导思想上的拨乱反正胜利完成"}, "answer": ["A"], "note": "主义思想解放运动：成为正本清源、拨乱反正和改革开放的思想先导", "sourcePages": [133], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-122", "subject": "史纲", "chapter": 9, "chapterTitle": "第九章改革开放与中国特色社会主义的开创和发展", "type": "单选", "number": 122, "stem": "1978年12月，党召开了十一届三中全会。全会果断停止使用“以阶级斗争为纲”的口号，实现党和国家工作重心战略转移，实现了新中国成立以来党的历史上具有深远意义的伟大转折。党的十一届三中全会", "options": {"A": "提出了“建设有中国特色社会主义”的重大命题", "B": "把改革开放和现代化建设推向新阶段", "C": "开启了我国改革开放和社会主义现代化建设新时期", "D": "标志着党在指导思想上的拨乱反正胜利完成"}, "answer": ["C"], "note": "党的十一届三中全会：开启了我国改革开放和社会主义现代化建设新时期", "sourcePages": [133], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-124", "subject": "史纲", "chapter": 9, "chapterTitle": "第九章改革开放与中国特色社会主义的开创和发展", "type": "单选", "number": 124, "stem": "从1979年11月起，在邓小平主持下，中共中央着手起草《关于建国以来党的若干历史问题的决议》。邓小平对《决议》的起草提出了指导原则，其中，最核心的一条是", "options": {"A": "对建国30年来历史上的大事，要进行实事求是的分析", "B": "宜粗不宜细，总结过去是为了引导大家团结一致向前看", "C": "确立毛泽东同志的历史地位，坚持和发展毛泽东思想", "D": "走自己的路，开辟中国特色社会主义道路"}, "answer": ["C"], "note": "邓小平对《关于建国以来党的若干历史问题的决议》的起草提出了指导原则，其中，最核心的一条是：确立毛泽东同志的历史地位，坚持和发展毛泽东思想", "sourcePages": [133], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-125", "subject": "史纲", "chapter": 9, "chapterTitle": "第九章改革开放与中国特色社会主义的开创和发展", "type": "单选", "number": 125, "stem": "《关于建国以来党的若干历史问题的决议》对于新时期我国社会主要矛盾作出正确判断，指出社会主义改造基本完成以后，我国所要解决的主要矛盾是", "options": {"A": "人民日益增长的物质文化需要同落后的社会生产之间的矛盾", "B": "人民对于经济文化迅速发展的需要同当前经济文化不能满足人民需要的状况之间的矛盾", "C": "人民对于建立先进的工业国的要求同落后的农业国的现实之间的矛盾", "D": "人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾"}, "answer": ["A"], "note": "《关于建国以来党的若干历史问题的决议》指出社会主义改造基本完成以后，我国所要解决的主要矛盾是：人民日益增长的物质文化需要同落后的社会生产之间的矛盾", "sourcePages": [133, 134], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-126", "subject": "史纲", "chapter": 9, "chapterTitle": "第九章改革开放与中国特色社会主义的开创和发展", "type": "单选", "number": 126, "stem": "1981年，党的十一届六中全会通过了《关于建国以来党的若干历史问题的决议》，具有深远历史意义。党制定《决议》标志着", "options": {"A": "党重新确立了马克思主义的思想路线、政治路线、组织路线", "B": "党在指导思想上的拨乱反正胜利完成", "C": "新中国成立以来党的历史上具有深远意义的伟大转折的实现", "D": "我国改革开放和社会主义现代化建设新时期的开启"}, "answer": ["B"], "note": "党制定《关于建国以来党的若干历史问题的决议》标志着：党在指导思想上的拨乱反正胜利完成", "sourcePages": [134], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-113", "subject": "史纲", "chapter": 9, "chapterTitle": "第九章改革开放与中国特色社会主义的开创和发展", "type": "多选", "number": 113, "stem": "改革开放和社会主义现代化建设新时期，党面临的主要任务是", "options": {"A": "继续探索中国建设社会主义的正确道路", "B": "解放和发展社会生产力", "C": "使人民摆脱贫困、尽快富裕起来", "D": "为实现中华民族伟大复兴提供充满新的活力的体制保证和快速发展的物质条件"}, "answer": ["A", "B", "C", "D"], "note": "改革开放和社会主义现代化建设新时期，党面临的主要任务是：继续探索中国建设社会主义的正确道路；解放和发展社会生产力；使人民摆脱贫困、尽快富裕起来；为实现中华民族伟大复兴提供充满新的活力的体制保证和快速发展的物质条件", "sourcePages": [151], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-114", "subject": "史纲", "chapter": 9, "chapterTitle": "第九章改革开放与中国特色社会主义的开创和发展", "type": "多选", "number": 114, "stem": "1978年12月，邓小平在为党的十一届三中全会做准备的中央工作会议上发表了《解放思想，实事求是，团结一致向前看》的重要讲话，这个讲话", "options": {"A": "实际上是党的十一届三中全会的主题报告", "B": "是解放思想、开辟新时期新道路的宣言书", "C": "标志着党在指导思想上的拨乱反正胜利完成", "D": "为党的十一届三中全会实现具有划时代意义的伟大转折奠定了重要基础"}, "answer": ["A", "B", "D"], "note": "《解放思想，实事求是，团结一致向前看》的重要讲话：实际上是党的十一届三中全会的主题报告；是解放思想、开辟新时期新道路的宣言书；为党的十一届三中全会实现具有划时代意义的伟大转折奠定了重要基础", "sourcePages": [151, 152], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-115", "subject": "史纲", "chapter": 9, "chapterTitle": "第九章改革开放与中国特色社会主义的开创和发展", "type": "多选", "number": 115, "stem": "1978年12月，党召开十一届三中全会，实现了新中国成立以来党的历史上具有深远意义的伟大转折。党的十一届三中全会", "options": {"A": "重新确立解放思想、实事求是的思想路线", "B": "停止使用“以阶级斗争为纲”的错误提法", "C": "作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策", "D": "成为正本清源、拨乱反正和改革开放的思想先导"}, "answer": ["A", "B", "C"], "note": "党的十一届三中全会：重新确立解放思想、实事求是的思想路线；停止使用“以阶级斗争为纲”的错误提法；作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策", "sourcePages": [152], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-116", "subject": "史纲", "chapter": 9, "chapterTitle": "第九章改革开放与中国特色社会主义的开创和发展", "type": "多选", "number": 116, "stem": "1981年，党的十一届六中全会通过的《关于建国以来党的若干历史问题的决议》，彻底否定了“文化大革命”，对新中国成立以来的重大历史事件和重要历史人物作出了基本结论，科学地评价了毛泽东和毛泽东思想的历史地位，对毛泽东思想的科学体系和活的灵魂（实事求是、群众路线、独立自主）作了概括，强调毛泽东思想是我们党的宝贵的精神财富，它将长期指导我们的行动。《关于建国以来党的若干历史问题的决议》", "options": {"A": "重新确立解放思想、实事求是的思想路线", "B": "明确社会主义改造基本完成以后我国所要解决的主要矛盾", "C": "标志着党在指导思想上的拨乱反正胜利完成", "D": "实质上初步提出了在中国建设什么样的社会主义和怎样建设社会主义的问题"}, "answer": ["B", "C", "D"], "note": "《关于建国以来党的若干历史问题的决议》：明确社会主义改造基本完成以后我国所要解决的主要予盾；标志着党在指导思想上的拨乱反正胜利完成；实质上初步提出了在中国建设什么样的社会主义和怎样建设社会主义的问题", "sourcePages": [152], "answerSource": "配套资料与题目核对"}, {"id": "史纲-多选-118", "subject": "史纲", "chapter": 9, "chapterTitle": "第九章改革开放与中国特色社会主义的开创和发展", "type": "多选", "number": 118, "stem": "1992年1月18日至2月21日，邓小平先后到武昌、深圳、珠海、上海等地视察，发表了一系列重要谈话，即南方谈话。邓小平的南方谈话", "options": {"A": "从理论上深刻回答了长期困扰和束缚人们思想的许多重大问题", "B": "是把改革开放和现代化建设推向新阶段的又一个解放思想、实事求是的宣言书", "C": "对之后召开的党的十四大具有十分重要的指导作用", "D": "开启了我国改革开放和社会主义现代化建设新时期"}, "answer": ["A", "B", "C"], "note": "邓小平的南方谈话：从理论上深刻回答了长期困扰和束缚人们思想的许多重大问题；是把改革开放和现代化建设推向新阶段的又一个解放思想、实事求是的宣言书；对之后召开的党的十四大具有十分重要的指导作用", "sourcePages": [152], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-127", "subject": "史纲", "chapter": 10, "chapterTitle": "第十章中国特色社会主义进入新时代", "type": "单选", "number": 127, "stem": "为了实现中华民族伟大复兴，中国共产党团结带领中国人民，创造了新民主主义革命的伟大成就、社会主义革命和建设的伟大成就、改革开放和社会主义现代化建设的伟大成就、新时代中国特色社会主义的伟大成就。其中，为实现中华民族伟大复兴提供了更为完善的制度保证、更为坚实的物质基础、更为主动的精神力量的是", "options": {"A": "新民主主义革命的伟大成就", "B": "社会主义革命和建设的伟大成就", "C": "改革开放和社会主义现代化建设的伟大成就", "D": "新时代中国特色社会主义的伟大成就"}, "answer": ["D"], "note": "为实现中华民族伟大复兴提供了更为完善的制度保证、更为坚实的物质基础、更为主动的精神力量的是：新时代中国特色社会主义的伟大成就", "sourcePages": [134], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-128", "subject": "史纲", "chapter": 10, "chapterTitle": "第十章中国特色社会主义进入新时代", "type": "单选", "number": 128, "stem": "党的十九大报告提出新时代党的建设总要求，提出要全面推进党的政治建设、思想建设、组织建设、作风建设、纪律建设，其中摆在首位的是", "options": {"A": "政治建设", "B": "思想建设", "C": "组织建设", "D": "作风建设"}, "answer": ["A"], "note": "党的十九大报告提出新时代党的建设总要求，摆在首位的是：政治建设", "sourcePages": [134], "answerSource": "帽子题配套资料"}, {"id": "史纲-单选-129", "subject": "史纲", "chapter": 10, "chapterTitle": "第十章中国特色社会主义进入新时代", "type": "单选", "number": 129, "stem": "2025年是“十四五”规划收官之年。科学制定和接续实施五年规划，是我们党治国理政一条重要经验，也是中国特色社会主义一个重要政治优势。从“一五”到“十四五”，一以贯之的主题是", "options": {"A": "不断提高人民生活水平", "B": "不断壮大我国综合国力", "C": "不断推进中华民族伟大复兴", "D": "把我国建设成为社会主义现代化国家"}, "answer": ["D"], "note": "从“一五”到“十四五”，一以贯之的主题是：把我国建设成为社会主义现代化国家", "sourcePages": [134], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-119", "subject": "史纲", "chapter": 10, "chapterTitle": "第十章中国特色社会主义进入新时代", "type": "多选", "number": 119, "stem": "党的十八大以来，中国特色社会主义进入新时代。党面临的主要任务是", "options": {"A": "实现第一个百年奋斗目标", "B": "开启实现第二个百年奋斗目标新征程", "C": "为实现中华民族伟大复兴提供充满新的活力的体制保证和快速发展的物质条件", "D": "朝着实现中华民族伟大复兴的宏伟目标继续前进"}, "answer": ["A", "B", "D"], "note": "党的十八大以来，中国特色社会主义进入新时代，党面临的主要任务是：实现第一个百年奋斗目标；开启实现第二个百年奋斗目标新征程；朝着实现中华民族伟大复兴的宏伟目标继续前进", "sourcePages": [152], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-120", "subject": "史纲", "chapter": 10, "chapterTitle": "第十章中国特色社会主义进入新时代", "type": "多选", "number": 120, "stem": "党的十九大是在全面建成小康社会决胜阶段、中国特色社会主义进入新时代的关键时期召开的一次十分重要的大会，是一次不忘初心、牢记使命、高举旗帜、团结奋进的大会。党的十九大的主要贡献有", "options": {"A": "确立习近平新时代中国特色社会主义思想的指导地位", "B": "作出中国特色社会主义进入新时代、我国社会主要矛盾发生转化的重大政治论断", "C": "确定决胜全面建成小康社会、开启全面建设社会主义现代化国家新征程的目标", "D": "对新时代推进中国特色社会主义伟大事业和党的建设伟大工程作出全面部署"}, "answer": ["A", "B", "C", "D"], "note": "党的十九大的主要贡献有：确立主席新时代中国特色社会主义思想的指导地位；作出中国特色社会主义进入新时代、我国社会主要矛盾发生转化的重大政治论断；确定决胜全面建成小康社会、开启全面建设社会主义现代化国家新征程的目标；对新时代推进中国特色社会主义伟大事业和党的建设伟大工程作出全面部署", "sourcePages": [152], "answerSource": "配套资料与题目核对"}, {"id": "史纲-多选-121", "subject": "史纲", "chapter": 10, "chapterTitle": "第十章中国特色社会主义进入新时代", "type": "多选", "number": 121, "stem": "党的二十大报告指出，从现在起，中国共产党的中心任务是", "options": {"A": "团结带领全国各族人民全面建成社会主义现代化强国、实现第二个百年奋斗目标", "B": "促进世界和平与发展", "C": "推动构建人类命运共同体", "D": "以中国式现代化全面推进中华民族伟大复兴"}, "answer": ["A", "D"], "note": "党的二十大报告指出，从现在起，中国共产党的中心任务是：团结带领全国各族人民全面建成社会主义现代化强国、实现第二个百年奋斗目标；以中国式现代化全面推进中华民族伟大复兴", "sourcePages": [153], "answerSource": "帽子题配套资料"}, {"id": "史纲-多选-122", "subject": "史纲", "chapter": 10, "chapterTitle": "第十章中国特色社会主义进入新时代", "type": "多选", "number": 122, "stem": "“十四五”时期，我国发展历程极不寻常、极不平凡。面对错综复杂的国际形势和艰巨繁重的国内改革发展稳定任务，以习近平同志为核心的党中央团结带领全党全国各族人民，迎难而上、砥砺前行，经受住世纪疫情严重冲击，有效应对一系列重大风险挑战，推动党和国家事业取得新的重大成就。“十四五”时期我国发展取得的重大成就主要有", "options": {"A": "我国经济实力、科技实力、综合国力跃上新台阶", "B": "人均国内生产总值达到中等发达国家水平", "C": "中国式现代化迈出新的坚实步伐", "D": "第二个百年奋斗目标新征程实现良好开局"}, "answer": ["A", "C", "D"], "note": "“十四五”时期我国发展取得的重大成就主要有：我国经济实力、科技实力、综合国力跃上新台阶；中国式现代化迈出新的坚实步伐；第二个百年奋斗目标新征程实现良好开局", "sourcePages": [153], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-1", "subject": "思修", "chapter": 0, "chapterTitle": "绪论", "type": "单选", "number": 1, "stem": "法律是成文的道德，道德是内心的法律。法律和思想道德的共同点在于", "options": {"A": "都发挥引领和教化作用", "B": "都发挥规范和强制作用", "C": "都提供思想指引和价值基础", "D": "都属于上层建筑的重要组成部分"}, "answer": ["D"], "note": "法律是成文的道德，道德是内心的法律。法律和思想道德的共同点在于：都属于上层建筑的重要组成部分", "sourcePages": [157], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-3", "subject": "思修", "chapter": 0, "chapterTitle": "绪论", "type": "单选", "number": 3, "stem": "道德和法律是维护社会秩序的两种重要手段。下列关于二者关系的说法中，正确的是", "options": {"A": "法律是道德形成的基础，能够为道德规范的制定提供依据", "B": "凡是道德所反对和谴责的行为，必定是法律所制裁的行为", "C": "法律的调节更具有广泛性，能够渗透到道德不能调节的领域", "D": "凡是法律所禁止和制裁的行为，通常也是道德所反对和遣责的行为"}, "answer": ["D"], "note": "道德和法律是维护社会秩序的两种重要手段。下列关于二者关系的说法中，正确的是：凡是法律所禁止和制裁的行为，通常也是道德所反对和遣责的行为", "sourcePages": [157], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-4", "subject": "思修", "chapter": 0, "chapterTitle": "绪论", "type": "多选", "number": 4, "stem": "法律是成文的道德，道德是内心的法律，法律和道德都具有规范社会行为、维护社会秩序的作用。以下既属于道德规范又是法律规范的是", "options": {"A": "爱国主义", "B": "诚实守信", "C": "尊重他人权利", "D": "男女平等"}, "answer": ["A", "B", "C", "D"], "note": "既属于道德规范又是法律规范的是：爱国主义；诚实守信；尊重他人权利；男女平等", "sourcePages": [164], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-4", "subject": "思修", "chapter": 1, "chapterTitle": "第一章领悟人生真谛把握人生方向", "type": "单选", "number": 4, "stem": "人生观是人们关于人生目的、人生态度、人生价值等问题的总观点和总看法。对人的认识，核心在于认识", "options": {"A": "人的本质", "B": "人的属性", "C": "人的行为", "D": "人的阶级关系"}, "answer": ["A"], "note": "对人的认识，核心在于认识：人的本质", "sourcePages": [157], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-5", "subject": "思修", "chapter": 1, "chapterTitle": "第一章领悟人生真谛把握人生方向", "type": "单选", "number": 5, "stem": "人生观主要是通过人生目的、人生态度和人生价值三个方面体现出来的。其中核心是", "options": {"A": "人生目的", "B": "人生态度", "C": "人生价值", "D": "人生意义"}, "answer": ["A"], "note": "人生观主要是通过人生目的、人生态度和人生价值三个方面体现出来的。其中核心是：人生目的", "sourcePages": [157], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-7", "subject": "思修", "chapter": 1, "chapterTitle": "第一章领悟人生真谛把握人生方向", "type": "单选", "number": 7, "stem": "“为掩护战友身负重伤的扫雷英雄”杜富国，“用爱照亮山区女孩人生梦想的教育燃灯者”张桂梅，“为莫高窟研究保护倾尽一生的敦煌女儿”樊锦诗，“60多年深藏功名的战斗英雄”张富清，以及在黄山风景区分别从事环卫保洁和迎客松守护工作的“中国好人”李培生、胡晓春等平凡英雄，他们最可贵的地方就是在平凡的工作中创造了不平凡的业绩。他们的事迹告诉我们，评价人生价值的根本尺度，是看一个人的", "options": {"A": "劳动以及通过劳动对社会和他人作出的贡献", "B": "个人社会地位的高低", "C": "个人成绩的大小", "D": "实践活动是否符合社会发展的客观规律，是否促进了历史的进步"}, "answer": ["D"], "note": "评价人生价值的根本尺度，是看一个人的：实践活动是否符合社会发展的客观规律，是否促进了历史的进步", "sourcePages": [158], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-8", "subject": "思修", "chapter": 1, "chapterTitle": "第一章领悟人生真谛把握人生方向", "type": "单选", "number": 8, "stem": "认识和处理人生问题的重要着眼点和出发点是", "options": {"A": "个人与群众的关系问题", "B": "个人与社会的关系问题", "C": "个人与国家的关系问题", "D": "个人与集体的关系问题"}, "answer": ["B"], "note": "认识和处理人生问题的重要着眼点和出发点是：个人与社会的关系问题", "sourcePages": [158], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-9", "subject": "思修", "chapter": 1, "chapterTitle": "第一章领悟人生真谛把握人生方向", "type": "单选", "number": 9, "stem": "个人与社会的关系，最根本的是", "options": {"A": "人的自然属性与社会属性的关系", "B": "个人需要与社会需要的关系", "C": "享受个人权利与承担社会责任的关系", "D": "个人利益与社会利益的关系"}, "answer": ["D"], "note": "个人与社会的关系，最根本的是：个人利益与社会利益的关系", "sourcePages": [158], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-5", "subject": "思修", "chapter": 1, "chapterTitle": "第一章领悟人生真谛把握人生方向", "type": "多选", "number": 5, "stem": "习近平在湖南大学岳麓书院考察调研时指出，新时代是一个英雄辈出的时代，青年人正逢其时。习近平希望同学们不负青春、不负韶华、不负时代，珍惜时光好好学习，掌握知识本领，树立正确的世界观、人生观、价值观，系好人生第一粒扣子，走好人生道路，为实现中华民族伟大复兴贡献聪明才智。世界观、人生观、价值观是紧密联系在一起的，三者的关系是", "options": {"A": "世界观决定人生观", "B": "价值观对于人生观的形成和发展有重要的引导作用", "C": "世界观从属于人生观", "D": "人生观对世界观的巩固、发展和变化起着重要的作用"}, "answer": ["A", "B", "D"], "note": "世界观、人生观、价值观是紧密联系在一起的，三者的关系是：世界观决定人生观；价值观对于人生观的形成和发展有重要的引导作用；人生观对世界观的巩固、发展和变化起着重要的作用", "sourcePages": [164], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-6", "subject": "思修", "chapter": 1, "chapterTitle": "第一章领悟人生真谛把握人生方向", "type": "多选", "number": 6, "stem": "人生目的是人生观的核心，这是因为", "options": {"A": "人生目的决定人生道路", "B": "人生目的决定人生态度", "C": "人生目的决定人生价值选择", "D": "人生目的决定人的本质"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [164], "answerSource": "待核对"}, {"id": "思修-多选-10", "subject": "思修", "chapter": 1, "chapterTitle": "第一章领悟人生真谛把握人生方向", "type": "多选", "number": 10, "stem": "近年来，一些地方政府出于社会利益考虑，准备在某些地点设立垃圾场、核电厂、殡仪馆等设施，这往往引起当地居民或单位的不满，滋生“不要建在我家后院”的心理。“邻避效应”涉及个人与社会的关系问题。个人与社会的关系，最根本的是个人利益与社会利益的关系。社会利益是", "options": {"A": "社会发展的根本目标", "B": "作为社会成员的个人的根本利益和长远利益的体现", "C": "个人利益得以实现的前提和基础", "D": "所有人利益的有机统一"}, "answer": ["B", "C", "D"], "note": "社会利益是：作为社会成员的个人的根本利益和长远利益的体现；个人利益得以实现的前提和基础；所有人利益的有机统一", "sourcePages": [165], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-11", "subject": "思修", "chapter": 2, "chapterTitle": "第二章追求远大理想坚定崇高信念", "type": "单选", "number": 11, "stem": "理想是多方面和多类型的。从主体上划分，理想有", "options": {"A": "政治理想和道德理想", "B": "个人理想和社会理想", "C": "近期理想和远期理想", "D": "职业理想和生活理想"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [158], "answerSource": "待核对"}, {"id": "思修-单选-12", "subject": "思修", "chapter": 2, "chapterTitle": "第二章追求远大理想坚定崇高信念", "type": "单选", "number": 12, "stem": "走向绞刑架的李大钊，发出了“共产主义在中国必然得到光辉的胜利”的坚贞誓言。面对敌人屠刀的夏明翰，写下“砍头不要紧，只要主义真。杀了夏明翰，还有后来人”的雄壮诗篇。面对敌人6天内9次劝降，瞿秋白作出了“人爱自己的历史，比鸟爱自己的翅膀更厉害，请勿撕破我的历史”的铿锵回答。理想信念是精神之“钙”。信念是认知、情感和意志的有机统一体。信念的特征包括\n\n①超越性\n\n②支撑性\n\n③执着性\n\n④多样性", "options": {"A": "①②③", "B": "①②④", "C": "②③④", "D": "①③④"}, "answer": ["C"], "note": "信念的特征包括：支撑性、执着性、多样性", "sourcePages": [158], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-17", "subject": "思修", "chapter": 2, "chapterTitle": "第二章追求远大理想坚定崇高信念", "type": "多选", "number": 17, "stem": "习近平总书记在上海瞻仰中共一大代表群像浮雕时，曾对着浮雕一一列数中共一大13名代表的姓名，感叹英雄辈出，也感叹大浪淘沙。个人坚守理想信念力量的强弱决定着人生命运的方向。理想信念的作用和意义在于", "options": {"A": "昭示奋斗目标", "B": "催生前进动力", "C": "提供精神支柱", "D": "提高精神境界"}, "answer": ["A", "B", "C", "D"], "note": "理想信念的作用和意义在于：照示奋斗目标；催生前进动力；提供精神支柱；提高精神境界", "sourcePages": [166], "answerSource": "配套资料与题目核对"}, {"id": "思修-多选-18", "subject": "思修", "chapter": 2, "chapterTitle": "第二章追求远大理想坚定崇高信念", "type": "多选", "number": 18, "stem": "在追求理想的过程中，人们常常会感受到理想与现实之间的矛盾。因此，正确认识理想与现实的关系，是追求理想的过程中必须解决的问题。理想与现实的关系是", "options": {"A": "理想与现实之间的矛盾与冲突属于“应然”和“实然”的矛盾", "B": "理想受现实的规定和制约，是在对现实认识的基础上发展起来的", "C": "现实中包含着理想的因素，理想中也包含着现实", "D": "在一定条件下，理想可以转化为未来的现实"}, "answer": ["A", "B", "C", "D"], "note": "理想与现实的关系是：理想与现实之间的矛盾与冲突属于“应然”和“实然”的矛盾；理想受现实的规定和制约，是在对现实认识的基础上发展起来的；现实中包含着理想的因素，理想中也包含着现实；在一定条件下，理想可以转化为未来的现实", "sourcePages": [166], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-15", "subject": "思修", "chapter": 3, "chapterTitle": "第三章继承优良传统弘扬中国精神", "type": "单选", "number": 15, "stem": "孙中山先生说，做人最大的事情，“就是要知道怎么样爱国”。习近平指出：“爱国，是人世间最深沉、最持久的情感，是一个人立德之源、立功之本。”“气节也好，人格也好，爱国是第一位的。”检验一个人对祖国忠诚程度的试金石是", "options": {"A": "对民族利益共同体的自觉认同", "B": "对祖国大好河山的热爱程度", "C": "对祖国灿烂文化的认同程度", "D": "对民族优良传统的熟悉程度"}, "answer": ["A"], "note": "检验一个人对祖国忠诚程度的试金石是：对民族利益共同体的自觉认同", "sourcePages": [159], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-16", "subject": "思修", "chapter": 3, "chapterTitle": "第三章继承优良传统弘扬中国精神", "type": "单选", "number": 16, "stem": "爱国主义是具体的、现实的。当代中国爱国主义精神最重要的体现是", "options": {"A": "维护祖国统一和民族团结", "B": "坚持爱国和爱党、爱社会主义相统一", "C": "尊重和传承中华民族历史文化", "D": "坚持立足中国又面向世界"}, "answer": ["B"], "note": "当代中国爱国主义精神最重要的体现是：坚持爱国和爱党、爱社会主义相统一", "sourcePages": [159], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-17", "subject": "思修", "chapter": 3, "chapterTitle": "第三章继承优良传统弘扬中国精神", "type": "单选", "number": 17, "stem": "1935年，在中华民族危急存亡之际，著名教育家张伯苓在南开大学开学典礼上问了三个问题：“你是中国人吗？你爱中国吗？你愿意中国好吗？”振奋了师生爱国斗志。习近平强调，这三个问题是历史之问，更是时代之问、未来之问，我们要一代一代问下去、答下去！新时代爱国主义教育的鲜明主题是", "options": {"A": "全面建成社会主义现代化强国、实现中华民族伟大复兴", "B": "维护祖国统一和民族团结", "C": "广泛开展党史、国史、改革开放史教育", "D": "大力弘扬民族精神和时代精神"}, "answer": ["A"], "note": "新时代爱国主义教育的鲜明主题是：全面建成社会主义现代化强国、实现中华民族伟大复兴", "sourcePages": [159], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-18", "subject": "思修", "chapter": 3, "chapterTitle": "第三章继承优良传统弘扬中国精神", "type": "单选", "number": 18, "stem": "在5000多年的历史发展进程中，中华民族形成了伟大民族精神。中华民族伟大民族精神的核心是", "options": {"A": "团结统一", "B": "爱国主义", "C": "勤劳勇敢", "D": "自强不息"}, "answer": ["B"], "note": "中华民族伟大民族精神的核心是：爱国主义", "sourcePages": [159], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-21", "subject": "思修", "chapter": 3, "chapterTitle": "第三章继承优良传统弘扬中国精神", "type": "多选", "number": 21, "stem": "中华民族在5000多年的历史进程中，不仅创造出光辉灿烂、享誉世界的中华文明，也塑造出独特的精神气质和精神品格，形成了崇尚精神的优秀传统。中华民族崇尚精神的优秀传统表现为", "options": {"A": "对物质生活与精神生活相互关系的独到理解", "B": "对理想的不解追求", "C": "对品格养成的重视", "D": "对法治精神的推崇"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [167], "answerSource": "待核对"}, {"id": "思修-多选-22", "subject": "思修", "chapter": 3, "chapterTitle": "第三章继承优良传统弘扬中国精神", "type": "多选", "number": 22, "stem": "在几千年的历史进程中，中国人民用勤劳和智慧书写了辉煌的中华历史，也培育铸就了独特的中国精神，为中国发展和人类文明进步提供了强大的精神动力。中国精神的内涵是", "options": {"A": "伟大创造精神", "B": "伟大奋斗精神", "C": "伟大团结精神", "D": "伟大梦想精神"}, "answer": ["A", "B", "C", "D"], "note": "中国精神的内涵是：伟大创造精神；伟大奋斗精神；伟大团结精神；伟大梦想精神", "sourcePages": [167], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-23", "subject": "思修", "chapter": 3, "chapterTitle": "第三章继承优良传统弘扬中国精神", "type": "多选", "number": 23, "stem": "中国精神是兴国强国之魂，是", "options": {"A": "推进复兴伟业的精神支柱", "B": "凝聚中国力量的精神纽带", "C": "激发创新创造的精神动力", "D": "政治文明建设的重要内容"}, "answer": ["A", "B", "C"], "note": "中国精神是兴国强国之魂，是：推进复兴伟业的精神支柱；凝聚中国力量的精神纽带；激发创新创造的精神动力", "sourcePages": [167], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-24", "subject": "思修", "chapter": 3, "chapterTitle": "第三章继承优良传统弘扬中国精神", "type": "多选", "number": 24, "stem": "从“把我们的血肉，筑成我们新的长城”，到“这是英雄的祖国，是我生长的地方”，再到“我和我的祖国，一刻也不能分割”，这些歌声激励着中国人民百折不挠向前进的壮丽征程，也激荡着当代中国强国复兴的澎湃动力。历史的天空里，家国情怀的光芒熠熠生辉；时间的长河中，家国情怀的源流绵绵不断。爱国主义是", "options": {"A": "中华民族的民族心、民族魂", "B": "中华民族最重要的精神财富", "C": "调节个人与祖国之间关系的道德要求、政治原则和法律规范", "D": "中国人民和中华民族维护民族独立和民族尊严的强大精神动力"}, "answer": ["A", "B", "C", "D"], "note": "爱国主义是：中华民族的民族心、民族魂；中华民族最重要的精神财富；调节个人与祖国之间关系的道德要求、政治原则和法律规范；中国人民和中华民族维护民族独立和民族尊严的强大精神动力", "sourcePages": [167], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-26", "subject": "思修", "chapter": 3, "chapterTitle": "第三章继承优良传统弘扬中国精神", "type": "多选", "number": 26, "stem": "爱国主义的基本内涵是", "options": {"A": "爱祖国的大好河山", "B": "爱自己的骨肉同胞", "C": "爱祖国的灿烂文化、爱自己的国家", "D": "爱社会主义"}, "answer": ["A", "B", "C"], "note": "爱国主义的基本内涵是：爱祖国的大好河山；爱自己的骨肉同胞；爱祖国的灿烂文化、爱自己的国家", "sourcePages": [167], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-28", "subject": "思修", "chapter": 3, "chapterTitle": "第三章继承优良传统弘扬中国精神", "type": "多选", "number": 28, "stem": "2023年10月24日，第十四届全国人大常委会第六次会议表决通过了《中华人民共和国爱国主义教育法》，自2024年1月1日起施行。制定该法的目的是加强新时代爱国主义教育，传承和弘扬爱国主义精神，凝聚全面建设社会主义现代化国家、全面推进中华民族伟大复兴的磅礴力量。爱国主义是中华民族精神的核心。中国特色社会主义进入新时代，实现中华民族伟大复兴的中国梦是新时代爱国主义的鲜明主题。大力弘扬新时代爱国主义，必须", "options": {"A": "坚持爱国爱党爱社会主义相统一", "B": "维护祖国统一和民族团结", "C": "尊重和传承中华民族历史文化", "D": "坚持立足中国又面向世界"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [168], "answerSource": "待核对"}, {"id": "思修-多选-29", "subject": "思修", "chapter": 3, "chapterTitle": "第三章继承优良传统弘扬中国精神", "type": "多选", "number": 29, "stem": "近年来，《中国汉字听写大会》《中国诗词大会》《中国成语大会》《经典咏流传》《朗读者》等节目广受欢迎。这类节目符合国情、接地气，从中华历史和优秀传统文化资源中汲取养分，增进了人们对祖国悠久历史、深厚文化的理解和接受，是人们爱国主义情感培育和发展的重要条件。中华优秀传统文化是", "options": {"A": "中华民族精神的核心", "B": "中华民族得以延续的文化基因", "C": "我们在世界文化激荡中站稳脚跟的根基", "D": "中华民族的精神命脉"}, "answer": ["B", "C", "D"], "note": "中华优秀传统文化是：中华民族得以延续的文化基因；我们在世界文化激荡中站稳脚跟的根基；中华民族的精神命脉", "sourcePages": [168], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-19", "subject": "思修", "chapter": 4, "chapterTitle": "第四章明确价值要求践行价值准则", "type": "单选", "number": 19, "stem": "富强、民主、文明、和谐，这一价值追求回答了我们", "options": {"A": "要建设什么样的国家的重大问题", "B": "要建设什么样的社会的重大问题", "C": "要建设什么样的政府的重大问题", "D": "要培育什么样的公民的重大问题"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [159], "answerSource": "待核对"}, {"id": "思修-单选-20", "subject": "思修", "chapter": 4, "chapterTitle": "第四章明确价值要求践行价值准则", "type": "单选", "number": 20, "stem": "自由、平等、公正、法治，这一价值追求回答了我们要建设什么样的社会的重大问题，反映了人们对美好社会的期望和憧憬，是", "options": {"A": "衡量现代社会是否高度发展、充满活力、和谐有序的重要标志", "B": "判断社会性质的主要标准", "C": "社会进步的根本内容", "D": "衡量社会进步的根本尺度"}, "answer": ["A"], "note": "自由、平等、公正、法治，是：衡量现代社会是否高度发展、充满活力、和谐有序的重要标志", "sourcePages": [159], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-22", "subject": "思修", "chapter": 4, "chapterTitle": "第四章明确价值要求践行价值准则", "type": "单选", "number": 22, "stem": "社会主义核心价值观的根本特性是", "options": {"A": "先进性", "B": "人民性", "C": "普适性", "D": "真实性"}, "answer": ["B"], "note": "社会主义核心价值观的根本特性是：人民性", "sourcePages": [159], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-23", "subject": "思修", "chapter": 4, "chapterTitle": "第四章明确价值要求践行价值准则", "type": "单选", "number": 23, "stem": "社会主义核心价值观的先进性集中体现在", "options": {"A": "它是社会主义所坚持和追求的价值理念", "B": "它吸纳了世界文明有益成果", "C": "它是真切、具体、广泛的现实", "D": "它扎根于中华优秀传统文化土壤"}, "answer": ["A"], "note": "社会主义核心价值观的先进性集中体现在：它是社会主义所坚持和追求的价值理念", "sourcePages": [159], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-31", "subject": "思修", "chapter": 4, "chapterTitle": "第四章明确价值要求践行价值准则", "type": "多选", "number": 31, "stem": "人类社会发展的历史表明，对一个民族、一个国家来说，最持久、最深沉的力量是全社会共同认可的核心价值观。核心价值观", "options": {"A": "承载着一个民族、一个国家的精神追求", "B": "体现着一个社会评判是非曲直的价值标准", "C": "是一定社会形态、社会性质的集中体现，在整个上层建筑中处于主导地位", "D": "体现着社会制度的阶级属性、社会运行的基本原则和社会发展的基本方向"}, "answer": ["A", "B", "D"], "note": "核心价值观：：承载着一个民族、一个国家的精神追求；体现着一个社会评判是非曲直的价值标准；体现着社会制度的阶级属性、社会运行的基本原则和社会发展的基本方向", "sourcePages": [168], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-32", "subject": "思修", "chapter": 4, "chapterTitle": "第四章明确价值要求践行价值准则", "type": "多选", "number": 32, "stem": "社会主义核心价值观", "options": {"A": "是当代中国精神的集中体现", "B": "凝结着全体人民共同的价值追求", "C": "集中体现社会主义的本质属性", "D": "是整个上层建筑的核心"}, "answer": ["A", "B", "C"], "note": "社会主义核心价值观：是当代中国精神的集中体现；凝结着全体人民共同的价值追求；集中体现社会主义的本质属性", "sourcePages": [168], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-34", "subject": "思修", "chapter": 4, "chapterTitle": "第四章明确价值要求践行价值准则", "type": "多选", "number": 34, "stem": "国家艺术基金资助项目、新编历史晋剧《日昇昌票号》里有这样的情节：当饥寒交迫的魏老太拿着被水浸过的汇票来兑银子，伙计难辨数额怎么办？日昇昌票号大掌柜雷履泰责人详查账目底簿，当机立断，兑！当伙计忽略差价少给客商兑了七两八钱银子怎么办？雷履泰斩钉截铁，补齐！正是靠着这种诚信精神，日昇昌票号实现了分号遍布全国几十个城市、商埠重镇，以“汇通天下”著称于世。诚信是社会主义核心价值观的重要内容，是", "options": {"A": "个人立身处世的基本价值规范", "B": "社会存续发展的重要价值基石", "C": "社会主义职业道德的基本规范之一", "D": "中华传统美德的根本要求"}, "answer": ["A", "B", "C"], "note": "诚信是社会主义核心价值观的重要内容，是：个人立身处世的基本价值规范；社会存续发展的重要价值基石；社会主义职业道德的规范之一", "sourcePages": [169], "answerSource": "配套资料与题目核对"}, {"id": "思修-多选-36", "subject": "思修", "chapter": 4, "chapterTitle": "第四章明确价值要求践行价值准则", "type": "多选", "number": 36, "stem": "爱国、敬业、诚信、友善，这一价值追求回答了我们要培育什么样的公民的重大问题，是每一个公民都应当遵守的价值规范。爱国、敬业、诚信、友善，涵盖了", "options": {"A": "社会公德", "B": "职业道德", "C": "家庭美德", "D": "个人品德"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [169], "answerSource": "待核对"}, {"id": "思修-多选-37", "subject": "思修", "chapter": 4, "chapterTitle": "第四章明确价值要求践行价值准则", "type": "多选", "number": 37, "stem": "真理的力量加上道义的力量，才能行之久远。社会主义核心价值观站在人类道义制高点，彰显出独特而强大的价值观优势。因为社会主义核心价值观具有", "options": {"A": "先进性", "B": "人民性", "C": "普适性", "D": "真实性"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [169], "answerSource": "待核对"}, {"id": "思修-多选-38", "subject": "思修", "chapter": 4, "chapterTitle": "第四章明确价值要求践行价值准则", "type": "多选", "number": 38, "stem": "社会主义核心价值观具有超越以往一切社会核心价值观的先进性。社会主义核心价值观", "options": {"A": "体现社会主义的本质属性", "B": "扎根中华优秀传统文化土壤", "C": "吸纳世界文明有益成果", "D": "是反映人类社会发展进步的价值理念"}, "answer": ["A", "B", "C", "D"], "note": "社会主义核心价值观体现社会主义的本质属性，扎根中华优秀传统文化土壤，吸纳世界文明有益成果，是反映人类社会发展进步的价值理念。", "sourcePages": [169], "answerSource": "配套资料与题目核对"}, {"id": "思修-单选-24", "subject": "思修", "chapter": 5, "chapterTitle": "第五章遵守道德规范锤炼道德品格", "type": "单选", "number": 24, "stem": "道德属于上层建筑的范畴，是一种特殊的社会意识形态。作为人类社会特有的一种社会现象，道德是人类社会发展到一定阶段的必然产物。道德起源的第一个历史前提是", "options": {"A": "意识", "B": "劳动", "C": "情感欲望", "D": "动物本能"}, "answer": ["B"], "note": "道德起源的第一个历史前提是：劳动", "sourcePages": [160], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-25", "subject": "思修", "chapter": 5, "chapterTitle": "第五章遵守道德规范锤炼道德品格", "type": "单选", "number": 25, "stem": "恩格斯说：“人们自觉地或不自觉地，归根到底总是从他们阶级地位所依据的实际关系中一从他们进行生产和交换的经济关系中，获得自已的伦理观念。”这说明，道德的产生、发展和变化，归根结底源于", "options": {"A": "社会意识形态", "B": "社会经济关系", "C": "社会存在", "D": "社会的阶级关系"}, "answer": ["B"], "note": "道德的产生、发展和变化，归根结底源于：社会经济关系", "sourcePages": [160], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-27", "subject": "思修", "chapter": 5, "chapterTitle": "第五章遵守道德规范锤炼道德品格", "type": "单选", "number": 27, "stem": "道德调节的主要形式是", "options": {"A": "道德评价", "B": "社会舆论", "C": "传统习俗", "D": "内心信念"}, "answer": ["A"], "note": "道德调节的主要形式是：道德评价", "sourcePages": [160], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-28", "subject": "思修", "chapter": 5, "chapterTitle": "第五章遵守道德规范锤炼道德品格", "type": "单选", "number": 28, "stem": "道德发挥作用的性质是由", "options": {"A": "社会发展的历史阶段决定的", "B": "道德所反映的经济基础、代表的阶级利益决定的", "C": "道德的性质决定的", "D": "上层建筑的性质决定的"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [160], "answerSource": "待核对"}, {"id": "思修-单选-29", "subject": "思修", "chapter": 5, "chapterTitle": "第五章遵守道德规范锤炼道德品格", "type": "单选", "number": 29, "stem": "集体主义可以增强一个人恪尽职守、担当任事的责任心，可以激发一个人面对困难和危险不退缩的战斗力，赋予一个人光辉的人格、英雄的风范。集体主义最高层次的道德要求是", "options": {"A": "先公后私、先人后己", "B": "顾全大局、遵纪守法", "C": "无私奉献、一心为公", "D": "热爱祖国、诚实劳动"}, "answer": ["C"], "note": "集体主义最高层次的道德要求是：无私奉献、一心为公", "sourcePages": [160], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-30", "subject": "思修", "chapter": 5, "chapterTitle": "第五章遵守道德规范锤炼道德品格", "type": "单选", "number": 30, "stem": "中华传统美德的根本要求是", "options": {"A": "以和为贵", "B": "注重人伦关系", "C": "追求精神境界，向往理想人格", "D": "公义胜私欲"}, "answer": ["D"], "note": "中华传统美德的根本要求是：公义胜私欲", "sourcePages": [160], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-31", "subject": "思修", "chapter": 5, "chapterTitle": "第五章遵守道德规范锤炼道德品格", "type": "单选", "number": 31, "stem": "中国革命道德是指中国共产党人、人民军队、一切先进分子和人民群众在中国革命、建设、改革中所形成的优秀道德，是马克思主义与中国革命、建设、改革的伟大实践相结合的产物，是中华民族极其宝贵的道德财富。中国革命道德的灵魂是", "options": {"A": "坚持社会主义和共产主义理想信念", "B": "全心全意为人民服务", "C": "始终把革命利益放在首位", "D": "修身自律、保持节操"}, "answer": ["A"], "note": "中国革命道德的灵魂是：坚持社会主义和共产主义理想信念", "sourcePages": [160], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-32", "subject": "思修", "chapter": 5, "chapterTitle": "第五章遵守道德规范锤炼道德品格", "type": "单选", "number": 32, "stem": "记者在采访诺贝尔生理学或医学奖得主、中国女药学家屠呦呦时问她：“你在小鼠和猴子身上测试了青蒿素，证明它是有效的之后，你自己也服了药。你害怕吗？”屠呦呦答：“我们担心药物是否安全。我和两位同事服了药，表明药不会死人。我认为这是我作为药物化学家的责任和工作的一部分。”屠呦呦的回答展现了崇高的社会主义职业道德。社会主义职业道德的最高层次的要求是", "options": {"A": "诚实守信", "B": "办事公道", "C": "热情服务", "D": "奉献社会"}, "answer": ["D"], "note": "社会主义职业道德的最高层次的要求是：奉献社会", "sourcePages": [160], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-35", "subject": "思修", "chapter": 5, "chapterTitle": "第五章遵守道德规范锤炼道德品格", "type": "单选", "number": 35, "stem": "在社会道德建设中具有基础性作用的是", "options": {"A": "社会公德", "B": "职业道德", "C": "家庭美德", "D": "个人品德"}, "answer": ["D"], "note": "在社会道德建设中具有基础性作用的是：个人品德", "sourcePages": [161], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-38", "subject": "思修", "chapter": 5, "chapterTitle": "第五章遵守道德规范锤炼道德品格", "type": "单选", "number": 38, "stem": "志愿服务是社会文明进步的重要标志，是新时代党引导动员人民群众贡献智慧力量、创造美好生活、实现奋斗目标的生动实践。志愿服务精神的精髓是", "options": {"A": "友爱", "B": "互助", "C": "进步", "D": "奉献"}, "answer": ["D"], "note": "志愿服务精神的精髓是：奉献", "sourcePages": [161], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-42", "subject": "思修", "chapter": 5, "chapterTitle": "第五章遵守道德规范锤炼道德品格", "type": "多选", "number": 42, "stem": "作为社会意识的道德一经产生，便有相对独立性。这种相对独立性表现为", "options": {"A": "道德的历史继承性", "B": "道德对社会发展具有能动的反作用", "C": "在阶级社会里道德具有阶级性", "D": "道德随着社会经济关系的变化而变化"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [170], "answerSource": "待核对"}, {"id": "思修-多选-43", "subject": "思修", "chapter": 5, "chapterTitle": "第五章遵守道德规范锤炼道德品格", "type": "多选", "number": 43, "stem": "道德属于上层建筑的范畴，是一种特殊的社会意识形态。道德以善恶为评价方式，发挥作用主要是依靠", "options": {"A": "社会舆论", "B": "传统习俗", "C": "内心信念", "D": "国家强制"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [170], "answerSource": "待核对"}, {"id": "思修-多选-44", "subject": "思修", "chapter": 5, "chapterTitle": "第五章遵守道德规范锤炼道德品格", "type": "多选", "number": 44, "stem": "道德的功能，一般是指道德作为社会意识的特殊形式对于社会发展所具有的功效与作用。在道德的功能系统中，最基本的功能是", "options": {"A": "认识功能", "B": "规范功能", "C": "调节功能", "D": "表达功能"}, "answer": ["A", "B", "C"], "note": "在道德的功能系统中，最基本的功能是：认识功能；规范功能；调节功能", "sourcePages": [170], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-45", "subject": "思修", "chapter": 5, "chapterTitle": "第五章遵守道德规范锤炼道德品格", "type": "多选", "number": 45, "stem": "道德功能的发挥和实现所产生的社会影响及实际效果，就是道德的作用。道德的作用主要表现在", "options": {"A": "巩固特定社会的经济基础和上层建筑", "B": "提高人的精神境界", "C": "促进人的自我完善", "D": "推动人的全面发展"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [170], "answerSource": "待核对"}, {"id": "思修-多选-46", "subject": "思修", "chapter": 5, "chapterTitle": "第五章遵守道德规范锤炼道德品格", "type": "多选", "number": 46, "stem": "道德功能的发挥和实现所产生的社会影响及实际效果，就是道德的作用。道德", "options": {"A": "是维系社会稳定、促进国家发展的重要因素", "B": "是激励人们改造客观世界和主观世界的一种精神力量", "C": "在本质上是知行合一的", "D": "对社会的发展和人的素质的提高总是起着积极的推动作用"}, "answer": ["A", "B", "C"], "note": "道德：是维系社会稳定、促进国家发展的重要因素；是激励人们改造客观世界和主观世界的一种精神力量；在本质上是知行合一的", "sourcePages": [170], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-47", "subject": "思修", "chapter": 5, "chapterTitle": "第五章遵守道德规范锤炼道德品格", "type": "多选", "number": 47, "stem": "与以往社会的道德形态相比，社会主义道德具有显著的先进性特征。这种先进性主要体现在，社会主义道德", "options": {"A": "是社会主义经济基础的反映", "B": "是对人类优秀道德资源的批判继承和创新发展", "C": "克服了以往阶级社会道德的片面性和局限性", "D": "是调节社会一切行为规范的准则"}, "answer": ["A", "B", "C"], "note": "社会主义道德：是社会主义经济基础的反映；是对人类优秀道德资源的批判继承和创新发展；克服了以往阶级社会道德的片面性和局限性", "sourcePages": [170], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-48", "subject": "思修", "chapter": 5, "chapterTitle": "第五章遵守道德规范锤炼道德品格", "type": "多选", "number": 48, "stem": "1949年春，毛泽东在宴请九三学社的朋友时说，“我和各位都是新中国的‘长工’，我们的主人是谁呢？不是地主老财或资本家，而是人民，四万万五千万中国人民，我们要全心全意为他们服务！”全心全意为人民服务是", "options": {"A": "贯穿中国革命道德始终的一根红线", "B": "社会主义道德观的集中体现", "C": "社会主义道德的原则", "D": "先进性要求和广泛性要求的统一"}, "answer": ["A", "B", "D"], "note": "全心全意为人民服务是：贯穿中国革命道德始终的一根红线；社会主义道德观的集中体现；先进性要求和广泛性要求的统一", "sourcePages": [170], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-50", "subject": "思修", "chapter": 5, "chapterTitle": "第五章遵守道德规范锤炼道德品格", "type": "多选", "number": 50, "stem": "根据我国现阶段经济社会生活和人们思想道德的实际，对公民最基本的集体主义的道德要求是", "options": {"A": "无私奉献、一心为公", "B": "先公后私、先人后己", "C": "顾全大局、遵纪守法", "D": "热爱祖国、诚实劳动"}, "answer": ["C", "D"], "note": "根据我国现阶段经济社会生活和人们思想道德的实际，对公民最基本的集体主义的道德要求是：顾全大局、遵纪守法；热爱祖国、诚实劳动", "sourcePages": [170], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-51", "subject": "思修", "chapter": 5, "chapterTitle": "第五章遵守道德规范锤炼道德品格", "type": "多选", "number": 51, "stem": "加强社会主义道德建设必须吸收借鉴优秀道德成果，传承中华传统美德。中华传统美德", "options": {"A": "是中华文化的精髓", "B": "蕴含着丰富的思想道德资源", "C": "是社会主义道德建设的源头活水", "D": "是人类文明发展的重要精神财富"}, "answer": ["A", "B", "C", "D"], "note": "中华传统美德：是中华文化的精髓；蕴含着丰富的思想道德资源；是社会主义道德建设的源头活水；是人类文明发展的重要精神财富", "sourcePages": [170], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-55", "subject": "思修", "chapter": 5, "chapterTitle": "第五章遵守道德规范锤炼道德品格", "type": "多选", "number": 55, "stem": "中国特色社会主义进入新时代，加强公民道德建设、提高全社会道德水平，具有十分重要的意义。新时代加强公民道德建设，作为着力点的是", "options": {"A": "社会公德建设", "B": "职业道德建设", "C": "家庭美德建设", "D": "个人品德建设"}, "answer": ["A", "B", "C", "D"], "note": "新时代加强公民道德建设，作为着力点的是：社会公德建设；职业道德建设；家庭美德建设；个人品德建设", "sourcePages": [171], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-56", "subject": "思修", "chapter": 5, "chapterTitle": "第五章遵守道德规范锤炼道德品格", "type": "多选", "number": 56, "stem": "新时代公民道德建设的重点任务是", "options": {"A": "筑牢理想信念之基", "B": "培育和践行社会主义核心价值观", "C": "传承中华传统美德", "D": "弘扬民族精神和时代精神"}, "answer": ["A", "B", "C", "D"], "note": "新时代公民道德建设的重点任务是：筑牢理想信念之基；培育和践行社会主义核心价值观；传承中华传统美德；弘扬民族精神和时代精神", "sourcePages": [171], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-57", "subject": "思修", "chapter": 5, "chapterTitle": "第五章遵守道德规范锤炼道德品格", "type": "多选", "number": 57, "stem": "当代公共生活的特征主要表现在", "options": {"A": "活动范围的广泛性", "B": "活动内容的开放性", "C": "交往对象的复杂性", "D": "活动方式的多样性"}, "answer": ["A", "B", "C", "D"], "note": "当代公共生活的特征主要表现在：活动范围的广泛性；活动内容的开放性；交往对象的复杂性；活动方式的多样性", "sourcePages": [171], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-58", "subject": "思修", "chapter": 5, "chapterTitle": "第五章遵守道德规范锤炼道德品格", "type": "多选", "number": 58, "stem": "网络空间同现实社会一样，既要提倡自由，也要保持秩序。公共生活需要公共秩序，有序的公共生活是", "options": {"A": "调整和规范人际关系的行为准则", "B": "社会生产活动的重要基础", "C": "提高社会成员生活质量的基本保障", "D": "社会文明的重要标志"}, "answer": ["B", "C", "D"], "note": "公共生活需要公共秩序，有序的公共生活是：社会生产活动的重要基础；提高社会成员生活质量的基本保障；社会文明的重要标志", "sourcePages": [171], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-61", "subject": "思修", "chapter": 5, "chapterTitle": "第五章遵守道德规范锤炼道德品格", "type": "多选", "number": 61, "stem": "“人与人交往在于言而有信，国与国相处讲究诚信为本。”诚实守信在我国思想道德建设中具有特殊重要的作用。诚实守信是", "options": {"A": "中华民族的传统美德", "B": "我国公民道德建设的重点", "C": "社会主义道德的核心", "D": "社会主义核心价值观的一条重要准则"}, "answer": ["A", "B", "D"], "note": "诚实守信是：中华民族的传统美德：我国公民道德建设的重点；社会主义核心价值观的一条重要准则", "sourcePages": [172], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-62", "subject": "思修", "chapter": 5, "chapterTitle": "第五章遵守道德规范锤炼道德品格", "type": "多选", "number": 62, "stem": "职业道德中的诚实守信，要求从业者在职业活动中", "options": {"A": "诚实劳动", "B": "合法经营", "C": "信守承诺", "D": "讲求信誉"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [172], "answerSource": "待核对"}, {"id": "思修-多选-64", "subject": "思修", "chapter": 5, "chapterTitle": "第五章遵守道德规范锤炼道德品格", "type": "多选", "number": 64, "stem": "为深入学习贯彻习近平总书记关于注重家庭家教家风建设的重要论述，中央宣传部、全国妇联于2026年5月向全社会发布2026年“最美家庭”，10户家庭光荣入选2026年“最美家庭”。家是最小国，国是千万家，家庭的命运同国家和民族的前途命运紧密相连，要以“最美家庭”为榜样，大力弘扬社会主义家庭文明新风尚。社会主义家庭文明新风尚的内容是", "options": {"A": "爱国爱家", "B": "相亲相爱", "C": "向上向善", "D": "共建共享"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [172], "answerSource": "待核对"}, {"id": "思修-单选-39", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "单选", "number": 39, "stem": "法律规范区别于道德规范、纪律规范等其他社会规范的一个重要特征是", "options": {"A": "法律规范具有国家强制性", "B": "法律是统治阶级意志的体现", "C": "法律由社会物质生活条件决定", "D": "法律所体现的统治阶级意志是统治阶级意志的全部"}, "answer": ["A"], "note": "法律规范区别于道德规范、纪律规范等其他社会规范的一个重要特征是：法律规范具有国家强制性", "sourcePages": [161], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-40", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "单选", "number": 40, "stem": "决定法律本质、内容和发展方向的根本因素是", "options": {"A": "生产方式", "B": "生产力的发展水平", "C": "文化的发展程度", "D": "人的素质"}, "answer": ["A"], "note": "决定法律本质、内容和发展方向的根本因素是：生产方式", "sourcePages": [161], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-41", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "单选", "number": 41, "stem": "法律的运行是一个从创制、实施到实现的过程。这个过程主要包括法律制定（立法）、法律执行（执法）、法律适用（司法）、法律遵守（守法）等环节。法律实施和实现的基本途径是", "options": {"A": "法律制定", "B": "法律遵守", "C": "法律执行", "D": "法律适用"}, "answer": ["B"], "note": "法律实施和实现的基本途径是：法律遵守", "sourcePages": [161], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-42", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "单选", "number": 42, "stem": "法律运行的关键性（起始性）环节是", "options": {"A": "法律制定", "B": "法律遵守", "C": "法律执行", "D": "法律适用"}, "answer": ["A"], "note": "法律运行的关键性（起始性）环节是：法律制定", "sourcePages": [161], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-43", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "单选", "number": 43, "stem": "国家司法机关及其公职人员依照法定职权和程序适用法律处理案件的专门活动，称为", "options": {"A": "法律执行", "B": "法律制裁", "C": "法律遵守", "D": "法律适用"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [161], "answerSource": "待核对"}, {"id": "思修-单选-44", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "单选", "number": 44, "stem": "法律的实施包括法律适用和法律执行。其中，狭义上的法律执行的主体是", "options": {"A": "国家司法机关及其公职人员", "B": "国家行政机关及其公职人员", "C": "国家立法机关及其公职人员", "D": "社会团体及其公职人员"}, "answer": ["B"], "note": "狭义上的法律执行的主体是：国家行政机关及其公职人员", "sourcePages": [161], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-45", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "单选", "number": 45, "stem": "推进全面依法治国的根本保证是", "options": {"A": "党的领导", "B": "中国特色社会主义制度", "C": "中国特色社会主义法治理论", "D": "依宪治国、依宪执政"}, "answer": ["A"], "note": "推进全面依法治国的根本保证是党的领导。", "sourcePages": [161], "answerSource": "配套资料与题目核对"}, {"id": "思修-单选-46", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "单选", "number": 46, "stem": "我国的法治同西方资本主义国家的法治最大的区别是", "options": {"A": "坚持党的领导", "B": "坚持以人民为中心", "C": "坚持中国特色社会主义制度", "D": "坚持中国特色社会主义法治理论"}, "answer": ["A"], "note": "我国的法治同西方资本主义国家的法治最大的区别是：坚持党的领导", "sourcePages": [161], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-47", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "单选", "number": 47, "stem": "全面推进依法治国是一个系统工程，是国家治理领域一场广泛而深刻的革命，涉及立法、执法、司法、守法等各个方面，在实际工作中必须有一个总揽全局、牵引各方的总抓手。全面依法治国的总抓手是", "options": {"A": "坚持科学立法、严格执法、公正司法、全民守法", "B": "保障和促进社会公平正义", "C": "建设中国特色社会主义法治体系", "D": "坚持依法治国和以德治国相结合"}, "answer": ["C"], "note": "建设中国特色社会主义法治体系，是全面推进依法治国的总抓手。", "sourcePages": [162], "answerSource": "配套资料与题目核对"}, {"id": "思修-单选-48", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "单选", "number": 48, "stem": "建设中国特色社会主义法治体系，就是在中国共产党领导下，坚持中国特色社会主义制度，贯彻中国特色社会主义法治理论，形成完备的法律规范体系、高效的法治实施体系、严密的法治监督体系、有力的法治保障体系，形成完善的党内法规体系。其中，建设中国特色社会主义法治体系的重点是建设", "options": {"A": "完备的法律规范体系", "B": "高效的法治实施体系", "C": "有力的法治保障体系", "D": "严密的法治监督体系"}, "answer": ["B"], "note": "建设中国特色社会主义法治体系的重点是建设：高效的法治实施体系", "sourcePages": [162], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-49", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "单选", "number": 49, "stem": "全面依法治国是国家治理的一场深刻革命，关系党执政兴国，关系人民幸福安康，关系党和国家长治久安。推进全面依法治国，根本目的是", "options": {"A": "依法保障人民权益", "B": "加强党对国家的全面领导", "C": "建设法治国家", "D": "保证法律面前人人平等"}, "answer": ["A"], "note": "推进全面依法治国，休根本目的是：依法保障人民权益", "sourcePages": [162], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-50", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "单选", "number": 50, "stem": "全面依法治国是一个系统工程，要整体谋划，更加注重系统性、整体性、协同性。推进全面依法治国，要坚持依法治国、依法执政、依法行政共同推进，坚持法治国家、法治政府、法治社会一体建设。其中，构筑法治国家的基础是", "options": {"A": "法治政府", "B": "依法执政", "C": "法治社会", "D": "依法行政"}, "answer": ["C"], "note": "构筑法治国家的基础是：法治社会", "sourcePages": [162], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-51", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "单选", "number": 51, "stem": "支持重大改革、护航国家发展，新时代我国立法更具针对性、有效性、可操作性。制定国家安全法、香港国安法、网络安全法等，坚决维护国家安全与核心利益，以宪法为统帅的中国特色社会主义法律体系不断完善。立法是", "options": {"A": "法治的龙头环节", "B": "法治的生命线", "C": "治国理政的基本方式", "D": "法律实施和实现的基本途径和重要环节"}, "answer": ["A"], "note": "立法是：法治的龙头环节", "sourcePages": [162], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-52", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "单选", "number": 52, "stem": "习近平曾指出，要懂得“100-1=0”的道理。一个错案的负面影响，足以摧毁九十九个公平裁判积累起来的良好形象。执法司法中万分之一的失误，对当事人就是百分之百的伤害。这说明了公正司法的重要性。公正司法是", "options": {"A": "法治社会的基础工程", "B": "法治的龙头环节", "C": "维护社会公平正义的最后一道防线", "D": "维护社会公平正义的决定因素"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [162], "answerSource": "待核对"}, {"id": "思修-单选-54", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "单选", "number": 54, "stem": "习近平指出，党纪国法不能成为“橡皮泥”“稻草人”，无论是因为“法盲”导致违纪违法，还是故意违规违法，都要受到追究，否则就会形成“破窗效应”。任何人不论权力大小、职位高低，只要有违法犯罪行为，就要受到法律制裁，这体现的是法律的", "options": {"A": "普遍适用", "B": "优先适用", "C": "不可违反", "D": "阶级属性"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [162], "answerSource": "待核对"}, {"id": "思修-单选-55", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "单选", "number": 55, "stem": "所有国家机关、社会组织和公民个人都必须遵守法律，依法享有和行使法定职权与权利，承担和履行法定职责与义务，这体现的是法律的", "options": {"A": "不可违反", "B": "优先适用", "C": "权力制约", "D": "普遍适用"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [162], "answerSource": "待核对"}, {"id": "思修-单选-57", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "单选", "number": 57, "stem": "《中华人民共和国民法典》是新中国成立以来第一部以“法典”命名的法律，被誉为“保障民事权利的宣言书”。权利保障主要是指对公民权利的法律保障，具体包括公民权利的宪法保障、立法保障、行政保障和司法保障。权利保障的关键环节是", "options": {"A": "宪法保障", "B": "立法保障", "C": "行政保障", "D": "司法保障"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [163], "answerSource": "待核对"}, {"id": "思修-单选-60", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "单选", "number": 60, "stem": "马克思主义权利观与其他权利观的根本区别在于", "options": {"A": "强调社会的物质生活条件对权利的制约和决定作用", "B": "强调公民的权利和义务是平等的", "C": "强调公民的权利和义务是统一的", "D": "强调权利和义务关系是社会关系的核心部分"}, "answer": ["A"], "note": "马克思主义权利观与其他权利观的根本区别在于：强调社会的物质生活条件对权利的制约和决定作用", "sourcePages": [163], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-61", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "单选", "number": 61, "stem": "法律权利是指由一定的社会物质生活条件所制约的行为自由，是法律所允许的权利人为了满足自己的利益而采取的、由其他人的法律义务所保障的法律手段。法律权利区别于其他权利的根本所在是", "options": {"A": "受社会物质生活条件的制约", "B": "由国家强制力保障其实现", "C": "源于现实需要", "D": "随着历史的发展变化而变化"}, "answer": ["B"], "note": "法律权利区别于其他权利的根本所在是：由国家强制力保障其实现", "sourcePages": [163], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-63", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "单选", "number": 63, "stem": "我国宪法法律规定了公民享有一系列权利，主要包括政治权利、宗教信仰自由、人身权利、财产权利、社会经济权利及文化教育权利等。公民参加国家政治、经济与社会生活的基础是", "options": {"A": "表达权利", "B": "人身权利", "C": "社会经济权利", "D": "文化教育权利"}, "answer": ["B"], "note": "公民参加国家政治、经济与社会生活的基础是：人身权利", "sourcePages": [163], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-64", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "单选", "number": 64, "stem": "我国宪法法律规定了公民享有一系列权利，主要包括政治权利、宗教信仰自由、人身权利、财产权利、社会经济权利及文化教育权利等。人们一切行动和生活的前提条件是", "options": {"A": "健康权", "B": "人格尊严", "C": "人身自由", "D": "言论自由"}, "answer": ["C"], "note": "人们一切行动和生活的前提条件是：人身自由", "sourcePages": [163], "answerSource": "帽子题配套资料"}, {"id": "思修-单选-65", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "单选", "number": 65, "stem": "我国宪法法律规定了公民享有一系列权利。人享有其他各项权利的前提是", "options": {"A": "生命权", "B": "健康权", "C": "人身自由权", "D": "人格尊严权"}, "answer": ["A"], "note": "人享有其他各项权利的前提是：生命权", "sourcePages": [163], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-66", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "多选", "number": 66, "stem": "法律是由国家创制和实施的行为规范。法律不但由国家制定和认可，而且由国家强制力保证实施。也就是说，法律具有国家强制性。法律的国家强制性表现为", "options": {"A": "国家对违法行为的否定和制裁", "B": "国家对合法行为的肯定和保护", "C": "法律的每一个实施过程都要借助于国家的强制力", "D": "国家强制力是保证法律实施的唯一力量"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [172], "answerSource": "待核对"}, {"id": "思修-多选-67", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "多选", "number": 67, "stem": "2026年3月，《生态环境法典（草案）》提请十四届全国人大四次会议审议并获得通过。这是《民法典》之后我国第二部以“法典”命名的法律，将为美丽中国建设提供坚实法治保障。我国社会主义法律", "options": {"A": "体现了党的主张和人民意志的统一", "B": "具有科学性和先进性", "C": "是中国特色社会主义建设的重要保障", "D": "具有比发达国家法律体系更高的成熟性"}, "answer": ["A", "B", "C"], "note": "我国社会主义法律：体现了党的主张和人民意志的统一；具有科学性和先进性；是中国特色社会主义建设的重要保障", "sourcePages": [172], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-68", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "多选", "number": 68, "stem": "法律的运行是一个从创制、实施到实现的过程。这个过程主要包括法律制定（立法）、法律执行（执法）、法律适用（司法）、法律遵守（守法）等环节。其中，把法律规范转化为法律实践，把法定的权利和义务转化为现实的权利和义务是法律运行环节中的", "options": {"A": "法律制定", "B": "法律执行", "C": "法律适用", "D": "法律遵守"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [173], "answerSource": "待核对"}, {"id": "思修-多选-69", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "多选", "number": 69, "stem": "我国大部分的法律法规都是由行政机关执行的。行政执法是法律实施和实现的重要环节，必须坚持的基本原则有", "options": {"A": "合法性", "B": "合理性", "C": "信赖保护", "D": "效率"}, "answer": ["A", "B", "C", "D"], "note": "行政执法是法律实施和实现的重要环节，必须坚持的基本原则有：合法性；合理性；信赖保护；效率", "sourcePages": [173], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-70", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "多选", "number": 70, "stem": "2020年11月，中央全面依法治国工作会议正式提出习近平法治思想。习近平法治思想", "options": {"A": "是新时代全面依法治国的指导思想和根本遵循", "B": "是马克思主义法治理论中国化时代化的最新成果", "C": "是顺应实现中华民族伟大复兴时代要求应运而生的重大理论创新成果", "D": "深刻回答了新时代为什么实行全面依法治国、怎样实行全面依法治国等一系列重大问题"}, "answer": ["A", "B", "C", "D"], "note": "习近平法治思想是新时代全面依法治国的指导思想和根本遵循，是马克思主义法治理论中国化时代化的最新成果，是顺应实现中华民族伟大复兴时代要求应运而生的重大理论创新成果，深刻回答了新时代为什么实行全面依法治国、怎样实行全面依法治国等一系列重大问题。", "sourcePages": [173], "answerSource": "配套资料与题目核对"}, {"id": "思修-多选-73", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "多选", "number": 73, "stem": "把党的领导贯彻到依法治国全过程和各方面，是我国社会主义法治建设的一条基本经验。我国是人民民主专政的社会主义国家，党的领导是", "options": {"A": "全面依法治国的关键", "B": "社会主义法治最根本的保证", "C": "中国特色社会主义法治之魂", "D": "我们的法治同西方资本主义国家的法治最大的区别"}, "answer": ["B", "C", "D"], "note": "我国是人民民主专政的社会主义国家，党的领导是：社会主义法治最根本的保证；中国特色社会主义法治之魂；我们的法治同西方资本主义国家的法治最大的区别", "sourcePages": [173], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-76", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "多选", "number": 76, "stem": "坚持党的领导，是社会主义法治的根本要求，是全面依法治国的题中应有之义。坚持党的领导，体现在党", "options": {"A": "领导立法", "B": "保证执法", "C": "支持司法", "D": "带头守法"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [173], "answerSource": "待核对"}, {"id": "思修-多选-78", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "多选", "number": 78, "stem": "坚持全面依法治国，是中国特色社会主义国家制度和国家治理体系的显著优势。我国社会主义法治凝聚着我们党治国理政的理论成果和实践经验，是制度之治最基本最稳定最可靠的保障。法治兴则国兴，法治强则国强。法治是", "options": {"A": "解决一切问题的总钥匙", "B": "治国理政的基本方式", "C": "国家治理体系和治理能力的重要依托", "D": "国家核心竞争力的重要内容"}, "answer": ["B", "C", "D"], "note": "法治是：治国理政的基本方式；国家治理体系和治理能力的重要依托；国家核心竞争力的重要内容", "sourcePages": [174], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-80", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "多选", "number": 80, "stem": "党的二十届三中全会通过的《中共中央关于进一步全面深化改革推进中国式现代化的决定》，站在党和国家事业发展全局的战略高度，着眼以中国式现代化全面推进强国建设、民族复兴伟业，为聚焦发展全过程人民民主指明方向，提出推动“中国特色社会主义法治体系更加完善，社会主义法治国家建设达到更高水平”的目标要求，并对“完善中国特色社会主义法治体系”作出专章部署。中国特色社会主义法治体系", "options": {"A": "是国家治理体系的骨干工程", "B": "是全过程人民民主制度体系的重要依托", "C": "本质上是中国特色社会主义制度的法律表现形式", "D": "集中反映了中国之治的制度精华"}, "answer": ["A", "B", "C", "D"], "note": "中国特色社会主义法治体系：是国家治理体系的骨干工程；是全过程人民民主制度体系的重要依托；本质上是中国特色社会主义制度的法律表现形式；集中反映了中国之治的制度精华", "sourcePages": [174], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-81", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "多选", "number": 81, "stem": "党的十八届四中全会提出和确立了建设中国特色社会主义法治体系、建设社会主义法治国家的总目标，开启了建设社会主义法治国家的新征程。建设中国特色社会主义法治体系就是要形成完备的法律规范体系、高效的法治实施体系、严密的法治监督体系、有力的法治保障体系，形成完善的党内法规体系。完备的法律规范体系是", "options": {"A": "中国特色社会主义法治体系的前提", "B": "法治国家、法治政府、法治社会的制度基础", "C": "宪法法律有效实施的重要保障", "D": "全面依法治国的重要依托"}, "answer": ["A", "B"], "note": "完备的法律规范体系是：中国特色社会主义法治体系的前提；法治国家、法治政府、法治社会的制度基础", "sourcePages": [174], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-82", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "多选", "number": 82, "stem": "“100-1=0”。“一个错案的负面影响足以摧毁99个公正裁判积累起来的良好形象。执法司法中万分之一的失误，对当事人就是百分之百的伤害。”党的二十大报告指出，要严格公正司法，深化司法体制综合配套改革，全面准确落实司法责任制，加快建设公正高效权威的社会主义司法制度，努力让人民群众在每一个司法案件中感受到公平正义。公正是", "options": {"A": "法治的生命线", "B": "司法活动最高的价值追求", "C": "全面依法治国的前提", "D": "社会主义法治最根本的保证"}, "answer": ["A", "B"], "note": "公正是：法治的生命线；司法活动最高的价值追求", "sourcePages": [174], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-83", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "多选", "number": 83, "stem": "必须坚持宪法的国家根本法地位，是对我国宪法制度建设的规律性认识之一。宪法集中体现了党和人民的统一意志和共同愿望，是国家意志的最高表现形式，具有", "options": {"A": "根本性", "B": "全局性", "C": "稳定性", "D": "长期性"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [174], "answerSource": "待核对"}, {"id": "思修-多选-85", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "多选", "number": 85, "stem": "宪法的力量不仅因其地位崇高，更源于其有效的监督。在新的历史条件下，推进全面依法治国、加强宪法实施，对宪法监督提出了新的更高要求。这些新的更高要求是", "options": {"A": "健全人大工作机制", "B": "健全宪法解释机制", "C": "健全备案审查机制", "D": "健全合宪性审查机制"}, "answer": ["A", "B", "C", "D"], "note": "宪法的力量不仅因其地位崇高，更源于其有效的监督。在新的历史条件下，推进全面依法治国、加强宪法实施，对宪法监督提出了新的更高要求。这些新的更高要求是：健全人大工作机制；健全宪法解释机制；健全备案审查机制；健全合宪性审查机制", "sourcePages": [175], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-86", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "多选", "number": 86, "stem": "2025年9月12日，十四届全国人大常委会第十七次会议表决通过《法治宣传教育法》。制定《法治宣传教育法》是夯实全面依法治国社会基础的迫切要求。通过国家立法，在全社会弘扬社会主义法治精神、培育法治信仰、传播法律知识，使尊法学法守法用法成为全体人民的共同追求，让法治成为全民思维方式和行为习惯，为全面建设社会主义现代化国家营造良好法治环境。法治思维是一种", "options": {"A": "正当性思维", "B": "规范思维", "C": "逻辑思维", "D": "科学思维"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [175], "answerSource": "待核对"}, {"id": "思修-多选-87", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "多选", "number": 87, "stem": "法律至上是法治思维的基本内容之一。法律至上，具体表现为", "options": {"A": "法律的普遍适用", "B": "法律的优先适用", "C": "法律的权利保障", "D": "法律的不可违反"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [175], "answerSource": "待核对"}, {"id": "思修-多选-88", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "多选", "number": 88, "stem": "清代史学家赵翼分析历代贪官案例，得出了“贿随权集”的结论：贿赂总是跟随权力而聚集，即使是曾经品行端正之人，一旦手中有了权力，也容易腐化堕落。权力是把双刃剑，它既是施展才华、干事创业的利器，也是自断前程、人生陷落的“凶器”，关键看怎么用。因此，只有依法对权力的配置和运行进行有效制约和监督，才能防止权力私用、权力滥用和权力腐败。权力制约是社会主义法治思维的重要内容，其要求是", "options": {"A": "权力由法定", "B": "有权必有责", "C": "用权受监督", "D": "违法受追究"}, "answer": ["A", "B", "C", "D"], "note": "权力制约的要求：权力由法定、有权必有责、用权受监督、违法受追究。", "sourcePages": [175], "answerSource": "配套资料与题目核对"}, {"id": "思修-多选-89", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "多选", "number": 89, "stem": "公平正义是法治思维的基本内容之一。公平正义主要包括权利公平、机会公平、规则公平和救济公平。权利公平包括", "options": {"A": "权利和义务对等", "B": "权利主体平等", "C": "享有的权利特别是基本权利平等", "D": "权利保护和权利救济平等"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [175], "answerSource": "待核对"}, {"id": "思修-多选-90", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "多选", "number": 90, "stem": "公平正义是法治思维的基本内容之一。公平正义主要包括权利公平、机会公平、规则公平和救济公平。机会公平包括", "options": {"A": "起点平等", "B": "结果平等", "C": "发展平等", "D": "代际平等"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [175], "answerSource": "待核对"}, {"id": "思修-多选-91", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "多选", "number": 91, "stem": "权利保障是法治思维的基本内容之一。权利保障主要是指对公民权利的法律保障，具体包括公民权利的", "options": {"A": "宪法保障", "B": "立法保障", "C": "行政保障", "D": "司法保障"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [175], "answerSource": "待核对"}, {"id": "思修-多选-92", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "多选", "number": 92, "stem": "法律权利具有的特征有", "options": {"A": "法律权利的内容、种类和实现程度受社会物质生活条件的制约", "B": "法律权利的内容、分配和实现方式因社会制度和国家法律的不同而存在差异", "C": "法律权利不仅由法律规定或认可，而且受法律维护或保障，具有不可侵犯性", "D": "法律权利必须依法行使，不能不择手段地行使法律权利"}, "answer": ["A", "B", "C", "D"], "note": "法律权利具有的特征有：法律权利的内容、种类和实现程度受社会物质生活条件的制约；法律权利的内容、分配和实现方式因社会制度和国家法律的不同而存在差异；法律权利不仅由法律规定或认可，而且受法律维护或保障，具有不可侵犯性；法律权利必须依法行使，不能不择手段地行使法律权利", "sourcePages": [175], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-93", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "多选", "number": 93, "stem": "义务与权利相对应，是指政治上、法律上、道义上应当承担的责任。法律义务具有的特点有", "options": {"A": "法律义务是历史的", "B": "法律义务源于现实需要", "C": "法律义务必须依法设定", "D": "法律义务可能发生变化"}, "answer": ["A", "B", "C", "D"], "note": "法律义务具有的特点有：法律义务是历史的；法律义务源于现实需要；法律义务必须依法设定；法律义务可能发生变化", "sourcePages": [175], "answerSource": "帽子题配套资料"}, {"id": "思修-多选-96", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "多选", "number": 96, "stem": "人身自由是人们一切行动和生活的前提条件。人身自由是指", "options": {"A": "人的身体不受拘束", "B": "人的行动自由", "C": "人身自由不受非法限制和剥夺", "D": "公民居住、生活、休息的场所不受非法侵入或搜查的权利"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [176], "answerSource": "待核对"}, {"id": "思修-多选-97", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "多选", "number": 97, "stem": "我国宪法法律规定了公民享有的一系列权利，主要包括政治权利、宗教信仰自由、人身权利、财产权利、社会经济权利及文化教育权利等。社会经济权利主要包括", "options": {"A": "劳动权和休息权", "B": "私有财产权", "C": "社会保障权", "D": "物质帮助权"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [176], "answerSource": "待核对"}, {"id": "思修-多选-99", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "多选", "number": 99, "stem": "除了在各个部门法中规定了公民的法律义务外，我国宪法特别规定了公民的基本义务。公民未能依法履行义务，根据情节轻重，应当承担相应的法律责任。法律责任包括", "options": {"A": "民事责任", "B": "行政责任", "C": "刑事责任", "D": "社会责任"}, "answer": [], "note": "配套资料未能提供可确认的完整答案，本题暂不自动判分。", "sourcePages": [176], "answerSource": "待核对"}, {"id": "思修-多选-100", "subject": "思修", "chapter": 6, "chapterTitle": "第六章学习法治思想提升法治素养", "type": "多选", "number": 100, "stem": "尊重法律权威的基本要求是", "options": {"A": "信仰法律", "B": "遵守法律", "C": "服从法律", "D": "维护法律"}, "answer": ["A", "B", "C", "D"], "note": "尊重法律权威的基本要求是：信仰法律；遵守法律；服从法律；维护法律", "sourcePages": [176], "answerSource": "帽子题配套资料"}];